import type { LatLong, Obstruction, Site } from '../../model/site'
import type { Project } from '../../model/types'
import type { Command, CommandHandler } from '../command'
import type { CommandRegistry } from '../command-registry'

export const SET_SITE_LOCATION = 'site/set-location'

export interface SetSiteLocationParams {
  latLong: LatLong
}

export function setSiteLocation(latLong: LatLong): Command<SetSiteLocationParams> {
  return { type: SET_SITE_LOCATION, params: { latLong }, description: 'Set site location' }
}

const setSiteLocationHandler: CommandHandler<Project, SetSiteLocationParams> = {
  apply(state, params) {
    // Reassign the whole site slice so the inverse-capture proxy records the
    // root-level change and undo restores the prior reference (including back to
    // an absent site).
    state.site = { ...state.site, latLong: params.latLong }
  },
}

export const SET_SITE_NORTH_BEARING = 'site/set-north-bearing'

export interface SetSiteNorthBearingParams {
  northBearing: number
}

export function setSiteNorthBearing(northBearing: number): Command<SetSiteNorthBearingParams> {
  return {
    type: SET_SITE_NORTH_BEARING,
    params: { northBearing },
    description: 'Set site north bearing',
  }
}

const setSiteNorthBearingHandler: CommandHandler<Project, SetSiteNorthBearingParams> = {
  apply(state, params) {
    state.site = { ...state.site, northBearing: params.northBearing }
  },
}

export const SET_SITE_TIMEZONE = 'site/set-timezone'

export interface SetSiteTimezoneParams {
  timezone: string
}

export function setSiteTimezone(timezone: string): Command<SetSiteTimezoneParams> {
  return { type: SET_SITE_TIMEZONE, params: { timezone }, description: 'Set site timezone' }
}

const setSiteTimezoneHandler: CommandHandler<Project, SetSiteTimezoneParams> = {
  apply(state, params) {
    state.site = { ...state.site, timezone: params.timezone }
  },
}

export const ADD_OBSTRUCTION = 'site/add-obstruction'

export interface AddObstructionParams {
  obstruction: Obstruction
}

export function addObstruction(obstruction: Obstruction): Command<AddObstructionParams> {
  return { type: ADD_OBSTRUCTION, params: { obstruction }, description: 'Add obstruction' }
}

const addObstructionHandler: CommandHandler<Project, AddObstructionParams> = {
  apply(state, params) {
    state.site = {
      ...state.site,
      obstructions: [...(state.site?.obstructions ?? []), params.obstruction],
    }
  },
}

export const REMOVE_OBSTRUCTION = 'site/remove-obstruction'

export interface RemoveObstructionParams {
  id: string
}

export function removeObstruction(id: string): Command<RemoveObstructionParams> {
  return { type: REMOVE_OBSTRUCTION, params: { id }, description: 'Remove obstruction' }
}

const removeObstructionHandler: CommandHandler<Project, RemoveObstructionParams> = {
  apply(state, params) {
    const remaining = (state.site?.obstructions ?? []).filter(
      (obstruction) => obstruction.id !== params.id,
    )
    const rebuilt: Site = { ...state.site }
    // The obstructions list treats an absent value as "none", so collapse an
    // emptied list back to undefined rather than leaving a contract-violating
    // empty array.
    if (remaining.length > 0) {
      rebuilt.obstructions = remaining
    } else {
      delete rebuilt.obstructions
    }
    state.site = rebuilt
  },
}

export function registerSiteCommands(registry: CommandRegistry<Project>): CommandRegistry<Project> {
  return registry
    .register(SET_SITE_LOCATION, setSiteLocationHandler)
    .register(SET_SITE_NORTH_BEARING, setSiteNorthBearingHandler)
    .register(SET_SITE_TIMEZONE, setSiteTimezoneHandler)
    .register(ADD_OBSTRUCTION, addObstructionHandler)
    .register(REMOVE_OBSTRUCTION, removeObstructionHandler)
}

core/commands/handlers/wall-commands.ts.source:
import { createWall } from '../../model/factories'
import type { Floor, Point, Project, Wall, WallEnd } from '../../model/types'
import { assertPositiveLength } from '../../units/length-bounds'
import type { Command, CommandHandler } from '../command'
import type { CommandRegistry } from '../command-registry'

export type { WallEnd } from '../../model/types'

export const ADD_WALL = 'floor/add-wall'
export const MOVE_WALL_ENDPOINT = 'floor/move-wall-endpoint'
export const SET_WALL_THICKNESS = 'floor/set-wall-thickness'

export interface AddWallParams {
  floorId: string
  wall: Wall
}

export interface MoveWallEndpointParams {
  floorId: string
  wallId: string
  end: WallEnd
  to: Point
}

export interface SetWallThicknessParams {
  floorId: string
  wallId: string
  thickness: number
}

export function addWall(floorId: string, start: Point, end: Point): Command<AddWallParams> {
  // Build the wall eagerly at command-creation time so its id is fixed once and
  // redo reapplies the same wall rather than minting a new id, mirroring addFloor.
  return {
    type: ADD_WALL,
    params: { floorId, wall: createWall(start, end) },
    description: 'Draw wall',
  }
}

// Reassigns the whole floors slice because the inverse-capture proxy records
// only the root's top-level properties; the edited floor becomes a new object
// while untouched floors keep their reference for entity-keyed dirty tracking.
const addWallHandler: CommandHandler<Project, AddWallParams> = {
  apply(state, params) {
    state.floors = state.floors.map((floor) =>
      floor.id === params.floorId ? { ...floor, walls: [...floor.walls, params.wall] } : floor,
    )
  },
}

// eslint-disable-next-line max-params -- floor, wall, which end, and the target point is the natural signature for moving one wall endpoint
export function moveWallEndpoint(
  floorId: string,
  wallId: string,
  end: WallEnd,
  to: Point,
): Command<MoveWallEndpointParams> {
  return {
    type: MOVE_WALL_ENDPOINT,
    params: { floorId, wallId, end, to },
    description: 'Move wall endpoint',
  }
}

// Reassigns the whole floors slice, then maps the target floor's inner walls
// array, so the inverse-capture proxy records the change and the dispatcher
// captures the inverse for undo; only the target floor and target wall become
// new objects while every untouched floor and wall keeps its reference.
// eslint-disable-next-line max-params -- the floors slice plus the floor, wall, and per-wall update is the minimal signature for replacing one wall in place
function updateWall(
  floors: Floor[],
  floorId: string,
  wallId: string,
  update: (wall: Wall) => Wall,
): Floor[] {
  return floors.map((floor) =>
    floor.id === floorId
      ? { ...floor, walls: floor.walls.map((wall) => (wall.id === wallId ? update(wall) : wall)) }
      : floor,
  )
}

const moveWallEndpointHandler: CommandHandler<Project, MoveWallEndpointParams> = {
  apply(state, params) {
    state.floors = updateWall(state.floors, params.floorId, params.wallId, (wall) => ({
      ...wall,
      [params.end]: params.to,
    }))
  },
}

export function setWallThickness(
  floorId: string,
  wallId: string,
  thickness: number,
): Command<SetWallThicknessParams> {
  return {
    type: SET_WALL_THICKNESS,
    params: { floorId, wallId, thickness },
    description: 'Set wall thickness',
  }
}

const setWallThicknessHandler: CommandHandler<Project, SetWallThicknessParams> = {
  apply(state, params) {
    assertPositiveLength(params.thickness, 'Thickness')
    state.floors = updateWall(state.floors, params.floorId, params.wallId, (wall) => ({
      ...wall,
      thickness: params.thickness,
    }))
  },
}

export function registerWallCommands(registry: CommandRegistry<Project>): CommandRegistry<Project> {
  return registry
    .register(ADD_WALL, addWallHandler)
    .register(MOVE_WALL_ENDPOINT, moveWallEndpointHandler)
    .register(SET_WALL_THICKNESS, setWallThicknessHandler)
}

