core/scene/opening-motion.ts.source:
import {
  builtinElementTypes,
  type HingeEdge,
  type OpeningTypeParameters,
} from '../registries/element-types'
import { getEntry } from '../registries/registry'

import { type HungSash, SASH_FRAME_WIDTH_MM } from './opening-fill'
import { planToWorld } from './plan-to-world'
import type { OpeningSceneNode } from './scene-graph'
import type { Vector3 } from './vector3'

/**
 * The part of an opening's fill that a motion drives. 'primary' is the whole fill (a door
 * leaf, a pair of leaves, a whole sash). A HungSash is only the fill parts whose `sash`
 * names it.
 */
export type OpeningPartId = 'primary' | HungSash

/** Rotation of a leaf or sash about a fixed edge. */
export interface HingeMotion {
  kind: 'hinge'
  /** Which edge the leaf or sash pivots on. */
  edge: HingeEdge
  /** World point on the hinge edge held fixed through the swing. */
  pivot: Vector3
  /** Unit rotation axis in world space. */
  axis: Vector3
  /** Signed swing angle (radians) at full openness. */
  openAngle: number
  /** The part this motion drives (the representative moving leaf or sash). */
  partId: OpeningPartId
  /** How many parts move together in the full opening; a double has two. */
  partCount: number
}

/** The axis a slide motion travels along. */
export type SlideAxis = 'along-wall' | 'vertical'

/**
 * Translation of a leaf or sash along an axis. A hung window moves its lower sash only, by
 * the height of that sash.
 */
export interface SlideMotion {
  kind: 'slide'
  /** Whether the part slides along the wall or vertically. */
  axis: SlideAxis
  /** World translation applied at full openness. */
  travel: Vector3
  /** The part this motion drives (the representative moving leaf or sash). */
  partId: OpeningPartId
  /** How many parts move together in the full opening; a double has two. */
  partCount: number
}

/** An opening with no moving part: a cased opening or a fixed window. */
export interface NoMotion {
  kind: 'none'
}

/** The motion an opening plays when opened in walk mode. */
export type OpeningMotion = HingeMotion | SlideMotion | NoMotion

// A fully open leaf turns a quarter circle from shut, which reads clearly as open.
const QUARTER_TURN_RAD = Math.PI / 2
// Openings hinged on a jamb turn about the vertical (world Y) axis.
const WORLD_UP: Vector3 = { x: 0, y: 1, z: 0 }
// The motion drives one representative part; partCount records how many move together.
const REPRESENTATIVE_PART: OpeningPartId = 'primary'
const SINGLE_PART = 1
const PAIRED_PARTS = 2

const NO_MOTION: NoMotion = { kind: 'none' }

/**
 * Resolves how an opening moves from its element type, reading the type's
 * operation family from the registry. A swing door hinges on a jamb; a fixed
 * window or a cased opening has no moving part. A hung window raises its lower
 * sash only.
 */
export function openingMotion(type: string, opening: OpeningSceneNode): OpeningMotion {
  const params = getEntry(builtinElementTypes, type)?.opening
  switch (params?.family) {
    case 'swing':
      return jambHinge(opening, partCountOf(params))
    // Fold and pivot openings reuse the jamb-hinge swing so the door still reads as
    // opening; their own motions are tracked separately.
    case 'fold':
    case 'pivot':
      return jambHinge(opening, SINGLE_PART)
    case 'slide':
      return alongWallSlide(opening, partCountOf(params))
    case 'window-hung':
      return lowerSashRise(opening)
    case 'window-slide':
      return alongWallSlide(opening, SINGLE_PART)
    case 'window-crank':
      return crankHinge(opening, params.hingeEdge)
    default:
      return NO_MOTION
  }
}

function partCountOf(params: OpeningTypeParameters): number {
  return params.double === true ? PAIRED_PARTS : SINGLE_PART
}

/**
 * A vertical-axis hinge about the opening's hinge jamb, the jamb taken from the
 * opening's orientation and the swing direction signed by its facing.
 */
function jambHinge(opening: OpeningSceneNode, partCount: number): HingeMotion {
  const half = opening.width / 2
  const hingeSign = opening.orientation.hinge === 'end' ? 1 : -1
  const pivot = planToWorld(
    {
      x: opening.center.x + hingeSign * opening.along.x * half,
      y: opening.center.y + hingeSign * opening.along.y * half,
    },
    0,
  )
  const facingSign = opening.orientation.facing === 'negative' ? -1 : 1
  return {
    kind: 'hinge',
    edge: 'jamb',
    pivot,
    axis: WORLD_UP,
    // The axis map is orientation-preserving (a proper rotation onto the ground
    // plane), so a world rotation about +Y reads in plan as the opposite turn the
    // old mirrored map produced. Negating the angle keeps the leaf swinging toward
    // the same plan-space side its facing names.
    openAngle: -QUARTER_TURN_RAD * facingSign,
    partId: REPRESENTATIVE_PART,
    partCount,
  }
}

/**
 * A crank window's hinge: a jamb (vertical axis) for a casement, the head or the
 * sill (horizontal along-wall axis) for an awning or a hopper.
 */
function crankHinge(opening: OpeningSceneNode, edge: HingeEdge | undefined): HingeMotion {
  if (edge === 'head' || edge === 'sill') {
    return horizontalHinge(opening, edge)
  }
  return jambHinge(opening, SINGLE_PART)
}

/**
 * A hinge about a horizontal axis running along the wall, at the opening head or
 * sill. The free edge cranks toward the opening's facing side.
 */
function horizontalHinge(opening: OpeningSceneNode, edge: Exclude<HingeEdge, 'jamb'>): HingeMotion {
  const height = edge === 'head' ? opening.sillHeight + opening.height : opening.sillHeight
  const pivot = planToWorld({ x: opening.center.x, y: opening.center.y }, height)
  const facingSign = opening.orientation.facing === 'negative' ? -1 : 1
  const edgeSense = edge === 'head' ? -1 : 1
  return {
    kind: 'hinge',
    edge,
    pivot,
    // Plan north (+y) maps to world -Z, so the along-wall axis Z negates along.y.
    // `0 - along.y` rather than `-along.y` keeps an axis-aligned wall's Z a clean +0.
    axis: { x: opening.along.x, y: 0, z: 0 - opening.along.y },
    // Orientation-preserving axis map: as with the jamb hinge, the world rotation
    // sign flips relative to the old mirrored map to keep the sash cranking toward
    // the side its facing names.
    openAngle: -QUARTER_TURN_RAD * facingSign * edgeSense,
    partId: REPRESENTATIVE_PART,
    partCount: SINGLE_PART,
  }
}

/** A slide one opening width along the wall, in the opening's along direction. */
function alongWallSlide(opening: OpeningSceneNode, partCount: number): SlideMotion {
  return {
    kind: 'slide',
    axis: 'along-wall',
    travel: {
      x: opening.along.x * opening.width,
      y: 0,
      // Plan north (+y) maps to world -Z, so the along-wall travel Z negates along.y.
      // `0 - ...` rather than negation keeps an axis-aligned wall's Z a clean +0.
      z: 0 - opening.along.y * opening.width,
    },
    partId: REPRESENTATIVE_PART,
    partCount,
  }
}

/**
 * A rise of the lower sash, meeting rail included, until its top meets the head. The lower
 * sash sits one meeting-rail half-width above the middle of the opening, so it rises half
 * the height less that half-width. The rise stops at zero: a window no higher than its sash
 * frame has no room to open, and a negative rise would move the sash down out of the frame
 * at the sill.
 */
function lowerSashRise(opening: OpeningSceneNode): SlideMotion {
  return {
    kind: 'slide',
    axis: 'vertical',
    travel: { x: 0, y: Math.max(0, opening.height / 2 - SASH_FRAME_WIDTH_MM / 2), z: 0 },
    partId: 'lower',
    partCount: SINGLE_PART,
  }
}

core/scene/walk-camera.ts.source:
import type { Vector3 } from './vector3'
import { sweepWalkCollision, type PlanarPoint, type WalkCollisionWorld } from './walk-collision'

/** Eye height above the floor datum, in millimeters. */
export const WALK_EYE_HEIGHT_MM = 1700

/** Walking speed, in millimeters per second. */
export const WALK_SPEED_MM_PER_S = 3000

/** Small angular margin that keeps the pitch limit shy of straight up or down. */
const PITCH_LIMIT_EPSILON_RAD = 0.01

/** Pitch limit, just shy of straight up or down to avoid a degenerate view. */
export const MAX_WALK_PITCH_RAD = Math.PI / 2 - PITCH_LIMIT_EPSILON_RAD

/** How far ahead of the eye the look target sits, in millimeters. */
export const WALK_LOOK_DISTANCE_MM = 1000

/** Where the walker is and which way they look. yaw 0 faces -Z. */
export interface WalkState {
  position: Vector3
  yaw: number
  pitch: number
}

/** Per-frame walk intent: held movement keys and accumulated look deltas. */
export interface WalkInput {
  forward: boolean
  back: boolean
  left: boolean
  right: boolean
  yawDelta: number
  pitchDelta: number
}

/** Returns 1 when the key is held, 0 otherwise, for axis blending. */
function axisSign(positive: boolean, negative: boolean): number {
  return (positive ? 1 : 0) - (negative ? 1 : 0)
}

/** Sweeps the horizontal move from the previous position against the collision world, if any. */
function resolveMove(
  from: PlanarPoint,
  proposed: PlanarPoint,
  collision: WalkCollisionWorld | undefined,
): PlanarPoint {
  if (collision === undefined) {
    return proposed
  }
  return sweepWalkCollision(from, proposed, collision)
}

/**
 * Advances a walking camera by one timestep. Movement is constrained to the
 * horizontal (x, z) plane at the current eye height: yaw 0 faces -Z, so the
 * forward axis is (sin yaw, 0, -cos yaw) and the right axis is (cos yaw, 0,
 * sin yaw). The net direction is normalized and scaled by speed and dt, so a
 * diagonal covers the same total distance as a single key. When a collision
 * world is supplied, the proposed horizontal move is clamped or slid so the
 * walker keeps clear of the walls, while the eye height (y) is left untouched.
 * Yaw advances by the input yaw delta, and pitch advances by the input pitch
 * delta clamped to +/-MAX_WALK_PITCH_RAD. Returns a new state and never mutates
 * the input.
 */
// eslint-disable-next-line max-params -- the optional collision world is an environmental input independent of the walk state, the per-frame intent, and the timestep; collapsing it into any of those would conflate distinct concerns.
export function advanceWalk(
  state: WalkState,
  input: WalkInput,
  dtSeconds: number,
  collision?: WalkCollisionWorld,
): WalkState {
  const forwardScale = axisSign(input.forward, input.back)
  const rightScale = axisSign(input.right, input.left)
  const directionX = Math.sin(state.yaw) * forwardScale + Math.cos(state.yaw) * rightScale
  const directionZ = -Math.cos(state.yaw) * forwardScale + Math.sin(state.yaw) * rightScale
  const magnitude = Math.hypot(directionX, directionZ)

  let nextX = state.position.x
  let nextZ = state.position.z
  if (magnitude > 0) {
    const step = (WALK_SPEED_MM_PER_S * dtSeconds) / magnitude
    nextX += directionX * step
    nextZ += directionZ * step
  }
  const from = { x: state.position.x, z: state.position.z }
  const moved = resolveMove(from, { x: nextX, z: nextZ }, collision)

  const pitch = state.pitch + input.pitchDelta
  const clampedPitch = Math.max(-MAX_WALK_PITCH_RAD, Math.min(MAX_WALK_PITCH_RAD, pitch))

  return {
    position: { x: moved.x, y: state.position.y, z: moved.z },
    yaw: state.yaw + input.yawDelta,
    pitch: clampedPitch,
  }
}

/** Yaw and pitch deltas produced from a single pointer-look move. */
export interface PointerLookDelta {
  yawDelta: number
  pitchDelta: number
}

/**
 * Maps a pointer-look move to yaw and pitch deltas, in radians. A rightward
 * pointer move (positive movementX) yaws the view to the right (positive yaw),
 * and a downward pointer move (positive movementY, screen-y grows downward)
 * lowers the view (negative pitch). Both deltas scale with the sensitivity in
 * radians per pixel.
 */
export function pointerLookDelta(
  movementX: number,
  movementY: number,
  sensitivityRadPerPx: number,
): PointerLookDelta {
  return {
    yawDelta: movementX * sensitivityRadPerPx,
    pitchDelta: -movementY * sensitivityRadPerPx,
  }
}

/**
 * Accumulates a single pointer-look move onto the walk input, returning a new
 * WalkInput whose yaw and pitch deltas are the input's existing values plus the
 * pointer-look deltas. The sign rule lives entirely in pointerLookDelta, so a
 * rightward pointer move yaws the view right and a downward move lowers it.
 * Never mutates the input.
 */
// eslint-disable-next-line max-params -- four physically-independent quantities: the walk input plus the two screen-axis deltas and the scale factor; none can be meaningfully collapsed, matching pointerLookDelta's arity.
export function accumulatePointerLook(
  input: WalkInput,
  movementX: number,
  movementY: number,
  sensitivityRadPerPx: number,
): WalkInput {
  const step = pointerLookDelta(movementX, movementY, sensitivityRadPerPx)
  return {
    ...input,
    yawDelta: input.yawDelta + step.yawDelta,
    pitchDelta: input.pitchDelta + step.pitchDelta,
  }
}

/**
 * The unit vector the walker looks along. yaw 0 faces -Z and a positive pitch
 * raises the view toward +Y, so the direction is (sin yaw cos pitch, sin pitch,
 * -cos yaw cos pitch). It is the seam an interaction ray casts from the eye.
 */
export function walkLookDirection(state: WalkState): Vector3 {
  const cosPitch = Math.cos(state.pitch)
  return {
    x: Math.sin(state.yaw) * cosPitch,
    y: Math.sin(state.pitch),
    z: -Math.cos(state.yaw) * cosPitch,
  }
}

/**
 * Returns the point the walker is looking at, one look-distance ahead of the
 * eye, along {@link walkLookDirection}.
 */
export function walkLookTarget(state: WalkState): Vector3 {
  const direction = walkLookDirection(state)
  return {
    x: state.position.x + direction.x * WALK_LOOK_DISTANCE_MM,
    y: state.position.y + direction.y * WALK_LOOK_DISTANCE_MM,
    z: state.position.z + direction.z * WALK_LOOK_DISTANCE_MM,
  }
}

