/** Local-Y span of a wall: base on the finished floor, top at its height
 *  (foundation spec section 2.2). */
export function wallVerticalSpan(height: number): { base: number; top: number } {
  return { base: 0, top: height }
}

/** Local-Y span of a floor slab: top flush with the finished floor (Y = 0),
 *  thickness extending below (foundation spec section 2.2). */
export function floorSlabVerticalSpan(thickness: number): { top: number; bottom: number } {
  return { top: 0, bottom: -thickness }
}

core/color/linear-rgb.ts.source:
import type { LinearRgb } from './oklab'

const RGB_CHANNEL_COUNT = 3

export function clampToUnitInterval(value: number): number {
  return Math.min(1, Math.max(0, value))
}

export function mixLinearRgb(from: LinearRgb, to: LinearRgb, fraction: number): LinearRgb {
  return {
    r: from.r + (to.r - from.r) * fraction,
    g: from.g + (to.g - from.g) * fraction,
    b: from.b + (to.b - from.b) * fraction,
  }
}

export function scaleLinearRgb(color: LinearRgb, factor: number): LinearRgb {
  return { r: color.r * factor, g: color.g * factor, b: color.b * factor }
}

export function addLinearRgb(first: LinearRgb, second: LinearRgb): LinearRgb {
  return { r: first.r + second.r, g: first.g + second.g, b: first.b + second.b }
}

export function divideLinearRgb(color: LinearRgb, divisor: LinearRgb): LinearRgb {
  return { r: color.r / divisor.r, g: color.g / divisor.g, b: color.b / divisor.b }
}

/** The grey a color flattens toward under cloud: its own channel mean. */
export function greyOf(color: LinearRgb): LinearRgb {
  const mean = (color.r + color.g + color.b) / RGB_CHANNEL_COUNT
  return { r: mean, g: mean, b: mean }
}

core/commands/inverse-capture.ts.source:
export interface CapturedInverse {
  revert(): void
}

interface PriorState {
  existed: boolean
  value: unknown
}

/**
 * Records the first-touch prior state of each top-level key so a command can be
 * reverted by restoring those keys. Command handlers update state immutably by
 * reassigning whole top-level slices (`state.floors = next`), so only the root's
 * own properties change; nested objects are never deep-proxied.
 */
export function captureInverse<S extends object>(
  root: S,
): {
  state: S
  inverse: CapturedInverse
} {
  const record = new Map<PropertyKey, PriorState>()

  const remember = (target: S, key: PropertyKey): void => {
    if (record.has(key)) {
      return
    }
    record.set(key, { existed: key in target, value: Reflect.get(target, key) })
  }

  const state = new Proxy(root, {
    set(target, key, value): boolean {
      remember(target, key)
      return Reflect.set(target, key, value)
    },
    deleteProperty(target, key): boolean {
      remember(target, key)
      return Reflect.deleteProperty(target, key)
    },
  })

  const revert = (): void => {
    for (const [key, prior] of record) {
      if (prior.existed) {
        Reflect.set(root, key, prior.value)
      } else {
        Reflect.deleteProperty(root, key)
      }
    }
  }

  return { state, inverse: { revert } }
}

