/** Placeholder thickness for a floor slab, in millimeters. A real floor
 *  thickness becomes a layered assembly later (finish floor over substrate over
 *  structure, sharing the construction-profile machinery of the ADR-0034 wall
 *  profiles). Until then this single flat value stands in, and
 *  `floorSlabThickness()` is the one read point that the future assembly will
 *  replace. */
export const DEFAULT_FLOOR_SLAB_THICKNESS_MM = 250

/** The single read point for a floor slab's thickness. It takes no argument
 *  today because no model entity carries a per-slab thickness yet. */
export function floorSlabThickness(): number {
  return DEFAULT_FLOOR_SLAB_THICKNESS_MM
}

core/scene/opening-openness.ts.source:
/**
 * How fast an opening swings, in openness units per second. Openness runs from 0
 * (shut) to 1 (fully open), so this rate opens or closes a leaf in a quarter
 * second, brisk enough to feel responsive without snapping.
 */
export const OPENNESS_RATE_PER_S = 4

/**
 * Advances an opening's openness one timestep toward its target (0 shut, 1 open)
 * at {@link OPENNESS_RATE_PER_S}, clamped so it lands exactly on the target
 * without overshooting. Returns the new openness and never reads any other state.
 */
export function advanceOpenness(current: number, target: number, dtSeconds: number): number {
  const step = OPENNESS_RATE_PER_S * dtSeconds
  if (target > current) {
    return Math.min(target, current + step)
  }
  return Math.max(target, current - step)
}

core/scene/scene-graph-empty.ts.source:
import type { SceneGraph } from './scene-graph'

/**
 * Reports whether a scene graph carries renderable 3D geometry. Walls, rooms,
 * openings, stairs, and furniture are geometry; underlays and dimensions are 2D
 * references and annotations, so a graph holding only those still reads as empty.
 */
export function sceneGraphHasGeometry(graph: SceneGraph): boolean {
  return (
    graph.walls.length > 0 ||
    graph.rooms.length > 0 ||
    graph.openings.length > 0 ||
    graph.stairs.length > 0 ||
    graph.furniture.length > 0
  )
}

