import type { Point, Project, Stair, StairRunType } from '../../model/types'
import type { Command, CommandHandler } from '../command'
import type { CommandRegistry } from '../command-registry'

export const ADD_STAIR = 'project/add-stair'
export const REMOVE_STAIR = 'project/remove-stair'
export const MOVE_STAIR = 'project/move-stair'
export const ROTATE_STAIR = 'project/rotate-stair'
export const SET_STAIR_RUN_TYPE = 'project/set-stair-run-type'

export interface AddStairParams {
  stair: Stair
}

export function addStair(stair: Stair): Command<AddStairParams> {
  return {
    type: ADD_STAIR,
    params: { stair },
    description: 'Add stair',
  }
}

export interface RemoveStairParams {
  stairId: string
}

export function removeStair(stairId: string): Command<RemoveStairParams> {
  return {
    type: REMOVE_STAIR,
    params: { stairId },
    description: 'Remove stair',
  }
}

export interface MoveStairParams {
  stairId: string
  position: Point
}

export function moveStair(stairId: string, position: Point): Command<MoveStairParams> {
  return {
    type: MOVE_STAIR,
    params: { stairId, position },
    description: 'Move stair',
    // Collapses a continuous drag of one stair into a single undoable step by
    // merging only with an immediately preceding move of the same stair.
    coalesceWith(previous) {
      if (previous.type !== MOVE_STAIR) {
        return null
      }
      if ((previous.params as MoveStairParams).stairId !== stairId) {
        return null
      }
      return moveStair(stairId, position)
    },
  }
}

export interface RotateStairParams {
  stairId: string
  /** The absolute angle in radians, about the stair position, not a delta. */
  rotation: number
}

export function rotateStair(stairId: string, rotation: number): Command<RotateStairParams> {
  return {
    type: ROTATE_STAIR,
    params: { stairId, rotation },
    description: 'Rotate stair',
  }
}

export interface SetStairRunTypeParams {
  stairId: string
  runType: StairRunType
}

export function setStairRunType(
  stairId: string,
  runType: StairRunType,
): Command<SetStairRunTypeParams> {
  return {
    type: SET_STAIR_RUN_TYPE,
    params: { stairId, runType },
    description: 'Set stair run type',
  }
}

// Reassigns the whole `stairs` slice so the inverse-capture proxy records the
// change; mutating the array in place would leave the change invisible to undo.
const addStairHandler: CommandHandler<Project, AddStairParams> = {
  apply(state, params) {
    state.stairs = [...state.stairs, params.stair]
  },
}

const removeStairHandler: CommandHandler<Project, RemoveStairParams> = {
  apply(state, params) {
    state.stairs = state.stairs.filter((stair) => stair.id !== params.stairId)
  },
}

// Applies `patch` to the stair whose id matches `stairId`, leaving every other
// stair reference-equal. Reassigns the slice for the same undo reason as above,
// mirroring `mapTargetFloor`.
function mapTargetStair(state: Project, stairId: string, patch: Partial<Stair>): void {
  state.stairs = state.stairs.map((stair) =>
    stair.id === stairId ? { ...stair, ...patch } : stair,
  )
}

const moveStairHandler: CommandHandler<Project, MoveStairParams> = {
  apply(state, params) {
    mapTargetStair(state, params.stairId, { position: params.position })
  },
}

const rotateStairHandler: CommandHandler<Project, RotateStairParams> = {
  apply(state, params) {
    mapTargetStair(state, params.stairId, { rotation: params.rotation })
  },
}

const setStairRunTypeHandler: CommandHandler<Project, SetStairRunTypeParams> = {
  apply(state, params) {
    mapTargetStair(state, params.stairId, { runType: params.runType })
  },
}

export function registerStairCommands(
  registry: CommandRegistry<Project>,
): CommandRegistry<Project> {
  return registry
    .register(ADD_STAIR, addStairHandler)
    .register(REMOVE_STAIR, removeStairHandler)
    .register(MOVE_STAIR, moveStairHandler)
    .register(ROTATE_STAIR, rotateStairHandler)
    .register(SET_STAIR_RUN_TYPE, setStairRunTypeHandler)
}

