// core/assets/license-policy.ts
//
// The curated open-license policy for vernacular packs (design specification
// section 4.8). A redistribution-friendly allowlist, not the full SPDX list. Pure:
// no filesystem or process access. Shared by the in-app loader, the pack CLI,
// and the manifest check so all gates run on one policy.

/**
 * Curated, redistribution-friendly open licenses (design specification section 4.8).
 */
export const RECOGNIZED_LICENSES: readonly string[] = Object.freeze([
  'CC0-1.0',
  'CC-BY-4.0',
  'CC-BY-3.0',
  'CC-BY-SA-4.0',
  'CC-BY-SA-3.0',
  'MIT',
  'Apache-2.0',
  'BSD-2-Clause',
  'BSD-3-Clause',
])

/**
 * Share-alike licenses: redistribution-friendly but viral, so redistribution
 * must preserve their terms. Warned about when mixed with other licenses.
 */
export const SHARE_ALIKE_LICENSES: readonly string[] = Object.freeze([
  'CC-BY-SA-4.0',
  'CC-BY-SA-3.0',
])

/**
 * Licenses that conflict with an openly redistributable, modifiable pack
 * (NonCommercial / NoDerivatives). They cannot ship in an open pack.
 */
export const NON_REDISTRIBUTABLE_LICENSES: readonly string[] = Object.freeze([
  'CC-BY-NC-4.0',
  'CC-BY-NC-3.0',
  'CC-BY-NC-SA-4.0',
  'CC-BY-ND-4.0',
  'CC-BY-ND-3.0',
  'CC-BY-NC-ND-4.0',
])

/**
 * Whether a license identifier is in the recognized open-license allowlist.
 */
export function recognize(licenseId: string): boolean {
  return RECOGNIZED_LICENSES.includes(licenseId)
}

/**
 * Whether a license identifier carries share-alike terms.
 */
export function isShareAlike(licenseId: string): boolean {
  return SHARE_ALIKE_LICENSES.includes(licenseId)
}

/**
 * Whether a license identifier forbids redistribution in an open pack.
 */
export function isNoRedistribution(licenseId: string): boolean {
  return NON_REDISTRIBUTABLE_LICENSES.includes(licenseId)
}

/**
 * Hard license errors for one identifier: a no-redistribution license cannot ship
 * in an open pack, and an unrecognized license is not on the curated allowlist.
 */
export function licenseProblems(licenseId: string): string[] {
  if (isNoRedistribution(licenseId)) {
    return [`license "${licenseId}" forbids redistribution and cannot ship in an open pack`]
  }
  if (!recognize(licenseId)) {
    return [`license "${licenseId}" is not a recognized open license`]
  }
  return []
}

/**
 * A pack-wide warning when a share-alike license is mixed with other distinct
 * licenses, so redistribution must preserve the share-alike terms.
 */
export function shareAlikeWarning(licenseIds: readonly string[]): string | null {
  const distinct = [...new Set(licenseIds)]
  if (distinct.some(isShareAlike) && distinct.length > 1) {
    return 'pack mixes a share-alike license with other licenses; redistribution must preserve the share-alike terms'
  }
  return null
}

core/format/codec/graft.ts.source:
import { KNOWN_KEYS, KNOWN_ROOT_TYPE, variantTypeOf } from '../../model/known-keys'
import type { KnownKeyTable, KnownUnion, KnownValue } from '../../model/known-keys'
import type { Project } from '../../model/types'

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

// A key from a file can be any name, `__proto__` included; a plain assignment with that name sets
// the prototype instead of creating a key, so every key from a file is written as an own property.
function setOwn(target: Record<string, unknown>, key: string, value: unknown): void {
  Object.defineProperty(target, key, {
    value,
    writable: true,
    enumerable: true,
    configurable: true,
  })
}

function graftObject(
  previous: Record<string, unknown>,
  next: Record<string, unknown>,
): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const key of Object.keys(next)) {
    setOwn(result, key, graftUntypedMember(key, previous, next))
  }
  for (const key of Object.keys(previous)) {
    // A key the next document lacks is unknown or reserved data the reader dropped; preserve it.
    if (!Object.hasOwn(next, key)) {
      setOwn(result, key, previous[key])
    }
  }
  return result
}

function graftUntypedMember(
  key: string,
  previous: Record<string, unknown>,
  next: Record<string, unknown>,
): unknown {
  return Object.hasOwn(previous, key) ? graftUntyped(previous[key], next[key]) : next[key]
}

function idOf(value: unknown): string | undefined {
  return isPlainObject(value) && typeof value.id === 'string' ? value.id : undefined
}

// Pair each next item with the previous item of the same id, if any, and graft the pair.
function graftById(
  previous: readonly unknown[],
  next: readonly unknown[],
  graftPair: (previousItem: unknown, nextItem: unknown) => unknown,
): unknown[] {
  return next.map((item) => {
    const id = idOf(item)
    const match =
      id === undefined ? undefined : previous.find((candidate) => idOf(candidate) === id)
    return match === undefined ? item : graftPair(match, item)
  })
}

function graftArray(previous: readonly unknown[], next: readonly unknown[]): unknown[] {
  return graftById(previous, next, graftUntyped)
}

// The graft where the table has nothing to say, such as inside the value of an unknown key: shared
// keys take the next value and previous-only keys are restored (VFPF section 6.4).
function graftUntyped(previous: unknown, next: unknown): unknown {
  if (Array.isArray(previous) && Array.isArray(next)) {
    return graftArray(previous, next)
  }
  if (isPlainObject(previous) && isPlainObject(next)) {
    return graftObject(previous, next)
  }
  return next
}

interface TablePosition {
  table: KnownKeyTable
  at: KnownValue
}

interface TypeScope {
  table: KnownKeyTable
  keys: Readonly<Record<string, KnownValue>>
}

// Only an own key of the table is known; a name every object inherits, such as `constructor`, is not.
function knownValueOf(scope: TypeScope, key: string): KnownValue | undefined {
  return Object.hasOwn(scope.keys, key) ? scope.keys[key] : undefined
}

// A type is known only as an own entry of the table; a name every object inherits, such as
// `toString`, is not a type.
function knownTypeOf(table: KnownKeyTable, typeName: string): KnownKeyTable[string] | undefined {
  return Object.hasOwn(table, typeName) ? table[typeName] : undefined
}

function graftKnownMember(
  key: string,
  { previous, next }: { previous: Record<string, unknown>; next: Record<string, unknown> },
  scope: TypeScope,
): unknown {
  const known = knownValueOf(scope, key)
  if (known === undefined) {
    return graftUntypedMember(key, previous, next)
  }
  const { table } = scope
  return Object.hasOwn(previous, key)
    ? graftWithTable(previous[key], next[key], { table, at: known })
    : next[key]
}

function graftObjectWithTable(
  previous: Record<string, unknown>,
  next: Record<string, unknown>,
  scope: TypeScope,
): Record<string, unknown> {
  const result: Record<string, unknown> = {}
  for (const key of Object.keys(next)) {
    setOwn(result, key, graftKnownMember(key, { previous, next }, scope))
  }
  for (const key of Object.keys(previous)) {
    // A known key the next document lacks was cleared; only a key the table does not know is restored.
    if (!Object.hasOwn(next, key) && knownValueOf(scope, key) === undefined) {
      setOwn(result, key, previous[key])
    }
  }
  return result
}

function graftArrayWithTable(
  previous: readonly unknown[],
  next: readonly unknown[],
  position: TablePosition,
): unknown[] {
  return graftById(previous, next, (match, item) => graftWithTable(match, item, position))
}

// A map the schema types is a collection the model owns: an entry the next document omits was
// deleted and stays absent.
function graftMapWithTable(previous: unknown, next: unknown, position: TablePosition): unknown {
  if (!isPlainObject(previous) || !isPlainObject(next)) {
    return graftUntyped(previous, next)
  }
  const result: Record<string, unknown> = {}
  for (const key of Object.keys(next)) {
    setOwn(
      result,
      key,
      Object.hasOwn(previous, key) ? graftWithTable(previous[key], next[key], position) : next[key],
    )
  }
  return result
}

function sharesTag(
  previous: Record<string, unknown>,
  next: Record<string, unknown>,
  tag: string,
): boolean {
  return Object.hasOwn(previous, tag) && Object.hasOwn(next, tag) && previous[tag] === next[tag]
}

// At a tagged union, only a value whose tag is the same on both sides is grafted, as an object of
// that variant's type. A changed or missing tag means a new value, so nothing of the old one belongs
// to it; the same tag means an edit, so data this build does not know must survive it.
function graftUnionWithTable(
  previous: unknown,
  next: unknown,
  { table, union }: { table: KnownKeyTable; union: KnownUnion },
): unknown {
  if (!isPlainObject(previous) || !isPlainObject(next)) {
    return next
  }
  const { tag } = union
  if (!sharesTag(previous, next, tag)) {
    return next
  }
  const variant = variantTypeOf(union, next[tag])
  // A tag no variant of the table names is of a variant from a newer build: graft it untyped.
  return variant === undefined
    ? graftObject(previous, next)
    : graftWithTable(previous, next, { table, at: { kind: 'object', type: variant } })
}

/** A pure function of the previous value, the next value, the table, and the place in it. */
export function graftWithTable(
  previous: unknown,
  next: unknown,
  { table, at }: TablePosition,
): unknown {
  if (at.kind === 'array' && Array.isArray(previous) && Array.isArray(next)) {
    return graftArrayWithTable(previous, next, { table, at: at.item })
  }
  if (at.kind === 'map') {
    return graftMapWithTable(previous, next, { table, at: at.value })
  }
  if (at.kind === 'union') {
    return graftUnionWithTable(previous, next, { table, union: at })
  }
  const knownType = at.kind === 'object' ? knownTypeOf(table, at.type) : undefined
  if (knownType !== undefined && isPlainObject(previous) && isPlainObject(next)) {
    return graftObjectWithTable(previous, next, { table, keys: knownType.keys })
  }
  return graftUntyped(previous, next)
}

const ROOT_POSITION: TablePosition = {
  table: KNOWN_KEYS,
  at: { kind: 'object', type: KNOWN_ROOT_TYPE },
}

/**
 * Re-graft any value the previous Document carried that the next Document dropped, so a
 * read-modify-write cycle preserves extension payloads and reserved keys a reader does not
 * model (VFPF section 6.4). The graft follows the table of known keys from the Document root.
 * Production code calls `preserveUnknown`; this untyped-result form serves the tests.
 */
export function graftUnknown(previous: unknown, next: unknown): unknown {
  return graftWithTable(previous, next, ROOT_POSITION)
}

/** Apply the preservation overlay, returning a Document that restores dropped unknown data. */
export function preserveUnknown(previous: unknown, project: Project): Project {
  // The graft only adds keys the typed model omits, so the result is still a Project shape.
  return graftUnknown(previous, project) as Project
}

core/format/codec/revision.ts.source:
import { CURRENT_SCHEMA_REVISION } from '../../model/factories'
import type { Project } from '../../model/types'
import type { SchemaMode } from '../current-schema'
import { isInteger } from './json-values'

/** The revision of a document that stores none, or none that is an integer of zero or more. */
const UNREADABLE_REVISION = 0

/**
 * The stored `meta.schemaRevision` when it is an integer of zero or more; the unreadable revision
 * otherwise, as for the schema, which publishes a revision as a non-negative integer.
 */
export function readRevision(document: Project): number {
  const revision = document.meta.schemaRevision
  return isInteger(revision) && revision >= UNREADABLE_REVISION ? revision : UNREADABLE_REVISION
}

/** A revision above this build's is read tolerantly (a newer build wrote it); any other strictly. */
export function checkModeFor(revision: number): SchemaMode {
  return revision > CURRENT_SCHEMA_REVISION ? 'tolerant' : 'strict'
}

core/format/codec/read-stored-document.t.source:
import { isMigrationPending, migrateProject, targetVersionOf } from '../../migrations/migrate'
import { MalformedProjectError, UnsupportedSchemaVersionError } from '../../migrations/types'
import type { Project } from '../../model/types'
import type { CodecOptions, ReadFailure } from './codec-types'
import { parseDocumentJson } from './document-json'
import { asRecord, isInteger } from './json-values'

const NOT_JSON_FALLBACK = 'The bytes are not UTF-8 JSON'
const MIGRATION_FAILED_FALLBACK = 'The migration failed'

/**
 * Stored bytes brought to the current version, not yet checked against the schema. `document` is
 * typed `Project` but unchecked: the format rules have not run on it.
 */
export type StoredDocumentRead =
  | {
      readonly ok: true
      readonly document: Project
      /** The `meta.schemaVersion` the bytes were stored at. */
      readonly storedVersion: number
      /** True when the stored version was below the target, so the document was migrated up. */
      readonly versionRaised: boolean
    }
  | { readonly ok: false; readonly failure: ReadFailure }

/** The message of a thrown value; `fallback` stands in when the message is empty. */
function describeError(error: unknown, fallback: string): string {
  const message = error instanceof Error ? error.message : String(error)
  return message === '' ? fallback : message
}

function parseJson(bytes: Uint8Array): { json: unknown } | { message: string } {
  try {
    return { json: parseDocumentJson(bytes) }
  } catch (error) {
    return { message: describeError(error, NOT_JSON_FALLBACK) }
  }
}

/** The stored `meta.schemaVersion` when it is an integer; undefined for anything else. */
function readStoredVersion(json: unknown): number | undefined {
  const version = asRecord(asRecord(json)?.meta)?.schemaVersion
  return isInteger(version) ? version : undefined
}

/** The mapping from what a migration throws to a failure; `storedVersion` starts the chain. */
function migrationFailure(error: unknown, storedVersion: number): ReadFailure {
  if (error instanceof MalformedProjectError) return { kind: 'not-a-project' }
  if (error instanceof UnsupportedSchemaVersionError) {
    return {
      kind: 'newer-version',
      version: error.fromVersion,
      buildVersion: error.targetVersion,
    }
  }
  return {
    kind: 'migration-failed',
    fromVersion: storedVersion,
    message: describeError(error, MIGRATION_FAILED_FALLBACK),
  }
}

/** A migration to a higher version sets the revision back: the older file had none. */
function withoutRevision(project: Project): Project {
  const meta = { ...project.meta }
  delete meta.schemaRevision
  return { ...project, meta }
}

/** The document after the migration chain, which runs only when a step is pending. */
function migrateWhenPending(json: unknown, options: CodecOptions): Project {
  const pending = isMigrationPending(json, options.migration)
  return pending ? migrateProject(json, options.migration) : (json as Project)
}

function failed(failure: ReadFailure): StoredDocumentRead {
  return { ok: false, failure }
}

/**
 * Read the stored bytes of a document: parse, check the shape, refuse a version above the target,
 * migrate when a migration is pending, and reset the revision when the version rose (ADR-0178).
 * The one reader that decode and encode share. It does not check the format rules. Pure: no I/O.
 */
export function readStoredDocument(bytes: Uint8Array, options: CodecOptions): StoredDocumentRead {
  const parsed = parseJson(bytes)
  if ('message' in parsed) return failed({ kind: 'not-json', message: parsed.message })
  const storedVersion = readStoredVersion(parsed.json)
  if (storedVersion === undefined) return failed({ kind: 'not-a-project' })
  const targetVersion = targetVersionOf(options.migration)
  if (storedVersion > targetVersion) {
    return failed({ kind: 'newer-version', version: storedVersion, buildVersion: targetVersion })
  }
  try {
    const migrated = migrateWhenPending(parsed.json, options)
    const versionRaised = storedVersion < targetVersion
    const document = versionRaised ? withoutRevision(migrated) : migrated
    return { ok: true, document, storedVersion, versionRaised }
  } catch (error) {
    return failed(migrationFailure(error, storedVersion))
  }
}

core/color/operations.ts.source:
import { colorFromOkLab, type Color } from './color'

/**
 * Linearly interpolate each OKLab component (L, a, b) between two colors and
 * rebuild a consistent Color. Mixing in OKLab yields a perceptual blend rather
 * than the muddy midpoints of an sRGB lerp (design spec 7.4).
 */
export function mixColors(from: Color, to: Color, t: number): Color {
  return colorFromOkLab({
    // eslint-disable-next-line @typescript-eslint/naming-convention -- L is the published OKLab lightness axis, not a renamable identifier
    L: from.oklab.L + (to.oklab.L - from.oklab.L) * t,
    a: from.oklab.a + (to.oklab.a - from.oklab.a) * t,
    b: from.oklab.b + (to.oklab.b - from.oklab.b) * t,
  })
}

/** Euclidean distance between two colors in OKLab, a perceptual difference metric. */
export function perceptualDistance(from: Color, to: Color): number {
  const dL = from.oklab.L - to.oklab.L
  const da = from.oklab.a - to.oklab.a
  const db = from.oklab.b - to.oklab.b
  return Math.hypot(dL, da, db)
}

/**
 * The OKLab chroma of a color: the Euclidean length of its a and b axes,
 * zero for an achromatic gray and larger for a more saturated hue. Backs the
 * tone-map-extreme gate's neutral-hue check (issue #512, ADR-0168).
 */
export function oklabChroma(color: Color): number {
  return Math.hypot(color.oklab.a, color.oklab.b)
}

/**
 * Find the candidate with the smallest perceptual distance to the target by
 * linear scan. Returns undefined (never null) for an empty candidate list.
 */
export function nearestColor(target: Color, candidates: readonly Color[]): Color | undefined {
  let best: Color | undefined
  let bestDistance = Number.POSITIVE_INFINITY
  for (const candidate of candidates) {
    const distance = perceptualDistance(target, candidate)
    if (distance < bestDistance) {
      best = candidate
      bestDistance = distance
    }
  }
  return best
}

core/environment/daylight-site.ts.source:
import type { LatLong, Site } from '../model/site'
import type { PlanDirection } from '../scene/front-direction'
import { DAYLIGHT_REFERENCE_PLACE } from './daylight-reference'
import { utcOffsetMinutesFor } from './timezone-offset'

/** The site the sun is computed for, and which parts of it are a sample. */
export interface DaylightSite {
  latLong: LatLong
  /** Radians, plan-up to true north. */
  northBearing: number
  utcOffsetMinutes: number
  sample: 'none' | 'location' | 'location-and-north'
}

export type DaylightSample = DaylightSite['sample']

/** The sample place reads solar time, so its clock offset is zero. */
const SAMPLE_UTC_OFFSET_MINUTES = 0

/** The stored north bearing when it is a finite number; otherwise it counts as missing. */
function usableNorthBearing(site: Site | undefined): number | undefined {
  const bearing = site?.northBearing
  return bearing !== undefined && Number.isFinite(bearing) ? bearing : undefined
}

/** The stored location when both coordinates are finite numbers; otherwise it counts as missing. */
function usableLatLong(site: Site | undefined): LatLong | undefined {
  const latLong = site?.latLong
  return latLong !== undefined &&
    Number.isFinite(latLong.latitude) &&
    Number.isFinite(latLong.longitude)
    ? latLong
    : undefined
}

/**
 * Which parts of the stored site are a sample: none, the location, or the
 * location and north. A north bearing that is not a finite number counts as missing.
 * A stored location with a latitude or longitude that is not a finite number
 * counts as missing.
 */
export function daylightSampleOf(site: Site | undefined): DaylightSample {
  if (usableLatLong(site) !== undefined) return 'none'
  if (usableNorthBearing(site) !== undefined) return 'location'
  return 'location-and-north'
}

/**
 * The site the sun is computed for. A stored location is kept as it is. Without
 * one, the sample place stands in, and a stored north bearing is kept; with no
 * bearing either, north is implied so that true south is the front. A north
 * bearing that is not a finite number counts as missing, so it is never kept.
 * A stored location with a latitude or longitude that is not a finite number
 * counts as missing.
 */
export function daylightSiteFor(
  site: Site | undefined,
  front: PlanDirection,
  date: string,
): DaylightSite {
  const sample = daylightSampleOf(site)
  const latLong = usableLatLong(site)
  if (latLong !== undefined) {
    return {
      latLong,
      northBearing: usableNorthBearing(site) ?? 0,
      utcOffsetMinutes: utcOffsetMinutesFor(site?.timezone, date, latLong.longitude),
      sample,
    }
  }
  return {
    latLong: DAYLIGHT_REFERENCE_PLACE,
    northBearing: usableNorthBearing(site) ?? Math.atan2(front.x, -front.y),
    utcOffsetMinutes: SAMPLE_UTC_OFFSET_MINUTES,
    sample,
  }
}

core/environment/environment-state.ts.source:
import {
  observationInstantToIso,
  parseObservationInstant,
  type ObservationInstant,
} from './observation-time'
import { openingInstant } from './opening-instant'
import { DEFAULT_CLOUD_COVER } from './sky-model'
import type { EnvironmentScene } from '../model/environment-scene'

export type LightingMode = 'schematic' | 'realistic'

/**
 * The panel-level session contract (spec: Architecture): everything the Environment
 * panel owns. Location and timezone stay on Site; the bridge composes the two.
 */
export interface EnvironmentState {
  readonly mode: LightingMode
  readonly observedAt: ObservationInstant
  readonly cloudCover: number // 0 clear .. 1 overcast
  readonly colorCheck: boolean
}

export const DEFAULT_ENVIRONMENT_STATE: EnvironmentState = {
  mode: 'schematic',
  observedAt: openingInstant({ site: undefined }),
  cloudCover: DEFAULT_CLOUD_COVER,
  colorCheck: false,
}

export interface EnvironmentSceneIdentity {
  id: string
  name: string
}

/** Persists the current "when and weather" as a named scene (observedAt ISO + weather). */
export function captureEnvironmentScene(
  state: EnvironmentState,
  identity: EnvironmentSceneIdentity,
): EnvironmentScene {
  return {
    id: identity.id,
    name: identity.name,
    observedAt: observationInstantToIso(state.observedAt),
    weather: { cloudCover: state.cloudCover },
  }
}

/** Recalls a scene's when-and-weather into the state; mode and colorCheck are untouched. */
export function applyEnvironmentScene(
  state: EnvironmentState,
  scene: EnvironmentScene,
): EnvironmentState {
  return {
    mode: state.mode,
    observedAt: parseObservationInstant(scene.observedAt),
    cloudCover: scene.weather?.cloudCover ?? DEFAULT_CLOUD_COVER,
    colorCheck: state.colorCheck,
  }
}

