import type { Point } from '../model/types'
import { getEntry, type Registry } from '../registries/registry'
import {
  builtinTrimProfiles,
  type TrimProfile,
  type TrimProfileShape,
} from '../registries/trim-profiles'
import type { Contour } from './contour'

/**
 * The cross-section outline of a trim profile in a profile-local frame: `x` runs
 * out from the wall face (0 at the wall, `+x` proud of it) and `y` runs up the
 * wall (0 at the bottom seat, `+y` up). The contour is closed; its last segment
 * returns to the wall face at the start. Core emits exact arcs and the engine owns
 * tessellation, mirroring `openingVoidContour` (foundation spec 3.2): the geometry
 * resolves from the registry shape parameter, so a new profile shape is a new
 * `case` here, not a change in the routine that draws it.
 */

/** Square-edged stock: a plain rectangle the height and projection of the moulding. */
function flatSection(height: number, projection: number): Contour {
  return {
    start: { x: 0, y: 0 },
    segments: [
      { kind: 'line', to: { x: projection, y: 0 } },
      { kind: 'line', to: { x: projection, y: height } },
      { kind: 'line', to: { x: 0, y: height } },
      { kind: 'line', to: { x: 0, y: 0 } },
    ],
  }
}

/**
 * A quarter-round-faced moulding: a flat seat and back, a front face rising to
 * where the round-over begins, then a quarter-circle of radius `projection` rolling
 * back to the wall at the top. A `concave` face (cove) is centered at the front-top
 * corner and sweeps toward the body; a convex face (ovolo) is centered on the wall
 * and sweeps away from it. `projection <= height` keeps the arc a true circle.
 */
function quarterRoundSection(height: number, projection: number, concave: boolean): Contour {
  const roundStart = height - projection
  const center: Point = concave ? { x: projection, y: height } : { x: 0, y: roundStart }
  return {
    start: { x: 0, y: 0 },
    segments: [
      { kind: 'line', to: { x: projection, y: 0 } },
      { kind: 'line', to: { x: projection, y: roundStart } },
      { kind: 'arc', to: { x: 0, y: height }, center, clockwise: concave },
      { kind: 'line', to: { x: 0, y: 0 } },
    ],
  }
}

/**
 * Resolves a trim profile's cross-section contour from its shape parameter and
 * stock dimensions (`height` up the wall, `projection` out from the wall face),
 * the trim analog of {@link openingVoidContour}. The shape is the registry
 * parameter (see `core/registries/trim-profiles.ts`); the union is exhaustive, so
 * a new {@link TrimProfileShape} surfaces here as a missing `case` at compile time.
 */
export function trimProfileSection(
  shape: TrimProfileShape,
  height: number,
  projection: number,
): Contour {
  switch (shape) {
    case 'cove':
      return quarterRoundSection(height, projection, true)
    case 'ovolo':
      return quarterRoundSection(height, projection, false)
    case 'flat':
      return flatSection(height, projection)
  }
}

/**
 * Resolves a trim profile's cross-section contour from a registry id, the trim
 * analog of {@link openingVoidContour} resolving an opening's void from its
 * element type. The shape and stock dimensions come from the registry entry, so
 * the 2D plan or section symbol reads geometry without knowing the profile shape.
 * An id the registry does not carry resolves to `undefined`, since the dimensions
 * live on the entry and there is nothing plausible to draw without it.
 */
export function resolveTrimProfileSection(
  profileId: string,
  trimProfiles: Registry<TrimProfile> = builtinTrimProfiles,
): Contour | undefined {
  const entry = getEntry(trimProfiles, profileId)
  if (entry === undefined) return undefined
  return trimProfileSection(entry.shape, entry.height, entry.projection)
}

core/topology/junction-fill.ts.source:
import { distance } from '../geometry/point'
import { lineIntersection } from '../geometry/segment'
import {
  directionAngle,
  dot,
  leftNormal,
  leftPerp,
  negate,
  subtract,
  unit,
} from '../geometry/vector'
import type { Point } from '../model/types'
import { signedArea } from '../scene/winding'

import type { GraphEdge, PlanarGraph } from './wall-graph'
import { type WallFootprint, vertexIncidence, wallFootprints } from './wall-footprint'

/**
 * The plan-space core a junction leaves uncovered, ready to be filled. Its `polygon`
 * is the closed ring of resolved wall-footprint corners around the junction vertex,
 * read off the same corners the walls stop at, and `edgeIndexes` lists the graph
 * edges incident to that vertex (its source walls).
 */
export interface JunctionFill {
  /** The closed ring of footprint corners enclosing the junction vertex. */
  polygon: Point[]
  /** Indices into {@link PlanarGraph.edges} of the walls meeting at the vertex. */
  edgeIndexes: number[]
}

/**
 * One incident edge as seen from a junction vertex: its outgoing unit direction from
 * the vertex, whether the vertex is the edge's `a` end, the edge's global `+normal`,
 * and the edge's index into the footprint result.
 */
interface Spoke {
  edgeIndex: number
  atA: boolean
  out: Point
  normal: Point
}

/** A junction gets a fill only where this many or more walls meet. */
const MIN_FILL_INCIDENCE = 3

/** Square millimeters below which a junction's core has collapsed to a line and gets no fill. */
const AREA_EPSILON = 1

/** Two points this close together count as the same footprint corner. */
const CORNER_EPSILON = 1e-6

/**
 * How many bounding-corner spans a cap crossing may stray from its midpoint fallback
 * before it counts as the near-parallel runaway and is clamped back to that midpoint.
 * Clean miters, tees, and acute bays cross within a fraction of a span of the midpoint;
 * the near-parallel runaway lands many spans away, so this sits comfortably between them.
 */
const MAX_CROSSING_SPANS = 4

/**
 * The plan-view fill polygon for every junction where three or more walls meet whose
 * uncovered core has area, read from the resolved corners the walls stop at. A free
 * end and a two-way corner yield no fill (the wall prisms already join those solid).
 * `thicknessByEdge[i]` is the thickness of the wall on edge `i`. The polygon's points
 * are read from `wallFootprints`, so the fill abuts each wall along its near edge.
 */
export function junctionFills(graph: PlanarGraph, thicknessByEdge: number[]): JunctionFill[] {
  const context: FillContext = { graph, footprints: wallFootprints(graph, thicknessByEdge) }
  const fills: JunctionFill[] = []
  for (const [vertexIndex, edgeIndexes] of vertexIncidence(graph)) {
    if (edgeIndexes.length < MIN_FILL_INCIDENCE) continue
    const polygon = corePolygon(context, vertexIndex, edgeIndexes)
    if (Math.abs(signedArea(polygon)) > AREA_EPSILON) fills.push({ polygon, edgeIndexes })
  }
  return fills
}

/** Per-call lookups shared while reading every junction's core polygon. */
interface FillContext {
  graph: PlanarGraph
  footprints: WallFootprint[]
}

/**
 * The uncovered core ring around a junction vertex: sort its incident spokes in
 * counter-clockwise fan order, read each wall's near edge (cap) at the vertex, then
 * cross each adjacent pair of cap lines. For a clean wedge this crossing is the walls'
 * shared miter; for an acute wedge where the walls overlap it is the near-vertex
 * crossing, so the ring stays simple with one vertex per incident wall.
 */
function corePolygon(context: FillContext, vertexIndex: number, edgeIndexes: number[]): Point[] {
  const spokes = edgeIndexes.map((edgeIndex) => spokeAt(context.graph, edgeIndex, vertexIndex))
  spokes.sort((left, right) => directionAngle(left.out) - directionAngle(right.out))
  const caps = spokes.map((spoke) =>
    wallCap(context.footprints[spoke.edgeIndex] as WallFootprint, spoke),
  )
  const polygon = caps.map((cap, index) =>
    capCrossing(cap, caps[(index + 1) % caps.length] as WallCap),
  )
  return dedupeAdjacent(polygon)
}

/**
 * A wall's near edge at a junction vertex: the footprint corners on the spoke's
 * counter-clockwise (`+leftPerp(spoke.out)`) and clockwise (`-leftPerp(spoke.out)`) sides.
 */
interface WallCap {
  ccwCorner: Point
  cwCorner: Point
}

/** Read a wall's near edge at the vertex from its footprint corners on each side. */
function wallCap(footprint: WallFootprint, spoke: Spoke): WallCap {
  return {
    ccwCorner: cornerOf(footprint, spoke, leftPerp(spoke.out)),
    cwCorner: cornerOf(footprint, spoke, negate(leftPerp(spoke.out))),
  }
}

/**
 * Where the cap lines of two angularly-adjacent spokes cross, with `a` the
 * counter-clockwise-earlier spoke and `b` its counter-clockwise neighbor: the shared
 * miter for a clean wedge, the near-vertex crossing for an acute overlapping wedge.
 *
 * The crossing falls back to the midpoint of the two corners that bound this wedge
 * (`a`'s counter-clockwise-side corner and `b`'s clockwise-side corner) in two cases:
 * when the cap lines are exactly parallel (collinear walls, no crossing), and when they
 * are near-parallel (a very wide wedge between two nearly-collinear walls, close to 180
 * degrees) so the crossing runs away far from the vertex. The runaway is detected by the
 * crossing landing more than {@link MAX_CROSSING_SPANS} bounding-corner spans from that
 * midpoint, which clamps it back inside the junction. Clean miters and acute overlaps
 * cross near the vertex and well within the bound, so they keep their exact corners.
 */
function capCrossing(a: WallCap, b: WallCap): Point {
  const fallback = midpoint(a.ccwCorner, b.cwCorner)
  const crossing = lineIntersection(
    a.ccwCorner,
    subtract(a.cwCorner, a.ccwCorner),
    b.ccwCorner,
    subtract(b.cwCorner, b.ccwCorner),
  )
  if (crossing === null) return fallback
  const span = distance(a.ccwCorner, b.cwCorner)
  if (distance(crossing, fallback) > span * MAX_CROSSING_SPANS) return fallback
  return crossing
}

/** The midpoint of `p` and `q`. */
function midpoint(p: Point, q: Point): Point {
  return { x: (p.x + q.x) / 2, y: (p.y + q.y) / 2 }
}

/** Build one spoke: the edge's outgoing direction from the vertex and its global normal. */
function spokeAt(graph: PlanarGraph, edgeIndex: number, vertexIndex: number): Spoke {
  const edge = graph.edges[edgeIndex] as GraphEdge
  const atA = edge.a === vertexIndex
  const vertex = graph.vertices[vertexIndex] as Point
  const far = graph.vertices[atA ? edge.b : edge.a] as Point
  // `a` and `b` are the edge's canonical endpoints, fixing the global `leftNormal(a, b)`.
  const a = graph.vertices[edge.a] as Point
  const b = graph.vertices[edge.b] as Point
  return { edgeIndex, atA, out: unit(subtract(far, vertex)), normal: leftNormal(a, b) }
}

/**
 * Read the footprint corner on the side `sideDir` selects: whichever of the spoke's
 * `+normal`/`-normal` corners at its vertex end lies on that side. This inverts the
 * footprint pass's corner assignment, so the fill reads the corners the walls committed.
 */
function cornerOf(footprint: WallFootprint, spoke: Spoke, sideDir: Point): Point {
  const isPlus = dot(sideDir, spoke.normal) > 0
  if (spoke.atA) return isPlus ? footprint.aPlus : footprint.aMinus
  return isPlus ? footprint.bPlus : footprint.bMinus
}

/** Drop each point equal (within epsilon) to the one before it, and the last if it equals the first. */
function dedupeAdjacent(points: Point[]): Point[] {
  const deduped: Point[] = []
  for (const point of points) {
    const previous = deduped[deduped.length - 1]
    if (previous === undefined || !samePoint(previous, point)) deduped.push(point)
  }
  const first = deduped[0]
  const last = deduped[deduped.length - 1]
  if (deduped.length > 1 && first !== undefined && last !== undefined && samePoint(first, last)) {
    deduped.pop()
  }
  return deduped
}

/** Whether two points are the same footprint corner, within epsilon. */
function samePoint(a: Point, b: Point): boolean {
  return Math.abs(a.x - b.x) < CORNER_EPSILON && Math.abs(a.y - b.y) < CORNER_EPSILON
}

core/environment/daylight-calibration.ts.source:
import { linearLuminance } from '../color/contrast'
import {
  addLinearRgb,
  clampToUnitInterval,
  divideLinearRgb,
  greyOf,
  mixLinearRgb,
  scaleLinearRgb,
} from '../color/linear-rgb'
import type { LinearRgb } from '../color/oklab'
import { referenceLightingInput } from './daylight-reference'
import { solarPosition } from './solar-position'
import { agxNeutralInverse } from './tone-response'

/*
 * The daylight calibration: three stated targets and the constants derived from them.
 * 1. The ratio of direct to diffuse light on a level card, a function of the sun's height.
 * 2. The white point: the color of sun plus sky on a level white card at the reference instant.
 * 3. The sunlit white level: at the reference instant a wall of reflectance 0.85 facing south
 *    returns the linear level that AgX at exposure 1 shows as the white code floor.
 * Every value on a level card is irradiance over pi, so a white card returns it as radiance.
 */

/** The lowest display code a sunlit white wall reads as white. */
export const WHITE_CODE_FLOOR = 225
/** The largest 8-bit display code. */
const DISPLAY_CODE_MAX = 255
/** The lux on the level card at the reference instant. */
export const REFERENCE_HORIZONTAL_ILLUMINANCE_LUX = 80_000

/** Fraction of full dome brightness the sky keeps through the night. */
const NIGHT_DOME_SCALE = 0.35
/**
 * The mean luminance of the dome before calibration, frozen as a number. It does not follow a
 * later change of the raw tints.
 */
const DOME_MEAN_LUMINANCE = 0.4445
/**
 * The level the diffuse light on the level card never falls below. It holds the sky's level
 * through the night and until the sun is about 12.19 degrees up, where the sun-driven level first
 * exceeds it.
 */
export const NIGHT_DIFFUSE_LEVEL = NIGHT_DOME_SCALE * DOME_MEAN_LUMINANCE

const EIGHTH_TURN_DIVISOR = 4
/** The sun height, 45 degrees, at which the direct to diffuse ratio is stated as 5 to 1. */
const RATIO_STATED_HEIGHT = Math.PI / EIGHTH_TURN_DIVISOR
/** How far the direct to diffuse ratio rises above 1 at RATIO_STATED_HEIGHT, giving 5 to 1. */
const RATIO_RISE_AT_STATED_HEIGHT = 4

/** Direct sun tint with the sun on the horizon: strongly reddened by the long air path. */
const HORIZON_SUN_TINT: LinearRgb = { r: 1, g: 0.55, b: 0.25 }
/** Direct sun tint with the sun overhead: near-white with a faint residual warmth. */
const ZENITH_SUN_TINT: LinearRgb = { r: 1, g: 0.98, b: 0.95 }
/** Dome tint at the horizon: a dim, nearly grey band. */
const HORIZON_DOME_TINT: LinearRgb = { r: 0.45, g: 0.45, b: 0.5 }
/** Dome tint at the zenith: a saturated daytime blue, bluer than the horizon band. */
const ZENITH_DOME_TINT: LinearRgb = { r: 0.25, g: 0.45, b: 0.9 }

/**
 * The clear-sky optical depth of the direct sun in the daylight availability formula that
 * ADR-0192 cites: the direct normal illuminance goes as exp(-0.21 / sin h). ADR-0192 uses it
 * when it derives the photometric anchor; in the code it multiplies the relative air mass in
 * the fade of the sun's level.
 */
export const SUN_OPTICAL_DEPTH = 0.21

const HALF_TURN_IN_DEGREES = 180
const DEGREES_PER_RADIAN = HALF_TURN_IN_DEGREES / Math.PI
/** The coefficient of the height term in the Kasten and Young air mass. */
const KASTEN_YOUNG_COEFFICIENT = 0.50572
/** The degrees added to the sun's height in the Kasten and Young air mass. */
const KASTEN_YOUNG_OFFSET_DEGREES = 6.07995
/** The power the offset height is raised to in the Kasten and Young air mass. */
const KASTEN_YOUNG_EXPONENT = -1.6364

/**
 * The relative air mass at a sun height in radians: the length of the light's path through the
 * air relative to the path overhead. It is the formula of F. Kasten and A. T. Young, "Revised
 * optical air mass tables and approximation formula", Applied Optics 28 (1989), 4735-4738:
 * 1 / (sin h + 0.50572 (h + 6.07995) ^ -1.6364) with h in degrees in the second term. Unlike
 * 1 / sin h it stays finite at the horizon, about 38 there, and it is about 0.9997 overhead.
 */
export function relativeAirMass(sunAltitude: number): number {
  const heightDegrees = sunAltitude * DEGREES_PER_RADIAN
  return (
    1 /
    (Math.sin(sunAltitude) +
      KASTEN_YOUNG_COEFFICIENT *
        (heightDegrees + KASTEN_YOUNG_OFFSET_DEGREES) ** KASTEN_YOUNG_EXPONENT)
  )
}

/** The relative air mass with the sun overhead, where the fade is exactly 1. */
const ZENITH_AIR_MASS = relativeAirMass(Math.PI / 2)

/**
 * Exponent of the Kasten-Czeplak direct-beam cloud transmission curve: convex, so light cloud
 * cover barely dims the direct sun while heavy cover extinguishes it by full overcast.
 */
const DIRECT_BEAM_CLOUD_EXPONENT = 3.4
/** Fraction of the diffuse level a fully overcast sky removes. */
const OVERCAST_DIFFUSE_DIMMING = 0.3

/**
 * The view height whose dome radiance equals the cosine-weighted mean of the upper dome. The dome
 * is linear in the view height y, and the mean of a + b y under the weight y over the hemisphere
 * is a + 2 b / 3: the ratio of the integrals of y squared and y over [0, 1]. The term toward the
 * sun integrates to zero over each ring, so it drops out.
 */
const HEIGHT_INTEGRAL_DENOMINATOR = 2
const HEIGHT_SQUARED_INTEGRAL_DENOMINATOR = 3
const COSINE_WEIGHTED_MEAN_HEIGHT =
  HEIGHT_INTEGRAL_DENOMINATOR / HEIGHT_SQUARED_INTEGRAL_DENOMINATOR

const referenceInput = referenceLightingInput()
/**
 * The sun's height at the reference place and instant, computed rather than rounded to 45 degrees.
 */
const REFERENCE_SUN_ALTITUDE = solarPosition({
  latitude: referenceInput.latLong.latitude,
  longitude: referenceInput.latLong.longitude,
  observedAt: referenceInput.observedAt,
  utcOffsetMinutes: referenceInput.utcOffsetMinutes,
}).altitude

/**
 * How many times brighter the clear horizon toward the reference sun is than the horizon away from
 * it.
 */
const SUNWARD_HORIZON_RATIO = 3
/**
 * Strength of the dome's brightening toward the sun's azimuth. On the horizon under the reference
 * sun, (1 + gain cos h) / (1 - gain cos h) equals SUNWARD_HORIZON_RATIO.
 */
export const SUNWARD_GAIN =
  (SUNWARD_HORIZON_RATIO - 1) / ((SUNWARD_HORIZON_RATIO + 1) * Math.cos(REFERENCE_SUN_ALTITUDE))

/** Fixed-point steps of the white point solve; it settles to double precision well before this. */
const WHITE_POINT_ITERATION_COUNT = 50

function withLuminance(color: LinearRgb, luminance: number): LinearRgb {
  return scaleLinearRgb(color, luminance / linearLuminance(color))
}

function rawSunTint(sunAltitude: number): LinearRgb {
  return mixLinearRgb(HORIZON_SUN_TINT, ZENITH_SUN_TINT, clampToUnitInterval(Math.sin(sunAltitude)))
}

function rawDomeTint(viewHeight: number): LinearRgb {
  return mixLinearRgb(HORIZON_DOME_TINT, ZENITH_DOME_TINT, clampToUnitInterval(viewHeight))
}

/**
 * The ratio of direct to diffuse light on a level card: 5 to 1 at 45 degrees, 1 to 1 at the horizon
 * and below.
 */
export function directToDiffuseRatio(sunAltitude: number): number {
  return (
    1 +
    (RATIO_RISE_AT_STATED_HEIGHT * Math.max(0, Math.sin(sunAltitude))) /
      Math.sin(RATIO_STATED_HEIGHT)
  )
}

/**
 * The white point, at luminance 1. Divided by it, sun plus sky on the reference card is neutral.
 * With the sun and sky tints S and K and their level ratio R, the card's undivided color is
 * S t + K for the sun share t = R lum(K / W) / lum(S / W), and W is that color itself, so t is
 * a fixed point, found by iteration.
 */
function solveWhitePoint(): LinearRgb {
  const sunTint = rawSunTint(REFERENCE_SUN_ALTITUDE)
  const skyTint = rawDomeTint(COSINE_WEIGHTED_MEAN_HEIGHT)
  const levelRatio = directToDiffuseRatio(REFERENCE_SUN_ALTITUDE)
  let sunShare = levelRatio
  for (let step = 0; step < WHITE_POINT_ITERATION_COUNT; step += 1) {
    const white = addLinearRgb(scaleLinearRgb(sunTint, sunShare), skyTint)
    sunShare =
      (levelRatio * linearLuminance(divideLinearRgb(skyTint, white))) /
      linearLuminance(divideLinearRgb(sunTint, white))
  }
  return withLuminance(addLinearRgb(scaleLinearRgb(sunTint, sunShare), skyTint), 1)
}

const WHITE_POINT = solveWhitePoint()

/** A raw tint divided by the white point, then flattened toward grey under cloud. */
function whiteBalanced(color: LinearRgb, cloudCover: number): LinearRgb {
  const balanced = divideLinearRgb(color, WHITE_POINT)
  return mixLinearRgb(balanced, greyOf(balanced), clampToUnitInterval(cloudCover))
}

/**
 * The sun level overhead under a clear sky. The reference wall's level is linear in it, so it
 * was solved once with the scale at 1 (and the night floor set aside, which the reference sky
 * clears): under the Kasten and Young fade the wall then returns a luminance of about 0.192423,
 * and the sunlit white level 2.099829 over it gives about 10.9126, the frozen value. At the
 * reference height the sun's level is then 10.0056.
 */
const SUN_SCALE = 10.9126

/**
 * The fraction of the sun's level its height leaves: the clear-sky attenuation
 * exp(-SUN_OPTICAL_DEPTH (m(h) - m(zenith))) for the Kasten and Young relative air mass m, so
 * exactly 1 at the zenith. It falls smoothly as the sun nears the horizon; just above it the
 * level is about 0.005, under 0.05 percent of the reference level, a small step to the 0 it keeps
 * at and below the horizon. The height is in radians, from minus to plus a quarter turn.
 */
function sunFade(sunAltitude: number): number {
  if (sunAltitude <= 0) return 0
  return Math.exp(-SUN_OPTICAL_DEPTH * (relativeAirMass(sunAltitude) - ZENITH_AIR_MASS))
}

/**
 * Fraction of the direct beam that reaches the ground through cloud cover, on a
 * Kasten-Czeplak-style convex curve: near 1 until cloud cover thickens, then 0 at full overcast.
 */
function directBeamCloudTransmission(cloudCover: number): number {
  return clampToUnitInterval(1 - clampToUnitInterval(cloudCover) ** DIRECT_BEAM_CLOUD_EXPONENT)
}

/**
 * The direct sun's level, the engine's light intensity: the sun scale times the fade and the cloud
 * transmission.
 */
export function sunLevelAt(sunAltitude: number, cloudCover: number): number {
  return SUN_SCALE * sunFade(sunAltitude) * directBeamCloudTransmission(cloudCover)
}

/** The direct sun's color: the raw tint divided by the white point, at luminance 1. */
export function sunColorAt(sunAltitude: number, cloudCover: number): LinearRgb {
  return withLuminance(whiteBalanced(rawSunTint(sunAltitude), cloudCover), 1)
}

/**
 * The sky level on the level card: the clear direct level over the ratio, floored at night, dimmed
 * by cloud.
 */
export function diffuseLevelAt(sunAltitude: number, cloudCover: number): number {
  const clearDirect = (sunLevelAt(sunAltitude, 0) * Math.max(0, Math.sin(sunAltitude))) / Math.PI
  const clearDiffuse = Math.max(
    clearDirect / directToDiffuseRatio(sunAltitude),
    NIGHT_DIFFUSE_LEVEL,
  )
  return clearDiffuse * (1 - OVERCAST_DIFFUSE_DIMMING * clampToUnitInterval(cloudCover))
}

/**
 * The upper dome's radiance at the horizon and at the zenith; it blends linearly on the view
 * height.
 */
export type UpperDomeTints = { horizon: LinearRgb; zenith: LinearRgb }

/**
 * The upper dome's end tints, scaled so the dome's light on the level card is the diffuse level.
 */
export function upperDomeTints(sunAltitude: number, cloudCover: number): UpperDomeTints {
  const meanTint = whiteBalanced(rawDomeTint(COSINE_WEIGHTED_MEAN_HEIGHT), cloudCover)
  const domeScale = diffuseLevelAt(sunAltitude, cloudCover) / linearLuminance(meanTint)
  return {
    horizon: scaleLinearRgb(whiteBalanced(HORIZON_DOME_TINT, cloudCover), domeScale),
    zenith: scaleLinearRgb(whiteBalanced(ZENITH_DOME_TINT, cloudCover), domeScale),
  }
}

/** What a white level card returns from the sun and from the sky, each as irradiance over pi. */
export type LevelCardLight = { sun: LinearRgb; sky: LinearRgb }

/** The light on a level white card, in closed form over the upper dome. */
export function levelCardLight(sunAltitude: number, cloudCover: number): LevelCardLight {
  const sunOnCard =
    (sunLevelAt(sunAltitude, cloudCover) * Math.max(0, Math.sin(sunAltitude))) / Math.PI
  const dome = upperDomeTints(sunAltitude, cloudCover)
  return {
    sun: scaleLinearRgb(sunColorAt(sunAltitude, cloudCover), sunOnCard),
    sky: mixLinearRgb(dome.horizon, dome.zenith, COSINE_WEIGHTED_MEAN_HEIGHT),
  }
}

export type DaylightCalibration = {
  whitePoint: LinearRgb
  sunScale: number
  sunlitWhiteLevel: number
}

export const DAYLIGHT_CALIBRATION: DaylightCalibration = {
  whitePoint: WHITE_POINT,
  sunScale: SUN_SCALE,
  sunlitWhiteLevel: agxNeutralInverse(WHITE_CODE_FLOOR / DISPLAY_CODE_MAX),
}

const referenceCard = levelCardLight(REFERENCE_SUN_ALTITUDE, 0)
/**
 * The photometric anchor: the lux that one unit of irradiance stands for, fixed by the reference
 * card.
 */
export const LUX_PER_UNIT_IRRADIANCE =
  REFERENCE_HORIZONTAL_ILLUMINANCE_LUX /
  (Math.PI * linearLuminance(addLinearRgb(referenceCard.sun, referenceCard.sky)))

core/units/format-length.ts.source:
import type { ImperialForm, MetricForm, Millimeters } from './length-units'
import {
  INCHES_PER_FOOT,
  millimetersToCentimeters,
  millimetersToFeet,
  millimetersToInches,
  millimetersToMeters,
} from './length-units'
import type { DecimalPrecision, DisplayPrecision } from './precision'
import { roundToDecimalPlaces, roundToNearestFraction } from './precision'

// Only feet-and-inches accepts fractional precision; every other form is decimal-only.
// Encoding that in the union (via DecimalPrecision) makes an invalid fraction/form
// pairing a compile error.
type ImperialDecimalForm = Exclude<ImperialForm, 'feet-and-inches'>

// Arms are ordered to match the dispatch order in formatLength: metric first, then the
// feet-and-inches arm, then the remaining imperial decimal forms.
export type FormatLengthOptions =
  | { system: 'metric'; form: MetricForm; precision: DecimalPrecision }
  | { system: 'imperial'; form: 'feet-and-inches'; precision: DisplayPrecision }
  | { system: 'imperial'; form: ImperialDecimalForm; precision: DecimalPrecision }

// en-US unit symbols with a leading space so the value and symbol read as "2.03 m".
const METRIC_SYMBOL: Record<MetricForm, string> = {
  meters: ' m',
  centimeters: ' cm',
  millimeters: ' mm',
}

const METRIC_CONVERSION: Record<MetricForm, (mm: Millimeters) => number> = {
  meters: millimetersToMeters,
  centimeters: millimetersToCentimeters,
  // The canonical value is already in millimeters, so this form needs no conversion.
  millimeters: (mm) => mm,
}

// Imperial decimal symbols abut the value with no leading space, matching trade
// notation: 6.667' and 80".
const FOOT_SYMBOL = "'"
const INCH_SYMBOL = '"'

function formatDecimal(value: number, places: number, suffix: string): string {
  // toFixed alone rounds half to even at the boundary; round first so the displayed
  // digits match the project's half-away-from-zero rounding helper.
  const rounded = roundToDecimalPlaces(value, places)
  return `${rounded.toFixed(places)}${suffix}`
}

// Splits a length into its sign, whole feet, and inch remainder. Math.abs makes
// totalInches the magnitude, so feet and remainderInches stay >= 0; formatting the
// magnitude and reapplying the sign later keeps the foot/inch split and the rounding
// carry from ever having to reason about a negative value. That invariant also lets the
// inch-part guards test "the part is non-empty" without tracing the sign.
function splitInchesFromMillimeters(mm: Millimeters): {
  isNegative: boolean
  feet: number
  remainderInches: number
} {
  const isNegative = mm < 0
  const totalInches = Math.abs(millimetersToInches(mm))
  const feet = Math.floor(totalInches / INCHES_PER_FOOT)
  const remainderInches = totalInches - feet * INCHES_PER_FOOT
  return { isNegative, feet, remainderInches }
}

// Rounding the inch remainder can reach a full foot (e.g. 11.97" rounds to 12"); carry
// it up so the result reads 1'0" rather than 0'12".
function carryFullFoot(feet: number, inches: number): { feet: number; inches: number } {
  if (inches >= INCHES_PER_FOOT) {
    return { feet: feet + 1, inches: 0 }
  }
  return { feet, inches }
}

// Joins the foot part and the already-formatted inch part into a reading, falling back
// to 0" when the length is zero. The sign is applied only for a non-zero magnitude so
// -0 mm does not print as -0".
function assembleFeetAndInches(isNegative: boolean, feet: number, inchPart: string): string {
  const feetPart = feet > 0 ? `${feet}${FOOT_SYMBOL}` : ''
  const combined = feetPart + inchPart
  const body = combined.length > 0 ? combined : `0${INCH_SYMBOL}`
  return isNegative && combined.length > 0 ? `-${body}` : body
}

function formatFeetAndInchesDecimal(mm: Millimeters, places: number): string {
  const { isNegative, feet, remainderInches } = splitInchesFromMillimeters(mm)
  const carried = carryFullFoot(feet, roundToDecimalPlaces(remainderInches, places))
  const inchPart = carried.inches !== 0 ? `${carried.inches.toFixed(places)}${INCH_SYMBOL}` : ''
  return assembleFeetAndInches(isNegative, carried.feet, inchPart)
}

// Builds the inch portion of a fractional reading: '' when the inch part is empty, a
// bare whole-inch part when the fraction reduces away, a bare fraction when there are
// no whole inches, and "8 1/2"" when both are present.
function formatFractionalInchPart(
  wholeInches: number,
  numerator: number,
  denominator: number,
): string {
  if (wholeInches === 0 && numerator === 0) {
    return ''
  }
  if (numerator === 0) {
    return `${wholeInches}${INCH_SYMBOL}`
  }
  const wholePrefix = wholeInches > 0 ? `${wholeInches} ` : ''
  return `${wholePrefix}${numerator}/${denominator}${INCH_SYMBOL}`
}

function formatFeetAndInchesFraction(mm: Millimeters, denominator: number): string {
  // The denominator originates in user-controlled UnitPreferences, so guard it at this
  // consumer boundary before handing it to roundToNearestFraction (which assumes a
  // positive integer). The message names "positive integer" so the cause is clear.
  if (!Number.isInteger(denominator) || denominator <= 0) {
    throw new Error(`fraction denominator must be a positive integer, got ${denominator}`)
  }
  const { isNegative, feet, remainderInches } = splitInchesFromMillimeters(mm)
  const fraction = roundToNearestFraction(remainderInches, denominator)
  const carried = carryFullFoot(feet, fraction.whole)
  const inchPart = formatFractionalInchPart(
    carried.inches,
    fraction.numerator,
    fraction.denominator,
  )
  return assembleFeetAndInches(isNegative, carried.feet, inchPart)
}

function formatFeetAndInches(mm: Millimeters, precision: DisplayPrecision): string {
  return precision.kind === 'fraction'
    ? formatFeetAndInchesFraction(mm, precision.denominator)
    : formatFeetAndInchesDecimal(mm, precision.places)
}

export function formatLength(mm: Millimeters, options: FormatLengthOptions): string {
  if (options.system === 'metric') {
    return formatDecimal(
      METRIC_CONVERSION[options.form](mm),
      options.precision.places,
      METRIC_SYMBOL[options.form],
    )
  }
  if (options.form === 'decimal-feet') {
    return formatDecimal(millimetersToFeet(mm), options.precision.places, FOOT_SYMBOL)
  }
  if (options.form === 'decimal-inches') {
    return formatDecimal(millimetersToInches(mm), options.precision.places, INCH_SYMBOL)
  }
  // feet-and-inches: precision is the full DisplayPrecision (decimal or fraction).
  return formatFeetAndInches(mm, options.precision)
}

