import type { Color } from './color'
import { COLOR_ACCURACY_TOLERANCE, withinColorTolerance } from './color-accuracy'
import { perceptualDistance } from './operations'

/**
 * How a sampled color reads against a reference swatch, in the same terms a
 * person describes a repaint: overall closeness, plus which direction it
 * drifted on the two axes a human eye actually notices. This is what lets a
 * readout say a sample "reads as painted" for a shift the color-accuracy gate
 * (`withinColorTolerance`, `COLOR_ACCURACY_TOLERANCE`) would already accept,
 * instead of surfacing a bare distance number.
 */
export interface PerceivedShift {
  readonly distance: number
  readonly faithful: boolean
  readonly lightness: 'lighter' | 'darker' | 'unchanged'
  readonly warmth: 'warmer' | 'cooler' | 'unchanged'
}

/** The number of OKLab axes (L, a, b) `perceptualDistance` combines. */
const OKLAB_AXIS_COUNT = 3

/**
 * The per-axis share of the color-accuracy gate's isotropic tolerance ball.
 *
 * `COLOR_ACCURACY_TOLERANCE` bounds the total OKLab `perceptualDistance`,
 * which combines all three axes (L, a, b) as a Euclidean norm. A shift spread
 * evenly across all three axes therefore reaches the tolerance boundary when
 * each axis sits at `COLOR_ACCURACY_TOLERANCE / Math.sqrt(3)`: three such
 * per-axis deltas combine via `Math.hypot` to exactly `COLOR_ACCURACY_TOLERANCE`.
 * This is a derived constant, not a tuned one, so classifying a single axis'
 * delta against it stays consistent with the gate's own pass/fail boundary.
 */
export const PERCEIVED_AXIS_THRESHOLD = COLOR_ACCURACY_TOLERANCE / Math.sqrt(OKLAB_AXIS_COUNT)

/**
 * Classify a signed delta against the axis threshold, in the given
 * direction labels for a positive and a negative delta. Both `lightness`
 * and `warmth` are the same symmetric three-way comparison, just against
 * different OKLab components and direction words.
 */
function classifyAxis<Positive extends string, Negative extends string>(
  delta: number,
  positiveDirection: Positive,
  negativeDirection: Negative,
): Positive | Negative | 'unchanged' {
  if (delta > PERCEIVED_AXIS_THRESHOLD) {
    return positiveDirection
  }
  if (delta < -PERCEIVED_AXIS_THRESHOLD) {
    return negativeDirection
  }
  return 'unchanged'
}

/**
 * Describe how a sampled color reads against a reference swatch: the overall
 * perceptual distance, whether that distance is within the color-accuracy
 * gate's tolerance, and which way the sample drifted on lightness (OKLab L)
 * and warmth (OKLab b, the blue-yellow axis). A drift under the per-axis
 * threshold on a given axis reads as `'unchanged'` on that axis even when the
 * two colors are not byte-identical, matching how a person would describe
 * the swatch: close enough that they would not call it lighter, darker,
 * warmer, or cooler.
 */
export function describePerceivedShift(sample: Color, reference: Color): PerceivedShift {
  return {
    distance: perceptualDistance(sample, reference),
    // Delegates to the color-accuracy gate's own predicate rather than
    // re-deriving the `<=` comparison here: `faithful` means "the gate would
    // accept this render", so the two must stay structurally in agreement
    // even if the gate's tolerance or comparison rule changes later.
    faithful: withinColorTolerance(sample, reference),
    lightness: classifyAxis(sample.oklab.L - reference.oklab.L, 'lighter', 'darker'),
    warmth: classifyAxis(sample.oklab.b - reference.oklab.b, 'warmer', 'cooler'),
  }
}

/**
 * Phrases a `PerceivedShift` as the short label a readout prints beside a
 * sampled swatch. The axis values are already the exact words the phrase
 * needs (`'lighter'`, `'darker'`, `'warmer'`, `'cooler'`), so this reads them
 * straight off the shift instead of re-deriving them with a lookup table.
 */
export function perceivedShiftLabel(shift: PerceivedShift): string {
  if (shift.faithful) {
    return 'Reads as painted'
  }
  const movedAxes = [shift.lightness, shift.warmth].filter((axis) => axis !== 'unchanged')
  if (movedAxes.length === 0) {
    // Neither lightness nor warmth crossed its threshold, yet the shift is
    // not faithful: the drift lives entirely on the OKLab a axis (green to
    // pink), which has no phrase of its own. Say something honest rather
    // than claim the paint reads as chosen.
    return 'Reads slightly different'
  }
  return `Reads ${movedAxes.join(' and ')}`
}

core/scene/plan-to-world.ts.source:
import type { Point } from '../model/types'
import type { Vector3 } from './vector3'

/**
 * Maps a plan point at vertical `height` into Three.js world space
 * (right-handed, Y-up): plan x to world X, plan north (+y) to world -Z, height to
 * world Y. This is the single source of the axis mapping; every three-dimensional
 * consumer goes through it (foundation spec section 2.1).
 *
 * The plan frame is y-up: `worldToScreen` in `editor/plan/viewport.ts` negates
 * plan y, so larger plan y is higher on screen (north), matching the `Point`
 * type's y-increases-upward convention. North must therefore map to world -Z, not
 * +Z. The negation keeps this map orientation-preserving (a proper rotation onto
 * the ground plane), so the three-dimensional scene is not a mirror image of the
 * plan, and it agrees with the camera-preset axis map (plan north is world -Z).
 *
 * @param point Plan point, in millimeters (see the `Point` type).
 * @param height Elevation above the finished-floor datum, in millimeters
 *   (the same millimeter unit policy noted on `Vector3`).
 * @see worldToPlan for the ground-plane inverse in this file.
 */
export function planToWorld(point: Point, height: number): Vector3 {
  // `0 - point.y` rather than `-point.y`: a point on the floor line (plan y = 0)
  // then maps to a clean world z of +0 instead of the negative zero `-point.y`
  // yields, so floor-line world coordinates compare equal to a plain 0.
  return { x: point.x, y: height, z: 0 - point.y }
}

/**
 * Ground-plane inverse of `planToWorld`: recovers the plan point from a world
 * position, dropping its height (world Y). World X returns to plan x and world -Z
 * returns to plan north (+y). This shares the single axis mapping documented on
 * `planToWorld` (foundation spec section 2.1).
 *
 * @param world Three.js world position (right-handed, Y-up), in millimeters.
 */
export function worldToPlan(world: Vector3): Point {
  // `0 - world.z` rather than `-world.z`: mirrors the `+0` convention in
  // `planToWorld`, so a world z of +0 round-trips back to a plan y of 0 instead
  // of negative zero.
  return { x: world.x, y: 0 - world.z }
}

core/scene/front-direction.ts.source:
import { openingKindOfType } from '../registries/opening-kind'
import { exteriorWalls } from './exterior-walls'
import type { OpeningSceneNode, SceneGraph } from './scene-graph'

/** A unit direction in the y-up plan frame. */
export type PlanDirection = { readonly x: number; readonly y: number }

/** Plan-down, the direction a front takes when no exterior door says otherwise. */
export const PLAN_DOWN: PlanDirection = { x: 0, y: -1 }

export type FrontDirectionInput = Pick<SceneGraph, 'walls' | 'rooms' | 'openings'>

/** An exterior door and the outward normal of the wall that hosts it. */
interface FrontCandidate {
  readonly opening: OpeningSceneNode
  readonly outward: PlanDirection
}

function dotWithPlanDown(direction: PlanDirection): number {
  return direction.x * PLAN_DOWN.x + direction.y * PLAN_DOWN.y
}

/**
 * Two fronts whose dot products with plan-down differ by no more than this are
 * equally near. Outward normals are computed from wall endpoints, so
 * mirror-image walls can differ in the last bits; this is far below any
 * difference a drawn plan can mean.
 */
const DIRECTION_TIE_TOLERANCE = 1e-9

/** True when `candidate` is a better front than `current`; see `frontDirection` for the rule. */
function beats(candidate: FrontCandidate, current: FrontCandidate): boolean {
  if (candidate.opening.width !== current.opening.width) {
    return candidate.opening.width > current.opening.width
  }
  const candidateDot = dotWithPlanDown(candidate.outward)
  const currentDot = dotWithPlanDown(current.outward)
  if (Math.abs(candidateDot - currentDot) > DIRECTION_TIE_TOLERANCE) {
    return candidateDot > currentDot
  }
  return candidate.opening.id < current.opening.id
}

/** The doors in exterior walls of one floor, each with its host wall's outward normal. */
function exteriorDoorsOnFloor(input: FrontDirectionInput, floorId: string): FrontCandidate[] {
  const openings = input.openings.filter((opening) => opening.floorId === floorId)
  const walls = exteriorWalls(
    input.walls.filter((wall) => wall.floorId === floorId),
    input.rooms.filter((room) => room.floorId === floorId),
    openings,
  )
  return walls.flatMap((wall) =>
    openings
      .filter((opening) => wall.openingIds.includes(opening.id))
      .filter((opening) => openingKindOfType(opening.type) === 'door')
      .map((opening) => ({ opening, outward: wall.outwardNormal })),
  )
}

/**
 * The plan direction the building faces: the outward normal of the wall that
 * hosts the widest exterior door. Equal widths prefer the direction nearer
 * plan-down (directions within a rounding tolerance are equally near), then
 * the opening id that sorts first as a string (so `opening:10` comes before
 * `opening:9`). With no exterior door it is plan-down.
 */
export function frontDirection(input: FrontDirectionInput): PlanDirection {
  const floorIds = [...new Set(input.walls.map((wall) => wall.floorId))]
  const candidates = floorIds.flatMap((floorId) => exteriorDoorsOnFloor(input, floorId))
  const best = candidates.reduce<FrontCandidate | undefined>(
    (current, candidate) =>
      current === undefined || beats(candidate, current) ? candidate : current,
    undefined,
  )
  return best === undefined ? PLAN_DOWN : best.outward
}

core/scene/walk-collision.ts.source:
import type { Point } from '../model/types'
import { openingKindOfType, openingTypeHasFill } from '../registries/opening-kind'
import { effectiveWallThickness } from './construction-profile'
import { planToWorld } from './plan-to-world'
import {
  WALL_NODE_PREFIX,
  type FurnitureSceneNode,
  type OpeningSceneNode,
  type WallSceneNode,
} from './scene-graph'

/**
 * A point in the world horizontal plane (X, Z), in millimeters. Walk collision
 * runs entirely in this plane: the walker stands on the floor at a fixed eye
 * height, so only the horizontal axes can move into a wall.
 */
export interface PlanarPoint {
  x: number
  z: number
}

/** A wall as a collision segment in the world horizontal plane (X, Z). */
export interface WallSegment {
  start: PlanarPoint
  end: PlanarPoint
  /**
   * The solid width the segment stands for, in millimeters. The walker stands off
   * the centerline by `radius + thickness / 2`, so half the width widens the
   * standoff to clear the face. On a wall-derived segment this is the resolved
   * construction assembly total rather than the wall node's raw `thickness`
   * field, which is what the 3D wall builder extrudes and so what the walker
   * sees. Optional: a footprint-perimeter segment is the exact solid boundary and
   * omits it, keeping the plain `radius` standoff.
   */
  thickness?: number
}

/** The walls a walker is blocked by and the walker's radius, passed to advanceWalk. */
export interface WalkCollisionWorld {
  segments: readonly WallSegment[]
  radius: number
}

// Below this separation the push-out direction is taken from the wall's own
// normal rather than the (degenerate) vector from the wall to the walker.
const CONTACT_EPSILON_MM = 1e-6

/** The point on a finite segment nearest the given point, clamped to its ends. */
function closestPointOnSegment(point: PlanarPoint, segment: WallSegment): PlanarPoint {
  const spanX = segment.end.x - segment.start.x
  const spanZ = segment.end.z - segment.start.z
  const lengthSquared = spanX * spanX + spanZ * spanZ
  if (lengthSquared === 0) {
    return { x: segment.start.x, z: segment.start.z }
  }
  const projection =
    ((point.x - segment.start.x) * spanX + (point.z - segment.start.z) * spanZ) / lengthSquared
  const clamped = Math.max(0, Math.min(1, projection))
  return { x: segment.start.x + clamped * spanX, z: segment.start.z + clamped * spanZ }
}

/** The wall's unit normal in the horizontal plane, used when the walker is on it. */
function segmentNormal(segment: WallSegment): PlanarPoint {
  const spanX = segment.end.x - segment.start.x
  const spanZ = segment.end.z - segment.start.z
  const length = Math.hypot(spanX, spanZ)
  if (length === 0) {
    return { x: 1, z: 0 }
  }
  return { x: -spanZ / length, z: spanX / length }
}

/**
 * Pushes a single point out of one wall segment. The effective clearance is
 * `radius + thickness / 2`, so the walker clears the wall face rather than its
 * centerline; a segment without `thickness` keeps the plain `radius` standoff.
 * If the point is within that clearance it is moved to exactly the clearance
 * distance along the outward direction; the along-wall component is left
 * untouched, so a glancing move slides instead of stopping. A point already
 * clear of the wall is returned unchanged.
 */
function pushOutOfSegment(point: PlanarPoint, segment: WallSegment, radius: number): PlanarPoint {
  const clearance = radius + (segment.thickness ?? 0) / 2
  const closest = closestPointOnSegment(point, segment)
  const outX = point.x - closest.x
  const outZ = point.z - closest.z
  const distance = Math.hypot(outX, outZ)
  if (distance >= clearance) {
    return point
  }
  const direction =
    distance > CONTACT_EPSILON_MM
      ? { x: outX / distance, z: outZ / distance }
      : segmentNormal(segment)
  return { x: closest.x + direction.x * clearance, z: closest.z + direction.z * clearance }
}

/**
 * Resolves a proposed walker position against every wall segment, modeling the
 * walker as a circle of the given radius (a capsule seen from above). Each
 * penetrating segment pushes the position out to the radius along that wall's
 * normal, which clamps a head-on move and lets an angled move slide along the
 * wall. Segments are resolved in sequence so a later wall corrects a position an
 * earlier wall left inside it.
 */
export function resolveWalkCollision(
  position: PlanarPoint,
  segments: readonly WallSegment[],
  radius: number,
): PlanarPoint {
  let resolved = position
  for (const segment of segments) {
    resolved = pushOutOfSegment(resolved, segment, radius)
  }
  return resolved
}

/**
 * Sweeps a walker from `from` to `to`, resolving collision along the whole path
 * so a large per-frame move can never tunnel through a wall. The straight move
 * is sub-stepped into increments no larger than the walker radius, and each
 * increment is resolved with resolveWalkCollision against the running position,
 * so a wall lying between the two endpoints always stops the walker on the near
 * side at the radius standoff. When the move is already within one radius it
 * reduces to a single resolveWalkCollision(to). Returns the final resolved
 * position; never mutates its inputs. See ADR-0135 for why the sweep
 * sub-steps rather than solving the contact analytically.
 */
export function sweepWalkCollision(
  from: PlanarPoint,
  to: PlanarPoint,
  world: WalkCollisionWorld,
): PlanarPoint {
  const { segments, radius } = world
  const spanX = to.x - from.x
  const spanZ = to.z - from.z
  const distance = Math.hypot(spanX, spanZ)
  const steps = radius > 0 ? Math.max(1, Math.ceil(distance / radius)) : 1
  const incrementX = spanX / steps
  const incrementZ = spanZ / steps
  let resolved = from
  for (let step = 1; step <= steps; step += 1) {
    const advanced = { x: resolved.x + incrementX, z: resolved.z + incrementZ }
    resolved = resolveWalkCollision(advanced, segments, radius)
  }
  return resolved
}

/**
 * A plan point as a point in the world horizontal plane, dropping the height the
 * walker cannot move along. This goes through `planToWorld` so collision reads the
 * same axis map the renderer draws with: plan x to world X, plan north (+y) to
 * world -Z. See ADR-0139; mapping plan y to +Z instead would put the collision
 * field at the building's reflection across world z = 0.
 */
function planPointToPlanar(point: Point): PlanarPoint {
  const world = planToWorld(point, 0)
  return { x: world.x, z: world.z }
}

/**
 * The wall centerline as a world-plane segment: plan x to X, plan north to -Z. The
 * standoff thickness is the resolved assembly total, the same figure the 3D wall
 * builder extrudes its footprint from, so the walker clears the face it can see
 * rather than a thinner raw thickness the renderer never draws.
 */
function wallToSegment(wall: WallSceneNode): WallSegment {
  return {
    start: planPointToPlanar(wall.start),
    end: planPointToPlanar(wall.end),
    thickness: effectiveWallThickness(wall),
  }
}

/** A range of the parameter t in [0, 1] that walks a segment from start to end. */
interface SpanInterval {
  start: number
  end: number
}

function clampUnit(value: number): number {
  return Math.max(0, Math.min(1, value))
}

/** The position of a world point as a parameter t along the segment. */
function wallParam(segment: WallSegment, point: PlanarPoint): number {
  const spanX = segment.end.x - segment.start.x
  const spanZ = segment.end.z - segment.start.z
  const lengthSquared = spanX * spanX + spanZ * spanZ
  if (lengthSquared === 0) {
    return 0
  }
  return ((point.x - segment.start.x) * spanX + (point.z - segment.start.z) * spanZ) / lengthSquared
}

/** The world point at parameter t along the segment. */
function pointAtParam(segment: WallSegment, t: number): PlanarPoint {
  return {
    x: segment.start.x + (segment.end.x - segment.start.x) * t,
    z: segment.start.z + (segment.end.z - segment.start.z) * t,
  }
}

/** The span an opening covers on its host wall, as a t interval along the wall. */
function openingSpan(segment: WallSegment, opening: OpeningSceneNode): SpanInterval {
  const half = opening.width / 2
  const spanStart = planPointToPlanar({
    x: opening.center.x - opening.along.x * half,
    y: opening.center.y - opening.along.y * half,
  })
  const spanEnd = planPointToPlanar({
    x: opening.center.x + opening.along.x * half,
    y: opening.center.y + opening.along.y * half,
  })
  const startParam = wallParam(segment, spanStart)
  const endParam = wallParam(segment, spanEnd)
  return { start: Math.min(startParam, endParam), end: Math.max(startParam, endParam) }
}

/** The solid stretches of a wall once the given gap spans are cut out of it. */
function solidSubsegments(segment: WallSegment, gaps: readonly SpanInterval[]): WallSegment[] {
  const ordered = [...gaps].sort((first, second) => first.start - second.start)
  const result: WallSegment[] = []
  let cursor = 0
  for (const gap of ordered) {
    const gapStart = clampUnit(gap.start)
    if (gapStart > cursor) {
      result.push({
        ...segment,
        start: pointAtParam(segment, cursor),
        end: pointAtParam(segment, gapStart),
      })
    }
    cursor = Math.max(cursor, clampUnit(gap.end))
  }
  if (cursor < 1) {
    result.push({ ...segment, start: pointAtParam(segment, cursor), end: pointAtParam(segment, 1) })
  }
  return result
}

/** Whether the wall hosts the opening, matching the wall node's prefixed id. */
function hostsOpening(wall: WallSceneNode, opening: OpeningSceneNode): boolean {
  return opening.hostWallId !== undefined && wall.id === `${WALL_NODE_PREFIX}${opening.hostWallId}`
}

function splitWall(
  wall: WallSceneNode,
  openings: readonly OpeningSceneNode[],
  passableOpeningIds: ReadonlySet<string>,
): WallSegment[] {
  const segment = wallToSegment(wall)
  const gaps = openings
    .filter((opening) => passableOpeningIds.has(opening.id) && hostsOpening(wall, opening))
    .map((opening) => openingSpan(segment, opening))
  return gaps.length === 0 ? [segment] : solidSubsegments(segment, gaps)
}

/**
 * Builds the collision segments a walker is blocked by on the active floor. Each
 * wall contributes its centerline. Only an opening named in `passableOpeningIds`
 * cuts a gap in its host wall; every other opening leaves the wall solid, so the
 * walker cannot pass through it. This function does not decide which openings
 * qualify. {@link passableDoorIds} builds that set, and {@link isWalkableOpening}
 * carries the rule, which is not a plain open-or-shut test.
 */
export function wallSegmentsForWalk(
  walls: readonly WallSceneNode[],
  openings: readonly OpeningSceneNode[],
  passableOpeningIds: ReadonlySet<string> = new Set(),
): WallSegment[] {
  return walls.flatMap((wall) => splitWall(wall, openings, passableOpeningIds))
}

/**
 * Whether the walker can step through this opening right now. Only a door is ever
 * walkable, since you cannot walk through a window, and an unknown or non-opening
 * type is not a door. The door check has to come first: it is what keeps a window
 * that happens to carry no fill body out of the leafless case below. A door with a
 * leaf hung in it has to be opened first, so it has to appear in `openIds`. A
 * leafless door, such as a cased opening, is a bare hole in the wall with nothing
 * to open, so it passes regardless of the open state.
 */
function isWalkableOpening(opening: OpeningSceneNode, openIds: ReadonlySet<string>): boolean {
  if (openingKindOfType(opening.type) !== 'door') {
    return false
  }
  return !openingTypeHasFill(opening.type) || openIds.has(opening.id)
}

/**
 * Narrows a set of openings to the ones the walker can pass through, given the ids
 * currently open. Open doors and leafless doorways qualify; shut doors with a leaf,
 * every window, and unknown types do not. See {@link isWalkableOpening} for the
 * per-opening rule. The result feeds `wallSegmentsForWalk` as its passable set.
 */
export function passableDoorIds(
  openings: readonly OpeningSceneNode[],
  openIds: ReadonlySet<string>,
): Set<string> {
  const passable = new Set<string>()
  for (const opening of openings) {
    if (isWalkableOpening(opening, openIds)) {
      passable.add(opening.id)
    }
  }
  return passable
}

/** The four perimeter segments of a footprint, traced as a closed loop. */
function footprintSegments(corners: FurnitureSceneNode['footprintCorners']): WallSegment[] {
  const [first, second, third, fourth] = corners
  return [
    { start: planPointToPlanar(first), end: planPointToPlanar(second) },
    { start: planPointToPlanar(second), end: planPointToPlanar(third) },
    { start: planPointToPlanar(third), end: planPointToPlanar(fourth) },
    { start: planPointToPlanar(fourth), end: planPointToPlanar(first) },
  ]
}

/**
 * Builds the collision segments a walker is blocked by from furniture footprints.
 * Each piece contributes the four perimeter segments of its footprint as a closed
 * loop, so the walker cannot step into a piece of furniture from any side. Plan x
 * maps to world X and plan north to world -Z, matching the wall mapping.
 */
export function furnitureSegmentsForWalk(furniture: readonly FurnitureSceneNode[]): WallSegment[] {
  return furniture.flatMap((node) => footprintSegments(node.footprintCorners))
}

core/format/validate-document.ts.source:
import Ajv from 'ajv'
import type { ErrorObject, ValidateFunction } from 'ajv'

/** The outcome of validating a Document against a VFPF schema. */
export interface DocumentValidationResult {
  valid: boolean
  errors: ErrorObject[]
}

/** Validates a single Document and reports whether it conforms. */
export type DocumentValidator = (document: unknown) => DocumentValidationResult

/**
 * Compile a reusable validator for Vernacular Floor Plan Format Documents from a
 * generated CORE JSON Schema. The schema is supplied by the caller (the published
 * artifact under schema/<version>/), so core/ stays decoupled from where the file
 * lives. See docs/specs/2026-06-10-vernacular-floor-plan-format.md.
 */
export function createDocumentValidator(schema: object): DocumentValidator {
  // strict: false keeps Ajv from rejecting the generated CORE *schema* over
  // strict-mode schema-quality checks (for example metadata keywords kept
  // beside a $ref in the generated artifact). That schema is generated from the
  // model, guarded against drift, and exercised by the conformance suite, so
  // Document correctness is covered without Ajv's strict schema linting.
  // allErrors collects every violation so callers can report them all.
  const ajv = new Ajv({ allErrors: true, strict: false })
  const validate: ValidateFunction = ajv.compile(schema)
  return (document: unknown): DocumentValidationResult => {
    const valid = validate(document) === true
    return { valid, errors: valid ? [] : (validate.errors ?? []) }
  }
}

