import { formatHex, parseHex } from './hex'
import { okLabToSrgb, srgbToOkLab, type OkLab } from './oklab'

/**
 * A stored color in the three forms the design specification (section 7.4)
 * requires: OKLab (canonical, used for all math), sRGB hex (display and
 * serialization), and an optional originalSpec source identifier (for example a
 * descriptive source color code the user records). The triple is always
 * consistent because it is only built through the constructors below.
 */
export interface Color {
  oklab: OkLab
  srgbHex: string
  originalSpec?: string
}

export function colorFromHex(srgbHex: string, originalSpec?: string): Color {
  const oklab = srgbToOkLab(parseHex(srgbHex))
  const normalizedHex = formatHex(parseHex(srgbHex))
  return { oklab, srgbHex: normalizedHex, ...(originalSpec !== undefined ? { originalSpec } : {}) }
}

export function colorFromOkLab(oklab: OkLab, originalSpec?: string): Color {
  const srgbHex = formatHex(okLabToSrgb(oklab))
  return { oklab, srgbHex, ...(originalSpec !== undefined ? { originalSpec } : {}) }
}

/**
 * A color with a required accessible name (design spec 7.4: every chip carries
 * its name). It lives here, beside Color, so both the palette registry and the
 * project-local palette model import it from one home and the import direction
 * stays core/registries and core/model both depending on core/color.
 */
export interface NamedColor {
  name: string
  color: Color
}

core/model/asset-reference.ts.source:
export type AssetScope = `pack:${string}@${string}` | 'user' | 'project'

/** Content-addressed reference to an external asset. See ADR-0007. */
export interface AssetReference {
  scope: AssetScope
  contentHash: string
}

const SCOPE_SEPARATOR = '#'

export function formatAssetReference(reference: AssetReference): string {
  return `${reference.scope}${SCOPE_SEPARATOR}${reference.contentHash}`
}

export function parseAssetReference(serialized: string): AssetReference {
  // Split on the last separator: the content hash is the trailing segment and never
  // contains the separator, so this tolerates a separator appearing within the scope.
  const separatorIndex = serialized.lastIndexOf(SCOPE_SEPARATOR)
  if (separatorIndex === -1) {
    throw new Error(`Malformed asset reference: "${serialized}"`)
  }

  // The scope is validated structurally at the parse boundary; callers treat the
  // result as opaque until it is resolved through the asset registry.
  return {
    scope: serialized.slice(0, separatorIndex) as AssetScope,
    contentHash: serialized.slice(separatorIndex + 1),
  }
}

core/model/known-keys.ts.source:
// The table of known keys (ADR-0184): for each object type in the CORE schema,
// the keys the schema defines, what sits under each key, and which keys are
// optional. Generated by `pnpm schema:generate` into known-keys.json; this
// module is the typed reader over that file.

import knownKeysData from './known-keys.json' with { type: 'json' }

/** A tagged union: `tag` names the key that holds the tag, and each variant is a table entry. */
export interface KnownUnion {
  readonly kind: 'union'
  readonly tag: string // the key that holds the tag, for example 'kind'
  readonly variants: readonly { readonly value: string; readonly type: string }[]
}

export type KnownValue =
  | { readonly kind: 'leaf' } // a scalar, an enum, or an array of scalars
  | { readonly kind: 'opaque' } // the schema leaves the value open
  | { readonly kind: 'object'; readonly type: string }
  | KnownUnion
  | { readonly kind: 'array'; readonly item: KnownValue }
  | { readonly kind: 'map'; readonly value: KnownValue } // a collection the model owns

export interface KnownType {
  readonly keys: Readonly<Record<string, KnownValue>>
  readonly optional: readonly string[]
}
export type KnownKeyTable = Readonly<Record<string, KnownType>>

export const KNOWN_ROOT_TYPE = 'Project'

/** The type names the generated table holds, so a lookup by one of them is known to exist. */
type GeneratedTypeName = keyof typeof knownKeysData
type GeneratedKeyTable = KnownKeyTable & Readonly<Record<GeneratedTypeName, KnownType>>

export const KNOWN_KEYS: GeneratedKeyTable = knownKeysData as GeneratedKeyTable

/** Names of the types whose keys include `extensions`, the root included. */
export function typesWithExtensions(): GeneratedTypeName[]
export function typesWithExtensions(table: KnownKeyTable): string[]
export function typesWithExtensions(table: KnownKeyTable = KNOWN_KEYS): string[] {
  return Object.keys(table).filter((typeName) => table[typeName]?.keys.extensions !== undefined)
}

/** The table entry name of the variant whose tag value is `tagValue`, or undefined when no variant has it. */
export function variantTypeOf(union: KnownUnion, tagValue: unknown): string | undefined {
  return union.variants.find((variant) => variant.value === tagValue)?.type
}

core/registries/construction-profiles.ts.source:
import { createRegistry, type Registry, type RegistryEntry } from './registry'

/**
 * The primary structural system a wall assembly is built around, covering the
 * period structural vocabulary the old-house track needs (ADR-0044): platform and
 * balloon framing are the two historic light wood-framing systems (balloon framing
 * runs continuous studs the full height of the wall, platform framing stacks one
 * storey on the next), and solid masonry is a load-bearing brick or stone wall.
 * The union is open to further systems (post-and-beam, insulated concrete)
 * additively, the way `TrimProfileShape` is.
 */
export type ConstructionSystem = 'platform-frame' | 'balloon-frame' | 'solid-masonry'

/**
 * One material layer within a wall assembly: its `material` identifier and its
 * `thickness` across the wall in millimeters. Layers are ordered interior face to
 * exterior face (see {@link ConstructionProfile}). The material is a plain string
 * id (for example `plaster`, `wood-lath`, `stud-cavity`, `brick`) so a profile can
 * name a material the finish or paint registries do not yet carry; a later slice
 * can tighten it to a material-registry id without reshaping the layer.
 */
export interface ConstructionLayer {
  material: string
  /** Layer thickness across the wall, in millimeters. */
  thickness: number
}

/**
 * A wall construction profile: a named layered assembly that describes a historic
 * wall by its build-up rather than a single thickness (design spec 4.4,
 * `ConstructionProfileRegistry`; the old-house structural vocabulary of ADR-0044
 * and ADR-0046). It is the structural analog of a {@link
 * import('./trim-profiles').TrimProfile}: `system` classifies the assembly the way
 * a trim profile's `category` names its run, and `layers` carry the per-layer
 * thickness and material the 2D plan wall symbol and the (later) 3D wall builder
 * read, the way a trim profile's `shape` and stock dimensions resolve its section.
 * Layers run from interior face to exterior face; the assembly's total thickness is
 * the sum of the layer thicknesses (see `core/scene/construction-profile.ts`). A
 * new assembly is a new registry entry, not a model change.
 */
export interface ConstructionProfile extends RegistryEntry {
  system: ConstructionSystem
  /** Ordered material layers, interior face first. */
  layers: readonly ConstructionLayer[]
}

export const CONSTRUCTION_PROFILE_REGISTRY_VERSION = 1

/**
 * The bundled starter set of wall assemblies, at least one per named structural
 * system. Layer thicknesses are nominal millimeters for common North American
 * residential construction (design spec phase-4 wall construction profiles:
 * lath-and-plaster, drywall over studs, solid brick, solid stone); a registry pack
 * can override or extend them (design spec 4.6).
 */
export const builtinConstructionProfiles: Registry<ConstructionProfile> = createRegistry(
  CONSTRUCTION_PROFILE_REGISTRY_VERSION,
  [
    {
      // Drywall over a 2x4 platform-framed partition: the modern baseline at 4.5".
      id: 'platform-framed-drywall',
      system: 'platform-frame',
      layers: [
        { material: 'drywall', thickness: 13 },
        { material: 'stud-cavity', thickness: 89 },
        { material: 'drywall', thickness: 13 },
      ],
    },
    {
      // The classic Victorian wall: lath and plaster over continuous balloon-framed
      // studs, plastered on both faces.
      id: 'balloon-framed-lath-and-plaster',
      system: 'balloon-frame',
      layers: [
        { material: 'plaster', thickness: 16 },
        { material: 'wood-lath', thickness: 7 },
        { material: 'stud-cavity', thickness: 89 },
        { material: 'wood-lath', thickness: 7 },
        { material: 'plaster', thickness: 16 },
      ],
    },
    {
      // A double-wythe solid brick bearing wall, plastered on the interior face.
      id: 'solid-masonry-brick',
      system: 'solid-masonry',
      layers: [
        { material: 'plaster', thickness: 16 },
        { material: 'brick', thickness: 215 },
      ],
    },
    {
      // A solid rubble-stone bearing wall, plastered on the interior face.
      id: 'solid-masonry-stone',
      system: 'solid-masonry',
      layers: [
        { material: 'plaster', thickness: 16 },
        { material: 'stone', thickness: 300 },
      ],
    },
  ],
)

core/environment/solar-position.ts.source:
import { MINUTES_PER_DAY, type ObservationInstant } from './observation-time'

/**
 * Where and when the sun is observed. Latitude is in decimal degrees, north
 * positive; longitude is in decimal degrees, east positive. The observation
 * instant is civil (wall-clock) time at the site, and `utcOffsetMinutes` maps
 * it to UTC: local civil time = UTC + offset (for example -300 for UTC-5).
 */
export interface SolarPositionInput {
  /** Site latitude in decimal degrees, north positive. */
  readonly latitude: number
  /** Site longitude in decimal degrees, east positive. */
  readonly longitude: number
  /** The civil date and wall-clock minutes the scene is observed at. */
  readonly observedAt: ObservationInstant
  /** Offset from UTC in minutes; local civil time = UTC + this offset. */
  readonly utcOffsetMinutes: number
}

/**
 * The sun's direction in the local horizontal frame, in radians. Azimuth is
 * measured clockwise from true north (0 north, pi/2 east, pi south). Altitude
 * is the geometric angle above the horizon, with no atmospheric-refraction
 * correction, so it goes negative once the sun is below the horizon.
 */
export interface SolarAngles {
  /** Radians clockwise from true north. */
  readonly azimuth: number
  /** Geometric radians above the horizon; negative below it. */
  readonly altitude: number
}

const HALF_TURN_DEGREES = 180
const FULL_TURN_DEGREES = 2 * HALF_TURN_DEGREES
const FULL_TURN_RADIANS = 2 * Math.PI
const QUARTER_TURN_RADIANS = Math.PI / 2
/** Earth turns a full circle of longitude per civil day: four minutes per degree. */
const MINUTES_PER_DEGREE_OF_ROTATION = MINUTES_PER_DAY / FULL_TURN_DEGREES

function toRadians(degrees: number): number {
  return (degrees * Math.PI) / HALF_TURN_DEGREES
}

function toDegrees(radians: number): number {
  return (radians * HALF_TURN_DEGREES) / Math.PI
}

/** Guards `Math.acos` against floating-point drift just past the unit interval. */
function clampCosine(value: number): number {
  return Math.min(1, Math.max(-1, value))
}

/**
 * How close `|cos(zenith)|` may get to 1 before the sun counts as directly
 * overhead or underfoot, where the azimuth denominator `sin(zenith)` vanishes.
 */
const ZENITH_ALIGNMENT_COSINE_EPSILON = 1e-12

interface SunGeometry {
  readonly declinationDegrees: number
  readonly equationOfTimeMinutes: number
}

/* eslint-disable no-magic-numbers -- published astronomical formulas from the NOAA
   solar calculator (https://gml.noaa.gov/grad/solcalc/): the Gregorian-calendar
   Julian Day formula, the J2000 epoch and century length, the solar-orbit series
   (mean longitude, mean anomaly, eccentricity, equation of center), the obliquity
   series, and the equation-of-time terms; documented coefficients, not
   unexplained numbers. */

/** Julian Day for a `YYYY-MM-DD` civil date plus minutes since midnight UTC. */
function julianDay(date: string, utcMinutesSinceMidnight: number): number {
  const [yearField = 0, monthField = 0, day = 0] = date.split('-').map(Number)
  const monthShifted = monthField <= 2
  const year = monthShifted ? yearField - 1 : yearField
  const month = monthShifted ? monthField + 12 : monthField
  const century = Math.floor(year / 100)
  const gregorianCorrection = 2 - century + Math.floor(century / 4)
  return (
    Math.floor(365.25 * (year + 4716)) +
    Math.floor(30.6001 * (month + 1)) +
    day +
    utcMinutesSinceMidnight / MINUTES_PER_DAY +
    gregorianCorrection -
    1524.5
  )
}

function julianCenturiesSinceJ2000(day: number): number {
  return (day - 2451545) / 36525
}

/** Solar declination (degrees) and the equation of time (minutes) at a Julian-century epoch. */
function sunGeometry(t: number): SunGeometry {
  const meanLongitude = (280.46646 + t * (36000.76983 + t * 0.0003032)) % FULL_TURN_DEGREES
  const meanAnomaly = 357.52911 + t * (35999.05029 - 0.0001537 * t)
  const orbitEccentricity = 0.016708634 - t * (0.000042037 + 0.0000001267 * t)
  const equationOfCenter =
    Math.sin(toRadians(meanAnomaly)) * (1.914602 - t * (0.004817 + 0.000014 * t)) +
    Math.sin(toRadians(2 * meanAnomaly)) * (0.019993 - 0.000101 * t) +
    Math.sin(toRadians(3 * meanAnomaly)) * 0.000289
  const trueLongitude = meanLongitude + equationOfCenter
  const moonNodeLongitude = 125.04 - 1934.136 * t
  const apparentLongitude =
    trueLongitude - 0.00569 - 0.00478 * Math.sin(toRadians(moonNodeLongitude))
  const meanObliquity = 23 + (26 + (21.448 - t * (46.815 + t * (0.00059 - t * 0.001813))) / 60) / 60
  const obliquity = meanObliquity + 0.00256 * Math.cos(toRadians(moonNodeLongitude))
  const declinationDegrees = toDegrees(
    Math.asin(Math.sin(toRadians(obliquity)) * Math.sin(toRadians(apparentLongitude))),
  )
  const obliquityFactor = Math.tan(toRadians(obliquity / 2)) ** 2
  const equationOfTimeMinutes =
    4 *
    toDegrees(
      obliquityFactor * Math.sin(2 * toRadians(meanLongitude)) -
        2 * orbitEccentricity * Math.sin(toRadians(meanAnomaly)) +
        4 *
          orbitEccentricity *
          obliquityFactor *
          Math.sin(toRadians(meanAnomaly)) *
          Math.cos(2 * toRadians(meanLongitude)) -
        0.5 * obliquityFactor ** 2 * Math.sin(4 * toRadians(meanLongitude)) -
        1.25 * orbitEccentricity ** 2 * Math.sin(2 * toRadians(meanAnomaly)),
    )
  return { declinationDegrees, equationOfTimeMinutes }
}
/* eslint-enable no-magic-numbers */

/** Minutes past local solar midnight, folding the equation of time and longitude in. */
function trueSolarTimeMinutes(input: SolarPositionInput, equationOfTimeMinutes: number): number {
  const raw =
    input.observedAt.minutesSinceMidnight +
    equationOfTimeMinutes +
    MINUTES_PER_DEGREE_OF_ROTATION * input.longitude -
    input.utcOffsetMinutes
  return ((raw % MINUTES_PER_DAY) + MINUTES_PER_DAY) % MINUTES_PER_DAY
}

/** Hour angle in degrees: zero at local solar noon, negative before it. */
function hourAngleDegrees(trueSolarTime: number): number {
  const degrees = trueSolarTime / MINUTES_PER_DEGREE_OF_ROTATION - HALF_TURN_DEGREES
  return degrees < -HALF_TURN_DEGREES ? degrees + FULL_TURN_DEGREES : degrees
}

/**
 * Resolves the horizontal-frame angles from latitude, declination, and hour
 * angle (degrees). When the sun sits at the zenith or nadir the azimuth is
 * conventionally undefined; this returns 0 (true north) for stability instead
 * of dividing by the vanishing `sin(zenith)`.
 */
function horizontalAngles(
  latitudeDegrees: number,
  declinationDegrees: number,
  hourAngle: number,
): SolarAngles {
  const latitude = toRadians(latitudeDegrees)
  const declination = toRadians(declinationDegrees)
  const zenithCosine = clampCosine(
    Math.sin(latitude) * Math.sin(declination) +
      Math.cos(latitude) * Math.cos(declination) * Math.cos(toRadians(hourAngle)),
  )
  const zenith = Math.acos(zenithCosine)
  if (1 - Math.abs(zenithCosine) < ZENITH_ALIGNMENT_COSINE_EPSILON) {
    return { azimuth: 0, altitude: QUARTER_TURN_RADIANS - zenith }
  }
  const azimuthCosine =
    (Math.sin(latitude) * Math.cos(zenith) - Math.sin(declination)) /
    (Math.cos(latitude) * Math.sin(zenith))
  const azimuthFromSouth = Math.acos(clampCosine(azimuthCosine))
  const azimuth =
    hourAngle > 0
      ? (azimuthFromSouth + Math.PI) % FULL_TURN_RADIANS
      : (FULL_TURN_RADIANS + Math.PI - azimuthFromSouth) % FULL_TURN_RADIANS
  return { azimuth, altitude: QUARTER_TURN_RADIANS - zenith }
}

/**
 * Computes the sun's direction for a site and a civil observation instant using
 * the NOAA solar calculator formulas. Returns radians: azimuth clockwise from
 * true north, and geometric altitude above the horizon with no
 * atmospheric-refraction correction (negative once the sun has set). With the
 * sun effectively at the zenith or nadir the azimuth is undefined, and this
 * function returns 0 by convention.
 */
export function solarPosition(input: SolarPositionInput): SolarAngles {
  const utcMinutesSinceMidnight = input.observedAt.minutesSinceMidnight - input.utcOffsetMinutes
  const epoch = julianCenturiesSinceJ2000(julianDay(input.observedAt.date, utcMinutesSinceMidnight))
  const { declinationDegrees, equationOfTimeMinutes } = sunGeometry(epoch)
  const hourAngle = hourAngleDegrees(trueSolarTimeMinutes(input, equationOfTimeMinutes))
  return horizontalAngles(input.latitude, declinationDegrees, hourAngle)
}

core/environment/tone-response.ts.source:
import { clampToUnitInterval } from '../color/linear-rgb'
import { linearToSrgb } from '../color/oklab'

/*
 * The AgX tone curve of the pinned three.js build (0.184.0), transcribed from
 * agxToneMapping in node_modules/three/src/nodes/display/ToneMappingFunctions.js.
 * For a neutral input both AgX matrices keep the value, so only the log encoding,
 * the contrast polynomial, and the power 2.2 remain. The conversions to and from
 * Rec. 2020 keep a neutral value to four digits, so they are left out. core must not import three,
 * so the numbers live here as named constants.
 */

/** The darkest exposure value, in stops, that the curve distinguishes. */
const AGX_MIN_EV = -12.47393
/** The brightest exposure value, in stops, that the curve distinguishes. */
const AGX_MAX_EV = 4.026069
/** The floor applied before the logarithm so zero input stays finite. */
const AGX_LINEAR_FLOOR = 1e-10
/** The power that turns the polynomial output into linear light. */
const AGX_OUTPUT_POWER = 2.2

/* Coefficients of the sixth-degree contrast polynomial, named by the power each multiplies. */
const CONTRAST_DEGREE_6 = 15.5
const CONTRAST_DEGREE_5 = -40.14
const CONTRAST_DEGREE_4 = 31.96
const CONTRAST_DEGREE_3 = -6.868
const CONTRAST_DEGREE_2 = 0.4298
const CONTRAST_DEGREE_1 = 0.1191
const CONTRAST_DEGREE_0 = -0.00232

/** The contrast coefficients, highest degree first. */
const AGX_CONTRAST_COEFFICIENTS: readonly number[] = [
  CONTRAST_DEGREE_6,
  CONTRAST_DEGREE_5,
  CONTRAST_DEGREE_4,
  CONTRAST_DEGREE_3,
  CONTRAST_DEGREE_2,
  CONTRAST_DEGREE_1,
  CONTRAST_DEGREE_0,
]

/** Bisection steps; each halves the bracket, so this exceeds double precision for any bracket here. */
const INVERSE_ITERATION_COUNT = 60
/** The largest linear input the inverse searches; the curve is saturated well before it. */
const INVERSE_SEARCH_CEILING = 64

function contrast(position: number): number {
  return AGX_CONTRAST_COEFFICIENTS.reduce((total, coefficient) => total * position + coefficient, 0)
}

/** The display-encoded value, 0 to 1, of a neutral linear input at exposure 1. */
export function agxNeutralResponse(linear: number): number {
  const stops = Math.log2(Math.max(linear, AGX_LINEAR_FLOOR))
  const position = clampToUnitInterval((stops - AGX_MIN_EV) / (AGX_MAX_EV - AGX_MIN_EV))
  const outputLinear = clampToUnitInterval(
    Math.pow(Math.max(0, contrast(position)), AGX_OUTPUT_POWER),
  )
  return linearToSrgb(outputLinear)
}

/** The neutral linear input whose response is the given display-encoded value, by bisection. */
export function agxNeutralInverse(encoded: number): number {
  let low = 0
  let high = INVERSE_SEARCH_CEILING
  for (let step = 0; step < INVERSE_ITERATION_COUNT; step += 1) {
    const middle = (low + high) / 2
    if (agxNeutralResponse(middle) < encoded) {
      low = middle
    } else {
      high = middle
    }
  }
  return (low + high) / 2
}

core/color/hex.ts.source:
import type { Srgb } from './oklab'

const MAX_CHANNEL = 255
// Hexadecimal is base 16; naming the radix keeps no-magic-numbers satisfied.
const HEX_RADIX = 16
const HEX_PAIR_LENGTH = 2
const SHORTHAND_LENGTH = 3

function channelToHex(channel: number): string {
  return Math.round(channel * MAX_CHANNEL)
    .toString(HEX_RADIX)
    .padStart(HEX_PAIR_LENGTH, '0')
}

export function formatHex(srgb: Srgb): string {
  return `#${channelToHex(srgb.r)}${channelToHex(srgb.g)}${channelToHex(srgb.b)}`
}

function channelFromHexPair(pair: string): number {
  return parseInt(pair, HEX_RADIX) / MAX_CHANNEL
}

export function parseHex(hex: string): Srgb {
  const match = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(hex.trim())
  if (match === null) {
    throw new Error(`Not a valid hex color: "${hex}"`)
  }
  const digits = match[1]!
  const full = digits.length === SHORTHAND_LENGTH ? digits.replace(/(.)/g, '$1$1') : digits
  const pairs = full.match(/.{2}/g)!
  return {
    r: channelFromHexPair(pairs[0]!),
    g: channelFromHexPair(pairs[1]!),
    b: channelFromHexPair(pairs[2]!),
  }
}

