/** The named shape of an opening's head: its wall-cut void in 3D and its plan symbol in 2D. The union is open to further variants (bay, bow, octagonal) additively, the way `ContourSegment` is. */
export type VoidContourKind = 'rectangular' | 'round' | 'arched' | 'lancet'

/** The named body an opening renders in its void. Open to further variants additively. */
export type OpeningFillKind = 'door-leaf' | 'window-sash' | 'window-sash-hung'

export interface Scene3DReference {
  /** Identifier of the 3D builder routine or asset-reference key. */
  builder: string
  /** Names the opening's wall-cut shape (the void), distinct from `builder` (the eventual fill). Non-opening types omit it. */
  voidContour?: VoidContourKind
  /** Names the opening's body (leaf, sash, glass) that fills the void, distinct from `voidContour` (the cut). Non-opening types omit it. */
  fill?: OpeningFillKind
}

export type OpeningFamily =
  | 'swing'
  | 'slide'
  | 'fold'
  | 'pivot'
  | 'cased'
  | 'window-fixed'
  | 'window-hung'
  | 'window-slide'
  | 'window-crank'

/** The edge a crank window (or other hinged opening) pivots on. */
export type HingeEdge = 'jamb' | 'head' | 'sill'

export interface OpeningTypeParameters {
  family: OpeningFamily
  double?: boolean
  /** The hinge edge for a crank window: jamb (casement), head (awning), sill (hopper). */
  hingeEdge?: HingeEdge
  /**
   * The sash of a hung window that is fixed shut, leaving the other sash operable.
   * Absent for a double-hung window, where both sashes operate.
