core/units/length-units.ts.source:
/** A length in real-valued millimeters: the canonical storage unit, matching core/model. */
export type Millimeters = number

export type ImperialForm = 'feet-and-inches' | 'decimal-feet' | 'decimal-inches'
export type MetricForm = 'meters' | 'centimeters' | 'millimeters'

export const MM_PER_INCH = 25.4
export const MM_PER_FOOT = 304.8
export const MM_PER_CENTIMETER = 10
export const MM_PER_METER = 1000
export const INCHES_PER_FOOT = 12

// 25.4 = 254/10 and 304.8 = 3048/10 expressed as integer fractions so integer
// inputs produce exact terminating-decimal outputs (avoids IEEE-754 drift).
const INCHES_NUMERATOR = 254
const FEET_NUMERATOR = 3048
const IMPERIAL_DENOMINATOR = 10

export function inchesToMillimeters(inches: number): Millimeters {
  return (inches * INCHES_NUMERATOR) / IMPERIAL_DENOMINATOR
}

export function millimetersToInches(mm: Millimeters): number {
  return (mm * IMPERIAL_DENOMINATOR) / INCHES_NUMERATOR
}

export function feetToMillimeters(feet: number): Millimeters {
  return (feet * FEET_NUMERATOR) / IMPERIAL_DENOMINATOR
}

export function millimetersToFeet(mm: Millimeters): number {
  return (mm * IMPERIAL_DENOMINATOR) / FEET_NUMERATOR
}

// The metric factors are exact integers, but a decimal input such as 2.03 is not
// exactly representable, so the bare product drifts (2.03 * 1000 is 2029.9999...).
// IEEE-754 double holds ~15.9 significant decimal digits; 15 sig figs removes
// sub-ULP noise without rounding away genuine user-supplied precision.
const SIGNIFICANT_DIGITS_FOR_SNAP = 15

function snapToExactDecimal(value: number): number {
  return Number(value.toPrecision(SIGNIFICANT_DIGITS_FOR_SNAP))
}

export function centimetersToMillimeters(centimeters: number): Millimeters {
  return snapToExactDecimal(centimeters * MM_PER_CENTIMETER)
}

export function millimetersToCentimeters(mm: Millimeters): number {
  return snapToExactDecimal(mm / MM_PER_CENTIMETER)
}

export function metersToMillimeters(meters: number): Millimeters {
  return snapToExactDecimal(meters * MM_PER_METER)
}

export function millimetersToMeters(mm: Millimeters): number {
  return snapToExactDecimal(mm / MM_PER_METER)
}

core/units/precision.ts.source:
export type DisplayPrecision =
  | { kind: 'decimal-places'; places: number }
  | { kind: 'fraction'; denominator: number }

/** The decimal-places member of DisplayPrecision; the only precision metric and decimal forms accept. */
export type DecimalPrecision = Extract<DisplayPrecision, { kind: 'decimal-places' }>

const DECIMAL_BASE = 10

/** Rounds half away from zero (symmetric for negatives, unlike Math.round). */
export function roundToDecimalPlaces(value: number, places: number): number {
  const scale = DECIMAL_BASE ** places
  // Math.round rounds half toward +Infinity, so it is asymmetric for negatives
  // (Math.round(-2.5) is -2). Rounding the magnitude and reapplying the sign keeps
  // the magnitude of negative values consistent with their positive counterparts.
  const sign = Math.sign(value)
  return (sign * Math.round(Math.abs(value) * scale)) / scale
}

function greatestCommonDivisor(a: number, b: number): number {
  return b === 0 ? a : greatestCommonDivisor(b, a % b)
}

/**
 * Rounds a non-negative value to the nearest 1/denominator, returns a reduced
 * fraction; numerator may be 0. Sign is the caller's responsibility (formatLength
 * formats the magnitude and applies the sign around it).
 */
export function roundToNearestFraction(
  value: number,
  denominator: number,
): { whole: number; numerator: number; denominator: number } {
  const totalParts = Math.round(value * denominator)
  const whole = Math.floor(totalParts / denominator)
  const numerator = totalParts % denominator

  // A zero numerator has no fraction to display, so report it as 0/1 rather than
  // 0/denominator to avoid a misleading denominator.
  if (numerator === 0) {
    return { whole, numerator: 0, denominator: 1 }
  }

  const divisor = greatestCommonDivisor(numerator, denominator)
  return {
    whole,
    numerator: numerator / divisor,
    denominator: denominator / divisor,
  }
}

core/commands/handlers/transform-command.source:
import type { InstantiatedEntities } from '../../clipboard/clipboard'
import { rotatePoint, translatePoint } from '../../geometry/point'
import type { Dimension, Floor, Opening, Point, Project, Wall } from '../../model/types'
import type { Command, CommandHandler } from '../command'
import type { CommandRegistry } from '../command-registry'
import { mapTargetFloor } from './map-target-floor'

// Moves the start/end of every wall and dimension whose id is in `idSet` through `move`,
// leaving openings and every unselected entity reference-equal so dirty tracking stays
// entity-keyed. Returns a new floor only when at least one entity changed identity.
function transformFloorEntities(
  floor: Floor,
  idSet: ReadonlySet<string>,
  move: (point: Point) => Point,
): Floor {
  return {
    ...floor,
    walls: floor.walls.map((wall) =>
      idSet.has(wall.id) ? { ...wall, start: move(wall.start), end: move(wall.end) } : wall,
    ),
    dimensions: floor.dimensions.map((dimension) =>
      idSet.has(dimension.id)
        ? { ...dimension, start: move(dimension.start), end: move(dimension.end) }
        : dimension,
    ),
  }
}

// Removes every selected wall, dimension, and opening, and additionally cascades to
// any opening hosted on a deleted wall so no opening is left without a host.
function deleteFloorEntities(floor: Floor, idSet: ReadonlySet<string>): Floor {
  const deletedWallIds = new Set(
    floor.walls.filter((wall) => idSet.has(wall.id)).map((wall) => wall.id),
  )
  return {
    ...floor,
    walls: floor.walls.filter((wall) => !idSet.has(wall.id)),
    openings: floor.openings.filter(
      (opening) => !idSet.has(opening.id) && !deletedWallIds.has(opening.hostWallId),
    ),
    dimensions: floor.dimensions.filter((dimension) => !idSet.has(dimension.id)),
  }
}

export const TRANSLATE_ENTITIES = 'floor/translate-entities'
export const ROTATE_ENTITIES = 'floor/rotate-entities'
export const DELETE_ENTITIES = 'floor/delete-entities'
export const PASTE_ENTITIES = 'floor/paste-entities'

export interface TranslateEntitiesParams {
  floorId: string
  entityIds: string[]
  delta: Point
}

export interface RotateEntitiesParams {
  floorId: string
  entityIds: string[]
  pivot: Point
  radians: number
}

export interface DeleteEntitiesParams {
  floorId: string
  entityIds: string[]
}

export interface PasteEntitiesParams {
  floorId: string
  walls: Wall[]
  openings: Opening[]
  dimensions: Dimension[]
}

export function translateEntities(
  floorId: string,
  entityIds: string[],
  delta: Point,
): Command<TranslateEntitiesParams> {
  return {
    type: TRANSLATE_ENTITIES,
    params: { floorId, entityIds, delta },
    description: 'Move',
  }
}

const translateEntitiesHandler: CommandHandler<Project, TranslateEntitiesParams> = {
  apply(state, params) {
    const idSet = new Set(params.entityIds)
    mapTargetFloor(state, params.floorId, (floor) =>
      transformFloorEntities(floor, idSet, (point) => translatePoint(point, params.delta)),
    )
  },
}

// eslint-disable-next-line max-params -- floor, the entity ids, the pivot, and the angle is the natural signature for rotating a selection
export function rotateEntities(
  floorId: string,
  entityIds: string[],
  pivot: Point,
  radians: number,
): Command<RotateEntitiesParams> {
  return {
    type: ROTATE_ENTITIES,
    params: { floorId, entityIds, pivot, radians },
    description: 'Rotate',
  }
}

const rotateEntitiesHandler: CommandHandler<Project, RotateEntitiesParams> = {
  apply(state, params) {
    const idSet = new Set(params.entityIds)
    mapTargetFloor(state, params.floorId, (floor) =>
      transformFloorEntities(floor, idSet, (point) =>
        rotatePoint(point, params.pivot, params.radians),
      ),
    )
  },
}

export function deleteEntities(
  floorId: string,
  entityIds: string[],
): Command<DeleteEntitiesParams> {
  return {
    type: DELETE_ENTITIES,
    params: { floorId, entityIds },
    description: 'Delete',
  }
}

const deleteEntitiesHandler: CommandHandler<Project, DeleteEntitiesParams> = {
  apply(state, params) {
    const idSet = new Set(params.entityIds)
    mapTargetFloor(state, params.floorId, (floor) => deleteFloorEntities(floor, idSet))
  },
}

export function pasteEntities(
  floorId: string,
  entities: InstantiatedEntities,
): Command<PasteEntitiesParams> {
  // Capture the already-instantiated entities in params so redo reuses the same ids
  // rather than minting fresh ones, mirroring addWall.
  return {
    type: PASTE_ENTITIES,
    params: {
      floorId,
      walls: entities.walls,
      openings: entities.openings,
      dimensions: entities.dimensions,
    },
    description: 'Paste',
  }
}

const pasteEntitiesHandler: CommandHandler<Project, PasteEntitiesParams> = {
  apply(state, params) {
    mapTargetFloor(state, params.floorId, (floor) => ({
      ...floor,
      walls: [...floor.walls, ...params.walls],
      openings: [...floor.openings, ...params.openings],
      dimensions: [...floor.dimensions, ...params.dimensions],
    }))
  },
}

function collectSelectedEndpoints(floor: Floor, idSet: ReadonlySet<string>): Point[] {
  const endpoints: Point[] = []
  for (const wall of floor.walls) {
    if (idSet.has(wall.id)) endpoints.push(wall.start, wall.end)
  }
  for (const dimension of floor.dimensions) {
    if (idSet.has(dimension.id)) endpoints.push(dimension.start, dimension.end)
  }
  return endpoints
}

function midpoint(min: number, max: number): number {
  return (min + max) / 2
}

/**
 * Midpoint of the axis-aligned bounding box of every selected wall and dimension
 * endpoint. Returns the origin when the selection has no measurable geometry.
 */
export function selectionCenter(floor: Floor, entityIds: Iterable<string>): Point {
  const endpoints = collectSelectedEndpoints(floor, new Set(entityIds))
  if (endpoints.length === 0) return { x: 0, y: 0 }
  const xs = endpoints.map((point) => point.x)
  const ys = endpoints.map((point) => point.y)
  return {
    x: midpoint(Math.min(...xs), Math.max(...xs)),
    y: midpoint(Math.min(...ys), Math.max(...ys)),
  }
}

export function registerTransformCommands(
  registry: CommandRegistry<Project>,
): CommandRegistry<Project> {
  return registry
    .register(TRANSLATE_ENTITIES, translateEntitiesHandler)
    .register(ROTATE_ENTITIES, rotateEntitiesHandler)
    .register(DELETE_ENTITIES, deleteEntitiesHandler)
    .register(PASTE_ENTITIES, pasteEntitiesHandler)
}

core/export/svg/svg-plan-exporter.ts.source:
import { dimensionGeometry } from '../../geometry/dimension'
import type { DimensionGeometry } from '../../geometry/dimension'
import { polygonCentroid } from '../../geometry/polygon'
import { dot, subtract, unit } from '../../geometry/vector'
import { wallFaceGeometry } from '../../geometry/wall-face'
import type { WallFaceGap, WallFaceRun, WallFaceStretch } from '../../geometry/wall-face'
import type { Point, Project } from '../../model/types'
import type { UnitPreferences } from '../../units'
import { formatArea, formatLength, lengthFormatOptions, preferencesForUnits } from '../../units'
import { effectiveWallThickness } from '../../scene/construction-profile'
import { deriveSceneGraph } from '../../scene/scene-graph'
import type {
  DimensionSceneNode,
  OpeningSceneNode,
  RoomSceneNode,
  SceneGraph,
  WallSceneNode,
} from '../../scene/scene-graph'
import { rawWallId } from '../../scene/wall-id'
import type { Exporter, ExportResult } from '../exporter'
import { svgDocument, svgGroup, svgLine, svgPolygon, svgText } from './svg-document'
import { createSvgView, planContentBounds } from './svg-view'
import type { SvgView } from './svg-view'

/** Wall stroke color, mirroring the on-screen plan ink (redeclared in core). */
const WALL_INK = '#222222'
/** Room fill color, mirroring the on-screen room fill (redeclared in core). */
const ROOM_FILL = '#eef2f6'
/** Room label ink, mirroring the on-screen label color (redeclared in core). */
const LABEL_INK = '#37414d'
/** Opening jamb cap stroke, mirroring the wall ink. */
const OPENING_INK = '#222222'
/** Dimension line, extension, and arrowhead ink, mirroring the on-screen dimension. */
const DIMENSION_INK = '#222222'
/** Room label font size in world millimeters. */
const LABEL_FONT_SIZE = 280
/** Vertical advance between the name and area label lines, in world millimeters. */
const LABEL_LINE_HEIGHT = 320
/** Arrowhead barb length in world millimeters (SVG user units are millimeters). */
const ARROWHEAD_LENGTH_MM = 120
/** Divisor of pi giving the arrowhead barb half-angle (a 22.5 degree barb). */
const ARROWHEAD_HALF_ANGLE_DIVISOR = 8
/** Half-angle each arrowhead barb is rotated from the dimension line direction. */
const ARROWHEAD_HALF_ANGLE = Math.PI / ARROWHEAD_HALF_ANGLE_DIVISOR

export interface SvgPlanExportOptions {
  /** Margin around the content in world millimeters. Default 100. */
  marginMm?: number
  /** Unit preferences for area and length text. Defaults to the project's units. */
  preferences?: UnitPreferences
  /** The ids of the floors to draw. Default: every floor. */
  floorIds?: readonly string[]
  /** False leaves out the room labels and the dimensions. Default true. */
  annotations?: boolean
}

/** Collaborators every render function needs, bundled to keep parameter lists small. */
interface SvgPlanContext {
  view: SvgView
  preferences: UnitPreferences
}

/** The pure SVG exporter for the two-dimensional plan. */
export class SvgPlanExporter implements Exporter<SvgPlanExportOptions> {
  readonly media = 'image/svg+xml'

  export(project: Project, options?: SvgPlanExportOptions): ExportResult {
    const graph = narrowGraph(deriveSceneGraph(project), options)
    const bounds = planContentBounds(graph)
    const view = createSvgView(bounds, options)
    const preferences = options?.preferences ?? preferencesForUnits(project.meta.units)
    const context: SvgPlanContext = { view, preferences }
    const annotationLayers =
      options?.annotations === false
        ? []
        : [
            renderRoomLabels(graph, context),
            // Dimensions are annotation overlays painted above the plan.
            renderDimensions(graph, context),
          ]
    const body = svgGroup(
      [
        renderRooms(graph, context),
        renderWalls(graph, context),
        // Openings paint no fill of their own; see `renderOpening`.
        renderOpenings(graph, context),
        ...annotationLayers,
      ],
      {},
    )
    return { media: 'image/svg+xml', extension: 'svg', content: svgDocument(view, body) }
  }
}

/**
 * The graph the plan draws: only the nodes of the listed floors, and no dimensions
 * when annotations are off, so neither widens the view.
 */
function narrowGraph(graph: SceneGraph, options: SvgPlanExportOptions | undefined): SceneGraph {
  const floorIds = options?.floorIds
  const onListedFloor = (node: { floorId: string }): boolean =>
    floorIds === undefined || floorIds.includes(node.floorId)
  return {
    ...graph,
    walls: graph.walls.filter(onListedFloor),
    rooms: graph.rooms.filter(onListedFloor),
    openings: graph.openings.filter(onListedFloor),
    dimensions: options?.annotations === false ? [] : graph.dimensions.filter(onListedFloor),
  }
}

/** Render every wall as one `<line>` per standing stretch, wrapped in a walls layer group. */
function renderWalls(graph: SceneGraph, { view }: SvgPlanContext): string {
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  const lines = graph.walls.flatMap((wall) => wallStrokeLines(wall, graph.openings, view))
  return svgGroup(lines, { 'data-layer': 'walls' })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/**
 * One `<line>` per stretch of `wall`'s centerline left standing by its openings,
 * in order from the wall's start.
 */
function wallStrokeLines(
  wall: WallSceneNode,
  openings: readonly OpeningSceneNode[],
  view: SvgView,
): string[] {
  const stretches = wallFaceGeometry(wallCenterlineRun(wall, openings))
  return stretches.map((stretch) => wallStrokeLine(wall, stretch, view))
}

/**
 * `wall` as a `wallFaceGeometry` run whose two faces are the centerline itself.
 * The exported wall symbol is a stroked centerline rather than a poche between two
 * drawn faces, so every corner collapses to the wall's own start or end; each
 * returned stretch then carries the centerline sub-segment the `<line>` needs as
 * `plusFace`.
 */
function wallCenterlineRun(
  wall: WallSceneNode,
  openings: readonly OpeningSceneNode[],
): WallFaceRun {
  return {
    start: wall.start,
    end: wall.end,
    corners: {
      aPlus: wall.start,
      aMinus: wall.start,
      bPlus: wall.end,
      bMinus: wall.end,
    },
    gaps: wallOpeningGaps(wall, openings),
  }
}

/** The clear spans `wall`'s own openings cut out of it, as distances from its start. */
function wallOpeningGaps(
  wall: WallSceneNode,
  openings: readonly OpeningSceneNode[],
): WallFaceGap[] {
  const hostId = rawWallId(wall)
  const axis = unit(subtract(wall.end, wall.start))
  return openings
    .filter((opening) => opening.hostWallId === hostId)
    .map((opening) => wallOpeningGap(wall, axis, opening))
}

/** One opening's clear span on `wall`'s axis, from its near jamb to its far jamb. */
function wallOpeningGap(wall: WallSceneNode, axis: Point, opening: OpeningSceneNode): WallFaceGap {
  const [nearJamb, farJamb] = openingJambPoints(opening)
  return {
    from: dot(subtract(nearJamb, wall.start), axis),
    to: dot(subtract(farJamb, wall.start), axis),
  }
}

/** One projected `<line>` for a wall stretch, capped square where a cut bounds it. */
function wallStrokeLine(wall: WallSceneNode, stretch: WallFaceStretch, view: SvgView): string {
  const [from, to] = stretch.plusFace
  const start = view.project(from)
  const end = view.project(to)
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgLine({
    x1: start.x,
    y1: start.y,
    x2: end.x,
    y2: end.y,
    attributes: {
      stroke: WALL_INK,
      'stroke-width': effectiveWallThickness(wall),
      'stroke-linecap': isUncutStretch(wall, from, to) ? 'round' : 'butt',
      // wall.id already carries the `wall:` scene-node prefix (see scene-graph).
      'data-node-id': wall.id,
    },
  })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/**
 * True when a stretch still reaches both of the wall's own endpoints, rather than
 * being bounded by a cut. A round cap belongs only here: `wallFaceGeometry` passes
 * the run's own corners through untouched at its ends, so exact coordinate equality
 * is the right test and no epsilon is needed.
 */
function isUncutStretch(wall: WallSceneNode, from: Point, to: Point): boolean {
  return pointsEqual(from, wall.start) && pointsEqual(to, wall.end)
}

/** Exact coordinate equality. */
function pointsEqual(a: Point, b: Point): boolean {
  return a.x === b.x && a.y === b.y
}

/** Render every opening as its jamb caps, wrapped in an openings layer group. */
function renderOpenings(graph: SceneGraph, context: SvgPlanContext): string {
  const groups = graph.openings.map((opening) => renderOpening(opening, context))
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgGroup(groups, { 'data-layer': 'openings' })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/**
 * Render one opening as its two jamb caps.
 *
 * The wall stroke already breaks at the opening's jambs (see `wallOpeningGaps`),
 * so the opening itself paints nothing over the plan beneath it; it only caps the
 * break. The coarse per-family glyph (swing leaf, window frame lines) is deferred
 * per Decision 4: registry-driven symbol classification is an editor/bridge
 * concern, and no committed test drives a glyph this slice.
 */
function renderOpening(opening: OpeningSceneNode, context: SvgPlanContext): string {
  // opening.id already carries the `opening:` scene-node prefix (see scene-graph).
  /* eslint-disable-next-line @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgGroup(openingJambs(opening, context), { 'data-node-id': opening.id })
}

/** The opening's two jamb points on the host wall centerline, near jamb first. */
function openingJambPoints(opening: OpeningSceneNode): [Point, Point] {
  const halfWidth = opening.width / 2
  return [
    translate(opening.center, opening.along, -halfWidth),
    translate(opening.center, opening.along, halfWidth),
  ]
}

/** Emit an across-wall `<line>` jamb cap at each of the opening's two jambs. */
function openingJambs(opening: OpeningSceneNode, context: SvgPlanContext): string[] {
  const [jambStart, jambEnd] = openingJambPoints(opening)
  return [jambCap(jambStart, opening, context), jambCap(jambEnd, opening, context)]
}

/** Emit one across-wall jamb cap centered on `jamb`, spanning the host thickness. */
function jambCap(jamb: Point, opening: OpeningSceneNode, { view }: SvgPlanContext): string {
  const halfThickness = opening.hostThickness / 2
  const near = view.project(translate(jamb, opening.normal, -halfThickness))
  const far = view.project(translate(jamb, opening.normal, halfThickness))
  return svgLine({
    x1: near.x,
    y1: near.y,
    x2: far.x,
    y2: far.y,
    attributes: { stroke: OPENING_INK },
  })
}

/** Translate `origin` along unit `direction` by `distance` (world millimeters). */
function translate(origin: Point, direction: Point, distance: number): Point {
  return { x: origin.x + direction.x * distance, y: origin.y + direction.y * distance }
}

/** Render every room as a projected fill `<polygon>`, wrapped in a rooms layer group. */
function renderRooms(graph: SceneGraph, context: SvgPlanContext): string {
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  const polygons = graph.rooms.map((room) => {
    const projected = room.polygon.map((point) => context.view.project(point))
    // room.id already carries the `room:` scene-node prefix (see scene-graph).
    return svgPolygon(projected, { fill: ROOM_FILL, 'data-node-id': room.id })
  })
  return svgGroup(polygons, { 'data-layer': 'rooms' })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/** Render every room's name and area labels, wrapped in a labels layer group painted last. */
function renderRoomLabels(graph: SceneGraph, context: SvgPlanContext): string {
  const labels = graph.rooms.flatMap((room) => renderRoomLabel(room, context))
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgGroup(labels, { 'data-layer': 'room-labels' })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/** Render one room's label: its name above its area, or just the area when unnamed. */
function renderRoomLabel(room: RoomSceneNode, context: SvgPlanContext): string[] {
  const anchor = context.view.project(polygonCentroid(room.polygon))
  const areaText = formatArea(room.area, context.preferences)
  if (room.name === undefined) {
    return [labelText(areaText, anchor)]
  }
  const areaAnchor = { x: anchor.x, y: anchor.y + LABEL_LINE_HEIGHT }
  return [labelText(room.name, anchor), labelText(areaText, areaAnchor)]
}

/** Emit a centered `<text>` line styled like the on-screen room label. */
function labelText(text: string, position: { x: number; y: number }): string {
  /* eslint-disable @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgText(text, position, {
    fill: LABEL_INK,
    'font-size': LABEL_FONT_SIZE,
    'text-anchor': 'middle',
  })
  /* eslint-enable @typescript-eslint/naming-convention */
}

/** A world-space line segment with the SVG stroke attributes to render it. */
interface WorldSegment {
  from: Point
  to: Point
  attributes: Record<string, string | number | undefined>
}

/** Project a world segment's endpoints and emit the `<line>` between them in SVG space. */
function svgLineWorld({ view }: SvgPlanContext, segment: WorldSegment): string {
  const start = view.project(segment.from)
  const end = view.project(segment.to)
  return svgLine({
    x1: start.x,
    y1: start.y,
    x2: end.x,
    y2: end.y,
    attributes: segment.attributes,
  })
}

/** Render every dimension as its line, extensions, arrowheads, and length text. */
function renderDimensions(graph: SceneGraph, context: SvgPlanContext): string {
  const groups = graph.dimensions.map((dimension) => renderDimension(dimension, context))
  /* eslint-disable-next-line @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgGroup(groups, { 'data-layer': 'dimensions' })
}

/** Render one dimension: offset line, two extension lines, arrowheads, and length text. */
function renderDimension(dimension: DimensionSceneNode, context: SvgPlanContext): string {
  const geom = dimensionGeometry(dimension.start, dimension.end, dimension.offset)
  const ink = { stroke: DIMENSION_INK }
  const fragments = [
    svgLineWorld(context, { from: geom.lineStart, to: geom.lineEnd, attributes: ink }),
    svgLineWorld(context, {
      from: geom.extensionStart[0],
      to: geom.extensionStart[1],
      attributes: ink,
    }),
    svgLineWorld(context, {
      from: geom.extensionEnd[0],
      to: geom.extensionEnd[1],
      attributes: ink,
    }),
    ...dimensionArrowheads(geom, context),
    dimensionLabel(dimension, geom, context),
  ]
  // dimension.id already carries the `dimension:` scene-node prefix (see scene-graph).
  /* eslint-disable-next-line @typescript-eslint/naming-convention -- SVG attribute names are kebab-case per the SVG specification. */
  return svgGroup(fragments, { 'data-node-id': dimension.id })
}

/** Emit two arrowhead barb `<line>`s at each end of the projected dimension line. */
function dimensionArrowheads(geom: DimensionGeometry, context: SvgPlanContext): string[] {
  const start = context.view.project(geom.lineStart)
  const end = context.view.project(geom.lineEnd)
  return [...arrowheadBarbs(end, start), ...arrowheadBarbs(start, end)]
}

/** Two short `<line>` barbs at `tip`, opening back toward the line's `other` end. */
function arrowheadBarbs(tip: Point, other: Point): string[] {
  const dx = other.x - tip.x
  const dy = other.y - tip.y
  const length = Math.hypot(dx, dy)
  if (length === 0) {
    return []
  }
  const angle = Math.atan2(dy, dx)
  return [angle - ARROWHEAD_HALF_ANGLE, angle + ARROWHEAD_HALF_ANGLE].map((barbAngle) =>
    arrowheadBarb(tip, barbAngle),
  )
}

/** One arrowhead barb `<line>` from `tip` along `barbAngle` for the barb length. */
function arrowheadBarb(tip: Point, barbAngle: number): string {
  return svgLine({
    x1: tip.x,
    y1: tip.y,
    x2: tip.x + Math.cos(barbAngle) * ARROWHEAD_LENGTH_MM,
    y2: tip.y + Math.sin(barbAngle) * ARROWHEAD_LENGTH_MM,
    attributes: { stroke: DIMENSION_INK },
  })
}

/** Emit the formatted length `<text>` centered at the projected dimension-line midpoint. */
function dimensionLabel(
  dimension: DimensionSceneNode,
  geom: DimensionGeometry,
  context: SvgPlanContext,
): string {
  const start = context.view.project(geom.lineStart)
  const end = context.view.project(geom.lineEnd)
  const midpoint = { x: (start.x + end.x) / 2, y: (start.y + end.y) / 2 }
  const text = formatLength(dimension.length, lengthFormatOptions(context.preferences))
  return labelText(text, midpoint)
}

core/commands/testing/schema-fixture.ts.source:
// A project document for the test that every command leaves a document that
// passes the current schema. It is the extensions fixture without the unknown
// key that the extensions fixture plants on its objects, so the strict check can
// pass, and it keeps every id, so the command samples still match.

import { UNKNOWN_PROBE_KEY, createExtensionsFixture } from './extensions-fixture'
import type { Project } from '../../model/types'

function withoutProbeKey(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map(withoutProbeKey)
  }
  if (typeof value !== 'object' || value === null) {
    return value
  }
  const kept = Object.entries(value).filter(([key]) => key !== UNKNOWN_PROBE_KEY)
  return Object.fromEntries(kept.map(([key, entry]) => [key, withoutProbeKey(entry)]))
}

/** A fresh document with the ids of the extensions fixture and no planted unknown key. */
export function schemaFixture(): Project {
  return withoutProbeKey(createExtensionsFixture()) as Project
}

