import { clampToUnitInterval } from '../color/linear-rgb'
import type { LinearRgb } from '../color/oklab'
import type { LatLong } from '../model/site'
import type { Vector3 } from '../scene/vector3'
import { referenceLightingInput } from './daylight-reference'
import type { ObservationInstant } from './observation-time'
import { DEFAULT_CLOUD_COVER, skyLighting } from './sky-model'
import { type SolarAngles, type SolarPositionInput, solarPosition } from './solar-position'
import { projectDomeToSphericalHarmonics } from './spherical-harmonics'
import { sunWorldDirection } from './sun-world-direction'

const FALLBACK_NORTH_BEARING = 0

/** Everything the outdoor-lighting rig needs for one site, instant, and sky. */
export interface EnvironmentLighting {
  /** Unit world-space direction pointing from the scene toward the sun. */
  sunDirection: Vector3
  /** Direct sun tint in linear-light sRGB. */
  sunColor: LinearRgb
  /** Ambient/hemisphere sky tint in linear-light sRGB. */
  skyColor: LinearRgb
  /**
   * Direct-sun level, 0 (extinguished) to the full sun's level, fading along the light's path,
   * 0 at and below the horizon.
   */
  sunLevel: number
  /**
   * Cloud-cover fraction the sky was computed with, after the fallback and the clamp; the visible
   * sky mesh reads it.
   */
  cloudCover: number
  /** Nine RGB spherical-harmonic triples of the sky dome, SphericalHarmonics3 order. */
  skyAmbient: readonly number[]
}

/** The site, civil observation instant, and weather that drive the lighting. */
export interface EnvironmentLightingInput {
  /** Site location in decimal degrees. */
  latLong: LatLong
  /** Site north bearing in radians, plan-up to true north. A bearing that is not finite counts as 0. */
  northBearing: number
  /** Offset from UTC in minutes; local civil time = UTC + this offset. */
  utcOffsetMinutes: number
  /** The civil date and wall-clock minutes the scene is observed at. */
  observedAt: ObservationInstant
  /**
   * Cloud-cover fraction, 0 (clear) to 1 (fully overcast). `NaN` counts as `DEFAULT_CLOUD_COVER`; a
   * value outside 0..1 is clamped into it.
   */
  cloudCover: number
}

/**
 * Composes the full outdoor lighting state for one observation: `solarPosition`
 * resolves the sun's horizontal-frame angles for the site and civil instant,
 * `sunWorldDirection` rotates them through the site north bearing into the
 * y-up world frame (ADR-0139), and `skyLighting` derives the sun and sky tints
 * from the solar altitude and cloud cover. `sunLevel` passes straight through
 * from `skyLighting`, carrying the fade along the light's path, 0 at and below the horizon, so
 * the direct sun fades to nothing as it sets. `skyAmbient` projects the same analytic sky dome into
 * spherical-harmonic coefficients for the ambient probe, and `cloudCover` reports the
 * cloud cover the sky was computed with, so the visible sky mesh can read it.
 * Frame and unit conventions follow those piece functions.
 *
 * Input that cannot be used falls back, and the function never throws. When the solar angles for
 * the site and instant are not finite (a coordinate, offset or minute that is not finite or too
 * large for the formulas, or a date whose text gives no number), the sun is the daylight reference
 * sun: the place, the instant, and the UTC offset of `referenceLightingInput()`, still under the
 * input's north bearing and cloud cover. A north bearing that is not finite counts as 0. A cloud
 * cover of `NaN` counts as `DEFAULT_CLOUD_COVER`, any other cloud cover is clamped into 0..1, and
 * `cloudCover` in the result is the value used. Every number of the result is then finite.
 */
export function computeEnvironmentLighting(input: EnvironmentLightingInput): EnvironmentLighting {
  const angles = lightingSolarAngles(input)
  const cloudCover = lightingCloudCover(input)
  const { sunColor, skyColor, sunLevel } = skyLighting(angles.altitude, cloudCover)
  const sunDirection = sunWorldDirection(angles, lightingNorthBearing(input))
  return {
    sunDirection,
    sunColor,
    skyColor,
    sunLevel,
    cloudCover,
    skyAmbient: projectDomeToSphericalHarmonics({ sunDirection, cloudCover }),
  }
}

function lightingNorthBearing(input: EnvironmentLightingInput): number {
  return Number.isFinite(input.northBearing) ? input.northBearing : FALLBACK_NORTH_BEARING
}

function lightingCloudCover(input: EnvironmentLightingInput): number {
  return Number.isNaN(input.cloudCover)
    ? DEFAULT_CLOUD_COVER
    : clampToUnitInterval(input.cloudCover)
}

function lightingSolarAngles(input: EnvironmentLightingInput): SolarAngles {
  const angles = solarPosition(solarPositionOf(input))
  if (Number.isFinite(angles.azimuth) && Number.isFinite(angles.altitude)) return angles
  return solarPosition(solarPositionOf(referenceLightingInput()))
}

function solarPositionOf(input: EnvironmentLightingInput): SolarPositionInput {
  return {
    latitude: input.latLong.latitude,
    longitude: input.latLong.longitude,
    observedAt: input.observedAt,
    utcOffsetMinutes: input.utcOffsetMinutes,
  }
}

core/environment/sky-dome.ts.source:
import { clampToUnitInterval, mixLinearRgb, scaleLinearRgb } from '../color/linear-rgb'
import type { LinearRgb } from '../color/oklab'
import type { Vector3 } from '../scene/vector3'
import { SUNWARD_GAIN, levelCardLight, upperDomeTints } from './daylight-calibration'
import { GROUND_BOUNCE_COLOR } from './ground-surface'

/**
 * The sky the dome is drawn for: a unit world-frame direction toward the sun, and the cloud cover.
 */
export type SkyDomeInput = { sunDirection: Vector3; cloudCover: number }

/**
 * The sun's height above the horizon in radians, from its unit direction, with the sine clamped
 * against rounding.
 */
export function sunAltitudeOf(sky: Pick<SkyDomeInput, 'sunDirection'>): number {
  return Math.asin(Math.min(1, Math.max(-1, sky.sunDirection.y)))
}

/**
 * The neutral grey ground bounce under the light a level card receives: the direct sun's
 * irradiance over pi plus the cosine-weighted mean of the upper dome, both from the daylight
 * calibration.
 */
function groundRadiance(sunAltitude: number, cloudCover: number): LinearRgb {
  const { sun, sky } = levelCardLight(sunAltitude, cloudCover)
  return {
    r: GROUND_BOUNCE_COLOR.r * (sun.r + sky.r),
    g: GROUND_BOUNCE_COLOR.g * (sun.g + sky.g),
    b: GROUND_BOUNCE_COLOR.b * (sun.b + sky.b),
  }
}

/**
 * Builds the dome's radiance function for one sky. Everything that depends only on the sky (the
 * sun's altitude, the dome's end tints, the ground's radiance) is computed here once, so a caller
 * sampling many directions pays only the per-direction work for each.
 * Above the horizon (y at or above 0) the dome blends the calibrated horizon tint into the zenith
 * tint on the view height and brightens toward the sun's azimuth under a clear sky. Below the
 * horizon it is the neutral grey ground bounce lit by the sun and the upper dome.
 */
export function skyDomeSampler(sky: SkyDomeInput): (view: Vector3) => LinearRgb {
  const { sunDirection, cloudCover } = sky
  const sunAltitude = sunAltitudeOf(sky)
  const dome = upperDomeTints(sunAltitude, cloudCover)
  const ground = groundRadiance(sunAltitude, cloudCover)
  const sunwardGain = SUNWARD_GAIN * (1 - cloudCover)
  return (view) => {
    if (view.y < 0) return ground
    const sunwardAlignment = view.x * sunDirection.x + view.z * sunDirection.z
    const brightening = 1 + sunwardGain * sunwardAlignment
    const radiance = mixLinearRgb(dome.horizon, dome.zenith, clampToUnitInterval(view.y))
    return scaleLinearRgb(radiance, brightening)
  }
}

/** Radiance of the analytic sky dome in a unit view direction (y up), as linear-light sRGB. */
export function skyDomeRadiance(view: Vector3, sky: SkyDomeInput): LinearRgb {
  return skyDomeSampler(sky)(view)
}

core/commands/testing/floor-command-samp.source:
// Sample parameters for the commands that act on the objects of one floor:
// walls, underlays, openings, furniture, dimensions, and the multi-entity
// transforms. Built against the ids of the extensions fixture.

import {
  createDimension,
  createFurnitureInstance,
  createOpening,
  createUnderlay,
  createWall,
} from '../../model/factories'
import type { FurnitureFootprint, Point } from '../../model/types'
import * as dimensions from '../handlers/dimension-commands'
import * as furniture from '../handlers/furniture-commands'
import * as openings from '../handlers/opening-commands'
import * as transforms from '../handlers/transform-commands'
import * as underlays from '../handlers/underlay-commands'
import * as walls from '../handlers/wall-commands'
import {
  FIXTURE_DOOR_TYPE,
  FIXTURE_IDS,
  MAIN_WALL_LENGTH_MM,
  SIDE_WALL_LENGTH_MM,
} from './extensions-fixture'
import type { CommandSamples } from './project-command-samples'

const ids = FIXTURE_IDS
const floor = ids.groundFloor
const STEP_MM = 250
const NEW_WALL_THICKNESS_MM = 150
const ADDED_OPENING_POSITION_MM = 3000
const MOVED_OPENING_POSITION_MM = 1200
const RESIZED_OPENING_WIDTH_MM = 900
const RESIZED_OPENING_HEIGHT_MM = 2100
const RESIZED_OPENING_POSITION_MM = 1550
const UNDERLAY_SIDE_PX = 400
const UNDERLAY_SCALE_MM_PER_PX = 5
const UNDERLAY_OPACITY = 0.5
const FURNITURE_SIDE_MM = 700
const FURNITURE_HEIGHT_MM = 900
const FURNITURE_ROTATION_DEGREES = 45
const QUARTER_TURN_RADIANS = Math.PI / 2

/** A fresh point one step from the origin, so no sample shares an object with the document. */
function step(): Point {
  return { x: STEP_MM, y: STEP_MM }
}

const WALL_SAMPLES: CommandSamples = {
  [walls.ADD_WALL]: () =>
    walls.addWall(floor, { x: MAIN_WALL_LENGTH_MM, y: 0 }, { x: MAIN_WALL_LENGTH_MM, y: STEP_MM })
      .params,
  [walls.MOVE_WALL_ENDPOINT]: () =>
    walls.moveWallEndpoint(floor, ids.mainWall, 'end', {
      x: MAIN_WALL_LENGTH_MM + STEP_MM,
      y: 0,
    }).params,
  [walls.SET_WALL_THICKNESS]: () =>
    walls.setWallThickness(floor, ids.mainWall, NEW_WALL_THICKNESS_MM).params,
}

const UNDERLAY_SAMPLES: CommandSamples = {
  [underlays.PLACE_UNDERLAY]: () => {
    const image = { scope: 'project', contentHash: 'hash-underlay-added' } as const
    const size = { width: UNDERLAY_SIDE_PX, height: UNDERLAY_SIDE_PX }
    return underlays.placeUnderlay(floor, createUnderlay({ image, ...size })).params
  },
  [underlays.CALIBRATE_UNDERLAY]: () =>
    underlays.calibrateUnderlay(floor, ids.mainUnderlay, {
      offset: step(),
      millimetersPerPixel: UNDERLAY_SCALE_MM_PER_PX,
      rotation: QUARTER_TURN_RADIANS,
    }).params,
  [underlays.MOVE_UNDERLAY]: () => underlays.moveUnderlay(floor, ids.mainUnderlay, step()).params,
  [underlays.SET_UNDERLAY_OPACITY]: () =>
    underlays.setUnderlayOpacity(floor, ids.mainUnderlay, UNDERLAY_OPACITY).params,
  [underlays.SET_UNDERLAY_VISIBILITY]: () =>
    underlays.setUnderlayVisibility(floor, ids.mainUnderlay, false).params,
  [underlays.REMOVE_UNDERLAY]: () => underlays.removeUnderlay(floor, ids.spareUnderlay).params,
}

const RESIZED_OPENING = {
  width: RESIZED_OPENING_WIDTH_MM,
  height: RESIZED_OPENING_HEIGHT_MM,
  sillHeight: 0,
}

const OPENING_SAMPLES: CommandSamples = {
  [openings.PLACE_OPENING]: () =>
    openings.placeOpening(
      floor,
      createOpening({
        type: FIXTURE_DOOR_TYPE,
        hostWallId: ids.mainWall,
        position: ADDED_OPENING_POSITION_MM,
        id: 'opening-added',
      }),
    ).params,
  [openings.MOVE_OPENING]: () =>
    openings.moveOpening(floor, ids.mainOpening, MOVED_OPENING_POSITION_MM).params,
  [openings.RESIZE_OPENING]: () =>
    openings.resizeOpening(floor, ids.mainOpening, { ...RESIZED_OPENING }).params,
  [openings.RESIZE_OPENING_EDGE]: () =>
    openings.resizeOpeningEdge(
      floor,
      ids.mainOpening,
      RESIZED_OPENING_WIDTH_MM,
      RESIZED_OPENING_POSITION_MM,
    ).params,
  [openings.FLIP_OPENING]: () => openings.flipOpening(floor, ids.mainOpening, 'hinge').params,
  [openings.SET_OPENING_TYPE]: () =>
    openings.setOpeningType(floor, ids.mainOpening, 'double-swing-door').params,
  [openings.REMOVE_OPENING]: () => openings.removeOpening(floor, ids.sideOpening).params,
}

function squareFootprint(): FurnitureFootprint {
  return { width: FURNITURE_SIDE_MM, depth: FURNITURE_SIDE_MM }
}

const FURNITURE_SAMPLES: CommandSamples = {
  [furniture.PLACE_FURNITURE]: () =>
    furniture.placeFurniture(
      floor,
      createFurnitureInstance({
        assetRef: { scope: 'user', contentHash: 'hash-furniture-added' },
        position: step(),
        footprint: squareFootprint(),
        id: 'furniture-added',
      }),
    ).params,
  [furniture.MOVE_FURNITURE]: () => furniture.moveFurniture(floor, ids.furniture, step()).params,
  [furniture.ROTATE_FURNITURE]: () =>
    furniture.rotateFurniture(floor, ids.furniture, FURNITURE_ROTATION_DEGREES).params,
  [furniture.RESIZE_FURNITURE]: () =>
    furniture.resizeFurniture(floor, ids.furniture, squareFootprint()).params,
  [furniture.SET_FURNITURE_HEIGHT]: () =>
    furniture.setFurnitureHeight(floor, ids.furniture, FURNITURE_HEIGHT_MM).params,
  [furniture.SET_FURNITURE_NAME]: () =>
    furniture.setFurnitureName(floor, ids.furniture, 'Settee').params,
  [furniture.REMOVE_FURNITURE]: () => furniture.removeFurniture(floor, ids.furniture).params,
}

const DIMENSION_SAMPLES: CommandSamples = {
  [dimensions.ADD_DIMENSION]: () =>
    dimensions.addDimension(
      floor,
      createDimension({ start: { x: 0, y: 0 }, end: { x: 0, y: SIDE_WALL_LENGTH_MM } }),
    ).params,
  [dimensions.REMOVE_DIMENSION]: () => dimensions.removeDimension(floor, ids.spareDimension).params,
}

const SELECTION = [ids.mainWall, ids.mainDimension]

const TRANSFORM_SAMPLES: CommandSamples = {
  [transforms.TRANSLATE_ENTITIES]: () =>
    transforms.translateEntities(floor, [...SELECTION], step()).params,
  [transforms.ROTATE_ENTITIES]: () =>
    transforms.rotateEntities(floor, [...SELECTION], { x: 0, y: 0 }, QUARTER_TURN_RADIANS).params,
  [transforms.DELETE_ENTITIES]: () => transforms.deleteEntities(floor, [ids.sideWall]).params,
  [transforms.PASTE_ENTITIES]: () => {
    const wall = createWall(step(), { x: SIDE_WALL_LENGTH_MM, y: STEP_MM }, { id: 'wall-pasted' })
    const pasted = { walls: [wall], openings: [], dimensions: [], ids: [wall.id] }
    return transforms.pasteEntities(floor, pasted).params
  },
}

/** Sample parameters for every command type that acts on one floor, keyed by command type. */
export const FLOOR_COMMAND_SAMPLES: CommandSamples = {
  ...WALL_SAMPLES,
  ...UNDERLAY_SAMPLES,
  ...OPENING_SAMPLES,
  ...FURNITURE_SAMPLES,
  ...DIMENSION_SAMPLES,
  ...TRANSFORM_SAMPLES,
}

core/environment/sky-model.ts.source:
import { clampToUnitInterval, greyOf, mixLinearRgb, scaleLinearRgb } from '../color/linear-rgb'
import type { LinearRgb } from '../color/oklab'
import { sunColorAt, sunLevelAt } from './daylight-calibration'

/**
 * The light an outdoor scene needs: the direct sun tint and the ambient sky tint,
 * both colors in linear-light sRGB, plus the sun's level. The sun warms
 * toward the horizon in `sunColor` while `sunLevel` carries the clear-sky
 * attenuation along the light's path, which is 0 at and below the horizon; the sky stays cooler
 * (bluer) than the sun.
 */
export interface SkyLighting {
  /**
   * Direct sun tint at luminance 1, warmer near the horizon; the dimming lives in sunLevel, not
   * here.
   */
  sunColor: LinearRgb
  /**
   * Direct-sun level, 0 (extinguished below the horizon) to the calibrated sun scale (full sun
   * overhead).
   */
  sunLevel: number
  /** Hemisphere fill tint, cooler than the sun; only the zeroed fill reads it. */
  skyColor: LinearRgb
}

/**
 * The cloud-cover fraction the solar path assumes when no weather is specified: a
 * clear sky. This is the absent-weather default, not a placeholder awaiting a future
 * weather layer; `EnvironmentState.cloudCover` and saved environment scenes carry the
 * real, user-set value.
 */
export const DEFAULT_CLOUD_COVER = 0

/** Hemisphere fill tint with the sun on the horizon: a dim, nearly grey dusk sky. */
const HORIZON_SKY_TINT: LinearRgb = { r: 0.45, g: 0.45, b: 0.5 }
/** Hemisphere fill tint with the sun overhead: a saturated daytime blue. */
const ZENITH_SKY_TINT: LinearRgb = { r: 0.35, g: 0.55, b: 1 }
/**
 * Fraction of the fill's light a fully overcast sky removes, alongside flattening it toward grey.
 */
const OVERCAST_DIMMING = 0.3

/** Clouds scatter the fill toward grey and absorb some of it outright. */
function overcastAdjusted(color: LinearRgb, cloudCover: number): LinearRgb {
  const flattened = mixLinearRgb(color, greyOf(color), cloudCover)
  return scaleLinearRgb(flattened, 1 - OVERCAST_DIMMING * cloudCover)
}

/**
 * Analytic clear-sky lighting model. `altitude` is the sun's height above the
 * horizon in radians (negative once it has set); `cloudCover` is a 0..1
 * fraction (0 clear, 1 fully overcast). The sun's color and level come from the
 * daylight calibration: the color is white-balanced at luminance 1, and the level
 * carries the dimming along the light's path through the air, gone at the
 * horizon and below it, and the cloud transmission. The sky color is the tint of
 * the hemisphere fill, which daylight does not read: it blends between named
 * horizon and zenith tints on the sun's elevation and flattens toward grey under
 * cloud while dimming.
 */
export function skyLighting(altitude: number, cloudCover: number): SkyLighting {
  const elevation = clampToUnitInterval(Math.sin(altitude))
  const clearSky = mixLinearRgb(HORIZON_SKY_TINT, ZENITH_SKY_TINT, elevation)
  return {
    sunColor: sunColorAt(altitude, cloudCover),
    sunLevel: sunLevelAt(altitude, cloudCover),
    skyColor: overcastAdjusted(clearSky, cloudCover),
  }
}

core/daylight/doorway-light.ts.source:
import { OPEN_SKY_VISIBILITY } from './daylight-field'
import { cellVisibility, enteringFlux, roomAverageTerm } from './room-average'
import type { RoomGeometry } from './room-geometry'

/**
 * Mean sky visibility of a room lit by its sky apertures alone, from 0 to 1. Its own doorways count
 * for nothing, so light crosses one doorway and no more, and rooms that open only to each other
 * stay dark. `skyWeights` holds, for each aperture of the room, the sky's relative radiance toward
 * a sky aperture times its net transmittance, and 0 for a doorway. A room with no cell has a
 * mean of 0.
 */
export function skyLitMeanVisibility(room: RoomGeometry, skyWeights: readonly number[]): number {
  if (room.cells.length === 0) return 0
  const roomAverage = roomAverageTerm(enteringFlux(room.apertures, skyWeights), room.surfaces)
  const total = room.cells.reduce(
    (sum, cell) => sum + cellVisibility(cell.factors, skyWeights, roomAverage),
    0,
  )
  return total / room.cells.length
}

/**
 * Luminance that a doorway into this room shows to its neighbor, relative to the open sky: a room
 * open to the sky passes 1 because its doorway shows the sky itself, and the cell sampling would
 * read that room as lit only by its own apertures. Any other room shows its lit surfaces, so it
 * passes its sky-lit mean visibility times its mean reflectance.
 */
export function doorwayLuminance(room: RoomGeometry, skyWeights: readonly number[]): number {
  if (room.openToSky) return OPEN_SKY_VISIBILITY
  return skyLitMeanVisibility(room, skyWeights) * room.surfaces.meanReflectance
}

/**
 * The weight of each aperture of a room, relative to the open sky: a sky aperture keeps its sky
 * weight, and a doorway takes the luminance of the room it opens to times its net transmittance.
 */
export function apertureWeights(
  room: RoomGeometry,
  skyWeights: readonly number[],
  doorwayLuminances: readonly number[],
): number[] {
  return room.apertures.map((aperture, index) =>
    aperture.kind === 'sky'
      ? (skyWeights[index] ?? 0)
      : (doorwayLuminances[aperture.neighbor] ?? 0) * aperture.netTransmittance,
  )
}

core/migrations/schema/add-environment-s.source:
import type { ProjectShape, SchemaMigration } from '../types'

/**
 * Migrates a version-14 document to version 15 by backfilling the top-level
 * `environmentScenes` array; an already-present array is preserved unchanged. The
 * orchestrator advances `meta.schemaVersion`, so the migration must not.
 */
export const addEnvironmentScenesMigration: SchemaMigration = {
  from: 14,
  migrate(project) {
    const environmentScenes = project.environmentScenes
    return {
      ...project,
      environmentScenes: Array.isArray(environmentScenes) ? environmentScenes : [],
    } satisfies ProjectShape
  },
}

core/migrations/schema/add-floor-dimensi.source:
import type { ProjectShape, SchemaMigration } from '../types'

/**
 * Migrates a version-3 document forward to version 4, which backfills the
 * per-floor `dimensions` array. The `openings` and `underlays` arrays already
 * exist at version 3, so only `dimensions` needs a default here.
 *
 * The array defaults to `[]` only when it is absent, preserving any
 * already-present array unchanged. The orchestrator advances
 * `meta.schemaVersion`, so the migration must not.
 */
export const addFloorDimensionsMigration: SchemaMigration = {
  from: 3,
  migrate(project) {
    const floors = project.floors
    if (!Array.isArray(floors)) {
      return project
    }
    const migratedFloors = floors.map((floor) => {
      const floorRecord = floor as Record<string, unknown>
      return {
        ...floorRecord,
        dimensions: Array.isArray(floorRecord.dimensions) ? floorRecord.dimensions : [],
      }
