import type { UnitSystem } from '../model/types'
import type { FormatLengthOptions } from './format-length'
import type { ImperialForm, MetricForm } from './length-units'
import type { DecimalPrecision, DisplayPrecision } from './precision'

export interface UnitPreferences {
  system: UnitSystem
  imperialForm: ImperialForm
  metricForm: MetricForm
  imperialLengthPrecision: DisplayPrecision
  metricLengthPrecision: DisplayPrecision
}

export const DEFAULT_IMPERIAL_PREFERENCES: UnitPreferences = {
  system: 'imperial',
  imperialForm: 'feet-and-inches',
  metricForm: 'meters',
  imperialLengthPrecision: { kind: 'fraction', denominator: 8 },
  metricLengthPrecision: { kind: 'decimal-places', places: 2 },
}

export const DEFAULT_METRIC_PREFERENCES: UnitPreferences = {
  system: 'metric',
  imperialForm: 'feet-and-inches',
  metricForm: 'meters',
  imperialLengthPrecision: { kind: 'fraction', denominator: 8 },
  metricLengthPrecision: { kind: 'decimal-places', places: 2 },
}

// Preferences are loaded from persisted project data, so the form/precision pairing
// is validated at runtime: only feet-and-inches can use a fraction precision, every
// other form is decimal-only. This narrows the precision to its decimal-places member
// and throws when the persisted data pairs a fraction with a decimal-only form.
function requireDecimalPlaces(precision: DisplayPrecision): DecimalPrecision {
  if (precision.kind === 'fraction') {
    throw new Error(
      'expected decimal-places precision for this form, received a fraction precision',
    )
  }
  return precision
}

/** Resolves the active system's form and precision into explicit format options. */
export function lengthFormatOptions(preferences: UnitPreferences): FormatLengthOptions {
  if (preferences.system === 'metric') {
    return {
      system: 'metric',
      form: preferences.metricForm,
      precision: requireDecimalPlaces(preferences.metricLengthPrecision),
    }
  }
  if (preferences.imperialForm === 'feet-and-inches') {
    // feet-and-inches passes the full DisplayPrecision through unchanged; it is the
    // only form that accepts a fraction precision.
    return {
      system: 'imperial',
      form: 'feet-and-inches',
      precision: preferences.imperialLengthPrecision,
    }
  }
  return {
    system: 'imperial',
    form: preferences.imperialForm,
    precision: requireDecimalPlaces(preferences.imperialLengthPrecision),
  }
}

core/geometry/point.ts.source:
import type { Point } from '../model/types'

/** Euclidean distance between two points, in millimeters. */
export function distance(a: Point, b: Point): number {
  return Math.hypot(b.x - a.x, b.y - a.y)
}

/** `point` shifted by `delta` (component-wise addition), in millimeters. */
export function translatePoint(point: Point, delta: Point): Point {
  return { x: point.x + delta.x, y: point.y + delta.y }
}

/** `point` rotated about `pivot` by `radians` (positive is counter-clockwise in plan space). */
export function rotatePoint(point: Point, pivot: Point, radians: number): Point {
  const cos = Math.cos(radians)
  const sin = Math.sin(radians)
  const dx = point.x - pivot.x
  const dy = point.y - pivot.y
  return {
    x: pivot.x + (dx * cos - dy * sin),
    y: pivot.y + (dx * sin + dy * cos),
  }
}

core/migrations/types.ts.source:
import type { SchemaVersion } from '../model/types'

/** A project document before validation; migrations operate structurally. */
export type ProjectShape = Record<string, unknown>

/** One forward schema migration from version `from` to `from + 1`. */
export interface SchemaMigration {
  readonly from: SchemaVersion
  /**
   * Transform the document's data only. The orchestrator advances
   * `meta.schemaVersion` after each step, so a migration must not set
   * `meta.schemaVersion` itself.
   */
  migrate(project: ProjectShape): ProjectShape
}

/** A per-registry migration applied after the schema chain. */
export interface RegistryMigration {
  readonly registry: string
  readonly from: number
  /**
   * Transform the document's data only. The orchestrator advances this
   * registry's entry in `meta.registryVersions` after each step, so a
   * migration must not set its own registry's version itself.
   */
  migrate(project: ProjectShape): ProjectShape
}

/** No migration bridges a required step. Carries the version it stalled at. */
export class MigrationFailedError extends Error {
  constructor(
    public readonly fromVersion: number,
    options?: { cause?: unknown },
  ) {
    super(`No migration from schema version ${fromVersion}`, options)
    this.name = 'MigrationFailedError'
  }
}

/** A document is not a recognizable project (missing or non-numeric meta.schemaVersion). */
export class MalformedProjectError extends Error {
  constructor(message = 'Project document is missing a numeric meta.schemaVersion') {
    super(message)
    this.name = 'MalformedProjectError'
  }
}

/** The document is newer than this build can read. */
export class UnsupportedSchemaVersionError extends Error {
  constructor(
    public readonly fromVersion: number,
    public readonly targetVersion: number,
  ) {
    super(`Schema version ${fromVersion} is newer than supported ${targetVersion}`)
    this.name = 'UnsupportedSchemaVersionError'
  }
}

