import type { Point } from '../model/types'

/** Cross products below this magnitude treat two edge directions as parallel. */
const PARALLEL_EPSILON = 1e-9

/** Squared edge lengths below this mark an effectively zero-length edge. */
const DEGENERATE_EDGE_EPSILON = 1e-9

/** Fewer vertices than this cannot bound an area, so they pass through unchanged. */
const MINIMUM_POLYGON_VERTICES = 3

/**
 * Snap-grid resolution, in units per millimeter, that offset corners round to:
 * each coordinate is snapped to the nearest 1/SNAP_UNITS_PER_MM of a millimeter.
 * A corner that mixes a zero and a nonzero edge offset comes from a shifted-line
 * intersection that carries IEEE-754 rounding noise far below the junction
 * tolerance, so it can land a fraction of a nanometer off its exact coordinate.
 * Snapping to this sub-micrometer grid clears that noise so abutting geometry
 * meets on exact coordinates, without disturbing any real geometry.
 */
const SNAP_UNITS_PER_MM = 1e6

/** An infinite line expressed as a point on it and a (non-unit) direction. */
interface Line {
  point: Point
  dir: Point
}

/**
 * Signed area of a polygon by the shoelace formula, in squared millimeters.
 * Positive for counter-clockwise winding, negative for clockwise.
 */
export function polygonArea(points: readonly Point[]): number {
  if (points.length === 0) return 0
  let sum = 0
  for (const [index, current] of points.entries()) {
    // points is non-empty (guarded above), so the wrap-around index is always
    // in bounds; the ?? only satisfies noUncheckedIndexedAccess and never runs.
    const next = points[(index + 1) % points.length] ?? current
    sum += current.x * next.y - next.x * current.y
  }
  return sum / 2
}

/** Arithmetic mean of the polygon vertices; the empty polygon yields the origin. */
export function polygonCentroid(polygon: readonly Point[]): Point {
  if (polygon.length === 0) {
    return { x: 0, y: 0 }
  }
  const sum = polygon.reduce((acc, point) => ({ x: acc.x + point.x, y: acc.y + point.y }), {
    x: 0,
    y: 0,
  })
  return { x: sum.x / polygon.length, y: sum.y / polygon.length }
}

/** True when `point` lies on the segment from `a` to `b` (collinear and within the span). */
function pointOnEdge(point: Point, a: Point, b: Point): boolean {
  const cross = (point.x - a.x) * (b.y - a.y) - (point.y - a.y) * (b.x - a.x)
  if (cross !== 0) {
    return false
  }
  const withinX = point.x >= Math.min(a.x, b.x) && point.x <= Math.max(a.x, b.x)
  const withinY = point.y >= Math.min(a.y, b.y) && point.y <= Math.max(a.y, b.y)
  return withinX && withinY
}

/**
 * Even-odd ray-casting test handling convex and non-convex polygons.
 *
 * Boundary rule: a point on an edge or vertex counts as inside. The crossing
 * loop uses a half-open edge convention (`a.y <= point.y < b.y` or its mirror),
 * so vertices are counted exactly once; the explicit on-edge check makes the
 * documented inclusive boundary deterministic rather than incidental.
 */
export function pointInPolygon(point: Point, polygon: readonly Point[]): boolean {
  let inside = false
  for (const [index, current] of polygon.entries()) {
    const previous = polygon[(index + polygon.length - 1) % polygon.length] ?? current
    if (pointOnEdge(point, previous, current)) {
      return true
    }
    const crossesRay = current.y > point.y !== previous.y > point.y
    if (crossesRay) {
      const intersectX =
        ((previous.x - current.x) * (point.y - current.y)) / (previous.y - current.y) + current.x
      if (point.x < intersectX) {
        inside = !inside
      }
    }
  }
  return inside
}

/**
 * Intersection of two infinite lines, or null when their directions are
 * parallel. Solves `lineA.point + t * lineA.dir == lineB.point + s * lineB.dir`.
 */
function intersectLines(lineA: Line, lineB: Line): Point | null {
  const denominator = lineA.dir.x * lineB.dir.y - lineA.dir.y * lineB.dir.x
  if (Math.abs(denominator) < PARALLEL_EPSILON) return null

  const offsetX = lineB.point.x - lineA.point.x
  const offsetY = lineB.point.y - lineA.point.y
  const t = (offsetX * lineB.dir.y - offsetY * lineB.dir.x) / denominator

  return { x: lineA.point.x + t * lineA.dir.x, y: lineA.point.y + t * lineA.dir.y }
}

/**
 * The shifted line for edge `index`: the edge direction, and a point on the edge
 * moved inward by `offset` along the inward unit normal. `inwardSign` is +1 for a
 * counter-clockwise polygon (interior to the left of each edge) and -1 otherwise.
 * A zero-length edge falls back to the previous vertex's direction.
 */
function shiftedEdgeLine(
  polygon: Point[],
  edgeOffsets: number[],
  context: { index: number; inwardSign: number },
): Line {
  const { index, inwardSign } = context
  const count = polygon.length
  // insetPolygon only calls this with count >= MINIMUM_POLYGON_VERTICES, so the
  // indexed lookups below are always in bounds; the ?? fallbacks exist solely to
  // satisfy noUncheckedIndexedAccess and never run.
  const start = polygon[index] ?? polygon[0]!
  const end = polygon[(index + 1) % count] ?? start
  let dx = end.x - start.x
  let dy = end.y - start.y
  if (dx * dx + dy * dy < DEGENERATE_EDGE_EPSILON) {
    const previous = polygon[(index + count - 1) % count] ?? start
    dx = start.x - previous.x
    dy = start.y - previous.y
  }
  // The `|| 1` is a best-effort guard for the second degenerate case: when the
  // edge and its predecessor share an endpoint (two identical adjacent vertices),
  // both fallbacks yield a zero-length direction and `|| 1` avoids dividing by 0.
  const length = Math.hypot(dx, dy) || 1
  const inwardX = (inwardSign * -dy) / length
  const inwardY = (inwardSign * dx) / length
  const offset = edgeOffsets[index] ?? 0
  return {
    point: { x: start.x + offset * inwardX, y: start.y + offset * inwardY },
    dir: { x: dx, y: dy },
  }
}

/** Clears the IEEE-754 dust left by `intersectLines`; see `SNAP_UNITS_PER_MM`. */
function snapCoordinate(value: number): number {
  return Math.round(value * SNAP_UNITS_PER_MM) / SNAP_UNITS_PER_MM
}

/** Snap every vertex so abutting geometry meets on exact coordinates. */
function snapPolygon(polygon: readonly Point[]): Point[] {
  return polygon.map((point) => ({ x: snapCoordinate(point.x), y: snapCoordinate(point.y) }))
}

/**
 * Each edge `i` (vertex `i` -> vertex `i+1`) is shifted inward by
 * `edgeOffsets[i]`; corners are the intersections of adjacent shifted-edge lines.
 * The winding is normalized via the shoelace sign so a clockwise input insets
 * inward too, with offsets staying aligned to edge indices. Parallel adjacent
 * edges keep the corner on their common shifted line. Best-effort on
 * self-intersection from over-inset.
 */
export function insetPolygon(polygon: Point[], edgeOffsets: number[]): Point[] {
  const count = polygon.length
  if (count < MINIMUM_POLYGON_VERTICES) return [...polygon]

  const inwardSign = polygonArea(polygon) >= 0 ? 1 : -1
  const lines = polygon.map((_, index) =>
    shiftedEdgeLine(polygon, edgeOffsets, { index, inwardSign }),
  )

  const corners = lines.map((current, index) => {
    const previous = lines[(index + count - 1) % count]!
    return intersectLines(previous, current) ?? current.point
  })
  return snapPolygon(corners)
}

/**
 * Outward mirror of `insetPolygon`: each edge `i` is shifted outward by
 * `edgeOffsets[i]`, tracing for a room the outer wall faces rather than the
 * inner ones. Equivalent to insetting by the negated offsets, so it inherits the
 * same winding normalization and best-effort behavior on degenerate corners.
 */
export function outsetPolygon(polygon: Point[], edgeOffsets: number[]): Point[] {
  return insetPolygon(
    polygon,
    edgeOffsets.map((offset) => -offset),
  )
}

core/units/length-bounds.ts.source:
// Shared positivity and range guard for millimetre dimensions. Command handlers
// call it before storing a value so out-of-range geometry never commits. The
// 100 m ceiling matches the MAX_DIMENSION_MM precedent in
// core/assets/pack-manifest.ts so the inspector and the pack validator agree on
// what a sane millimetre dimension is.

/** The smallest accepted dimension (1 mm); the guard rejects anything below it. */
export const MIN_POSITIVE_LENGTH_MM = 1

/** The absurd-max ceiling (100 m); the guard rejects anything above it. */
export const MAX_LENGTH_MM = 100_000

/** A dimension fell outside the accepted length range. */
export class InvalidLengthError extends Error {
  constructor(
    public readonly label: string,
    public readonly valueMm: number,
    message?: string,
  ) {
    super(message ?? `${label} must be a positive length up to 100 m`)
    this.name = 'InvalidLengthError'
  }
}

/**
 * Throw InvalidLengthError when `valueMm` is not a finite positive length within
 * the accepted range; otherwise return.
 */
export function assertPositiveLength(valueMm: number, label: string): void {
  if (!Number.isFinite(valueMm) || valueMm < MIN_POSITIVE_LENGTH_MM || valueMm > MAX_LENGTH_MM) {
    throw new InvalidLengthError(label, valueMm)
  }
}

/**
 * Throw InvalidLengthError when `valueMm` is not a finite non-negative length
 * within the accepted range; otherwise return. Allows 0 (for example an opening
 * sill that sits on the floor) while still rejecting negatives and the absurd-max.
 */
export function assertNonNegativeLength(valueMm: number, label: string): void {
  if (!Number.isFinite(valueMm) || valueMm < 0 || valueMm > MAX_LENGTH_MM) {
    throw new InvalidLengthError(label, valueMm, `${label} must be 0 or greater, up to 100 m`)
  }
}

core/daylight/sky-visibility.ts.source:
import type { Vector3 } from '../scene/vector3'
import type { DaylightField, DaylightRoom } from './daylight-field'
import { OPEN_SKY_VISIBILITY } from './daylight-field'
import { apertureWeights, doorwayLuminance } from './doorway-light'
import { cellVisibility, enteringFlux, roomAverageTerm } from './room-average'
import type { RoomGeometry, SolverGeometry } from './room-geometry'
import { measureGeometry } from './room-geometry'

export { UNPAINTED_SURFACE_REFLECTANCE } from './room-average'
export { DAYLIGHT_WORK_PLANE_HEIGHT_MM } from './room-geometry'

/**
 * Relative radiance of the sky toward a world direction (unit vector, Y up); 1 is the mean of the
 * open sky, so a brighter part of the dome lets more light through a window that faces it.
 */
export type SkyLuminance = (direction: Vector3) => number

/** A sky of the same radiance in every direction: each window passes its bare form factor. */
export const UNIFORM_SKY: SkyLuminance = () => 1

/** Computes the sky visibility of the rooms of one floor for any sky, from geometry it measures once. */
export interface DaylightFieldSolver {
  /** The field for this sky; each cell holds the share of open-sky light it receives. */
  field(sky: SkyLuminance): DaylightField
  /**
   * Light that enters the room through its apertures, in plan square millimetres of open sky: half
   * of each opening's area times its net transmittance times the radiance it faces, relative to
   * the open sky.
   */
  enteringFlux(room: number, sky: SkyLuminance): number
  /**
   * Share of open-sky light that reaches every point of the room after bouncing between surfaces.
   */
  interreflection(room: number, sky: SkyLuminance): number
  /** How many times the solver has measured the aperture-to-cell form factors. */
  readonly geometryPasses: number
}

/** The light of one room under one sky. */
interface RoomLight {
  /** Weight of each aperture, relative to the open sky. */
  weights: readonly number[]
  enteringFlux: number
  interreflection: number
}

/**
 * Reads the sky's radiance toward a direction as a weight: a value below 0 or `NaN` is no light,
 * so it counts as 0. A value above 1 is legal (a part of the dome brighter than the mean), so
 * nothing caps it here; only a cell's final visibility is capped.
 */
function readSkyRadiance(sky: SkyLuminance, direction: Vector3): number {
  const radiance = sky(direction)
  return Number.isNaN(radiance) || radiance < 0 ? 0 : radiance
}

function skyWeights(room: RoomGeometry, sky: SkyLuminance): number[] {
  return room.apertures.map((aperture) =>
    aperture.kind === 'sky'
      ? readSkyRadiance(sky, aperture.direction) * aperture.netTransmittance
      : 0,
  )
}

/** Weights every aperture of every room by the sky, then sums each room's entering flux. */
function lightRooms(geometry: SolverGeometry, sky: SkyLuminance): RoomLight[] {
  const skyOnly = geometry.rooms.map((room) => skyWeights(room, sky))
  const doorwayLuminances = geometry.rooms.map((room, index) =>
    doorwayLuminance(room, skyOnly[index] ?? []),
  )
  return geometry.rooms.map((room, index) => {
    const weights = apertureWeights(room, skyOnly[index] ?? [], doorwayLuminances)
    const flux = enteringFlux(room.apertures, weights)
    return { weights, enteringFlux: flux, interreflection: roomAverageTerm(flux, room.surfaces) }
  })
}

/**
 * Weights the cached form factors, then copies each source value into its cell under a wall.
 * Open-sky rooms and the other cells in no room keep 1.
 */
function fillField(geometry: SolverGeometry, light: readonly RoomLight[]): DaylightField {
  const field = {
    ...geometry.grid,
    origin: { ...geometry.grid.origin },
    data: geometry.grid.data.slice(),
  }
  for (const [roomIndex, room] of geometry.rooms.entries()) {
    const roomLight = light[roomIndex]
    if (room.openToSky || roomLight === undefined) continue
    for (const cell of room.cells) {
      field.data[cell.visibilityIndex] = cellVisibility(
        cell.factors,
        roomLight.weights,
        roomLight.interreflection,
      )
    }
  }
  for (const copy of geometry.cellsUnderWalls) {
    field.data[copy.targetIndex] = field.data[copy.sourceIndex] ?? OPEN_SKY_VISIBILITY
  }
  return field
}

/**
 * Creates a solver for the rooms of one floor. A cell's visibility is the sum over its room's
 * apertures of the form factor from the cell center at the work plane to the opening, times the
 * opening's weight, plus the room-average term, capped at 1. A sky aperture weighs the sky's
 * radiance toward its facing times its net transmittance; a doorway weighs the luminance of the
 * room it opens to times its net transmittance (that luminance is its mean
 * visibility, lit by that room's sky apertures alone, times its mean reflectance; 1 for a room
 * open to the sky). A cell whose center lies in no room, with a cell of a room (a room open to the
 * sky counts) among its eight neighbors, holds the sky visibility of one such neighbor; only cells
 * whose center lies in a room are sources. The room is the one whose outline lies nearest the
 * cell's center, and on an equal distance the first in the input; among its neighbors the source is
 * the nearest, and on a tie the first in the order left, right, below, above, lower left, lower
 * right, upper left, upper right. Every other cell in no room holds 1. The form factors depend on
 * geometry alone, so the solver checks and measures the rooms one time, and only re-weights them
 * for later skies; a caller that changes the rooms builds a new solver. That check runs on the
 * first call of any method, not when the solver is created, so a room or an aperture that the
 * field cannot use throws a RangeError that names it from that first call.
 */
export function createDaylightFieldSolver(rooms: readonly DaylightRoom[]): DaylightFieldSolver {
  let geometry: SolverGeometry | null = null
  let geometryPasses = 0
  const measuredGeometry = (): SolverGeometry => {
    if (geometry === null) {
      geometry = measureGeometry(rooms)
      geometryPasses += 1
    }
    return geometry
  }
  const roomLight = (room: number, sky: SkyLuminance): RoomLight | undefined =>
    lightRooms(measuredGeometry(), sky)[room]
  return {
    field: (sky) => fillField(measuredGeometry(), lightRooms(measuredGeometry(), sky)),
    enteringFlux: (room, sky) => roomLight(room, sky)?.enteringFlux ?? 0,
    interreflection: (room, sky) => roomLight(room, sky)?.interreflection ?? 0,
    get geometryPasses() {
      return geometryPasses
    },
  }
}

