import type { Color } from '../color/color'

/**
 * A reference to a paintable surface. The scene graph does not yet model wall
 * faces, floor surfaces, or ceilings as first-class nodes, so a surface is
 * addressed by the model entity it belongs to plus a discriminator. When the
 * three-dimensional track adds surface nodes, they carry this same SurfaceRef so
 * the painted preview reads the paint store keyed below.
 */
export type SurfaceRef =
  // `region` is the optional face-subdivision seam (ADR-0056); absent means the whole face.
  | { kind: 'wall-face'; wallId: string; side: 'left' | 'right'; region?: string }
  | { kind: 'floor'; floorId: string }
  | { kind: 'ceiling'; floorId: string }

/**
 * A surface treatment. Solid color and pattern are the built variants; the
 * discriminated `kind` keeps `tiled-image` as a future extension seam (ADR-0056).
 * A `pattern` treatment names a floor-pattern registry entry plus the repeat scale
 * (in millimeters) and the resolved colors the pattern is drawn in.
 */
export type SurfaceTreatment =
  | { kind: 'solid'; color: Color; finishId: string }
  | { kind: 'pattern'; patternId: string; scale: number; colors: Color[] }

export function solidTreatment(color: Color, finishId: string): SurfaceTreatment {
  return { kind: 'solid', color, finishId }
}

export function patternTreatment(
  patternId: string,
  scale: number,
  colors: Color[],
): SurfaceTreatment {
  return { kind: 'pattern', patternId, scale, colors }
}

/** The sRGB hex a 2D plan tints a surface with: the solid color, or a pattern's base color. */
export function surfaceTintHex(treatment: SurfaceTreatment): string {
  if (treatment.kind === 'solid') {
    return treatment.color.srgbHex
  }
  const base = treatment.colors[0]
  return base === undefined ? NEUTRAL_TINT_HEX : base.srgbHex
}

/** The fallback tint for a pattern with no colors, which the registry never seeds. */
const NEUTRAL_TINT_HEX = '#d8d4cc'

/** The stable string key the paint store is keyed by. Derivation-independent. */
export function surfaceKey(ref: SurfaceRef): string {
  switch (ref.kind) {
    case 'wall-face':
      return ref.region === undefined
        ? `wall-face:${ref.wallId}:${ref.side}`
        : `wall-face:${ref.wallId}:${ref.side}:${ref.region}`
    case 'floor':
      return `floor:${ref.floorId}`
    case 'ceiling':
      return `ceiling:${ref.floorId}`
  }
}

core/model/site.ts.source:
import type { Point } from './types'

/** A geographic location in decimal degrees. */
export interface LatLong {
  latitude: number
  longitude: number
}

/**
 * A top-down massing footprint of a nearby structure or tree, with a height.
 * A non-rendering placeholder (design spec 3.1 and Phase 6); the Phase-8 solar
 * lighting provider would later consume these for obstruction shadows.
 */
export interface Obstruction {
  id: string
  /** Footprint polygon in the plan frame, in world millimeters. */
  footprint: Point[]
  /** Massing height in millimeters. */
  height: number
}

/**
 * Ground-surface grade datum, in millimeters, used when a site carries no explicit
 * grade. Above-grade floors sit at positive elevations and basements at negative
 * ones relative to this datum (ADR-0131).
 */
export const DEFAULT_GRADE_ELEVATION_MM = 0

/** Optional project site metadata (design spec 3.1). */
export interface Site {
  latLong?: LatLong
  /** Angle from plan-up to true north, in radians (matching UnderlayPlacement.rotation). */
  northBearing?: number
  obstructions?: Obstruction[]
  /**
   * Ground-surface elevation in millimeters: the datum the ground plane sits at and
   * the threshold the whole-building view treats as below grade. Absent means the
   * 0 datum, decoupling grade from the finished-floor-zero convention only when set.
   */
  gradeElevation?: number
  /**
   * IANA time-zone identifier for the site, for example `America/New_York`. Used
   * with the site location and an observation instant to place the sun (slice 1a).
   * Absent means the timezone has not been set.
   */
  timezone?: string
}

/** The site's explicit grade elevation, or the default datum when none is set. */
export function resolveGradeElevation(site?: Site): number {
  return site?.gradeElevation ?? DEFAULT_GRADE_ELEVATION_MM
}

core/scene/scene-graph.ts.source:
import { dimensionLength } from '../geometry/dimension'
import type { AssetReference } from '../model/asset-reference'
import { furnitureFootprintCorners } from '../model/furniture-footprint'
import { effectiveWallThickness } from './construction-profile'
import { withRoomSide } from './opening-room-side'
import { assembleSceneGraph } from './scene-graph-assembly'
import type { SceneNodeDerivations } from './scene-graph-assembly'
import type {
  Dimension,
  Floor,
  FurnitureInstance,
  Opening,
  OpeningOrientation,
  Point,
  Project,
  RoomOverride,
  StairRunType,
  Underlay,
  UnderlayPlacement,
  UnderlaySource,
  Wall,
} from '../model/types'
import { deriveOpeningGeometry } from '../topology/openings'
import { applyRoomOverrides, deriveRooms } from '../topology/rooms'

// Kind-prefixed ids keep node ids globally unique within the scene graph.
export const FLOOR_NODE_PREFIX = 'floor:'
export const WALL_NODE_PREFIX = 'wall:'
export const UNDERLAY_NODE_PREFIX = 'underlay:'
export const OPENING_NODE_PREFIX = 'opening:'
export const DIMENSION_NODE_PREFIX = 'dimension:'
export const STAIR_NODE_PREFIX = 'stair:'
export const FURNITURE_NODE_PREFIX = 'furniture:'

export interface SceneNode {
  id: string
  kind: 'floor'
  name: string
  elevation: number
}

export interface WallSceneNode {
  id: string
  kind: 'wall'
  floorId: string
  start: Point
  end: Point
  thickness: number
  /**
   * Per-wall height in floor-plan units. Nodes from `deriveWallNode` always
   * carry it, sourced from the host floor's `defaultCeilingHeight`. It is
   * optional because hand-built `WallSceneNode` literals (chiefly the 2D
   * editor's fixtures) omit it; `wallHeight` supplies the
   * `DEFAULT_CEILING_HEIGHT_MM` fallback for those literal-built nodes.
   */
  height?: number
  /**
   * The wall's ConstructionProfileRegistry id when it carries one; resolved to a
   * footprint thickness by `effectiveWallThickness`.
   */
  constructionProfile?: string
}

export interface RoomSceneNode {
  id: string
  kind: 'room'
  floorId: string
  polygon: Point[]
  /** The thickness-aware clear-area polygon from the derived room. */
  clearPolygon: Point[]
  /**
   * The boundary at the bounding walls' outer faces (the gross-area boundary):
   * the mirror of `clearPolygon`, sourced from the derived room's
   * `outerPolygon`. It is optional because hand-built `RoomSceneNode` literals
   * (chiefly fixtures) omit it; the floor-slab builder supplies a
   * `clearPolygon` fallback for those literal-built nodes.
   */
  outerPolygon?: Point[]
  area: number
  name?: string
  /** Interior void rings in floor-plan space, mirroring the derived room's holes. */
  holes?: Point[][]
  /**
   * Ceiling height in floor-plan units. Nodes from `deriveRoomNodesForFloor`
   * always carry it, sourced from the host floor's `defaultCeilingHeight`. It is
   * optional because hand-built `RoomSceneNode` literals (chiefly fixtures) omit
   * it; `ceilingHeight` supplies the `DEFAULT_CEILING_HEIGHT_MM` fallback for
   * those literal-built nodes.
   */
  ceilingHeight?: number
}

export interface UnderlaySceneNode {
  id: string
  kind: 'underlay'
  floorId: string
  source: UnderlaySource
  width: number
  height: number
  placement: UnderlayPlacement
  opacity: number
  visible: boolean
}

export interface OpeningSceneNode {
  id: string
  kind: 'opening'
  floorId: string
  /** ElementType id, category 'opening'. */
  type: string
  center: Point
  along: Point
  normal: Point
  width: number
  height: number
  sillHeight: number
  /**
   * The host wall's effective assembly thickness: resolved through its
   * construction profile via `effectiveWallThickness`, falling back to the
   * raw wall thickness when it carries no profile.
   */
  hostThickness: number
  orientation: OpeningOrientation
  /**
   * Id of the wall this opening cuts. Nodes from `deriveOpeningNode` always
   * carry it, sourced from the opening's host wall. It is optional because
   * hand-built `OpeningSceneNode` literals (chiefly fixtures) omit it; the
   * opening-to-edge resolver treats its absence as an opening it cannot place.
   */
  hostWallId?: string
  /**
   * Derived, never stored: the sign of `normal` that points into the room at the opening's center,
   * from openingRoomSide. Omitted when both sides or neither side of the wall lie in a room there.
   * A hung window puts its lower sash on this side; `orientation.facing` decides when it is absent.
   */
  roomSide?: OpeningOrientation['facing']
}

export interface DimensionSceneNode {
  id: string
  kind: 'dimension'
  floorId: string
  start: Point
  end: Point
  offset: number
  length: number
}

export interface StairSceneNode {
  id: string
  kind: 'stair'
  floorId: string
  runType: StairRunType
  position: Point
  width: number
  length: number
  rotation: number
  wellFloorId: string
}

export interface FurnitureSceneNode {
  id: string
  kind: 'furniture'
  floorId: string
  /** Plan-space mm corners from furnitureFootprintCorners(position, rotation, footprint). */
  footprintCorners: [Point, Point, Point, Point]
  /** Box base, mm above the floor. */
  elevationZ: number
  /** Box rises to elevationZ + height, mm. */
  height: number
  /** Content-addressed reference to this piece's asset, for the model loader. */
  assetRef: AssetReference
  /** The user-set display name; absent when the user never named the item. */
  name?: string
}

export interface SceneGraph {
  nodes: SceneNode[]
  walls: WallSceneNode[]
  rooms: RoomSceneNode[]
  underlays: UnderlaySceneNode[]
  openings: OpeningSceneNode[]
  dimensions: DimensionSceneNode[]
  stairs: StairSceneNode[]
  furniture: FurnitureSceneNode[]
  /**
   * Ground-surface grade datum in millimeters for this projection. Optional so
   * hand-built literals omit it; `deriveSceneGraph` always sets it and readers
   * default to the 0 datum. Callers that narrow the graph forward this field so
   * the underground filter and the engine ground plane read the right datum.
   */
  gradeElevation?: number
}

export function deriveFloorNode(floor: Floor): SceneNode {
  return {
    id: `${FLOOR_NODE_PREFIX}${floor.id}`,
    kind: 'floor',
    name: floor.name,
    elevation: floor.elevation,
  }
}

export function deriveWallNode(floor: Floor, wall: Wall): WallSceneNode {
  return {
    id: `${WALL_NODE_PREFIX}${wall.id}`,
    kind: 'wall',
    floorId: floor.id,
    start: wall.start,
    end: wall.end,
    thickness: wall.thickness,
    height: floor.defaultCeilingHeight,
    ...(wall.constructionProfile === undefined
      ? {}
      : { constructionProfile: wall.constructionProfile }),
  }
}

export function deriveUnderlayNode(floor: Floor, underlay: Underlay): UnderlaySceneNode {
  return {
    id: `${UNDERLAY_NODE_PREFIX}${underlay.id}`,
    kind: 'underlay',
    floorId: floor.id,
    source: underlay.source,
    width: underlay.width,
    height: underlay.height,
    placement: underlay.placement,
    opacity: underlay.opacity,
    visible: underlay.visible,
  }
}

export function deriveUnderlayNodesForFloor(floor: Floor): UnderlaySceneNode[] {
  return floor.underlays.map((underlay) => deriveUnderlayNode(floor, underlay))
}

export function deriveOpeningNode(
  floor: Floor,
  opening: Opening,
  hostWall: Wall,
): OpeningSceneNode {
  const geometry = deriveOpeningGeometry(opening, hostWall)
  return {
    id: `${OPENING_NODE_PREFIX}${opening.id}`,
    kind: 'opening',
    floorId: floor.id,
    hostWallId: hostWall.id,
    type: opening.type,
    center: geometry.center,
    along: geometry.along,
    normal: geometry.normal,
    width: geometry.width,
    height: opening.height,
    sillHeight: opening.sillHeight,
    hostThickness: effectiveWallThickness(hostWall),
    orientation: opening.orientation,
  }
}

export function deriveOpeningNodesForFloor(
  floor: Floor,
  rooms: readonly RoomSceneNode[],
): OpeningSceneNode[] {
  return floor.openings.flatMap((opening) => {
    const hostWall = floor.walls.find((wall) => wall.id === opening.hostWallId)
    return hostWall ? [withRoomSide(deriveOpeningNode(floor, opening, hostWall), rooms)] : []
  })
}

export function deriveDimensionNode(floor: Floor, dimension: Dimension): DimensionSceneNode {
  return {
    id: `${DIMENSION_NODE_PREFIX}${dimension.id}`,
    kind: 'dimension',
    floorId: floor.id,
    start: dimension.start,
    end: dimension.end,
    offset: dimension.offset,
    length: dimensionLength(dimension),
  }
}

export function deriveDimensionNodesForFloor(floor: Floor): DimensionSceneNode[] {
  return floor.dimensions.map((dimension) => deriveDimensionNode(floor, dimension))
}

export function deriveFurnitureNode(floor: Floor, item: FurnitureInstance): FurnitureSceneNode {
  return {
    id: `${FURNITURE_NODE_PREFIX}${item.id}`,
    kind: 'furniture',
    floorId: floor.id,
    footprintCorners: furnitureFootprintCorners(item.position, item.rotation, item.footprint),
    elevationZ: item.elevationZ,
    height: item.height,
    assetRef: item.assetRef,
    // Omit the optional name when absent; exactOptionalPropertyTypes rejects
    // assigning an explicit undefined to the optional field.
    ...(item.name !== undefined && { name: item.name }),
  }
}

export function deriveRoomNodesForFloor(
  floor: Floor,
  overrides?: Readonly<Record<string, RoomOverride>>,
): RoomSceneNode[] {
  return applyRoomOverrides(deriveRooms(floor.walls), overrides).map((room) => ({
    // room.id already carries the `room:` namespace prefix from the topology
    // layer (see core/topology/rooms.ts), so it is used directly here rather
    // than re-prefixed, unlike the locally namespaced floor and wall node ids.
    id: room.id,
    kind: 'room',
    floorId: floor.id,
    polygon: room.polygon,
    clearPolygon: room.clearPolygon,
    outerPolygon: room.outerPolygon,
    area: room.area,
    ceilingHeight: room.ceilingHeight ?? floor.defaultCeilingHeight,
    // Omit the optional name when absent so the no-overrides projection stays
    // identical to slice 1 under exactOptionalPropertyTypes.
    ...(room.name !== undefined && { name: room.name }),
    // Omit holes for a plain room so its projection stays identical under
    // exactOptionalPropertyTypes; only a donut or courtyard room carries them.
    ...(room.holes !== undefined && { holes: room.holes }),
  }))
}

export function deriveStairNodes(project: Project): StairSceneNode[] {
  return project.stairs.map((stair) => ({
    id: `${STAIR_NODE_PREFIX}${stair.id}`,
    kind: 'stair',
    floorId: stair.connection.fromFloorId,
    runType: stair.runType,
    position: stair.position,
    width: stair.width,
    length: stair.length,
    rotation: stair.rotation,
    wellFloorId: stair.connection.toFloorId,
  }))
}

/**
 * The pure derivation of each kind of node. The memoized deriver spreads this set
 * and replaces the members it caches, so a new member falls back to the pure
 * function until it opts into a cache.
 */
export const PURE_NODE_DERIVATIONS: SceneNodeDerivations = {
  floorNode: deriveFloorNode,
  wallNode: deriveWallNode,
  roomNodes: deriveRoomNodesForFloor,
  underlayNodes: deriveUnderlayNodesForFloor,
  openingNodes: deriveOpeningNodesForFloor,
  dimensionNodes: deriveDimensionNodesForFloor,
  stairNodes: deriveStairNodes,
  furnitureNode: deriveFurnitureNode,
}

/** Pure projection of the project model into a normalized scene graph. */
export function deriveSceneGraph(project: Project): SceneGraph {
  return assembleSceneGraph(project, PURE_NODE_DERIVATIONS)
}

