import { describe, it, expect, afterEach, vi } from 'vitest'
import { render, screen, cleanup, act, within, fireEvent } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { EditorShell, type EditorShellProps } from './editor-shell'
import { ActiveToolProvider } from '../tools/active-tool-provider'
import { EditLayerProvider } from '../tools/edit-layer-provider'
import {
  ActiveFloorProvider,
  EditorSessionProvider,
  SceneSessionProvider,
  SelectionProvider,
  createActiveFloorStore,
  createSelectionStore,
} from '../../bridge'
import { createEditorSession } from '../../session/testing'
import { createEmptyProject, createFloor, type Project } from '../../core'
import { ThemeProvider } from '../design-system'
import { NotificationProvider } from '../design-system/notifications/use-notifications'
import { PAINT_PICKER_SLOT, PAINT_INSPECTOR_SLOT } from './shell-panel-slots'

// Every bridge export stays real; the scene session provider is wrapped in a
// passthrough spy so this file can read the props the shell hands it.
vi.mock('../../bridge', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../../bridge')>()
  return {
    ...actual,
    // A component export legitimately keeps its PascalCase name in the mock.
    // eslint-disable-next-line @typescript-eslint/naming-convention
    SceneSessionProvider: vi.fn(actual.SceneSessionProvider),
  }
})

function projectWithFloor(): Project {
  const project = createEmptyProject({
    name: 'Test',
    units: 'imperial',
    period: 'modern',
    appVersion: '0.0.0',
  })
  project.floors = [createFloor('Ground', { id: 'g' })]
  return project
}

function renderShell(props: Partial<EditorShellProps> = {}) {
  const session = createEditorSession(projectWithFloor())
  const selection = createSelectionStore()
  const activeFloor = createActiveFloorStore(session.getProject().floors[0]?.id ?? null)
  const { container } = render(
    <NotificationProvider>
      <ThemeProvider>
        <EditorSessionProvider session={session}>
          <SelectionProvider store={selection}>
            <ActiveFloorProvider store={activeFloor}>
              <ActiveToolProvider>
                <EditLayerProvider>
                  <EditorShell saveStatus="idle" {...props} />
                </EditLayerProvider>
              </ActiveToolProvider>
            </ActiveFloorProvider>
          </SelectionProvider>
        </EditorSessionProvider>
      </ThemeProvider>
    </NotificationProvider>,
  )
  return { session, selection, container }
}

describe('EditorShell', () => {
  afterEach(() => {
    cleanup()
    vi.unstubAllGlobals()
    vi.mocked(SceneSessionProvider).mockClear()
  })

  it('renders labeled toolbar, tools, viewport, and inspector regions', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.getByRole('banner')).toBeInTheDocument()
    expect(screen.getByRole('heading', { level: 1, name: /vernacular/i })).toBeInTheDocument()
    expect(screen.getByRole('navigation', { name: /tools/i })).toBeInTheDocument()
    expect(screen.getByRole('main', { name: /viewport/i })).toBeInTheDocument()
    expect(screen.getByRole('complementary', { name: /inspector/i })).toBeInTheDocument()
    expect(screen.getByLabelText(/floor plan/i)).toBeInTheDocument()
  })

  it('renders the brand mark beside the wordmark', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    const banner = screen.getByRole('banner')
    expect(within(banner).getByRole('img', { name: /vernacular/i })).toBeInTheDocument()
  })

  it('shows only the current project name in the breadcrumb', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    const breadcrumb = screen.getByRole('navigation', { name: /breadcrumb/i })

    // The single-project model has no projects list, so the false "My Projects"
    // parent crumb and the leading separator are gone.
    expect(within(breadcrumb).queryByText(/my projects/i)).not.toBeInTheDocument()
    expect(within(breadcrumb).getByText('Test')).toBeInTheDocument()
    expect(breadcrumb.textContent?.startsWith('/')).toBe(false)
    expect(breadcrumb.textContent).toContain('Test')
  })

  it('reveals the 3D preview when the 3D view mode is selected', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell()

    expect(screen.queryByRole('region', { name: /3d preview/i })).toBeNull()

    await user.click(screen.getByRole('button', { name: '3D view' }))

    expect(screen.getByRole('region', { name: /3d preview/i })).toBeInTheDocument()
  })

  it('renders a primary Export button in the toolbar', () => {
    vi.stubGlobal('navigator', {})

    renderShell({ onExportBundle: vi.fn() })

    const exportBtn = screen.getByRole('button', { name: /^export$/i })
    expect(exportBtn).toHaveClass('ds-button--primary')
  })

  it('renders single Undo and Redo buttons and no command-palette button in the toolbar', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.queryAllByRole('button', { name: /undo/i })).toHaveLength(1)
    expect(screen.queryAllByRole('button', { name: /redo/i })).toHaveLength(1)
    expect(screen.queryByRole('button', { name: /command palette/i })).toBeNull()
  })

  it('renders a theme toggle in the toolbar', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    const themeGroup = screen.getByRole('group', { name: /theme/i })
    expect(themeGroup).toBeInTheDocument()
    expect(within(themeGroup).getByRole('button', { name: /system/i })).toBeInTheDocument()
  })

  it('renders Grid and Dimensions toggle buttons in the toolbar', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.getByRole('button', { name: /grid/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /dimensions/i })).toBeInTheDocument()
  })

  it('shows visible text labels on the Grid and Dimensions toggles', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(
      within(screen.getByRole('button', { name: /grid/i })).getByText('Grid'),
    ).toBeInTheDocument()
    expect(
      within(screen.getByRole('button', { name: /dimensions/i })).getByText('Dimensions'),
    ).toBeInTheDocument()
  })

  it('does not advertise unregistered keyboard shortcuts on the Grid and Dimensions toggles', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    const gridBtn = screen.getByRole('button', { name: /grid/i })
    const dimensionsBtn = screen.getByRole('button', { name: /dimensions/i })

    // ADR-0155 withholds new keybindings pending the deliverability audit, so the
    // toolbar must not hint at a Grid or Dimensions shortcut that isn't registered.
    expect(gridBtn.getAttribute('title')).not.toMatch(/\(g\)/i)
    expect(dimensionsBtn.getAttribute('title')).not.toMatch(/\(d\)/i)
  })

  it('toggles the Grid button aria-pressed on click', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell()

    const gridBtn = screen.getByRole('button', { name: /grid/i })
    expect(gridBtn).toHaveAttribute('aria-pressed', 'true')

    await user.click(gridBtn)
    expect(gridBtn).toHaveAttribute('aria-pressed', 'false')
  })

  it('makes the Grid and Dimensions toggles inert while the 3D view holds the viewport', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell()
    const gridBtn = screen.getByRole('button', { name: /grid/i })
    const dimensionsBtn = screen.getByRole('button', { name: /dimensions/i })

    await user.click(screen.getByRole('button', { name: '3D view' }))

    // Both toggles describe layers of the 2D plan, which the 3D view mode does not
    // show, so they steer nothing there and say why on hover.
    expect(gridBtn).toBeDisabled()
    expect(dimensionsBtn).toBeDisabled()
    expect(gridBtn.getAttribute('title')).toMatch(/plan/i)
    expect(dimensionsBtn.getAttribute('title')).toMatch(/plan/i)

    await user.click(screen.getByRole('button', { name: 'Plan view' }))

    expect(gridBtn).toBeEnabled()
    expect(dimensionsBtn).toBeEnabled()
    expect(gridBtn.getAttribute('title')).toBe('Grid')
    expect(dimensionsBtn.getAttribute('title')).toBe('Dimensions')
  })

  it('routes the Grid, Dimensions, Undo, and Redo header buttons through the IconButton primitive', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell()

    const gridBtn = screen.getByRole('button', { name: /grid/i })
    const dimensionsBtn = screen.getByRole('button', { name: /dimensions/i })
    const undoBtn = screen.getByRole('button', { name: /undo/i })
    const redoBtn = screen.getByRole('button', { name: /redo/i })

    // Migrated to the design-system IconButton primitive (ds-icon-button), not the
    // retired hand-rolled editor-shell__icon-btn idiom.
    expect(gridBtn).toHaveClass('ds-icon-button')
    expect(dimensionsBtn).toHaveClass('ds-icon-button')
    expect(undoBtn).toHaveClass('ds-icon-button')
    expect(redoBtn).toHaveClass('ds-icon-button')
    expect(gridBtn).not.toHaveClass('editor-shell__icon-btn')

    // The labeled toggles keep their visible text label after migration.
    expect(within(gridBtn).getByText('Grid')).toBeInTheDocument()
    expect(within(dimensionsBtn).getByText('Dimensions')).toBeInTheDocument()

    // Behavior is preserved: the Grid toggle still flips aria-pressed on click.
    expect(gridBtn).toHaveAttribute('aria-pressed', 'true')
    await user.click(gridBtn)
    expect(gridBtn).toHaveAttribute('aria-pressed', 'false')
  })

  it('no longer shows the dev wall-count paragraph in the toolbar', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.queryByText(/walls:/i)).toBeNull()
  })

  it('shows the selected state in the inspector', () => {
    vi.stubGlobal('navigator', {})

    const { selection } = renderShell()
    act(() => {
      selection.select('wall:a')
    })

    // The selection surfaces as the Wall component title and the count badge, not a
    // placeholder body string.
    expect(screen.getByRole('heading', { level: 3, name: /wall/i })).toBeInTheDocument()
    expect(screen.getByText('1 selected')).toBeInTheDocument()
  })

  it('shows the active tool in the status bar', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.getByText(/tool: select/i)).toBeInTheDocument()
  })

  it('invokes the new and export handlers when their controls are used', async () => {
    vi.stubGlobal('navigator', {})
    const onNewProject = vi.fn()
    const onExportBundle = vi.fn()
    const user = userEvent.setup()

    renderShell({ onNewProject, onExportBundle })

    // New lives in the project menu near the wordmark; Export is the single
    // dominant header action now that autosave persists every change.
    await user.click(screen.getByRole('button', { name: /project/i }))
    await user.click(screen.getByRole('menuitem', { name: /new project/i }))
    await user.click(screen.getByRole('button', { name: /^export$/i }))
    await user.click(screen.getByRole('menuitem', { name: /bundle/i }))

    expect(onNewProject).toHaveBeenCalledTimes(1)
    expect(onExportBundle).toHaveBeenCalledTimes(1)
  })

  it('drops the manual Save button now that autosave persists changes', () => {
    vi.stubGlobal('navigator', {})

    renderShell({ onSave: vi.fn() })

    expect(screen.queryByRole('button', { name: /^save$/i })).toBeNull()
  })

  it('invokes the save handler on Mod+S', () => {
    vi.stubGlobal('navigator', {})
    const onSave = vi.fn()

    renderShell({ onSave })

    // navigator is the non-mac stub, so Mod resolves to the Ctrl key. The
    // keybinding layer listens on window for the global Mod+S save shortcut.
    fireEvent.keyDown(window, { key: 's', ctrlKey: true })

    expect(onSave).toHaveBeenCalledTimes(1)
  })

  it('invokes the save handler from the project menu Save item', async () => {
    vi.stubGlobal('navigator', {})
    const onSave = vi.fn()
    const user = userEvent.setup()

    renderShell({ onSave })

    await user.click(screen.getByRole('button', { name: /project/i }))
    await user.click(screen.getByRole('menuitem', { name: /save/i }))

    expect(onSave).toHaveBeenCalledTimes(1)
  })

  it('pairs the save-status label with a state icon', () => {
    vi.stubGlobal('navigator', {})

    const { container } = renderShell({ saveStatus: 'saved' })

    const status = container.querySelector('.editor-shell__save-status')
    expect(status).not.toBeNull()
    expect(status?.textContent).toMatch(/all changes saved/i)
    expect(status?.querySelector('svg')).not.toBeNull()
  })

  it('invokes the open-folder handler from the project menu', async () => {
    vi.stubGlobal('navigator', {})
    const onOpenFolder = vi.fn()
    const user = userEvent.setup()

    renderShell({ onOpenFolder })

    await user.click(screen.getByRole('button', { name: /project/i }))
    await user.click(screen.getByRole('menuitem', { name: /open folder/i }))

    expect(onOpenFolder).toHaveBeenCalledTimes(1)
  })

  it('opens a recent project by its id from the project menu', async () => {
    vi.stubGlobal('navigator', {})
    const onOpenRecent = vi.fn()
    const user = userEvent.setup()

    renderShell({
      recentProjects: [
        { id: 'a', name: 'Alpha' },
        { id: 'b', name: 'Beta' },
      ],
      onOpenRecent,
    })

    await user.click(screen.getByRole('button', { name: /project/i }))
    expect(screen.getByRole('menuitem', { name: /alpha/i })).toBeInTheDocument()
    await user.click(screen.getByRole('menuitem', { name: /beta/i }))

    expect(onOpenRecent).toHaveBeenCalledTimes(1)
    expect(onOpenRecent).toHaveBeenCalledWith('b')
  })

  it('renames the project from the project menu, but ignores a blank or whitespace-only name', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    const { session } = renderShell()

    await user.click(screen.getByRole('button', { name: /project/i }))
    await user.click(screen.getByRole('menuitem', { name: /^rename$/i }))
    const input = screen.getByRole('textbox', { name: /project name/i })
    await user.clear(input)
    await user.type(input, 'Cedar Hollow{Enter}')

    // The renamed project shows up everywhere the shell names it: the header
    // breadcrumb and the rail's project identity block.
    const breadcrumb = screen.getByRole('navigation', { name: /breadcrumb/i })
    expect(within(breadcrumb).getByText('Cedar Hollow')).toBeInTheDocument()
    expect(screen.getByRole('heading', { level: 2, name: 'Cedar Hollow' })).toBeInTheDocument()
    expect(session.getProject().meta.name).toBe('Cedar Hollow')

    // A blank or whitespace-only name is not a real rename, so the shown name
    // stays exactly what it was before this second attempt.
    await user.click(screen.getByRole('button', { name: /project/i }))
    await user.click(screen.getByRole('menuitem', { name: /^rename$/i }))
    const blankInput = screen.getByRole('textbox', { name: /project name/i })
    await user.clear(blankInput)
    await user.type(blankInput, '   {Enter}')

    expect(within(breadcrumb).getByText('Cedar Hollow')).toBeInTheDocument()
    expect(session.getProject().meta.name).toBe('Cedar Hollow')
  })

  it('renames the active floor from the status bar, but ignores a blank or whitespace-only name', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    const { session } = renderShell()

    await user.click(screen.getByRole('button', { name: /rename floor/i }))
    const blankInput = screen.getByRole('textbox', { name: /floor name/i })
    await user.clear(blankInput)
    await user.type(blankInput, '   {Enter}')

    // A blank or whitespace-only name is not a real rename, so the floor keeps
    // the name it had before this attempt, both in the switcher and in the
    // session's own project state.
    const floorsNav = screen.getByRole('navigation', { name: /floors/i })
    expect(within(floorsNav).getByRole('button', { name: 'Ground' })).toBeInTheDocument()
    expect(session.getProject().floors[0]?.name).toBe('Ground')
  })

  it('restores or discards from the recovery prompt and hides it otherwise', async () => {
    vi.stubGlobal('navigator', {})
    const onRestore = vi.fn()
    const onDiscard = vi.fn()
    const user = userEvent.setup()

    renderShell({ recovery: { onRestore, onDiscard } })

    const alert = screen.getByRole('alert')
    await user.click(within(alert).getByRole('button', { name: /restore/i }))
    await user.click(within(alert).getByRole('button', { name: /delete recovered copy/i }))

    expect(onRestore).toHaveBeenCalledTimes(1)
    expect(onDiscard).toHaveBeenCalledTimes(1)

    cleanup()
    renderShell()
    expect(screen.queryByRole('alert')).toBeNull()
    expect(screen.queryByRole('button', { name: /restore/i })).toBeNull()
    expect(screen.queryByRole('button', { name: /delete recovered copy/i })).toBeNull()
  })

  it('seats the recovery prompt in the frame banner slot rather than above the frame', () => {
    // Rendered as a sibling before the frame, the prompt pushes a viewport-tall
    // frame down by its own height, so the status bar leaves the window. The
    // frame already reserves a banner row for exactly this kind of notice and
    // reflows the rest of the layout around it.
    vi.stubGlobal('navigator', {})

    const { container } = renderShell({ recovery: { onRestore: vi.fn(), onDiscard: vi.fn() } })

    const banner = container.querySelector('.ds-app-frame__banner')
    expect(banner).not.toBeNull()
    expect(banner).toContainElement(screen.getByRole('alert'))
  })

  it('shows the open-file menu item and a viewport drop target', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell({
      onNewProject: vi.fn(),
      onOpenFile: vi.fn(),
      onImportDroppedFile: vi.fn(),
    })

    await user.click(screen.getByRole('button', { name: /project/i }))
    expect(screen.getByRole('menuitem', { name: /open file/i })).toBeInTheDocument()

    expect(screen.getByTestId('import-drop-target')).toBeInTheDocument()
  })

  it('hides project controls, the recent list, and the recovery prompt when no handlers are provided', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.queryByRole('button', { name: /^new$/i })).toBeNull()
    expect(screen.queryByRole('button', { name: /^save$/i })).toBeNull()
    expect(screen.queryByRole('button', { name: /export bundle/i })).toBeNull()
    expect(screen.queryByRole('button', { name: /open folder/i })).toBeNull()
    expect(screen.queryByRole('alert')).toBeNull()
  })

  it('no longer anchors the underlay controls to the plan canvas', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    // The underlay controls moved off the canvas into the tool-rail launcher, so
    // the canvas-anchored Trace underlay checkbox and the always-visible Load
    // image button are gone from the shell.
    expect(screen.queryByRole('checkbox', { name: /trace underlay/i })).toBeNull()
    expect(screen.queryByRole('button', { name: /load image/i })).toBeNull()
  })

  it('lays out the shell regions without a global paint slot', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    expect(screen.getByRole('complementary', { name: /tool rail/i })).toBeInTheDocument()
    expect(screen.getByRole('main', { name: /viewport/i })).toBeInTheDocument()

    // The always-on global paint list is gone; the inspector swaps by selection,
    // so neither the paint-picker nor the paint-inspector slot mounts.
    expect(document.querySelector(`[data-slot-id="${PAINT_PICKER_SLOT}"]`)).toBeNull()
    expect(document.querySelector(`[data-slot-id="${PAINT_INSPECTOR_SLOT}"]`)).toBeNull()

    expect(screen.getByRole('navigation', { name: /tools/i })).toBeInTheDocument()
    expect(screen.getByRole('navigation', { name: /floors/i })).toBeInTheDocument()
    expect(screen.getByRole('complementary', { name: /inspector/i })).toBeInTheDocument()
  })

  it('mounts the site editor in the tool rail', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    // The Timezone field is unique to the SiteEditor among the rail panels, so it is a
    // reliable marker that the site editor is mounted and the project's site fields are
    // editable from the shell.
    expect(screen.getByLabelText(/timezone/i)).toBeInTheDocument()
  })

  it('mounts the environment panel in the tool rail', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    // The Environment section hosts the environment panel's Schematic/Realistic mode
    // toggle, confirming the panel is mounted in the tool rail alongside Site.
    const environmentSection = screen.getByRole('region', { name: /environment/i })
    expect(
      within(environmentSection).getByRole('button', { name: 'Schematic' }),
    ).toBeInTheDocument()
    expect(
      within(environmentSection).getByRole('button', { name: 'Realistic' }),
    ).toBeInTheDocument()
  })

  it('renders the saved-scenes UI in the Environment rail section', () => {
    vi.stubGlobal('navigator', {})

    renderShell()

    // The saved-scenes UI (the Save scene control and the empty-list message) lives
    // in the same Environment region as the mode toggle, confirming it is wired into
    // the rail rather than mounted in isolation.
    const environmentSection = screen.getByRole('region', { name: /environment/i })
    expect(
      within(environmentSection).getByRole('button', { name: /save scene/i }),
    ).toBeInTheDocument()
    expect(within(environmentSection).getByText(/no saved scenes/i)).toBeInTheDocument()
  })

  it('mounts one scene session provider around the viewport and keeps its store across a view-mode round trip', async () => {
    vi.stubGlobal('navigator', {})
    const user = userEvent.setup()

    renderShell()

    await user.click(screen.getByRole('button', { name: '3D view' }))
    await user.click(screen.getByRole('button', { name: 'Plan view' }))

    // jsdom reports no WebGPU support, so the 3D pane shows its unsupported-hardware
    // message and no 3D toolbar to round-trip through. What the shell owes the preview
    // is the wiring: a scene session store made once per shell and held above the
    // viewport, so the same store survives every hop between plan and 3D. The
    // user-visible round trip is pinned by the end-to-end journey.
    const providerCalls = vi.mocked(SceneSessionProvider).mock.calls
    const firstStore = providerCalls[0]?.[0].store
    expect(providerCalls.length).toBeGreaterThan(0)
    expect(firstStore?.getSceneSession).toBeTypeOf('function')
    for (const [props] of providerCalls) {
      expect(props.store.getSceneSession).toBeTypeOf('function')
      expect(props.store).toBe(firstStore)
    }
  })
})

