  it('reports the doorway preset when the doorway button is enabled and clicked', async () => {
    const onPreset = vi.fn()
    render(
      <SceneNavToolbar
        {...baseProps}
        onPreset={onPreset}
        doorway={{ name: 'single swing door', selected: false }}
      />,
    )

