import { act } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { openDocumentHandle } from '../session'
import type { FlowResult, FolderRefusal } from '../session'
import { settle } from '../session/autosave/save-gate-test-kit'
import {
  createTestPorts,
  holdNextRead,
  openOrThrow,
  recordingPorts,
  workspaceRequest,
} from '../session/handle/handle-test-kit'
import type { TestPorts } from '../session/handle/handle-test-kit'
import type { Flow } from './use-open-project'
import {
  gatedFlow,
  lockCalls,
  MISSING_ID,
  OTHER_ID,
  renderOwner,
  resolvesWith,
  runFlowIn,
  settleRunFlow,
  START_ID,
  startRequest,
  unmountAndSettle,
  waitForFailure,
  waitForHandle,
} from './use-open-project-test-support'
import type { OwnerResult } from './use-open-project-test-support'

const FLOW_END = 'flow-end'
const DISK_GONE = 'The disk is gone.'
const CANCELLED: FlowResult<FolderRefusal> = { ok: false, failure: { kind: 'cancelled' } }

/** The owner after a start that failed because the project is not stored. */
async function renderFailedStart(ports: TestPorts) {
  const owner = renderOwner(ports, workspaceRequest(MISSING_ID))
  await waitForFailure(owner.result)
  return owner
}

/** The owner after a start that failed because another tab held the project, now free again. */
async function renderStartThatWasOpenElsewhere(ports: TestPorts) {
  const otherTab = createTestPorts({ root: ports.root, lockRegistry: ports.lockRegistry })
  const elsewhere = await openOrThrow(otherTab, startRequest())
  const owner = renderOwner(ports, startRequest())
  await waitForFailure(owner.result)
  await elsewhere.close()
  return owner
}

/** Starts `flow` through the owner inside `act` and gives the promise of `runFlow`. */
function startFlow<Refusal>(result: OwnerResult, flow: Flow<Refusal>) {
  const running: Array<Promise<FlowResult<Refusal> | undefined>> = []
  act(() => {
    running.push(result.current.runFlow(flow))
  })
  return Promise.all(running)
}

/** The lock calls and the flow ends in `log`, in their order. */
function lockCallsAndFlowEnds(log: readonly string[]): string[] {
  return log.filter((entry) => entry === FLOW_END || lockCalls([entry]).length > 0)
}

function rejecting(): Flow {
  return () => Promise.reject(new Error(DISK_GONE))
}

afterEach(() => {
  vi.restoreAllMocks()
})

describe('useOpenProject when a retry and a flow meet', () => {
  it('retry() and then runFlow in one handler: the flow is not called, runFlow resolves undefined, and one open runs', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, unmount } = await renderStartThatWasOpenElsewhere(ports)
    const flow = vi.fn<Flow>((given) => openDocumentHandle(given, startRequest(OTHER_ID)))
    const outcomes: Array<Promise<FlowResult | undefined>> = []

    act(() => {
      result.current.retry()
      outcomes.push(result.current.runFlow(flow))
    })
    const [outcome] = await act(() => Promise.all(outcomes))
    await waitForHandle(result)

    expect(outcome).toBeUndefined()
    expect(flow).not.toHaveBeenCalled()
    expect(lockCalls(log)).toEqual([`lock:${START_ID}`, `lock:${START_ID}`])
    await unmountAndSettle(unmount)
  })

  it('retry does nothing while a project is open and while the start runs, and a double retry gives one new open', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, unmount } = await renderStartThatWasOpenElsewhere(ports)
    const letReadEnd = holdNextRead(ports.workspace)

    act(() => {
      result.current.retry()
      result.current.retry()
    })
    await act(settle)
    act(() => result.current.retry())
    await act(async () => {
      letReadEnd()
      await settle()
    })
    const handle = await waitForHandle(result)
    act(() => result.current.retry())
    await act(settle)

    expect(result.current.handle).toBe(handle)
    expect(lockCalls(log)).toEqual([`lock:${START_ID}`, `lock:${START_ID}`])
    await unmountAndSettle(unmount)
  })
})

describe('useOpenProject when the start request changes while a flow runs', () => {
  it('a start request that changes while a flow runs takes no lock until the flow ends', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, rerender, unmount } = await renderFailedStart(ports)
    const held = gatedFlow(resolvesWith(CANCELLED))
    const running = startFlow(result, held.flow)
    const mark = log.length

    rerender({ ports, start: startRequest() })
    await act(settle)

    expect(lockCalls(log.slice(mark))).toEqual([])
    await act(async () => {
      held.letEnd()
      await running
    })
    await unmountAndSettle(unmount)
  })

  it('when that flow opened a project, the changed start never opens, and one lock is held', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, rerender, unmount } = await renderFailedStart(ports)
    const held = gatedFlow((given) => openDocumentHandle(given, startRequest(OTHER_ID)))
    const running = startFlow(result, held.flow)
    rerender({ ports, start: startRequest() })
    await act(settle)

    await act(async () => {
      held.letEnd()
      await running
      await settle()
    })

    expect(result.current.handle?.id).toBe(OTHER_ID)
    expect(await ports.locks.heldIds()).toEqual(new Set([OTHER_ID]))
    await unmountAndSettle(unmount)
  })

  it('when that flow opened a project, no lock call after the change takes the lock of the start', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, rerender, unmount } = await renderFailedStart(ports)
    const held = gatedFlow((given) => openDocumentHandle(given, startRequest(OTHER_ID)))
    const running = startFlow(result, held.flow)
    rerender({ ports, start: startRequest() })
    const mark = log.length
    await act(settle)

    await act(async () => {
      held.letEnd()
      await running
      await settle()
    })

    expect(lockCalls(log.slice(mark))).not.toContain(`lock:${START_ID}`)
    await unmountAndSettle(unmount)
  })

  it('when that flow opened nothing, the changed start opens after it', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, rerender, unmount } = await renderFailedStart(ports)
    const held = gatedFlow<FolderRefusal>(() => {
      log.push(FLOW_END)
      return Promise.resolve(CANCELLED)
    })
    const running = startFlow(result, held.flow)
    const mark = log.length
    rerender({ ports, start: startRequest() })
    await act(settle)

    await act(async () => {
      held.letEnd()
      await running
    })
    const handle = await waitForHandle(result)

    expect(lockCallsAndFlowEnds(log.slice(mark))).toEqual([FLOW_END, `lock:${START_ID}`])
    expect(handle.id).toBe(START_ID)
    await unmountAndSettle(unmount)
  })
})

describe('useOpenProject when a new start comes with no project open', () => {
  it('a changed start after a failed start shows no failure while it opens, then the handle', async () => {
    const ports = createTestPorts()
    const { result, rerender, unmount } = await renderFailedStart(ports)
    const letReadEnd = holdNextRead(ports.workspace)

    rerender({ ports, start: startRequest() })
    await act(settle)

    expect(result.current.failure).toBeNull()
    expect(result.current.handle).toBeNull()
    await act(async () => {
      letReadEnd()
      await settle()
    })
    expect((await waitForHandle(result)).id).toBe(START_ID)
    await unmountAndSettle(unmount)
  })

  it('null ports that become ports together with a start open that start on those ports', async () => {
    const ports = createTestPorts()
    const { result, rerender, unmount } = renderOwner(null, startRequest())

    rerender({ ports, start: startRequest(OTHER_ID) })
    const handle = await waitForHandle(result)

    expect(handle.id).toBe(OTHER_ID)
    expect(await ports.locks.heldIds()).toEqual(new Set([OTHER_ID]))
    await unmountAndSettle(unmount)
  })

  it('the same start request given again after a failed start opens nothing', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const start = workspaceRequest(MISSING_ID)
    const { result, rerender } = renderOwner(ports, start)
    await waitForFailure(result)
    const mark = log.length

    rerender({ ports, start })
    await act(settle)

    expect(log.slice(mark)).toEqual([])
    expect(result.current.failure).toEqual({ kind: 'not-found' })
  })
})

describe('useOpenProject when a flow rejects', () => {
  it('a flow that rejects is logged once, frees the owner, and runFlow resolves storage-unavailable with its message', async () => {
    const errors = vi.spyOn(console, 'error').mockImplementation(() => undefined)
    const { result, unmount } = renderOwner(createTestPorts(), startRequest())
    const handle = await waitForHandle(result)

    const settled = await settleRunFlow(result, rejecting())

    expect(settled).toEqual({
      status: 'resolved',
      value: { ok: false, failure: { kind: 'storage-unavailable', message: DISK_GONE } },
    })
    expect(errors).toHaveBeenCalledTimes(1)
    const next = vi.fn(resolvesWith(CANCELLED))
    await runFlowIn(result, next)
    expect(next).toHaveBeenCalledTimes(1)
    expect(result.current.handle).toBe(handle)
    await unmountAndSettle(unmount)
  })

  it('after a failed start, a flow that rejects makes storage-unavailable the failure', async () => {
    vi.spyOn(console, 'error').mockImplementation(() => undefined)
    const { result } = await renderFailedStart(createTestPorts())

    await settleRunFlow(result, rejecting())

    expect(result.current.failure).toEqual({ kind: 'storage-unavailable', message: DISK_GONE })
  })
})

describe('useOpenProject after a project opened or with nothing to open', () => {
  it('a change of the start request after a project opened opens nothing', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const { result, rerender, unmount } = renderOwner(ports, startRequest())
    const handle = await waitForHandle(result)

    rerender({ ports, start: startRequest(OTHER_ID) })
    await act(settle)

    expect(result.current.handle).toBe(handle)
    expect(lockCalls(log)).toEqual([`lock:${START_ID}`])
    await unmountAndSettle(unmount)
  })

  it('a change of the ports after a project opened opens and closes nothing, and the next flow gets the new ports', async () => {
    const log: string[] = []
    const ports = recordingPorts(log)
    const newPorts = createTestPorts()
    const start = startRequest()
    const { result, rerender, unmount } = renderOwner(ports, start)
    const handle = await waitForHandle(result)

    rerender({ ports: newPorts, start })
    await act(settle)

    expect(result.current.handle).toBe(handle)
    expect(lockCalls(log)).toEqual([`lock:${START_ID}`])
    expect(await newPorts.locks.heldIds()).toEqual(new Set())
    const flow = vi.fn(resolvesWith(CANCELLED))
    await runFlowIn(result, flow)
    expect(flow.mock.calls[0]?.[0]).toBe(newPorts)
    await unmountAndSettle(unmount)
  })

  it('runFlow with null ports resolves undefined and calls nothing', async () => {
    const { result } = renderOwner(null, startRequest())
    const flow = vi.fn(resolvesWith(CANCELLED))

    expect(await runFlowIn(result, flow)).toBeUndefined()
    expect(flow).not.toHaveBeenCalled()
  })

  it('after a failed start, folder-empty leaves the failure in place', async () => {
    const { result } = await renderFailedStart(createTestPorts())

    await runFlowIn(
      result,
      resolvesWith<FolderRefusal>({ ok: false, failure: { kind: 'folder-empty' } }),
    )

    expect(result.current.failure).toEqual({ kind: 'not-found' })
  })
})

tests/performance/timing/scene-update-ti.source:
import { describe, expect, it } from 'vitest'
import type { FramedScene } from '../../../bridge/react/framed-scene'
import { FLOOR_NODE_PREFIX, WALL_NODE_PREFIX, renameProject, type Command } from '../../../core'
import { REFERENCE_EDITS, createReferenceProject } from '../reference-project'
import { required } from '../required'
import { createReferenceSession } from './reference-session'
import {
  createSceneUpdateBench,
  timeSceneUpdate,
  type SceneUpdateBench,
} from './scene-update-timing'

const COUNTS = { warmup: 1, timed: 2 }
const MOVE_WALL_ENDPOINT = 'move-wall-endpoint'
const RENAME_PROJECT = 'rename-project'

type Call = 'now' | 'apply' | 'reconcile' | 'undo'

/** A bench that only notes which calls it got, and with which command. */
function loggingBench(log: Call[], applied: Command[]): SceneUpdateBench {
  return {
    apply: (command) => {
      log.push('apply')
      applied.push(command)
    },
    reconcile: () => {
      log.push('reconcile')
    },
    undo: () => {
      log.push('undo')
    },
    lastScene: () => undefined,
  }
}

/** A clock that logs each read among the bench calls and returns the readings in order. */
function scriptedClock(log: Call[], readings: readonly number[]): () => number {
  let next = 0
  return () => {
    log.push('now')
    const reading = required(readings[next], `clock reading ${next}`)
    next += 1
    return reading
  }
}

const commands = ['warm-up', 'first', 'second'].map((name) => renameProject(name))

function timeWithLoggingBench(readings: readonly number[]) {
  const log: Call[] = []
  const applied: Command[] = []
  const samples = timeSceneUpdate({
    bench: loggingBench(log, applied),
    commands,
    counts: COUNTS,
    now: scriptedClock(log, readings),
  })
  return { log, applied, samples }
}

describe('timing the 3D update of an edit', () => {
  const READINGS = [5, 8, 20, 27]

  it('returns one sample for each timed command and none for the warm-up', () => {
    expect(timeWithLoggingBench(READINGS).samples).toHaveLength(COUNTS.timed)
  })

  it('holds the edit and its reconcile in the interval, and the undo and its reconcile outside it', () => {
    const { log } = timeWithLoggingBench(READINGS)

    // The surface says the warm-up samples are not returned, so no clock read is expected for them.
    // That is an inference from the surface, not a stated rule.
    const warmUp: Call[] = ['apply', 'reconcile', 'undo', 'reconcile']
    const timed: Call[] = ['now', 'apply', 'reconcile', 'now', 'undo', 'reconcile']
    expect(log).toEqual([...warmUp, ...timed, ...timed])
  })

  it('reports each sample as the difference of the two clock reads around it', () => {
    expect(timeWithLoggingBench(READINGS).samples).toEqual([3, 7])
  })

  it('applies the commands it is given in order, the warm-up command first', () => {
    const { applied } = timeWithLoggingBench(READINGS)

    expect(applied).toHaveLength(commands.length)
    commands.forEach((command, index) => {
      expect(applied[index]).toBe(command)
    })
  })

  // The command list holds the warm-up commands first, then the timed ones: the first
  // `counts.warmup` commands are not timed and read no clock, the next `counts.timed` are timed.
  // A list shorter than warmup + timed is an error that names both numbers; it is not cycled.
  it('refuses a list of commands shorter than the warm-up and timed counts together', () => {
    const counts = { warmup: 2, timed: 3 }
    const tooShort = commands.concat(commands).slice(0, 4)
    const log: Call[] = []

    const timeShortList = () =>
      timeSceneUpdate({
        bench: loggingBench(log, []),
        commands: tooShort,
        counts,
        now: scriptedClock(log, READINGS),
      })

    expect(timeShortList).toThrow(/\b5\b/)
    expect(timeShortList).toThrow(/\b4\b/)
  })
})

/** An object of the framed scene, typed through the scene root so this test needs no `three`. */
type SceneObject = Parameters<Parameters<FramedScene['root']['traverse']>[0]>[0]

/**
 * The first object of the scene for each element id it carries. The scene gives its elements
 * kind-prefixed ids, as the count gate reads them: a floor is `floor:<floor id>` and a wall mesh is
 * `wall:<wall id>`. The wall group is the unnamed parent of the wall meshes.
 */
function objectsByElementId(bench: SceneUpdateBench): Map<string, SceneObject> {
  const scene = required(bench.lastScene(), 'the scene of the last reconcile')
  const objects = new Map<string, SceneObject>()
  scene.root.traverse((object) => {
    const id: unknown = object.userData['entityId']
    if (typeof id === 'string' && !objects.has(id)) {
      objects.set(id, object)
    }
  })
  return objects
}

/** The element ids that are in both scenes as different objects: the groups that were rebuilt. */
function rebuiltElementIds(before: Map<string, SceneObject>, after: Map<string, SceneObject>) {
  return [...before]
    .filter(([id, object]) => after.has(id) && after.get(id) !== object)
    .map(([id]) => id)
}

/** The wall group holding the mesh of a wall, the group the count gate counts as rebuilt. */
function wallGroupOf(objects: Map<string, SceneObject>, wallId: string): SceneObject | null {
  const mesh = required(objects.get(`${WALL_NODE_PREFIX}${wallId}`), `the mesh of wall ${wallId}`)
  return mesh.parent
}

function commandOf(editName: string): Command {
  const edit = required(
    REFERENCE_EDITS.find((candidate) => candidate.name === editName),
    editName,
  )
  return edit.command(createReferenceProject())
}

/** The bench on a session the test holds, so the test can read the session's document. */
function benchOnReferenceSession() {
  const session = createReferenceSession()
  return { session, bench: createSceneUpdateBench(session) }
}

describe('the real bench of the 3D update', () => {
  it('leaves the document as the reference project after an edit and its undo', () => {
    const { session, bench } = benchOnReferenceSession()

    bench.apply(commandOf(MOVE_WALL_ENDPOINT))
    bench.reconcile()
    expect(session.getProject()).not.toEqual(createReferenceProject())

    bench.undo()
    bench.reconcile()
    expect(session.getProject()).toEqual(createReferenceProject())
  })

  it('reconciles the whole building, all four floors of the reference project', () => {
    const { bench } = benchOnReferenceSession()

    bench.reconcile()

    const floorIds = createReferenceProject().floors.map((floor) => floor.id)
    expect(floorIds).toHaveLength(4)
    const present = objectsByElementId(bench)
    for (const floorId of floorIds) {
      const elementId = `${FLOOR_NODE_PREFIX}${floorId}`
      expect(present.has(elementId), `the scene has the element ${elementId}`).toBe(true)
    }
  })

  it('rebuilds the walls of the ground floor when a wall endpoint moves', () => {
    const { bench } = benchOnReferenceSession()
    bench.reconcile()
    const before = objectsByElementId(bench)

    bench.apply(commandOf(MOVE_WALL_ENDPOINT))
    bench.reconcile()

    const wall = required(createReferenceProject().floors[0]?.walls[0], 'the first wall')
    const groupBefore = wallGroupOf(before, wall.id)
    expect(groupBefore).not.toBeNull()
    expect(wallGroupOf(objectsByElementId(bench), wall.id)).not.toBe(groupBefore)
  })

  it('rebuilds nothing when the project is renamed, the control of the fixed cost', () => {
    const { bench } = benchOnReferenceSession()
    bench.reconcile()
    const before = objectsByElementId(bench)

    bench.apply(commandOf(RENAME_PROJECT))
    bench.reconcile()

    expect(rebuiltElementIds(before, objectsByElementId(bench))).toEqual([])
  })
})

