import { afterEach, describe, expect, it, vi } from 'vitest'
import { CURRENT_SCHEMA_VERSION, createWall, decodeDocument, encodeDocument } from '../../core'
import type { CodecOptions, Project, SchemaMigration } from '../../core'
import { versionFixtureBytes } from '../../tests/fixtures/projects/versions'
import {
  bytesOf,
  firstWallOf,
  fixtureDocument,
  metaOf,
  projectOf,
  UNKNOWN_FIELD,
  UNKNOWN_WALL_FIELD_PATH,
  withUnknownWallField,
} from '../../tests/fixtures/projects/versions/fixture-documents'
import type { Json } from '../../tests/fixtures/projects/versions/fixture-documents'
import {
  BACKUP_DIRECTORY,
  DOCUMENT_PATH,
  backupsOf,
  readProject,
  rootHolding,
  storeOver,
} from './document-store-test-kit'

const OLDER_VERSION = 8
const FAULT_BACKUP_PREFIX = 'last-valid-'
const NOT_JSON = new TextEncoder().encode('{ not json')

const throwingStep: SchemaMigration = {
  from: OLDER_VERSION,
  migrate: () => {
    throw new Error('the step broke')
  },
}

function currentBytes(): Uint8Array {
  return versionFixtureBytes(CURRENT_SCHEMA_VERSION)
}

function validProject(): Project {
  return projectOf(currentBytes())
}

/** A project that breaks the format rules: an unknown field on its first wall. */
function faultyProject(): Project {
  const project = validProject()
  withUnknownWallField(project as unknown as Json)
  return project
}

function storedJson(bytes: Uint8Array | undefined): Json {
  return JSON.parse(new TextDecoder().decode(bytes))
}

describe('saving a valid project through the store', () => {
  it('writes the document, reports no faults and no backup, and reads back as saved', async () => {
    const root = await rootHolding(undefined)
    const store = storeOver(root)
    const project = validProject()

    const report = await store.save('a', project)

    expect(report).toEqual({ faults: [], backedUp: false, lastChangedAt: expect.any(String) })
    expect(report.graftDropped).toBeUndefined()
    expect(await root.readFile(DOCUMENT_PATH)).toBeDefined()
    const read = await store.read('a')
    const expected = projectOf(encodeDocument(project, undefined).bytes)
    expect(read.ok && read.value.project).toEqual(expected)
    expect(await root.list(BACKUP_DIRECTORY)).toEqual([])
  })
})

describe('saving a project that breaks the format rules', () => {
  it('still writes it, reports the faults, and backs up the last stored file that passed', async () => {
    const stored = currentBytes()
    const root = await rootHolding(stored)

    const report = await storeOver(root).save('a', faultyProject())

    expect(report.backedUp).toBe(true)
    expect(report.faults.map((fault) => fault.path)).toContain(UNKNOWN_WALL_FIELD_PATH)
    expect(firstWallOf(storedJson(await root.readFile(DOCUMENT_PATH)))[UNKNOWN_FIELD]).toBe(1)
    const backups = await backupsOf(root)
    expect(backups).toHaveLength(1)
    expect(backups[0]?.name.startsWith(FAULT_BACKUP_PREFIX)).toBe(true)
    expect(backups[0]?.bytes).toEqual(stored)
  })

  it('adds no second backup when the next save is faulty too', async () => {
    const root = await rootHolding(currentBytes())
    const store = storeOver(root)
    await store.save('a', faultyProject())
    const [first] = await backupsOf(root)

    const report = await store.save('a', faultyProject())

    expect(report.backedUp).toBe(false)
    expect(report.faults.length).toBeGreaterThan(0)
    const backups = await backupsOf(root)
    expect(backups).toHaveLength(1)
    expect(backups[0]?.name).toBe(first?.name)
    expect(backups[0]?.bytes).toEqual(currentBytes())
  })
})

function newerVersionBytes(): Uint8Array {
  const document = fixtureDocument(CURRENT_SCHEMA_VERSION)
  metaOf(document).schemaVersion = CURRENT_SCHEMA_VERSION + 1
  return bytesOf(document)
}

describe('saving over a previous file that cannot be read', () => {
  afterEach(() => {
    vi.restoreAllMocks()
  })

  const cases: { name: string; previous: Uint8Array; options?: CodecOptions }[] = [
    { name: 'at a newer schema version', previous: newerVersionBytes() },
    { name: 'that is not JSON', previous: NOT_JSON },
    {
      name: 'whose migration throws',
      previous: versionFixtureBytes(OLDER_VERSION),
      options: { migration: { schemaMigrations: [throwingStep] } },
    },
  ]

  it.each(cases)(
    'writes the new document and reports why no graft was made for a previous file $name',
    async ({ previous, options }) => {
      const warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
      const root = await rootHolding(previous)
      const project = validProject()
      const reason = decodeDocument(previous, options)
      if (reason.ok) throw new Error('Expected the previous bytes to fail to decode')

      const report = await storeOver(root, options).save('a', project)

      expect(report.graftDropped).toEqual(reason.failure)
      expect(report.faults).toEqual([])
      const written = await root.readFile(DOCUMENT_PATH)
      expect(written).toEqual(encodeDocument(project, undefined, options).bytes)
      expect(written).not.toEqual(previous)
      const warned = warn.mock.calls.map((args) => JSON.stringify(args))
      expect(warned.some((text) => text.includes(reason.failure.kind))).toBe(true)
    },
  )
})

function growAndRename(project: Project): void {
  project.meta.name = 'Mutated'
  project.floors[0]!.walls.push(
    createWall({ x: 0, y: 0 }, { x: 1, y: 1 }, { id: 'wall-extra', thickness: 100 }),
  )
}

describe('the state a store keeps', () => {
  it('is isolated from a later change to the project that was saved', async () => {
    const store = storeOver(await rootHolding(undefined))
    const project = validProject()
    const savedName = project.meta.name
    const savedWalls = project.floors[0]!.walls.length
    await store.save('a', project)

    growAndRename(project)

    const loaded = await readProject(store, 'a')
    expect(loaded.meta.name).toBe(savedName)
    expect(loaded.floors[0]!.walls).toHaveLength(savedWalls)
  })

  it('is isolated from a change to a project that was loaded', async () => {
    const store = storeOver(await rootHolding(currentBytes()))
    const firstLoad = await readProject(store, 'a')
    const loadedName = firstLoad.meta.name
    const loadedWalls = firstLoad.floors[0]!.walls.length

    growAndRename(firstLoad)

    const secondLoad = await readProject(store, 'a')
    expect(secondLoad.meta.name).toBe(loadedName)
    expect(secondLoad.floors[0]!.walls).toHaveLength(loadedWalls)
  })
})

tests/format/known-keys-shapes.test.ts.source:
import { describe, expect, it } from 'vitest'
import { KNOWN_KEYS } from '../../core'
import { buildKnownKeys } from '../../scripts/schema/build-known-keys.mjs'
import { buildProjectSchema } from '../../scripts/schema/build-schema.mjs'

const GENERATION_TIMEOUT_MS = 30_000

type SchemaNode = Record<string, unknown>

/** A one-property root schema, with the definitions it refers to. */
function schemaWith(property: SchemaNode, definitions: Record<string, SchemaNode> = {}) {
  return {
    $schema: 'http://json-schema.org/draft-07/schema#',
    type: 'object',
    properties: { value: property },
    required: ['value'],
    additionalProperties: false,
    definitions,
  }
}

/** An object variant of a tagged union. */
function variant(tagKey: string, tagValue: string): SchemaNode {
  return {
    type: 'object',
    properties: { [tagKey]: { type: 'string', const: tagValue }, size: { type: 'number' } },
    required: [tagKey, 'size'],
    additionalProperties: false,
  }
}

/** One named definition, for the `definitions` of a schema. */
function definition(name: string, node: SchemaNode): Record<string, SchemaNode> {
  return { [name]: node }
}

/** A tagged union over the given tag key and tag values, referenced from the root. */
function taggedUnionSchema(
  tagKey: string,
  tagValues: string[],
  combinator: 'anyOf' | 'oneOf' = 'anyOf',
) {
  const variants = tagValues.map((tagValue) => variant(tagKey, tagValue))
  return schemaWith(
    { $ref: '#/definitions/Shape' },
    definition('Shape', { [combinator]: variants }),
  )
}

/** The error that `buildKnownKeys` stops with, which fails the test when it accepts the schema. */
function refusalOf(schema: object): Error {
  try {
    buildKnownKeys(schema)
  } catch (error) {
    return error as Error
  }
  return expect.fail('the generator accepted a schema it cannot express')
}

type TaggedUnionValue = {
  kind: 'union'
  tag?: string
  variants: { value: string; type: string }[]
}

/** Every union value found anywhere in the table, however deeply it is nested. */
function unionValuesIn(node: unknown): TaggedUnionValue[] {
  if (Array.isArray(node)) return node.flatMap(unionValuesIn)
  if (node === null || typeof node !== 'object') return []
  const found = Object.values(node).flatMap(unionValuesIn)
  return (node as { kind?: unknown }).kind === 'union'
    ? [node as TaggedUnionValue, ...found]
    : found
}

/** The key whose `const` marks each variant of the named union in the real schema. */
function tagKeyOf(schema: object, unionName: string): string | undefined {
  const definitions = (schema as SchemaNode).definitions as Record<string, { anyOf: SchemaNode[] }>
  const first = definitions[unionName]?.anyOf[0]?.properties as Record<string, SchemaNode>
  return Object.entries(first ?? {}).find(([, value]) => value.const !== undefined)?.[0]
}

interface InexpressibleShape {
  label: string
  property: SchemaNode
  definitions: Record<string, SchemaNode>
  namesTheShape: RegExp
}

/** An object definition with one scalar property, for the shapes that mix it with something else. */
const PATTERN = '^x-'

const PLAIN_OBJECT: SchemaNode = {
  type: 'object',
  properties: { a: { type: 'string' } },
  required: ['a'],
}

const INEXPRESSIBLE_SHAPES: InexpressibleShape[] = [
  {
    label: 'an array of arrays behind a reference',
    property: { $ref: '#/definitions/Grid' },
    definitions: definition('Grid', {
      type: 'array',
      items: { type: 'array', items: { type: 'number' } },
    }),
    namesTheShape: /Grid.*array of arrays/,
  },
  {
    label: 'an inline array of arrays',
    property: { type: 'array', items: { type: 'array', items: { type: 'number' } } },
    definitions: {},
    namesTheShape: /Project\.value.*array of arrays/,
  },
  {
    label: 'a tuple',
    property: { type: 'array', prefixItems: [{ type: 'number' }, { type: 'string' }] },
    definitions: {},
    namesTheShape: /Project\.value.*tuple/,
  },
  {
    label: 'a oneOf with no shared tag',
    property: { $ref: '#/definitions/Either' },
    definitions: definition('Either', { oneOf: [{ type: 'string' }, { type: 'number' }] }),
    namesTheShape: /Either.*tag/,
  },
  {
    label: 'an anyOf of objects with no constant tag that every variant shares',
    property: { $ref: '#/definitions/Either' },
    definitions: definition('Either', {
      anyOf: [
        { type: 'object', properties: { a: { type: 'string' } }, required: ['a'] },
        { type: 'object', properties: { b: { type: 'number' } }, required: ['b'] },
      ],
    }),
    namesTheShape: /Either.*tag/,
  },
  {
    label: 'a property whose type is a list of types',
    property: { type: ['string', 'null'] },
    definitions: {},
    namesTheShape: /Project\.value.*type list/,
  },
  {
    label: 'a property with allOf',
    property: { allOf: [{ type: 'string' }] },
    definitions: {},
    namesTheShape: /Project\.value.*allOf/,
  },
  {
    label: 'a reference to a definition that does not exist',
    property: { $ref: '#/definitions/Missing' },
    definitions: {},
    namesTheShape: /Project\.value.*Missing/,
  },
  {
    label: 'an object with properties and a schema-valued additionalProperties',
    property: { $ref: '#/definitions/Bag' },
    definitions: definition('Bag', { ...PLAIN_OBJECT, additionalProperties: { type: 'number' } }),
    namesTheShape: /Bag.*additionalProperties/,
  },
  {
    label: 'an object with properties and patternProperties',
    property: { $ref: '#/definitions/Bag' },
    definitions: definition('Bag', {
      ...PLAIN_OBJECT,
      patternProperties: { [PATTERN]: { type: 'number' } },
    }),
    namesTheShape: /Bag.*patternProperties/,
  },
  {
    label: 'a reference with sibling keywords beside it',
    property: {
      $ref: '#/definitions/A',
      type: 'object',
      properties: { b: { type: 'string' } },
    },
    definitions: definition('A', PLAIN_OBJECT),
    namesTheShape: /Project\.value.*sibling.*type.*properties/,
  },
  {
    label: 'a definition with both properties and anyOf',
    property: { $ref: '#/definitions/Mixed' },
    definitions: definition('Mixed', { ...PLAIN_OBJECT, anyOf: [{ type: 'string' }] }),
    namesTheShape: /Mixed.*anyOf/,
  },
  {
    label: 'an object with additionalProperties false and no properties',
    property: { additionalProperties: false },
    definitions: {},
    namesTheShape: /Project\.value.*no properties/,
  },
]

describe('the table of known keys, for a schema shape it cannot express', () => {
  it.each(INEXPRESSIBLE_SHAPES)(
    'refuses $label with a named error instead of recording it',
    ({ property, definitions, namesTheShape }) => {
      const error = refusalOf(schemaWith(property, definitions))

      expect(error).toBeInstanceOf(Error)
      expect(error).not.toBeInstanceOf(TypeError)
      expect(error.message).toMatch(namesTheShape)
    },
  )

  it('refuses two variants of one tagged union that carry the same tag value', () => {
    const schema = taggedUnionSchema('kind', ['circle', 'square', 'circle'])
    expect(() => buildKnownKeys(schema)).toThrow(/Shape.*circle|circle.*Shape/)
  })
})

describe('the table of known keys, for a schema shape it can express', () => {
  it('records a scalar, an enum, and an array of scalars as leaves', () => {
    const schema = {
      ...schemaWith({ type: 'string' }),
      properties: {
        name: { type: 'string' },
        mode: { type: 'string', enum: ['a', 'b'] },
        sizes: { type: 'array', items: { type: 'number' } },
      },
      required: ['name', 'mode', 'sizes'],
    }
    const keys = buildKnownKeys(schema).Project?.keys
    expect(keys?.name).toEqual({ kind: 'leaf' })
    expect(keys?.mode).toEqual({ kind: 'leaf' })
    expect(keys?.sizes).toEqual({ kind: 'leaf' })
  })
})

describe('the tag key of a union in the table of known keys', () => {
  it('is recorded for a union written with oneOf, with a variant entry for each tag value', () => {
    const table = buildKnownKeys(taggedUnionSchema('kind', ['circle', 'square'], 'oneOf'))
    expect(table.Project?.keys.value).toEqual({
      kind: 'union',
      tag: 'kind',
      variants: [
        { value: 'circle', type: 'Shape.circle' },
        { value: 'square', type: 'Shape.square' },
      ],
    })
    expect(Object.keys(table)).toEqual(
      expect.arrayContaining(['Project', 'Shape.circle', 'Shape.square']),
    )
  })

  it('is recorded for a union tagged by a key other than kind', () => {
    const table = buildKnownKeys(taggedUnionSchema('type', ['circle', 'square']))
    expect(table.Project?.keys.value).toEqual({
      kind: 'union',
      tag: 'type',
      variants: [
        { value: 'circle', type: 'Shape.circle' },
        { value: 'square', type: 'Shape.square' },
      ],
    })
  })

  it(
    'is recorded on every union of the real schema, as the key the schema tags it with',
    { timeout: GENERATION_TIMEOUT_MS },
    () => {
      const schema = buildProjectSchema()
      const unions = unionValuesIn(KNOWN_KEYS)
      expect(unions.length).toBeGreaterThan(0)
      for (const union of unions) {
        const unionName = (union.variants[0]?.type ?? '').split('.')[0] ?? ''
        expect(union.tag, unionName).toBe(tagKeyOf(schema, unionName))
      }
    },
  )
})

