import { describe, it, expect, afterEach, vi } from 'vitest'
import { render, screen, cleanup } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { AssetRegistry, type LibraryItem } from '../../storage'
import { AssetRegistryProvider } from '../../bridge/react/asset-registry-context'
import {
  MID_CENTURY_CHAIR_NAME,
  PACK_SCOPE,
  libraryItem,
  listingSource,
} from './library-test-support'
import { LibraryPanel } from './library-panel'

const USER_ITEM_NAME = 'Inherited armchair'
const EMPTY_STATE = 'Your library is empty'
const IMPORT_ACTION = /import a 3d model/i

function registryOf(packItems: LibraryItem[], userItems: LibraryItem[]): AssetRegistry {
  return new AssetRegistry([
    { kind: 'pack', source: listingSource(PACK_SCOPE, packItems) },
    { kind: 'user', source: listingSource('user', userItems) },
  ])
}

function renderPanel(
  registry: AssetRegistry,
  onPick: (item: LibraryItem) => void = vi.fn(),
  onImport: () => void = vi.fn(),
): HTMLElement {
  const { container } = render(
    <AssetRegistryProvider registry={registry}>
      <LibraryPanel onPick={onPick} onImport={onImport} />
    </AssetRegistryProvider>,
  )
  return container
}

afterEach(cleanup)

describe('LibraryPanel', () => {
  it('lists items from both the pack and user sources', async () => {
    const packItem = libraryItem({ name: MID_CENTURY_CHAIR_NAME })
    const userItem = libraryItem({ name: USER_ITEM_NAME })
    renderPanel(registryOf([packItem], [userItem]))

    expect(await screen.findByRole('button', { name: MID_CENTURY_CHAIR_NAME })).toBeInTheDocument()
    expect(await screen.findByRole('button', { name: USER_ITEM_NAME })).toBeInTheDocument()
  })

  it('exposes a labelled furniture library region', () => {
    renderPanel(registryOf([libraryItem()], []))

    expect(screen.getByRole('region', { name: /furniture library/i })).toBeInTheDocument()
  })

  it('calls onPick with the picked item when its button is clicked', async () => {
    const user = userEvent.setup()
    const packItem = libraryItem({ name: MID_CENTURY_CHAIR_NAME })
    const onPick = vi.fn()
    renderPanel(registryOf([packItem], []), onPick)

    await user.click(await screen.findByRole('button', { name: MID_CENTURY_CHAIR_NAME }))

    expect(onPick).toHaveBeenCalledWith(packItem)
  })

  it('calls onImport once when the import action is clicked', async () => {
    const user = userEvent.setup()
    const onImport = vi.fn()
    renderPanel(registryOf([libraryItem()], []), vi.fn(), onImport)

    await user.click(screen.getByRole('button', { name: IMPORT_ACTION }))

    expect(onImport).toHaveBeenCalledTimes(1)
  })

  it('shows an empty state and no item buttons when the registry lists nothing', async () => {
    renderPanel(new AssetRegistry([]))

    expect(await screen.findByText(EMPTY_STATE)).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: MID_CENTURY_CHAIR_NAME })).toBeNull()
  })

  it('presents the empty-state message as a heading', async () => {
    renderPanel(new AssetRegistry([]))

    expect(await screen.findByRole('heading', { name: EMPTY_STATE })).toBeInTheDocument()
  })
})

const EAMES_NAME = 'Eames chair'
const OAK_NAME = 'Oak table'

function packAndUserRegistry(): AssetRegistry {
  const packItem = libraryItem({
    name: EAMES_NAME,
    eras: ['mid-century'],
    styles: ['mid-century-modern'],
    reference: { scope: PACK_SCOPE, contentHash: 'p1' },
  })
  const userItem = libraryItem({
    name: OAK_NAME,
    eras: ['victorian'],
    styles: ['queen-anne'],
    reference: { scope: 'user', contentHash: 'u1' },
  })
  return registryOf([packItem], [userItem])
}

async function renderBothLoaded(): Promise<void> {
  renderPanel(packAndUserRegistry())
  await screen.findByRole('button', { name: EAMES_NAME })
  await screen.findByRole('button', { name: OAK_NAME })
}

describe('LibraryPanel filtering', () => {
  it('filters items by a case-insensitive name search', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.type(screen.getByRole('searchbox', { name: /search furniture/i }), 'chair')

    expect(screen.getByRole('button', { name: EAMES_NAME })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: OAK_NAME })).toBeNull()
  })

  it('shows only user-scoped items when the source toggle is set to Yours', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.click(screen.getByRole('button', { name: 'Yours' }))

    expect(screen.queryByRole('button', { name: EAMES_NAME })).toBeNull()
    expect(screen.getByRole('button', { name: OAK_NAME })).toBeInTheDocument()
  })

  it('shows only pack-scoped items when the source toggle is set to Sample', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.click(screen.getByRole('button', { name: 'Sample' }))

    expect(screen.getByRole('button', { name: EAMES_NAME })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: OAK_NAME })).toBeNull()
  })

  it('narrows the grid to items in the chosen era when an era chip is activated', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.click(screen.getByRole('button', { name: 'mid-century' }))

    expect(screen.getByRole('button', { name: EAMES_NAME })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: OAK_NAME })).toBeNull()
  })

  it('narrows the grid to items in the chosen style when a style chip is activated', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.click(screen.getByRole('button', { name: 'mid-century-modern' }))

    expect(screen.getByRole('button', { name: EAMES_NAME })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: OAK_NAME })).toBeNull()
  })

  it('announces the no-matches state to assistive technology when a filter empties the grid', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.type(screen.getByRole('searchbox', { name: /search furniture/i }), 'no such item')

    expect(screen.getByRole('status')).toHaveTextContent('No matches')
  })
})

const EXPECTED_SEGMENTED_GROUPS = 3
const SINGLE_ACTIVE_OPTION = 1

function segmentedGroups(container: HTMLElement): HTMLElement[] {
  return [...container.querySelectorAll<HTMLElement>('.ds-segmented')]
}

function activeOptionsIn(group: HTMLElement): HTMLElement[] {
  return [...group.querySelectorAll<HTMLElement>('.is-active')]
}

describe('LibraryPanel design-system primitives', () => {
  it('renders the source-filter, era-filter, and style-filter groups as Segmented controls', async () => {
    const container = renderPanel(packAndUserRegistry())
    await screen.findByRole('button', { name: EAMES_NAME })
    await screen.findByRole('button', { name: OAK_NAME })

    expect(segmentedGroups(container)).toHaveLength(EXPECTED_SEGMENTED_GROUPS)
  })

  it('marks exactly one option active in each segmented filter group', async () => {
    const container = renderPanel(packAndUserRegistry())
    await screen.findByRole('button', { name: EAMES_NAME })
    await screen.findByRole('button', { name: OAK_NAME })

    const groups = segmentedGroups(container)
    expect(groups).toHaveLength(EXPECTED_SEGMENTED_GROUPS)
    for (const group of groups) {
      expect(activeOptionsIn(group)).toHaveLength(SINGLE_ACTIVE_OPTION)
    }
  })

  it('exposes the active segmented option through aria-pressed', async () => {
    const container = renderPanel(packAndUserRegistry())
    await screen.findByRole('button', { name: EAMES_NAME })
    await screen.findByRole('button', { name: OAK_NAME })

    const groups = segmentedGroups(container)
    expect(groups).toHaveLength(EXPECTED_SEGMENTED_GROUPS)
    for (const group of groups) {
      const [active] = activeOptionsIn(group)
      expect(active).toHaveAttribute('aria-pressed', 'true')
    }
  })

  it('routes the import button through the Button primitive', async () => {
    renderPanel(registryOf([libraryItem()], []))

    expect(screen.getByRole('button', { name: IMPORT_ACTION })).toHaveClass('ds-button')
  })

  it('still updates the visible items when a source segmented option is selected', async () => {
    const user = userEvent.setup()
    await renderBothLoaded()

    await user.click(screen.getByRole('button', { name: 'Yours' }))

    expect(screen.queryByRole('button', { name: EAMES_NAME })).toBeNull()
    expect(screen.getByRole('button', { name: OAK_NAME })).toBeInTheDocument()
  })

  it('still fires onImport when the import button is clicked', async () => {
    const user = userEvent.setup()
    const onImport = vi.fn()
    renderPanel(registryOf([libraryItem()], []), vi.fn(), onImport)

    await user.click(screen.getByRole('button', { name: IMPORT_ACTION }))

    expect(onImport).toHaveBeenCalledTimes(1)
  })
})

const LOADING_MESSAGE = 'Loading furniture...'

function neverResolvingRegistry(): AssetRegistry {
  return { list: () => new Promise(() => {}) } as unknown as AssetRegistry
}

describe('LibraryPanel loading state', () => {
  it('shows a loading message while the registry is still listing items', () => {
    renderPanel(neverResolvingRegistry())

    expect(screen.getByText(LOADING_MESSAGE)).toBeInTheDocument()
  })
})

const EXPECTED_THUMBNAIL_TILES = 2

describe('LibraryPanel thumbnail placeholders', () => {
  it('renders one decorative placeholder thumbnail tile per item without replacing its name', async () => {
    const container = renderPanel(packAndUserRegistry())
    await screen.findByRole('button', { name: EAMES_NAME })
    await screen.findByRole('button', { name: OAK_NAME })

    expect(container.querySelectorAll('.library-panel__thumb')).toHaveLength(
      EXPECTED_THUMBNAIL_TILES,
    )
    expect(screen.getByRole('button', { name: EAMES_NAME })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: OAK_NAME })).toBeInTheDocument()
  })
})

// The panel with the pack item armed, both rows listed and ready to assert on.
async function renderArmedPanel(): Promise<void> {
  const armed = libraryItem({
    name: EAMES_NAME,
    reference: { scope: PACK_SCOPE, contentHash: 'p1' },
  })
  render(
    <AssetRegistryProvider registry={packAndUserRegistry()}>
      <LibraryPanel onPick={vi.fn()} onImport={vi.fn()} armed={armed} />
    </AssetRegistryProvider>,
  )
  await screen.findByRole('button', { name: EAMES_NAME })
  await screen.findByRole('button', { name: OAK_NAME })
}

// The rotate-key segment of the placement hint, located by class rather than
// by its rendered text so that wrapping the key letter in markup (e.g. kbd)
// doesn't break the query: getByText only matches a node's direct text.
function placementKeyHint(): HTMLElement {
  return screen.getByText(
    (_, element) => element?.classList.contains('library-panel__placement-key') ?? false,
  )
}

describe('LibraryPanel placement feedback', () => {
  it('names the key that turns the ghost while the placement hint shows', async () => {
    await renderArmedPanel()

    expect(placementKeyHint()).toHaveTextContent(/\bR to rotate\b/)
  })

  it('captions the armed item and marks only its button pressed', async () => {
    await renderArmedPanel()

    expect(screen.getByText(`Click the canvas to place ${EAMES_NAME}`)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: EAMES_NAME })).toHaveAttribute('aria-pressed', 'true')
    expect(screen.getByRole('button', { name: OAK_NAME })).toHaveAttribute('aria-pressed', 'false')
  })

  it('marks the rotate key name in the placement hint as keyboard input', async () => {
    await renderArmedPanel()

    const hint = placementKeyHint()
    const key = hint.querySelector('kbd')

    expect(key).not.toBeNull()
    expect(key?.textContent).toBe('R')
    expect(hint).toHaveTextContent(/to rotate/)
  })
})

function carriesFieldControlTreatment(control: HTMLElement): boolean {
  return control.classList.contains('ds-field__control') || control.closest('.ds-field') !== null
}

describe('LibraryPanel design-system surfaces', () => {
  it('gives the furniture library region the shared menu-surface class', async () => {
    renderPanel(registryOf([libraryItem()], []))
    await screen.findByRole('button', { name: MID_CENTURY_CHAIR_NAME })

    expect(screen.getByRole('region', { name: /furniture library/i })).toHaveClass(
      'ds-menu-surface',
    )
  })

  it('routes the grid item button through the Button primitive', async () => {
    renderPanel(registryOf([libraryItem()], []))

    expect(await screen.findByRole('button', { name: MID_CENTURY_CHAIR_NAME })).toHaveClass(
      'ds-button',
    )
  })

  it('gives the furniture search input the field control treatment', async () => {
    await renderBothLoaded()

    const search = screen.getByRole('searchbox', { name: /search furniture/i })

    expect(search).toBeInTheDocument()
    expect(carriesFieldControlTreatment(search)).toBe(true)
  })
})

