import { describe, it, expect, afterEach, vi } from 'vitest'
import { render, screen, cleanup, fireEvent } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import {
  REMOVE_UNDERLAY,
  SET_UNDERLAY_OPACITY,
  SET_UNDERLAY_VISIBILITY,
  createUnderlay,
  type AssetReference,
  type Command,
  type RemoveUnderlayParams,
  type SetUnderlayVisibilityParams,
  type Underlay,
} from '../../core'
import { UnderlayRow } from './underlay-panel'

// A known floor and a single underlay built from the factory so it carries a
// real id, opacity 1, and visible true. Fixed values keep the dispatched
// command payloads deterministic.
const FLOOR_ID = 'g'
const IMAGE: AssetReference = { scope: 'project', contentHash: 'deadbeef' }
const UNDERLAY_WIDTH = 1024
const UNDERLAY_HEIGHT = 768
const ROW_LABEL = 'Plan scan'

// A new opacity entered through the opacity control. Distinct from the
// factory default (1) so the dispatched value is unambiguous.
const NEW_OPACITY = 0.5

function newUnderlay(): Underlay {
  return createUnderlay({ image: IMAGE, width: UNDERLAY_WIDTH, height: UNDERLAY_HEIGHT })
}

interface RenderResult {
  dispatch: ReturnType<typeof vi.fn>
  onCalibrate: ReturnType<typeof vi.fn>
}

function renderRow(underlay: Underlay): RenderResult {
  const dispatch = vi.fn()
  const onCalibrate = vi.fn()
  render(
    <UnderlayRow
      floorId={FLOOR_ID}
      underlay={underlay}
      label={ROW_LABEL}
      dispatch={dispatch}
      onCalibrate={onCalibrate}
    />,
  )
  return { dispatch, onCalibrate }
}

function lastCommand<P>(dispatch: ReturnType<typeof vi.fn>): Command<P> {
  return dispatch.mock.calls[0]?.[0] as Command<P>
}

afterEach(cleanup)

describe('UnderlayRow', () => {
  it('shows opacity, visibility, calibrate, and remove controls', () => {
    renderRow(newUnderlay())

    expect(screen.getByLabelText(/opacity/i)).toBeInTheDocument()
    expect(screen.getByRole('checkbox', { name: /visible/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /calibrate/i })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /remove/i })).toBeInTheDocument()
  })

  it('dispatches exactly one setUnderlayOpacity when the opacity control changes to a new value', () => {
    const underlay = newUnderlay()
    const { dispatch } = renderRow(underlay)

    const opacity = screen.getByLabelText(/opacity/i)
    fireEvent.change(opacity, { target: { value: String(NEW_OPACITY) } })

    expect(dispatch).toHaveBeenCalledTimes(1)
    expect(dispatch).toHaveBeenCalledWith(
      expect.objectContaining({
        type: SET_UNDERLAY_OPACITY,
        params: { floorId: FLOOR_ID, underlayId: underlay.id, opacity: NEW_OPACITY },
      }),
    )
  })

  it('dispatches exactly one setUnderlayVisibility with the flipped visibility when the visibility control is toggled', async () => {
    const underlay = newUnderlay()
    const user = userEvent.setup()
    const { dispatch } = renderRow(underlay)

    // The factory underlay starts visible; toggling flips it to hidden.
    await user.click(screen.getByRole('checkbox', { name: /visible/i }))

    expect(dispatch).toHaveBeenCalledTimes(1)
    expect(lastCommand<SetUnderlayVisibilityParams>(dispatch).type).toBe(SET_UNDERLAY_VISIBILITY)
    expect(lastCommand<SetUnderlayVisibilityParams>(dispatch).params).toEqual({
      floorId: FLOOR_ID,
      underlayId: underlay.id,
      visible: false,
    })
  })

  it('dispatches exactly one removeUnderlay when the remove control is pressed', async () => {
    const underlay = newUnderlay()
    const user = userEvent.setup()
    const { dispatch } = renderRow(underlay)

    await user.click(screen.getByRole('button', { name: /remove/i }))

    expect(dispatch).toHaveBeenCalledTimes(1)
    expect(lastCommand<RemoveUnderlayParams>(dispatch).type).toBe(REMOVE_UNDERLAY)
    expect(lastCommand<RemoveUnderlayParams>(dispatch).params).toEqual({
      floorId: FLOOR_ID,
      underlayId: underlay.id,
    })
  })

  it('invokes onCalibrate with the underlay id and dispatches nothing when Calibrate is pressed', async () => {
    const underlay = newUnderlay()
    const user = userEvent.setup()
    const { dispatch, onCalibrate } = renderRow(underlay)

    await user.click(screen.getByRole('button', { name: /calibrate/i }))

    expect(onCalibrate).toHaveBeenCalledTimes(1)
    expect(onCalibrate).toHaveBeenCalledWith(underlay.id)
    expect(dispatch).not.toHaveBeenCalled()
  })

  it('displays the underlay opacity as a whole-number percentage next to the slider', () => {
    renderRow({ ...newUnderlay(), opacity: NEW_OPACITY })

    expect(screen.getByText('50%')).toBeInTheDocument()
  })

  it('renders its action controls as design-system buttons', () => {
    renderRow(newUnderlay())
    for (const name of [/calibrate/i, /remove/i]) {
      expect(screen.getByRole('button', { name })).toHaveClass('ds-button')
    }
  })

  it('wraps the opacity and visibility controls in the design-system field treatment', () => {
    renderRow(newUnderlay())

    const opacity = screen.getByRole('slider')
    expect(opacity).toBe(screen.getByLabelText(/opacity/i))
    expect(opacity.closest('.ds-field')).not.toBeNull()

    const visible = screen.getByRole('checkbox', { name: /visible/i })
    expect(visible.closest('.ds-field')).not.toBeNull()
  })

  it('renders an inline labeled distance entry and helper text while calibrating, reporting typed values', () => {
    const onKnownDistanceChange = vi.fn()
    render(
      <UnderlayRow
        floorId={FLOOR_ID}
        underlay={newUnderlay()}
        label={ROW_LABEL}
        dispatch={vi.fn()}
        onCalibrate={vi.fn()}
        calibrating
        knownDistance=""
        onKnownDistanceChange={onKnownDistanceChange}
      />,
    )

    const distance = screen.getByLabelText(/known distance/i)
    expect(distance).toBeInTheDocument()
    expect(distance).toHaveValue('')
    expect(screen.getByText('Set a known distance to scale the image')).toBeInTheDocument()

    fireEvent.change(distance, { target: { value: '3 m' } })
    expect(onKnownDistanceChange).toHaveBeenCalledWith('3 m')
  })

  it('wires the calibration helper text as the known-distance input accessible description', () => {
    render(
      <UnderlayRow
        floorId={FLOOR_ID}
        underlay={newUnderlay()}
        label={ROW_LABEL}
        dispatch={vi.fn()}
        onCalibrate={vi.fn()}
        calibrating
        knownDistance=""
        onKnownDistanceChange={vi.fn()}
      />,
    )

    const input = screen.getByLabelText(/known distance/i)
    expect(input).toHaveAccessibleDescription('Set a known distance to scale the image')
  })

  it('renders neither the distance entry nor its helper text when not calibrating', () => {
    renderRow(newUnderlay())

    expect(screen.queryByLabelText(/known distance/i)).toBeNull()
    expect(screen.queryByText(/set a known distance to scale the image/i)).toBeNull()
  })
})

