import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { currentBytes } from '../../tests/storage/conformance/conformance-documents'
import { gateSaves, settle } from '../autosave/save-gate-test-kit'
import {
  createControlledLocks,
  failSaves,
  handleOf,
  placeDocument,
  rename,
  storedName,
  workspaceRequest,
} from '../handle/handle-test-kit'
import { switchProject } from './switch-project'
import {
  PROJECT_ID,
  RECOVERED_NAME,
  openStored,
  snapshotRecovered,
} from './restore-snapshot-test-kit'
import { restoreSnapshot } from './restore-snapshot'

const OTHER_ID = 'b'

/** Locks whose releases end at once, and a stored project with a handle that holds the lock. */
async function openWithFreeingLocks() {
  const locks = createControlledLocks()
  locks.endRelease()
  const opened = await openStored(locks)
  await snapshotRecovered(opened.handle)
  return { ...opened, locks }
}

beforeEach(() => {
  vi.useFakeTimers()
  vi.spyOn(console, 'warn').mockImplementation(() => undefined)
  vi.spyOn(console, 'error').mockImplementation(() => undefined)
})
afterEach(() => {
  vi.restoreAllMocks()
  vi.useRealTimers()
})

describe('the lock after a restore that handed it over', () => {
  async function restoreThenSwitchAway() {
    const opened = await openWithFreeingLocks()
    await placeDocument(opened.ports, OTHER_ID, currentBytes())
    const restored = handleOf(await restoreSnapshot(opened.handle))
    await switchProject(opened.sessionPorts, restored, workspaceRequest(OTHER_ID))
    return opened
  }

  it('a switch away from the new handle frees the lock once', async () => {
    const { locks } = await restoreThenSwitchAway()

    expect(locks.releases()).toBe(1)
    expect(await locks.port.heldIds()).toEqual(new Set([OTHER_ID]))
  })

  it('a later close of the old handle frees nothing more', async () => {
    const { handle, locks } = await restoreThenSwitchAway()

    await handle.close()

    expect(locks.releases()).toBe(1)
  })
})

describe('a restore whose save of the restored document fails', () => {
  async function restoreWithFailingSave() {
    const opened = await openWithFreeingLocks()
    const realSave = opened.ports.workspace.save.bind(opened.ports.workspace)
    failSaves(opened.ports.workspace)
    const restored = handleOf(await restoreSnapshot(opened.handle))
    const storeWorksAgain = () => {
      opened.ports.workspace.save = realSave
    }
    return { ...opened, restored, storeWorksAgain }
  }

  it('still gives the new handle, with the status error and the lock held by it alone', async () => {
    const { restored, locks } = await restoreWithFailingSave()

    expect(restored.saveStatus()).toBe('error')
    expect(await locks.port.heldIds()).toEqual(new Set([PROJECT_ID]))
    expect(locks.releases()).toBe(0)
  })

  it('a close of the new handle fails and keeps the project open', async () => {
    const { restored, locks } = await restoreWithFailingSave()

    expect(await restored.close()).toMatchObject({ ok: false })
    expect(await locks.port.heldIds()).toEqual(new Set([PROJECT_ID]))
    expect(locks.releases()).toBe(0)
  })

  it('once the store works again, a close stores the restored document and frees the lock', async () => {
    const { ports, restored, locks, storeWorksAgain } = await restoreWithFailingSave()
    storeWorksAgain()

    expect(await restored.close()).toEqual({ ok: true })

    expect(await storedName(ports.workspace, PROJECT_ID)).toBe(RECOVERED_NAME)
    expect(await locks.port.heldIds()).toEqual(new Set())
    expect(locks.releases()).toBe(1)
  })
})

describe('the old handle after a restore handed the lock over', () => {
  async function restoredWithQuietOldHandle() {
    const opened = await openWithFreeingLocks()
    handleOf(await restoreSnapshot(opened.handle))
    const listener = vi.fn()
    opened.handle.subscribe(listener)
    const store = {
      save: vi.spyOn(opened.ports.workspace, 'save'),
      read: vi.spyOn(opened.ports.workspace, 'read'),
    }
    return { ...opened, listener, store }
  }

  it('refuses a save and a flush, and a close is ok', async () => {
    const { handle } = await restoredWithQuietOldHandle()

    expect(await handle.save()).toMatchObject({ ok: false })
    expect(await handle.flush()).toMatchObject({ ok: false })
    expect(await handle.close()).toEqual({ ok: true })
  })

  it('calls no status listener', async () => {
    const { handle, listener } = await restoredWithQuietOldHandle()

    await handle.save()
    await handle.flush()
    await handle.close()
    await settle()

    expect(listener).not.toHaveBeenCalled()
  })

  it('calls no store method', async () => {
    const { handle, store } = await restoredWithQuietOldHandle()

    await handle.save()
    await handle.flush()
    await handle.close()
    await settle()

    expect(store.save).not.toHaveBeenCalled()
    expect(store.read).not.toHaveBeenCalled()
  })
})

describe('a close of the old handle during a running restore', () => {
  async function closeDuringRestore() {
    const opened = await openWithFreeingLocks()
    const gate = gateSaves(opened.ports.workspace)
    rename(opened.handle, 'Edited before the restore')
    const restoring = restoreSnapshot(opened.handle)
    await settle()
    const closing = opened.handle.close()
    await settle()
    gate.endOldestSave()
    await settle()
    gate.endOldestSave()
    await settle()
    return { ...opened, gate, closing, restoring }
  }

  it('shares the hand-over and resolves ok', async () => {
    const { closing, restoring } = await closeDuringRestore()

    expect(await closing).toEqual({ ok: true })
    expect(handleOf(await restoring).id).toBe(PROJECT_ID)
  })

  it('frees nothing, so the restored handle keeps the lock', async () => {
    const { closing, restoring, locks } = await closeDuringRestore()
    await closing
    await restoring

    expect(locks.releases()).toBe(0)
    expect(await locks.port.heldIds()).toEqual(new Set([PROJECT_ID]))
  })
})

session/projects/upgrade-edges.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { InMemoryProjectIndex, withMemoryFallback } from '../../storage'
import {
  clearLegacyActiveProjectId,
  legacyActiveProjectIdIsStored,
  plantLegacyActiveProjectId,
  storedLegacyActiveProjectId,
} from '../../storage/active-project/legacy-active-project-id-test-kit'
import { gatePuts, sampleRecord } from '../../storage/project-index/project-record-test-kit'
import { INDEX_WRITE_WAIT_MS } from '../../storage/project-index/with-memory-fallback'
import type { TestPorts } from '../handle/handle-test-kit'
import { reconcileIndex } from '..'
import {
  EARLIER_CHANGE,
  USED_AT,
  holdPutOf,
  markedRecordOf,
  placeSound,
  rebuildPorts,
  soundRecordOf,
  upgradePortsOver,
} from './rebuild-test-kit'

const READ_FAILURE = new Error('the browser index cannot be read')
const PUT_FAILURE = new Error('the browser index is full')
const CLOCK_FAILURE = new Error('the clock cannot be read')

beforeEach(() => {
  clearLegacyActiveProjectId()
  vi.spyOn(console, 'warn').mockImplementation(() => undefined)
})
afterEach(() => {
  vi.restoreAllMocks()
  vi.useRealTimers()
  clearLegacyActiveProjectId()
})

/** The ports `ports` with the clock `now` in place of their own. */
function withClock(ports: TestPorts, now: () => Date): TestPorts {
  return { ...ports, now }
}

/** Durable ports over a sound in-memory index whose store holds a sound project under each of `ids`. */
function upgradePortsWith(ids: readonly string[]): Promise<TestPorts> {
  return upgradePortsOver(new InMemoryProjectIndex(), ids)
}

describe('a marked put that does not land', () => {
  it('a switch while the marked put is in flight, then a rejection of that put, keeps the remembered id and leaves the first index empty', async () => {
    const first = new InMemoryProjectIndex()
    const puts = gatePuts(first)
    vi.spyOn(first, 'get').mockRejectedValue(READ_FAILURE)
    const ports = await upgradePortsOver(withMemoryFallback(first), ['b'])
    plantLegacyActiveProjectId('b')

    const rebuilding = reconcileIndex(ports)
    await vi.waitFor(() => expect(puts.started()).toBe(1))
    expect(await ports.index.get('b')).toBeUndefined()
    puts.endOldestPut(PUT_FAILURE)

    expect(await rebuilding).toEqual([markedRecordOf(ports, 'b')])
    expect(await first.all()).toEqual([])
    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })

  it("another project's put that lands does not remove the remembered id when the marked put rejects", async () => {
    const first = new InMemoryProjectIndex()
    const puts = gatePuts(first)
    const ports = await upgradePortsOver(withMemoryFallback(first), ['a', 'b'])
    plantLegacyActiveProjectId('b')

    const rebuilding = reconcileIndex(ports)
    await vi.waitFor(() => expect(puts.started()).toBe(2))
    puts.endOldestPutOf('a')
    await vi.waitFor(async () => expect(await first.get('a')).toEqual(soundRecordOf('a')))
    expect(legacyActiveProjectIdIsStored()).toBe(true)
    puts.endOldestPutOf('b', PUT_FAILURE)

    expect(await rebuilding).toEqual([soundRecordOf('a'), markedRecordOf(ports, 'b')])
    expect(await first.all()).toEqual([soundRecordOf('a')])
    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })

  it('a marked put that reaches the write limit and lands later leaves the next call with nothing to change, and the remembered id stays', async () => {
    vi.useFakeTimers()
    const first = new InMemoryProjectIndex()
    const held = holdPutOf(first, 'b')
    const ports = await upgradePortsOver(withMemoryFallback(first), ['b'])
    plantLegacyActiveProjectId('b')
    const marked = markedRecordOf(ports, 'b')

    const rebuilding = reconcileIndex(ports)
    await vi.advanceTimersByTimeAsync(INDEX_WRITE_WAIT_MS)
    expect(await rebuilding).toEqual([marked])
    held.release()
    await vi.waitFor(async () => expect(await first.all()).toEqual([marked]))

    const put = vi.spyOn(ports.index, 'put')
    expect(await reconcileIndex(ports)).toEqual([marked])
    expect(put).not.toHaveBeenCalled()
    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })
})

describe('the remembered id where no mark is due', () => {
  it('a workspace record under the remembered id whose time of change differs is rebuilt with its own time of use and no mark, and the remembered id stays', async () => {
    const ports = await upgradePortsWith(['b'])
    await ports.index.put(
      sampleRecord({ id: 'b', lastChangedAt: EARLIER_CHANGE, lastUsedAt: USED_AT }),
    )
    plantLegacyActiveProjectId('b')
    const rebuilt = soundRecordOf('b', { lastUsedAt: USED_AT })

    expect(await reconcileIndex(ports)).toEqual([rebuilt])

    expect(await ports.index.get('b')).toEqual(rebuilt)
    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })

  it('a workspace that is not durable leaves a value that is not a valid id in place', async () => {
    const ports = rebuildPorts()
    await placeSound(ports, ['a'])
    plantLegacyActiveProjectId('../current')

    expect(await reconcileIndex(ports)).toEqual([soundRecordOf('a')])

    expect(storedLegacyActiveProjectId()).toBe('../current')
  })
})

describe('the read of the remembered id', () => {
  it('each run reads the browser storage one time, under one key', async () => {
    const ports = await upgradePortsWith(['a', 'b'])
    plantLegacyActiveProjectId('b')
    const getItem = vi.spyOn(Storage.prototype, 'getItem')

    await reconcileIndex(ports)
    expect(getItem).toHaveBeenCalledOnce()
    await reconcileIndex(ports)
    expect(getItem).toHaveBeenCalledTimes(2)

    expect(new Set(getItem.mock.calls.map(([key]) => key)).size).toBe(1)
  })
})

describe('a clock that fails while the remembered id is upgraded', () => {
  beforeEach(() => {
    vi.spyOn(console, 'error').mockImplementation(() => undefined)
  })

  it('a clock that throws still lets the rebuild give every record, without a new time of use, and the remembered id stays', async () => {
    const sound = await upgradePortsWith(['a', 'b'])
    const ports = withClock(sound, () => {
      throw CLOCK_FAILURE
    })
    plantLegacyActiveProjectId('b')

    await expect(reconcileIndex(ports)).resolves.toEqual([soundRecordOf('a'), soundRecordOf('b')])

    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })

  it('a clock that gives an invalid date still lets the rebuild give every record, none with an invalid time, and the remembered id stays', async () => {
    const sound = await upgradePortsWith(['a', 'b'])
    const ports = withClock(sound, () => new Date(Number.NaN))
    plantLegacyActiveProjectId('b')

    const records = await reconcileIndex(ports)

    expect(records).toEqual([soundRecordOf('a'), soundRecordOf('b')])
    const times = records.flatMap((record) => [record.lastUsedAt, record.lastChangedAt])
    expect(times.filter((time) => time !== undefined && Number.isNaN(Date.parse(time)))).toEqual([])
    expect(legacyActiveProjectIdIsStored()).toBe(true)
  })
})

