import { describe, it, expect, afterEach, vi } from 'vitest'
import { render, screen, within, cleanup, fireEvent } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { DEFAULT_ENVIRONMENT_STATE, type EnvironmentState, type Site } from '../../core'
import { EnvironmentPanel } from './environment-panel'

const SITE_WITH_TIMEZONE: Site = {
  latLong: { latitude: 42.36, longitude: -71.06 },
  timezone: 'America/New_York',
}

const SITE_WITHOUT_TIMEZONE: Site = {
  latLong: { latitude: 42.36, longitude: -71.06 },
}

const SAMPLE_DAYLIGHT_NOTICE =
  'Sample daylight. Set the location and north in the Site panel for true sun angles.'

const MISSING_TIMEZONE_NOTICE =
  'The site has no timezone, so solar time is estimated from its longitude. Set the timezone ' +
  'in the Site panel for exact sun angles.'

const SCHEMATIC_LIGHTING_NOTICE =
  'Schematic lighting uses a fixed rig, so the observation time and cloud cover change nothing. ' +
  'Switch to realistic lighting to scrub the sun.'

// The observation and cloud controls only reach the render under realistic lighting, so the
// cases that drive them start from a realistic environment on a located site.
const REALISTIC_ENVIRONMENT: EnvironmentState = { ...DEFAULT_ENVIRONMENT_STATE, mode: 'realistic' }

// The sample notice is a status region whose whole text is the notice.
function sampleDaylightNotices(): HTMLElement[] {
  return screen.queryAllByRole('status').filter((n) => n.textContent === SAMPLE_DAYLIGHT_NOTICE)
}

function renderPanel(site: Site | undefined, environment: EnvironmentState): void {
  render(<EnvironmentPanel site={site} environment={environment} onEnvironmentChange={vi.fn()} />)
}

afterEach(cleanup)

describe('EnvironmentPanel', () => {
  it('calls onEnvironmentChange with the realistic mode while preserving every other field when Realistic is pressed', async () => {
    const environment: EnvironmentState = {
      ...DEFAULT_ENVIRONMENT_STATE,
      cloudCover: 0.4,
      colorCheck: true,
      observedAt: { date: '2026-03-20', minutesSinceMidnight: 600 },
    }
    const onEnvironmentChange = vi.fn()
    const user = userEvent.setup()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    const modeGroup = screen.getByRole('group', { name: /lighting mode/i })
    await user.click(within(modeGroup).getByRole('button', { name: 'Realistic' }))

    expect(onEnvironmentChange).toHaveBeenCalledWith({ ...environment, mode: 'realistic' })
  })

  it('shows the site coordinates and timezone with no sample daylight notice when the site has a location and timezone', () => {
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={{ ...DEFAULT_ENVIRONMENT_STATE, mode: 'realistic' }}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByText(/42\.36/)).toBeInTheDocument()
    expect(screen.getByText(/-71\.06/)).toBeInTheDocument()
    expect(screen.getByText(/America\/New_York/)).toBeInTheDocument()
    expect(sampleDaylightNotices()).toHaveLength(0)
  })

  it.each([
    ['no site', undefined],
    ['an empty site', {}],
    ['a site with only a north bearing of 0.5', { northBearing: 0.5 }],
    ['a site with only a north bearing of pi', { northBearing: Math.PI }],
  ] satisfies [string, Site | undefined][])(
    'shows the sample daylight notice as a status when realistic mode is selected and there is %s',
    (_label, site) => {
      renderPanel(site, REALISTIC_ENVIRONMENT)

      expect(sampleDaylightNotices()).toHaveLength(1)
    },
  )

  it('shows no sample daylight notice when the site has a location and no north bearing', () => {
    renderPanel(SITE_WITHOUT_TIMEZONE, REALISTIC_ENVIRONMENT)

    expect(sampleDaylightNotices()).toHaveLength(0)
  })

  it('does not show the sample daylight notice in schematic mode even when the site has no coordinates', () => {
    renderPanel(undefined, { ...DEFAULT_ENVIRONMENT_STATE, mode: 'schematic' })

    expect(sampleDaylightNotices()).toHaveLength(0)
    expect(screen.getByText(SCHEMATIC_LIGHTING_NOTICE)).toBeInTheDocument()
  })

  it('shows the missing-timezone notice when realistic mode is selected and the site has coordinates but no timezone', () => {
    renderPanel(SITE_WITHOUT_TIMEZONE, REALISTIC_ENVIRONMENT)

    expect(screen.getByText(MISSING_TIMEZONE_NOTICE)).toBeInTheDocument()
  })

  it('does not show the missing-timezone notice in schematic mode even when the site has no timezone', () => {
    renderPanel(SITE_WITHOUT_TIMEZONE, { ...DEFAULT_ENVIRONMENT_STATE, mode: 'schematic' })

    expect(screen.queryByText(MISSING_TIMEZONE_NOTICE)).toBeNull()
  })

  it('shows that the location is not set when the site has no coordinates', () => {
    render(
      <EnvironmentPanel
        site={undefined}
        environment={DEFAULT_ENVIRONMENT_STATE}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByText('Location: not set')).toBeInTheDocument()
  })
})

describe('EnvironmentPanel sun controls under schematic lighting', () => {
  it('disables the observation and cloud controls in schematic mode, where scrubbing the sun changes nothing', () => {
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={DEFAULT_ENVIRONMENT_STATE}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByLabelText(/observation date and time/i)).toBeDisabled()
    expect(screen.getByRole('slider', { name: /time of day/i })).toBeDisabled()
    expect(screen.getByRole('slider', { name: /cloud cover/i })).toBeDisabled()
    expect(screen.getByText(SCHEMATIC_LIGHTING_NOTICE)).toBeInTheDocument()
  })

  it('leaves the observation and cloud controls live under realistic lighting, with no schematic notice', () => {
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={REALISTIC_ENVIRONMENT}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByLabelText(/observation date and time/i)).toBeEnabled()
    expect(screen.getByRole('slider', { name: /time of day/i })).toBeEnabled()
    expect(screen.getByRole('slider', { name: /cloud cover/i })).toBeEnabled()
    expect(screen.queryByText(SCHEMATIC_LIGHTING_NOTICE)).toBeNull()
  })

  it('keeps the color check live in schematic mode, where it still neutralizes the fixed rig', () => {
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={DEFAULT_ENVIRONMENT_STATE}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByRole('button', { name: /color check/i })).toBeEnabled()
  })
})

describe('EnvironmentPanel observation date and time', () => {
  it('seeds the observation date-and-time input from observedAt and reports the parsed instant on change', () => {
    const environment: EnvironmentState = {
      ...REALISTIC_ENVIRONMENT,
      observedAt: { date: '2026-06-21', minutesSinceMidnight: 720 },
    }
    const onEnvironmentChange = vi.fn()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    const input = screen.getByLabelText(/observation date and time/i)
    expect(input).toHaveValue('2026-06-21T12:00')

    fireEvent.change(input, { target: { value: '2026-12-04T16:00' } })

    expect(onEnvironmentChange).toHaveBeenCalledWith({
      ...environment,
      observedAt: { date: '2026-12-04', minutesSinceMidnight: 960 },
    })
  })

  it('does not call onEnvironmentChange when the observation date-and-time input is cleared', () => {
    const environment: EnvironmentState = {
      ...REALISTIC_ENVIRONMENT,
      observedAt: { date: '2026-06-21', minutesSinceMidnight: 720 },
    }
    const onEnvironmentChange = vi.fn()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    fireEvent.change(screen.getByLabelText(/observation date and time/i), {
      target: { value: '' },
    })

    expect(onEnvironmentChange).not.toHaveBeenCalled()
  })

  it('does not call onEnvironmentChange for a malformed observation datetime value', () => {
    const environment: EnvironmentState = {
      ...REALISTIC_ENVIRONMENT,
      observedAt: { date: '2026-06-21', minutesSinceMidnight: 720 },
    }
    const onEnvironmentChange = vi.fn()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    // A browser without native datetime-local support renders this input as
    // plain text, so it can emit a value that does not match the
    // YYYY-MM-DDThh:mm shape. jsdom sanitizes malformed datetime-local values
    // before a change ever reaches React, so the input's type is switched to
    // text here to exercise that fallback path.
    const input = screen.getByLabelText(/observation date and time/i)
    input.setAttribute('type', 'text')

    fireEvent.change(input, { target: { value: 'not-a-datetime' } })

    expect(onEnvironmentChange).not.toHaveBeenCalled()
  })

  it('seeds a time-of-day slider from minutesSinceMidnight and preserves the date when it changes', () => {
    const environment: EnvironmentState = {
      ...REALISTIC_ENVIRONMENT,
      observedAt: { date: '2026-06-21', minutesSinceMidnight: 720 },
    }
    const onEnvironmentChange = vi.fn()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    const slider = screen.getByRole('slider', { name: /time of day/i })
    expect(slider).toHaveAttribute('min', '0')
    expect(slider).toHaveAttribute('max', '1439')
    expect(slider).toHaveValue('720')

    fireEvent.change(slider, { target: { value: '510' } })

    expect(onEnvironmentChange).toHaveBeenCalledWith({
      ...environment,
      observedAt: { date: '2026-06-21', minutesSinceMidnight: 510 },
    })
  })
})

describe('EnvironmentPanel cloud cover', () => {
  it('renders a cloud-cover dial seeded from cloudCover with a percentage readout', () => {
    const environment: EnvironmentState = { ...REALISTIC_ENVIRONMENT, cloudCover: 0.6 }
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={vi.fn()}
      />,
    )

    const dial = screen.getByRole('slider', { name: /cloud cover/i })
    expect(dial).toHaveAttribute('min', '0')
    expect(dial).toHaveAttribute('max', '1')
    expect(dial).toHaveValue('0.6')
    expect(screen.getByText('60%')).toBeInTheDocument()
  })

  it('reports a cloud-cover change when the dial moves', () => {
    const environment: EnvironmentState = { ...REALISTIC_ENVIRONMENT, cloudCover: 0.4 }
    const onEnvironmentChange = vi.fn()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    fireEvent.change(screen.getByRole('slider', { name: /cloud cover/i }), {
      target: { value: '0.6' },
    })

    expect(onEnvironmentChange).toHaveBeenCalledWith({ ...environment, cloudCover: 0.6 })
  })
})

describe('EnvironmentPanel color check', () => {
  it('renders the color-check toggle pressed when environment.colorCheck is true', () => {
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={{ ...DEFAULT_ENVIRONMENT_STATE, colorCheck: true }}
        onEnvironmentChange={vi.fn()}
      />,
    )

    expect(screen.getByRole('button', { name: /color check/i })).toHaveAttribute(
      'aria-pressed',
      'true',
    )
  })

  it('reports the flipped colorCheck with every other field preserved when the color-check toggle is clicked', async () => {
    const environment: EnvironmentState = {
      ...DEFAULT_ENVIRONMENT_STATE,
      cloudCover: 0.4,
      observedAt: { date: '2026-03-20', minutesSinceMidnight: 600 },
      colorCheck: false,
    }
    const onEnvironmentChange = vi.fn()
    const user = userEvent.setup()
    render(
      <EnvironmentPanel
        site={SITE_WITH_TIMEZONE}
        environment={environment}
        onEnvironmentChange={onEnvironmentChange}
      />,
    )

    await user.click(screen.getByRole('button', { name: /color check/i }))

    expect(onEnvironmentChange).toHaveBeenCalledWith({ ...environment, colorCheck: true })
  })
})

