import { describe, it, expect, afterEach, vi } from 'vitest'
import { render, screen, cleanup } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { REMOVE_DIMENSION, type Command, type RemoveDimensionParams } from '../../core'
import { DimensionInspector } from './dimension-inspector'

// A single selected dimension, fixed so the formatted length and the dispatched
// command payload are deterministic. A metric project formats against the metric
// defaults, mirroring the opening inspector.
const FLOOR_ID = 'floor-1'
const DIMENSION_ID = 'd1'
const LENGTH_MM = 1000
const UNITS = 'metric' as const

// A metre-scale length reads in metres with two decimals under the adaptive
// metric rule: 1000 mm renders as "1.00 m", not "1000 mm".
const EXPECTED_LENGTH = '1.00 m'

function dimensionInspectorElement(dimensionId: string, dispatch: (command: unknown) => void) {
  return (
    <DimensionInspector
      floorId={FLOOR_ID}
      dimensionId={dimensionId}
      length={LENGTH_MM}
      units={UNITS}
      dispatch={dispatch as never}
    />
  )
}

function renderInspector(dispatch: (command: unknown) => void) {
  render(dimensionInspectorElement(DIMENSION_ID, dispatch))
}

function onlyCommand<P>(dispatch: ReturnType<typeof vi.fn>): Command<P> {
  return dispatch.mock.calls[0]?.[0] as Command<P>
}

afterEach(cleanup)

describe('DimensionInspector', () => {
  it('shows the measured length formatted for the active units', () => {
    renderInspector(vi.fn())

    expect(screen.getByText(EXPECTED_LENGTH)).toBeInTheDocument()
  })

  it('renders Remove as a destructive design-system Button', () => {
    renderInspector(vi.fn())

    const removeButton = screen.getByRole('button', { name: 'Remove' })

    // Remove is routed through the design-system Button with the destructive treatment.
    expect(removeButton).toHaveClass('ds-button', 'ds-button--destructive')
  })

  it('does not dispatch removeDimension on the first Remove click; it asks for confirmation instead', async () => {
    const dispatch = vi.fn()
    const user = userEvent.setup()
    renderInspector(dispatch)

    await user.click(screen.getByRole('button', { name: 'Remove' }))

    // The first click never deletes; it only enters the confirm state.
    expect(dispatch).not.toHaveBeenCalled()

    // The plain Remove button is replaced by an explicit confirm and a cancel.
    expect(screen.queryByRole('button', { name: 'Remove' })).toBeNull()
    expect(screen.getByRole('button', { name: 'Confirm remove' })).toBeInTheDocument()
    expect(screen.getByRole('button', { name: 'Cancel' })).toBeInTheDocument()
  })

  it('dispatches removeDimension once for the floor and dimension after Remove is confirmed', async () => {
    const dispatch = vi.fn()
    const user = userEvent.setup()
    renderInspector(dispatch)

    await user.click(screen.getByRole('button', { name: 'Remove' }))
    await user.click(screen.getByRole('button', { name: 'Confirm remove' }))

    expect(dispatch).toHaveBeenCalledTimes(1)
    const command = onlyCommand<RemoveDimensionParams>(dispatch)
    expect(command.type).toBe(REMOVE_DIMENSION)
    expect(command.params.floorId).toBe(FLOOR_ID)
    expect(command.params.dimensionId).toBe(DIMENSION_ID)
  })

  it('aborts the removal and restores the Remove control when Cancel is clicked', async () => {
    const dispatch = vi.fn()
    const user = userEvent.setup()
    renderInspector(dispatch)

    await user.click(screen.getByRole('button', { name: 'Remove' }))
    await user.click(screen.getByRole('button', { name: 'Cancel' }))

    // Cancel never deletes and returns to the plain Remove control.
    expect(dispatch).not.toHaveBeenCalled()
    expect(screen.getByRole('button', { name: 'Remove' })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Confirm remove' })).toBeNull()
  })

  it('returns Remove to the unarmed state when the dimension being inspected changes', async () => {
    const dispatch = vi.fn()
    const user = userEvent.setup()
    const { rerender } = render(dimensionInspectorElement(DIMENSION_ID, dispatch))

    await user.click(screen.getByRole('button', { name: 'Remove' }))
    expect(screen.getByRole('button', { name: 'Confirm remove' })).toBeInTheDocument()

    // Retargets the SAME mounted inspector at a different dimension, without
    // remounting, mirroring how the Inspector swaps props on selection change.
    rerender(dimensionInspectorElement('d2', dispatch))

    expect(screen.getByRole('button', { name: 'Remove' })).toBeInTheDocument()
    expect(screen.queryByRole('button', { name: 'Confirm remove' })).toBeNull()
    expect(dispatch).not.toHaveBeenCalled()
