    }

    expect(floor).toHaveClass('is-active')
    expect(floor).toHaveAttribute('aria-pressed', 'true')
    expect(ceiling).not.toHaveClass('is-active')
  })

  it('switches the active surface when Ceiling is clicked', async () => {
