import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, cleanup, fireEvent } from '@testing-library/react'
import { SettingsProvider } from '../../bridge'
import { createSettingsService } from '../../session'
import { InMemorySettingsPort } from '../../session/testing'
import { stubEmptyBrowserStorage } from '../design-system/browser-environment-test-support'
import { DEFAULT_SNAP_PREFERENCES, type SnapPreferences } from '../plan/snap-preferences'
import { SETTING_NAME, shellWithProbe } from './shell-settings-test-support'

/** A catch radius that the first service holds and no default has, so that its port is told apart. */
const RADIUS_OF_A = 30

beforeEach(() => {
  stubEmptyBrowserStorage()
})

afterEach(() => {
  cleanup()
  vi.restoreAllMocks()
})

/** Preferences like the defaults, with grid snapping set to `grid`. */
function preferencesWithGrid(grid: boolean): SnapPreferences {
  return { ...DEFAULT_SNAP_PREFERENCES, kinds: { ...DEFAULT_SNAP_PREFERENCES.kinds, grid } }
}

describe('the snap preferences of the shell when the settings above it change', () => {
  it('shows the value of the new service, and a change reaches the new port only', () => {
    const storedByA: SnapPreferences = { ...preferencesWithGrid(false), pixelRadius: RADIUS_OF_A }
    const portA = new InMemorySettingsPort()
    portA.write(SETTING_NAME, storedByA)
    const portB = new InMemorySettingsPort()
    portB.write(SETTING_NAME, preferencesWithGrid(true))
    const shell = shellWithProbe()
    const { rerender } = render(
      <SettingsProvider service={createSettingsService(portA)}>{shell}</SettingsProvider>,
    )
    expect(screen.getByRole('button', { name: 'Grid snapping off' })).toBeInTheDocument()

    rerender(<SettingsProvider service={createSettingsService(portB)}>{shell}</SettingsProvider>)

    expect(screen.getByRole('button', { name: 'Grid snapping on' })).toBeInTheDocument()
    fireEvent.click(screen.getByRole('button', { name: 'Grid snapping on' }))
    expect(screen.getByRole('button', { name: 'Grid snapping off' })).toBeInTheDocument()
    expect(portB.read(SETTING_NAME)).toEqual(preferencesWithGrid(false))
    expect(portA.read(SETTING_NAME)).toEqual(storedByA)
  })
})

core/format/codec/encode-document.test.t.source:
import { describe, expect, it } from 'vitest'
import {
  VERSION_FIXTURE_VERSIONS,
  versionFixtureBytes,
} from '../../../tests/fixtures/projects/versions'
import {
  atHigherRevision,
  bytesOf,
  firstWallOf,
  fixtureDocument,
  HIGHER_REVISION,
  metaOf,
  projectOf,
  UNKNOWN_FIELD,
  UNKNOWN_WALL_FIELD_PATH,
  withUnknownWallField,
} from '../../../tests/fixtures/projects/versions/fixture-documents'
import type { Json } from '../../../tests/fixtures/projects/versions/fixture-documents'
import { CURRENT_SCHEMA_REVISION, CURRENT_SCHEMA_VERSION } from '../../index'
import type { Project, ProjectShape, RegistryMigration } from '../../index'
import type { CodecOptions, DecodeFailure, DecodeResult } from './codec-types'
import { decodeDocument } from './decode-document'
import { encodeDocument } from './encode-document'

const OLDER_VERSION = 8
const REVISION_OF_AN_OLDER_FILE = 3
const VERSION_NO_STEP_STARTS_FROM = 0
const UNKNOWN_ROOT_FIELD = 'x-unknown-root'
const REGISTRY = 'example-registry'
const REGISTRY_VERSION_BEHIND = 1
const LEGACY = 'legacy'

const encodeText = (text: string): Uint8Array => new TextEncoder().encode(text)

function failureOf(result: DecodeResult): DecodeFailure {
  if (result.ok) throw new Error('Expected the decode to fail, and it succeeded')
  return result.failure
}

function writtenJson(bytes: Uint8Array): Json {
  return JSON.parse(new TextDecoder().decode(bytes))
}

function firstWallOfProject(project: Project): Json {
  const wall = project.floors[0]?.walls[0]
  if (wall === undefined) throw new Error('The project has no wall')
  return wall as unknown as Json
}

function withRevision(project: Project, revision: number): Project {
  return { ...project, meta: { ...project.meta, schemaRevision: revision } }
}

function writtenRevision(project: Project, previous?: Uint8Array): unknown {
  return metaOf(writtenJson(encodeDocument(project, previous).bytes)).schemaRevision
}

describe('the revision that encode writes', () => {
  it('writes the revision of this build into meta.schemaRevision', () => {
    const project = projectOf(versionFixtureBytes(CURRENT_SCHEMA_VERSION))
    expect(writtenRevision(project)).toBe(CURRENT_SCHEMA_REVISION)
  })

  it('keeps a higher revision of the same version instead of lowering it', () => {
    const project = projectOf(bytesOf(atHigherRevision(fixtureDocument(CURRENT_SCHEMA_VERSION))))
    expect(writtenRevision(project)).toBe(HIGHER_REVISION)
  })

  it('drops, on decode, the revision that an older document named, so it is written at this build revision', () => {
    const document = fixtureDocument(OLDER_VERSION)
    metaOf(document).schemaRevision = REVISION_OF_AN_OLDER_FILE
    expect(writtenRevision(projectOf(bytesOf(document)))).toBe(CURRENT_SCHEMA_REVISION)
  })
})

describe('encoding a document that was read at a higher revision', () => {
  it('reports no fault, and its unknown field survives a second decode', () => {
    const document = atHigherRevision(withUnknownWallField(fixtureDocument(CURRENT_SCHEMA_VERSION)))
    const project = projectOf(bytesOf(document))

    const encoded = encodeDocument(project, undefined)

    expect(encoded.faults).toEqual([])
    expect(firstWallOfProject(projectOf(encoded.bytes))[UNKNOWN_FIELD]).toBe(1)
  })
})

describe('encoding a document with an unknown field at the current revision', () => {
  it('reports faults and still returns bytes that hold the document', () => {
    const project = structuredClone(projectOf(versionFixtureBytes(CURRENT_SCHEMA_VERSION)))
    firstWallOfProject(project)[UNKNOWN_FIELD] = 1

    const encoded = encodeDocument(project, undefined)

    const fault = encoded.faults.find((candidate) => candidate.path === UNKNOWN_WALL_FIELD_PATH)
    expect(fault?.rule).toBe('additionalProperties')
    expect(writtenJson(encoded.bytes)).toEqual(withRevision(project, CURRENT_SCHEMA_REVISION))
  })
})

describe('grafting the unknown keys of the previous bytes', () => {
  it('keeps an unknown key on a wall and at the root of the previous bytes', () => {
    const previous = atHigherRevision(withUnknownWallField(fixtureDocument(CURRENT_SCHEMA_VERSION)))
    previous[UNKNOWN_ROOT_FIELD] = { kept: true }
    const project = projectOf(bytesOf(atHigherRevision(fixtureDocument(CURRENT_SCHEMA_VERSION))))

    const written = writtenJson(encodeDocument(project, bytesOf(previous)).bytes)

    expect(written[UNKNOWN_ROOT_FIELD]).toEqual({ kept: true })
    expect(firstWallOf(written)[UNKNOWN_FIELD]).toBe(1)
  })
})

function previousAtVersion(version: number): Uint8Array {
  const document = fixtureDocument(CURRENT_SCHEMA_VERSION)
  metaOf(document).schemaVersion = version
  return bytesOf(document)
}

const PREVIOUS_THAT_CANNOT_BE_GRAFTED = [
  { kind: 'not-json', previous: encodeText('{ this is not json') },
  { kind: 'not-a-project', previous: encodeText('{}') },
  { kind: 'newer-version', previous: previousAtVersion(CURRENT_SCHEMA_VERSION + 1) },
  { kind: 'migration-failed', previous: previousAtVersion(VERSION_NO_STEP_STARTS_FROM) },
]

describe('previous bytes that fail to decode', () => {
  it.each(PREVIOUS_THAT_CANNOT_BE_GRAFTED)(
    'are ignored when the failure is $kind, and the failure is reported as it is',
    ({ kind, previous }) => {
      const project = projectOf(versionFixtureBytes(CURRENT_SCHEMA_VERSION))
      const decodeFailure = failureOf(decodeDocument(previous))

      const encoded = encodeDocument(project, previous)

      expect(decodeFailure.kind).toBe(kind)
      expect(encoded.faults).toEqual([])
      expect(projectOf(encoded.bytes)).toEqual(withRevision(project, CURRENT_SCHEMA_REVISION))
      expect(encoded.graftDropped).toEqual(decodeFailure)
    },
  )
})

describe.each(VERSION_FIXTURE_VERSIONS)('encoding the decoded version %i fixture', (version) => {
  it('decodes to the same project, now at the revision of this build', () => {
    const bytes = versionFixtureBytes(version)
    const first = projectOf(bytes)

    const second = projectOf(encodeDocument(first, bytes).bytes)

    expect(second).toEqual(withRevision(first, CURRENT_SCHEMA_REVISION))
  })
})

const dropsLegacyFromExtensions: RegistryMigration = {
  registry: REGISTRY,
  from: REGISTRY_VERSION_BEHIND,
  migrate: (project: ProjectShape): ProjectShape => {
    const extensions = Object.entries(project.extensions as Json)
    return {
      ...project,
      extensions: Object.fromEntries(extensions.filter(([key]) => key !== LEGACY)),
    }
  },
}

function storedDocumentOneRegistryVersionBehind(): Json {
  const document = fixtureDocument(CURRENT_SCHEMA_VERSION)
  metaOf(document).registryVersions = { [REGISTRY]: REGISTRY_VERSION_BEHIND }
  document.extensions = { ...(document.extensions as Json), [LEGACY]: 'left behind' }
  return document
}

describe('bringing the previous file current before the graft', () => {
  it('does not bring back a key that a pending registry migration dropped', () => {
    const options: CodecOptions = { migration: { registryMigrations: [dropsLegacyFromExtensions] } }
    const stored = bytesOf(storedDocumentOneRegistryVersionBehind())
    const project = projectOf(stored, options)

    const encoded = encodeDocument(project, stored, options)

    expect(projectOf(encoded.bytes, options).extensions ?? {}).not.toHaveProperty(LEGACY)
  })
})

session/handle/handle-record-memory-fall.source:
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { InMemoryProjectIndex, withMemoryFallback } from '../../storage'
import type { ProjectIndex } from '../../storage'
import {
  gatePuts,
  holdFirstPut,
  holdReads,
  rejectEveryCall,
  sampleRecord,
  watch,
} from '../../storage/project-index/project-record-test-kit'
import {
  INDEX_READ_WAIT_MS,
  INDEX_WRITE_WAIT_MS,
} from '../../storage/project-index/with-memory-fallback'
import { currentBytes } from '../../tests/storage/conformance/conformance-documents'
import { settle } from '../autosave/save-gate-test-kit'
import { RECORD_WAIT_MS } from './handle-record'
import {
  createTestPorts,
  hideTimesOfChange,
  openOrThrow,
  placeDocument,
  recordOf,
  rename,
  workspaceRequest,
} from './handle-test-kit'
import type { TestPorts } from './handle-test-kit'

const PROJECT_ID = 'a'
const OTHER_ID = 'b'
const RECORDED_CHANGE = '2026-10-20T08:00:00.000Z'
const LAST_MILLISECOND = 1

let consoleWarn: ReturnType<typeof vi.spyOn>

interface OverFallback {
  readonly ports: TestPorts
  /** The index that the wrapper answers from until it switches. */
  readonly durable: InMemoryProjectIndex
  /** The wrapper that the ports hold. */
  readonly index: ProjectIndex
}

/** Ports whose index is the memory fall-back over `durable`, with the project `a` stored. */
async function portsOverFallback(durable = new InMemoryProjectIndex()): Promise<OverFallback> {
  const index = withMemoryFallback(durable)
  const ports = createTestPorts({ index })
  await placeDocument(ports, PROJECT_ID, currentBytes())
  return { ports, durable, index }
}

/** Makes the next `all` of `durable` reject, and reads through the wrapper, so that it switches. */
async function switchToMemory(durable: ProjectIndex, index: ProjectIndex): Promise<void> {
  vi.spyOn(durable, 'all').mockRejectedValueOnce(new Error('the browser index failed'))
  expect(await index.all()).toEqual([])
}

/**
 * Ports over the fall-back of an index whose puts never answer, a handle on `a` whose record of
 * the open is held in its put, and a save whose record waits behind it.
 */
async function saveBehindAHeldOpenRecord() {
  vi.useFakeTimers()
  const durable = new InMemoryProjectIndex()
  const puts = gatePuts(durable)
  const { ports } = await portsOverFallback(durable)
  const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
  await settle()
  expect(puts.started()).toBe(1)
  rename(handle, 'Saved while the record of the open waits')
  expect(await handle.save()).toEqual({ ok: true })
  await settle()
  expect(puts.started()).toBe(1)
  return { ports, handle, puts }
}

beforeEach(() => {
  consoleWarn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
  vi.spyOn(console, 'error').mockImplementation(() => undefined)
})
afterEach(() => {
  vi.restoreAllMocks()
  vi.useRealTimers()
})

describe('a record of the keeper when the index switches to memory', () => {
  it('a keeper read that is pending when the index switches gets the answer of memory', async () => {
    const { ports, durable, index } = await portsOverFallback()
    const stored = sampleRecord({ id: PROJECT_ID, lastChangedAt: RECORDED_CHANGE })
    await durable.put(stored)
    hideTimesOfChange(ports)
    const gets = holdReads(durable, 'get')
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    await settle()
    expect(gets.started()).toBe(1)

    await switchToMemory(durable, index)
    gets.answerOldest()

    const record = await recordOf(ports, PROJECT_ID)
    expect(record?.name).toBe(handle.session.getProject().meta.name)
    expect(record?.lastChangedAt).toBeUndefined()
    expect(await durable.all()).toEqual([stored])
    expect(consoleWarn).toHaveBeenCalledTimes(1)
  })

  it('an edit while that read is pending leaves no record in memory or in the browser index', async () => {
    const { ports, durable, index } = await portsOverFallback()
    const stored = sampleRecord({ id: PROJECT_ID, lastChangedAt: RECORDED_CHANGE })
    await durable.put(stored)
    hideTimesOfChange(ports)
    const gets = holdReads(durable, 'get')
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    await settle()
    const durablePut = vi.spyOn(durable, 'put')

    rename(handle, 'Edited while the index was read')
    await switchToMemory(durable, index)
    gets.answerOldest()
    await settle()

    expect(await index.all()).toEqual([])
    expect(await durable.all()).toEqual([stored])
    expect(durablePut).not.toHaveBeenCalled()
  })

  it('a record write that runs when the index switches lands in the browser index, and the next one in memory', async () => {
    const { ports, durable, index } = await portsOverFallback()
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    await settle()
    const firstPut = holdFirstPut(durable)
    rename(handle, 'First')
    await handle.save()
    await settle()
    expect(firstPut.started()).toBe(1)

    await switchToMemory(durable, index)
    firstPut.release()
    await settle()
    rename(handle, 'Second')
    await handle.save()

    expect(await recordOf(ports, PROJECT_ID)).toMatchObject({ name: 'Second' })
    expect(await durable.get(PROJECT_ID)).toMatchObject({ name: 'First' })
    expect(firstPut.started()).toBe(1)
  })
})

describe('the warnings of the keeper and of the memory fall-back', () => {
  it('writes that the browser index refuses switch nothing and warn once for each opened project', async () => {
    const durable = new InMemoryProjectIndex()
    rejectEveryCall(durable)
    const { ports, index } = await portsOverFallback(durable)
    await placeDocument(ports, OTHER_ID, currentBytes())

    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    await openOrThrow(ports, workspaceRequest(OTHER_ID))
    rename(handle, 'Saved')
    expect(await handle.save()).toEqual({ ok: true })
    await settle()
    expect(consoleWarn).toHaveBeenCalledTimes(2)

    expect(await index.all()).toEqual([])
    expect(consoleWarn).toHaveBeenCalledTimes(3)
  })

  it('a close over a read that never answers ends at the wait of the keeper, before the index switches', async () => {
    vi.useFakeTimers()
    const { ports, durable, index } = await portsOverFallback()
    hideTimesOfChange(ports)
    holdReads(durable, 'get')
    const durablePut = vi.spyOn(durable, 'put')
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    await settle()

    const closing = watch(handle.close())
    await settle()
    await vi.advanceTimersByTimeAsync(RECORD_WAIT_MS - LAST_MILLISECOND)
    expect(closing()).toEqual({ status: 'pending' })
    await vi.advanceTimersByTimeAsync(LAST_MILLISECOND)
    expect(closing()).toEqual({ status: 'answered', value: { ok: true } })
    expect(ports.lockRegistry.has(PROJECT_ID)).toBe(false)
    expect(consoleWarn).toHaveBeenCalledTimes(1)

    await vi.advanceTimersByTimeAsync(INDEX_READ_WAIT_MS - RECORD_WAIT_MS - LAST_MILLISECOND)
    expect(consoleWarn).toHaveBeenCalledTimes(1)
    await vi.advanceTimersByTimeAsync(LAST_MILLISECOND)
    await settle()
    expect(consoleWarn).toHaveBeenCalledTimes(2)
    const wrapperWarning: unknown[] = consoleWarn.mock.calls[1] ?? []
    expect(wrapperWarning.some((argument) => argument instanceof Error)).toBe(true)
    expect(await index.all()).toEqual([])
    expect(durablePut).not.toHaveBeenCalled()
  })
})

describe('record writes over the fall-back when the puts of the index never answer', () => {
  it('the put of the open gives up at the write limit with one warning, and the record of the waiting save starts its put at once', async () => {
    const { puts } = await saveBehindAHeldOpenRecord()

    await vi.advanceTimersByTimeAsync(INDEX_WRITE_WAIT_MS - LAST_MILLISECOND)
    expect([puts.started(), consoleWarn.mock.calls.length]).toEqual([1, 0])
    await vi.advanceTimersByTimeAsync(LAST_MILLISECOND)
    await settle()

    expect(puts.started()).toBe(2)
    expect(puts.startedRecords()[1]?.name).toBe('Saved while the record of the open waits')
    expect(consoleWarn).toHaveBeenCalledTimes(1)
  })

  it('a close while the put of the save is held resolves at the wait of the keeper, and no third put starts', async () => {
    const { ports, handle, puts } = await saveBehindAHeldOpenRecord()
    await vi.advanceTimersByTimeAsync(INDEX_WRITE_WAIT_MS)
    await settle()
    expect(puts.started()).toBe(2)

    const closing = watch(handle.close())
    await settle()
    await vi.advanceTimersByTimeAsync(RECORD_WAIT_MS - LAST_MILLISECOND)
    expect(closing()).toEqual({ status: 'pending' })
    await vi.advanceTimersByTimeAsync(LAST_MILLISECOND)

    expect(closing()).toEqual({ status: 'answered', value: { ok: true } })
    expect(ports.lockRegistry.has(PROJECT_ID)).toBe(false)
    await vi.advanceTimersByTimeAsync(INDEX_WRITE_WAIT_MS)
    await settle()
    expect(puts.started()).toBe(2)
  })
})

app/use-open-file-action-asset-report.te.source:
import { describe, it, expect, vi, afterEach } from 'vitest'
import { act, cleanup, renderHook, waitFor } from '@testing-library/react'
import type { AssetReference } from '../core'
import { NotificationProvider, useNotifications } from '../editor/design-system'
import type { DocumentHandle } from '../session'
import { ARCHIVE_LIMITS } from '../storage'
import { createTestPorts } from '../session/handle/handle-test-kit'
import {
  actionsContext,
  closeOpenedHandles,
  openStoredProject,
  packListing,
  projectFileReferring,
  READ_FAILURE,
  settleTheAction,
  shownMessages,
  shownWarnings,
  STORED_PROJECT_ID,
  STORED_PROJECT_NAME,
  unreadableFile,
  waitForOtherProject,
} from './action-test-support'
import { runNothing } from './app-test-support'
import { importMissingAssetsText } from './asset-report-text'
import { renderOpenFileAction, TOO_LARGE_SENTENCE } from './open-file-action-test-support'
import { useOpenFileAction } from './use-open-file-action'
import type { RunFlow } from './use-open-project'

const USER_REFERENCE: AssetReference = { scope: 'user', contentHash: 'a'.repeat(64) }
const PACK_REFERENCE: AssetReference = {
  scope: 'pack:vernacular-starter@1.0.0',
  contentHash: 'd'.repeat(64),
}
const OTHER_PACK_REFERENCE: AssetReference = {
  scope: 'pack:vernacular-starter@1.0.0',
  contentHash: 'e'.repeat(64),
}

/** The handles that an owner of a case opened by a flow, closed after the case. */
const importedHandles: DocumentHandle[] = []

afterEach(async () => {
  cleanup()
  await closeOpenedHandles()
  await act(async () => {
    await Promise.all(importedHandles.splice(0).map((handle) => handle.close()))
  })
  vi.restoreAllMocks()
})

/** A library that lists nothing, and how often its listing was asked for. */
function countedListing() {
  const list = vi.fn(() => Promise.resolve([]))
  return { packs: { list }, listed: () => list.mock.calls.length }
}

describe('the warning for a file that lacks assets, when the library is not known', () => {
  it('shows no warning for a pack asset, and opens the file, when the listing of the library fails', async () => {
    const warn = vi.spyOn(console, 'warn').mockImplementation(() => {})
    const failing = { list: () => Promise.reject(new Error(READ_FAILURE)) }
    const { handle, result } = await renderOpenFileAction(failing)

    await act(async () => {
      await result.current.actions.onImportDroppedFile(projectFileReferring(PACK_REFERENCE))
    })
    await waitForOtherProject(result, handle)
    await settleTheAction()

    expect(shownWarnings(result)).toEqual([])
    expect(warn).toHaveBeenCalledTimes(1)
  })

  it('counts a pack asset as lacking when the application has no library', async () => {
    const { handle, result } = await renderOpenFileAction()

    await act(async () => {
      await result.current.actions.onImportDroppedFile(projectFileReferring(PACK_REFERENCE))
    })
    await waitForOtherProject(result, handle)
    await settleTheAction()

    expect(shownWarnings(result)).toEqual([importMissingAssetsText(1)])
  })
})

describe('the warning for a file that lacks assets, when the library lists some', () => {
  it('counts only the asset that the library does not list, in the singular', async () => {
    const { result } = await renderOpenFileAction(packListing(PACK_REFERENCE))

    await act(async () => {
      await result.current.actions.onImportDroppedFile(
        projectFileReferring(PACK_REFERENCE, USER_REFERENCE),
      )
    })

    await waitFor(() => expect(shownWarnings(result)).toEqual([importMissingAssetsText(1)]))
  })

  it('asks the library for its listing one time for an import that refers to many assets', async () => {
    const { packs, listed } = countedListing()
    const { handle, result } = await renderOpenFileAction(packs)

    await act(async () => {
      await result.current.actions.onImportDroppedFile(
        projectFileReferring(PACK_REFERENCE, OTHER_PACK_REFERENCE, USER_REFERENCE),
      )
    })
    await waitForOtherProject(result, handle)
    await settleTheAction()

    expect(listed()).toBe(1)
  })
})

/** The ports and the open project of a case that runs its own owner. */
async function openedProject() {
  const ports = createTestPorts()
  const handle = await openStoredProject(ports, STORED_PROJECT_ID, STORED_PROJECT_NAME)
  return { ports, handle }
}

/** The open file action behind the owner `runFlow`, with the notifications that show beside it. */
function renderBehindOwner(handle: DocumentHandle, runFlow: RunFlow) {
  return renderHook(
    () => {
      const notifications = useNotifications()
      const actions = useOpenFileAction({ ...actionsContext(handle), notifications, runFlow })
      return { actions, shown: notifications.notifications }
    },
    { wrapper: NotificationProvider },
  )
}

describe('the warning for a file that is not opened', () => {
  it('shows no warning when the owner starts no flow, as when the unsaved edits are kept', async () => {
    const { handle } = await openedProject()
    const { result } = renderBehindOwner(handle, runNothing)

    await act(async () => {
      await result.current.actions.onImportDroppedFile(projectFileReferring(USER_REFERENCE))
    })
    await settleTheAction()

    expect(shownMessages(result)).toEqual([])
  })

  it('shows one warning for two files dropped together while the owner runs the first', async () => {
    const { ports, handle } = await openedProject()
    let openGate = () => {}
    const gate = new Promise<void>((resolve) => {
      openGate = resolve
    })
    const started = vi.fn()
    const runFlow: RunFlow = async (flow) => {
      if (started.mock.calls.length > 0) return undefined
      started()
      await gate
      const flowResult = await flow(ports, handle)
      if (flowResult.ok) importedHandles.push(flowResult.handle)
      return flowResult
    }
    const { result } = renderBehindOwner(handle, runFlow)

    await act(async () => {
      const drops = [USER_REFERENCE, USER_REFERENCE].map((reference) =>
        result.current.actions.onImportDroppedFile(projectFileReferring(reference)),
      )
      await settleTheAction()
      openGate()
      await Promise.all(drops)
    })
    await settleTheAction()

    expect(started).toHaveBeenCalledTimes(1)
    expect(shownWarnings(result)).toEqual([importMissingAssetsText(1)])
  })

  it('does not ask the library for its listing about a file that cannot be read', async () => {
    const { packs, listed } = countedListing()
    const { result } = await renderOpenFileAction(packs)

    await act(async () => {
      await result.current.actions.onImportDroppedFile(unreadableFile().file)
    })
    await settleTheAction()

    expect(shownMessages(result)).toEqual([`Open failed: ${READ_FAILURE}`])
    expect(listed()).toBe(0)
  })

  it('does not ask the library for its listing about a file above the size limit', async () => {
    const { packs, listed } = countedListing()
    const { result } = await renderOpenFileAction(packs)
    const { file } = unreadableFile({ size: ARCHIVE_LIMITS.archiveBytes + 1 })

    await act(async () => {
      await result.current.actions.onImportDroppedFile(file)
    })
    await settleTheAction()

    expect(shownMessages(result)).toEqual([TOO_LARGE_SENTENCE])
    expect(listed()).toBe(0)
  })
})

describe('the size limit on a dropped file', () => {
  it('refuses a .building file above the limit before it reads any of its bytes', async () => {
    const { result } = await renderOpenFileAction()
    const { file, reads } = unreadableFile({
      size: ARCHIVE_LIMITS.archiveBytes + 1,
      name: 'house.building',
    })

    await act(async () => {
      await result.current.actions.onImportDroppedFile(file)
    })
    await settleTheAction()

    expect(shownMessages(result)).toEqual([TOO_LARGE_SENTENCE])
    expect(reads()).toBe(0)
    expect(result.current.flowsStarted()).toBe(0)
  })

  it('tells a file of another kind above the limit that it is too large', async () => {
    const { result } = await renderOpenFileAction()
    const { file } = unreadableFile({ size: ARCHIVE_LIMITS.archiveBytes + 1, name: 'plan.pdf' })

    await act(async () => {
      await result.current.actions.onImportDroppedFile(file)
    })
    await settleTheAction()

    expect(shownMessages(result)).toEqual([TOO_LARGE_SENTENCE])
  })
})

