import { render, screen } from '@testing-library/react'
import { describe, expect, it } from 'vitest'
import { NotificationProvider, BannerRegion } from '../editor/design-system'
import { useDegradedStorageBanner } from './use-degraded-storage-banner'
import type { StorageCapabilities } from '../storage'

const degraded: StorageCapabilities = {
  opfs: false,
  indexedDb: false,
  fileSystemAccess: false,
  persisted: false,
  estimatedQuotaBytes: null,
}

function Harness({ capabilities }: { capabilities: StorageCapabilities | null }) {
  useDegradedStorageBanner(capabilities)
  return <BannerRegion />
}

describe('useDegradedStorageBanner', () => {
  it('raises a dismissible storage-degraded banner when degraded', () => {
    render(
      <NotificationProvider>
        <Harness capabilities={degraded} />
      </NotificationProvider>,
    )
    expect(screen.getByRole('alert')).toHaveTextContent(/storage/i)
    expect(screen.getByRole('button', { name: /dismiss/i })).toBeInTheDocument()
  })

  it('raises nothing while capabilities are still resolving', () => {
    const { container } = render(
      <NotificationProvider>
        <Harness capabilities={null} />
      </NotificationProvider>,
    )
    expect(container).toBeEmptyDOMElement()
  })
})

bridge/react/framed-scene.test.ts.source:
import { describe, it, expect } from 'vitest'
import { buildFramedScene } from './framed-scene'
import { findByEntityId } from '../../engine/testing'
import { updateNearWallTransparency } from '../../engine'
import {
  glassOpacityOf,
  opacitiesOf,
  squareRoomWithSouthWindow,
} from './near-wall-fade-test-support'
import {
  DEFAULT_CAMERA_POSE,
  builtinFinishes,
  cameraOutsideBuilding,
  colorFromHex,
  getEntry,
  solidTreatment,
  surfaceKey,
} from '../../core'
import type { RoomSceneNode, SceneGraph } from '../../core'

// Reads the roughness of the 'top' material on the painted floor slab. The slab mesh is
// found by its floor surface ref, so an unrelated 'top'-named material (a wall cap, a
// junction fill) cannot shadow it whatever the subgroup assembly order. Structural so the
// bridge test does not import three.
function topRoughnessOf(root: unknown): number | undefined {
  let roughness: number | undefined
  ;(root as { traverse(cb: (object: unknown) => void): void }).traverse((object) => {
    const mesh = object as {
      material?: unknown
      userData?: { surface?: { kind?: string } }
    }
    if (mesh.userData?.surface?.kind !== 'floor' || !Array.isArray(mesh.material)) {
      return
    }
    const top = (mesh.material as { name: string; roughness: number }[]).find(
      (material) => material.name === 'top',
    )
    if (top !== undefined) {
      roughness = top.roughness
    }
  })
  return roughness
}

describe('buildFramedScene', () => {
  const wallLength = 2000
  const thickness = 120
  const height = 2400
  const graph: SceneGraph = {
    nodes: [{ id: 'floor:g', kind: 'floor', name: 'Ground', elevation: 0 }],
    walls: [
      {
        id: 'wall:w1',
        kind: 'wall',
        floorId: 'g',
        start: { x: 0, y: 0 },
        end: { x: wallLength, y: 0 },
        thickness,
        height,
      },
    ],
    rooms: [],
    underlays: [],
    openings: [],
    dimensions: [],
    stairs: [],
    furniture: [],
  }

  it('frames the camera on the world bounds of a scene that has walls', () => {
    const { root, pose } = buildFramedScene(graph)

    // The wall mesh is present in the built scene.
    expect(findByEntityId(root, 'wall:w1')).not.toBeNull()

    // The wall extrudes into a box spanning x in [0, L], y in [0, h],
    // z in [-t/2, t/2]; its center is (L/2, h/2, 0).
    const precision = 3
    expect(pose.target.x).toBeCloseTo(wallLength / 2, precision)
    expect(pose.target.y).toBeCloseTo(height / 2, precision)
    expect(pose.target.z).toBeCloseTo(0, precision)

    // The far plane reaches at least the bounding box's diagonal, so the
    // geometry stays inside the frustum; both planes are finite and positive.
    const diagonal = Math.hypot(wallLength, height, thickness)
    expect(pose.far).toBeGreaterThanOrEqual(diagonal)
    expect(Number.isFinite(pose.near)).toBe(true)
    expect(Number.isFinite(pose.far)).toBe(true)
    expect(pose.near).toBeGreaterThan(0)
    expect(pose.far).toBeGreaterThan(0)

    // The camera is pulled back from the geometry on every axis rather than
    // sitting on the origin.
    expect(pose.position.x).toBeGreaterThan(pose.target.x)
    expect(pose.position.y).toBeGreaterThan(pose.target.y)
    expect(pose.position.z).toBeGreaterThan(pose.target.z)
  })

  it('returns the scene world bounds alongside the framed pose', () => {
    const { bounds } = buildFramedScene(graph)

    expect(bounds).not.toBeNull()
    expect(bounds?.max.x).toBeGreaterThan(bounds?.min.x ?? 0)
  })

  it('marks the shell meshes as shadow casters and receivers', () => {
    const { root } = buildFramedScene(graph)

    // findByEntityId returns the wall mesh; read the shadow flags structurally so the
    // bridge test does not import three.
    const wall = findByEntityId(root, 'wall:w1') as {
      castShadow: boolean
      receiveShadow: boolean
    } | null
    expect(wall?.castShadow).toBe(true)
    expect(wall?.receiveShadow).toBe(true)
  })

  it('returns a finite default pose for a scene with no renderable geometry', () => {
    const graph: SceneGraph = {
      nodes: [{ id: 'floor:g', kind: 'floor', name: 'Ground', elevation: 0 }],
      walls: [],
      rooms: [],
      underlays: [],
      openings: [],
      dimensions: [],
      stairs: [],
      furniture: [],
    }

    const { pose } = buildFramedScene(graph)

    // DEFAULT_CAMERA_POSE carries finite, non-NaN near/far, so this equality also
    // guards the empty-scene regression: an Infinity-valued bounds would frame to a
    // NaN pose that could never equal the fixed default.
    expect(pose).toEqual(DEFAULT_CAMERA_POSE)
  })

  it('prepares the exterior walls of a room for near-wall transparency', () => {
    const roomGraph: SceneGraph = { ...squareRoomWithSouthWindow(height), openings: [] }

    // All four walls of the single room are exterior, so the build prepares one
    // near-wall-transparency target per wall.
    expect(buildFramedScene(roomGraph).nearWallTargets).toHaveLength(4)
  })

  it('folds an opening on an exterior wall into its wall fade target', () => {
    const fadedOpacity = 0.1
    const { root, nearWallTargets } = buildFramedScene(squareRoomWithSouthWindow(height))

    const group = findByEntityId(root, 'opening:window')
    expect(group).not.toBeNull()
    // The glass starts solid, so the fade below is what changes it.
    expect(glassOpacityOf(group)).not.toBe(fadedOpacity)

    // Camera outside the south wall (world z > 0, since plan y maps to world -z): it
    // fades, and its window with it.
    updateNearWallTransparency(nearWallTargets, { x: 2000, z: 3000 })

    expect(glassOpacityOf(group)).toBe(fadedOpacity)
  })

  it('folds furniture standing against an exterior wall into its wall fade target', () => {
    const fadedOpacity = 0.1
    const graph = squareRoomWithSouthWindow(height)
    // A wardrobe flush against the south wall's interior face (plan y = 100), plus a
    // free-standing table mid-room that must not join any wall's fade target.
    graph.furniture = [
      {
        id: 'furniture:wardrobe',
        kind: 'furniture',
        floorId: 'g',
        footprintCorners: [
          { x: 500, y: 100 },
          { x: 1100, y: 100 },
          { x: 1100, y: 700 },
          { x: 500, y: 700 },
        ],
        elevationZ: 0,
        height: 1800,
        assetRef: { scope: 'user', contentHash: 'hash-of-a-wardrobe' },
      },
      {
        id: 'furniture:table',
        kind: 'furniture',
        floorId: 'g',
        footprintCorners: [
          { x: 1700, y: 1700 },
          { x: 2300, y: 1700 },
          { x: 2300, y: 2300 },
          { x: 1700, y: 2300 },
        ],
        elevationZ: 0,
        height: 750,
        assetRef: { scope: 'user', contentHash: 'hash-of-a-table' },
      },
    ]
    const { root, nearWallTargets } = buildFramedScene(graph)

    // Camera outside the south wall: the wall fades and the wardrobe against it
    // recedes with it, while the free-standing table keeps its own opacity.
    updateNearWallTransparency(nearWallTargets, { x: 2000, z: 3000 })

    // Furniture groups carry the RAW instance id (the furniture-builder convention).
    const wardrobe = findByEntityId(root, 'wardrobe')
    const table = findByEntityId(root, 'table')
    expect(wardrobe).not.toBeNull()
    expect(table).not.toBeNull()
    expect(opacitiesOf(wardrobe)).toEqual([fadedOpacity])
    expect(opacitiesOf(table)).not.toContain(fadedOpacity)
  })

  it('supplies the building top elevation so a camera above the roof still counts as outside', () => {
    const { roomPolygons, buildingTopWorld } = buildFramedScene(squareRoomWithSouthWindow(height))

    // Plan (2000, 2000) sits squarely inside the room, but the camera hovers well above
    // the building's top elevation (the floor's 0mm elevation plus its 2400mm ceiling
    // height), so it counts as outside despite its interior plan position, and the fade
    // must not stand down.
    const cameraAboveRoof = { x: 2000, y: 8000, z: -2000 }
    expect(cameraOutsideBuilding(cameraAboveRoof, roomPolygons, buildingTopWorld)).toBe(true)
  })

  it('paints a room floor from the supplied paint store', () => {
    const floorId = 'g'
    const room: RoomSceneNode = {
      id: 'room:r1',
      kind: 'room',
      floorId,
      polygon: [
        { x: 0, y: 0 },
        { x: 2000, y: 0 },
        { x: 2000, y: 2000 },
        { x: 0, y: 2000 },
      ],
      clearPolygon: [
        { x: 60, y: 60 },
        { x: 1940, y: 60 },
        { x: 1940, y: 1940 },
        { x: 60, y: 1940 },
      ],
      area: 1880 * 1880,
      ceilingHeight: 2400,
    }
    const paintedGraph: SceneGraph = {
      nodes: [{ id: 'floor:g', kind: 'floor', name: 'G', elevation: 0 }],
      walls: [],
      rooms: [room],
      underlays: [],
      openings: [],
      dimensions: [],
      stairs: [],
      furniture: [],
    }
    const hex = '#aa5500'
    const ref = { kind: 'floor', floorId } as const
    const paint = { [surfaceKey(ref)]: solidTreatment(colorFromHex(hex), 'matte') }

    const { root } = buildFramedScene(paintedGraph, paint)

    let topHex: string | undefined
    root.traverse((object) => {
      const mesh = object as unknown as { material?: unknown }
      if (Array.isArray(mesh.material)) {
        const top = (mesh.material as { name: string; color: { getHexString(): string } }[]).find(
          (material) => material.name === 'top',
        )
        if (top !== undefined) {
          topHex = top.color.getHexString()
        }
      }
    })
    expect(topHex).toBe('aa5500')
  })

  it('paints a room floor with the roughness of its gloss finish', () => {
    const floorId = 'g'
    const room: RoomSceneNode = {
      id: 'room:r1',
      kind: 'room',
      floorId,
      polygon: [
        { x: 0, y: 0 },
        { x: 2000, y: 0 },
        { x: 2000, y: 2000 },
        { x: 0, y: 2000 },
      ],
      clearPolygon: [
        { x: 60, y: 60 },
        { x: 1940, y: 60 },
        { x: 1940, y: 1940 },
        { x: 60, y: 1940 },
      ],
      area: 1880 * 1880,
      ceilingHeight: 2400,
    }
    const paintedGraph: SceneGraph = {
      nodes: [{ id: 'floor:g', kind: 'floor', name: 'G', elevation: 0 }],
      walls: [],
      rooms: [room],
      underlays: [],
      openings: [],
      dimensions: [],
      stairs: [],
      furniture: [],
    }
    const hex = '#aa5500'
    const ref = { kind: 'floor', floorId } as const
    const paint = { [surfaceKey(ref)]: solidTreatment(colorFromHex(hex), 'gloss') }
    const glossRoughness = getEntry(builtinFinishes, 'gloss')?.roughness

    const { root } = buildFramedScene(paintedGraph, paint)

    expect(glossRoughness).toBeDefined()
    expect(topRoughnessOf(root)).toBe(glossRoughness)
  })
})

// Counts the edge-overlay lines under a built group, structurally so the bridge test
// does not import three. The surface edge overlay is the only build step that adds
// LineSegments to the scene.
function edgeLineCount(root: unknown): number {
  let count = 0
  ;(root as { traverse(cb: (object: { type: string }) => void): void }).traverse((object) => {
    if (object.type === 'LineSegments') count += 1
  })
  return count
}

describe('buildFramedScene edge overlay', () => {
  const ceiling = 2400

  it('draws no surface edge overlay by default (an opt-in view toggle, ADR-0132)', () => {
    const { root } = buildFramedScene(squareRoomWithSouthWindow(ceiling))

    expect(edgeLineCount(root)).toBe(0)
  })

  it('draws the surface edge overlay when the view option turns it on', () => {
    const { root } = buildFramedScene(squareRoomWithSouthWindow(ceiling), {}, { edgeOverlay: true })

    expect(edgeLineCount(root)).toBeGreaterThan(0)
  })
})

bridge/react/framed-scene-reconciler.tes.source:
/* eslint-disable max-lines --
 * A behavior-organized suite whose cases each own a self-contained SceneGraph
 * literal (reconcile caching, whole-building stacking, ground plane, edge overlay,
 * and paint). The file length tracks the number of reconciler cases, not any
 * single hard-to-read unit. */
import { describe, it, expect } from 'vitest'
import { builtinFinishes, colorFromHex, getEntry, solidTreatment, surfaceKey } from '../../core'
import type { Point, SceneGraph, SceneNode, SurfaceTreatment } from '../../core'
import { isGroundPlane, type SceneRoot } from '../../engine'
import { collectEntityIds, findByEntityId } from '../../engine/testing'
import { createFramedSceneReconciler } from './framed-scene-reconciler'

const WALL_LENGTH_MM = 2000
const WALL_THICKNESS_MM = 120
const WALL_HEIGHT_MM = 2400
const UPPER_FLOOR_ELEVATION_MM = 2700

// A one-floor, one-wall graph wrapping the given floor node, mimicking the
// active-floor-scoped graph the preview feeds the reconciler. Passing the same
// floorNode object models an unchanged floor; a fresh object models an edit.
function floorGraph(floorNode: SceneNode): SceneGraph {
  const floorId = floorNode.id.slice('floor:'.length)
  return {
    nodes: [floorNode],
    walls: [
      {
        id: `wall:${floorId}1`,
        kind: 'wall',
        floorId,
        start: { x: 0, y: 0 },
        end: { x: WALL_LENGTH_MM, y: 0 },
        thickness: WALL_THICKNESS_MM,
        height: WALL_HEIGHT_MM,
      },
    ],
    rooms: [],
    underlays: [],
    openings: [],
    dimensions: [],
    stairs: [],
    furniture: [],
  }
}

const groundFloorNode = (): SceneNode => ({
  id: 'floor:g',
  kind: 'floor',
  name: 'Ground',
  elevation: 0,
})

const emptyPaint = (): Record<string, SurfaceTreatment> => ({})

describe('createFramedSceneReconciler', () => {
  it('reuses the built scene when the floor node and paint are unchanged', () => {
    const reconciler = createFramedSceneReconciler()
    const node = groundFloorNode()
    const paint = emptyPaint()

    const first = reconciler.reconcile(floorGraph(node), paint)
    // A later render passes a fresh scoped-graph container with the same floor node.
    const second = reconciler.reconcile(floorGraph(node), paint)

    expect(second).toBe(first)
  })

  it('rebuilds when the floor node reference changes', () => {
    const reconciler = createFramedSceneReconciler()
    const paint = emptyPaint()

    const first = reconciler.reconcile(floorGraph(groundFloorNode()), paint)
    // An edit replaces the floor with a new object carrying the same id.
    const second = reconciler.reconcile(floorGraph(groundFloorNode()), paint)

    expect(second).not.toBe(first)
  })

  it('rebuilds when the paint reference changes', () => {
    const reconciler = createFramedSceneReconciler()
    const node = groundFloorNode()

    const first = reconciler.reconcile(floorGraph(node), emptyPaint())
    // Same unchanged floor node, but a new paint set: materials may differ, so rebuild.
    const second = reconciler.reconcile(floorGraph(node), emptyPaint())

    expect(second).not.toBe(first)
  })

  it('reuses a floor built earlier after switching to another floor and back', () => {
    const reconciler = createFramedSceneReconciler()
    const paint = emptyPaint()
    const ground = groundFloorNode()
    const upper: SceneNode = {
      id: 'floor:u',
      kind: 'floor',
      name: 'Upper',
      elevation: UPPER_FLOOR_ELEVATION_MM,
    }

    const groundFirst = reconciler.reconcile(floorGraph(ground), paint)
    const upperBuild = reconciler.reconcile(floorGraph(upper), paint)
    // Switch back to the unchanged ground floor (same node reference).
    const groundAgain = reconciler.reconcile(floorGraph(ground), paint)

    expect(upperBuild).not.toBe(groundFirst)
    expect(groundAgain).toBe(groundFirst)
  })

  it('builds an empty graph without throwing and returns a finite pose', () => {
    const reconciler = createFramedSceneReconciler()
    const empty: SceneGraph = {
      nodes: [],
      walls: [],
      rooms: [],
      underlays: [],
      openings: [],
      dimensions: [],
      stairs: [],
      furniture: [],
    }

    const framed = reconciler.reconcile(empty, emptyPaint())

    expect(framed.root).toBeDefined()
    expect(Number.isFinite(framed.pose.near)).toBe(true)
    expect(Number.isFinite(framed.pose.far)).toBe(true)
  })
})

// The upper floor's wall runs longer than the ground floor's, so the whole-building
// footprint (and its ground plane) reaches past the ground floor on its own.
const UPPER_WALL_LENGTH_MM = 5000

const upperFloorNode = (): SceneNode => ({
  id: 'floor:u',
  kind: 'floor',
  name: 'Upper',
  elevation: UPPER_FLOOR_ELEVATION_MM,
})

function floorWall(floorId: string, length: number): SceneGraph['walls'][number] {
  return {
    id: `wall:${floorId}1`,
    kind: 'wall',
    floorId,
    start: { x: 0, y: 0 },
    end: { x: length, y: 0 },
    thickness: WALL_THICKNESS_MM,
    height: WALL_HEIGHT_MM,
  }
}

// A two-floor whole-building graph (the projection sceneGraphForBuilding feeds the
// reconciler in building scope): one node per floor, each seated at its own elevation,
// with a wall on each floor so both floors' geometry is observable.
function twoFloorBuildingGraph(): SceneGraph {
  return {
    nodes: [groundFloorNode(), upperFloorNode()],
    walls: [floorWall('g', WALL_LENGTH_MM), floorWall('u', UPPER_WALL_LENGTH_MM)],
    rooms: [],
    underlays: [],
    openings: [],
    dimensions: [],
    stairs: [],
    furniture: [],
  }
}

const STACKED_TOP_LOWER_ELEVATION_MM = 0
const STACKED_TOP_UPPER_ELEVATION_MM = 3000
const STACKED_TOP_CEILING_MM = 2400
const STACKED_TOP_EXPECTED_MM = 5400
const STACKED_TOP_ROOM_SPAN_MM = 4000

// A room spanning the same square footprint and ceiling height on every floor,
// so only each floor's own elevation, set independently below, differs.
function stackedTopRoom(floorId: string): SceneGraph['rooms'][number] {
  const span = STACKED_TOP_ROOM_SPAN_MM
  const corners = [
    { x: 0, y: 0 },
    { x: span, y: 0 },
    { x: span, y: span },
    { x: 0, y: span },
  ]
  return {
    id: `room:${floorId}`,
    kind: 'room',
    floorId,
    polygon: corners,
    clearPolygon: corners,
    area: span * span,
    ceilingHeight: STACKED_TOP_CEILING_MM,
  }
}

// A two-floor whole-building graph with a room on each floor, so the building top can
// be pinned to a floor's own elevation plus its own ceiling height, not just the
// taller of the two floor elevations alone.
function twoFloorGraphWithCeilings(): SceneGraph {
  return {
    nodes: [
      {
        id: 'floor:g',
        kind: 'floor',
        name: 'Ground',
        elevation: STACKED_TOP_LOWER_ELEVATION_MM,
      },
      {
        id: 'floor:u',
        kind: 'floor',
        name: 'Upper',
        elevation: STACKED_TOP_UPPER_ELEVATION_MM,
      },
    ],
    walls: [floorWall('g', WALL_LENGTH_MM), floorWall('u', WALL_LENGTH_MM)],
    rooms: [stackedTopRoom('g'), stackedTopRoom('u')],
    underlays: [],
    openings: [],
    dimensions: [],
    stairs: [],
    furniture: [],
  }
}

describe('createFramedSceneReconciler whole building', () => {
  it('stacks every floor at its elevation and frames the whole building', () => {
    const framed = createFramedSceneReconciler().reconcile(twoFloorBuildingGraph(), emptyPaint())

    // Every floor renders, not just the ground floor (issue #479): the upper floor's
    // wall and floor group are both present.
    expect(findByEntityId(framed.root, 'wall:g1')).not.toBeNull()
    expect(findByEntityId(framed.root, 'wall:u1')).not.toBeNull()
    // Each floor group is seated at its own elevation (millimetres, no scale factor).
    const upperGroup = findByEntityId(framed.root, 'floor:u')
    expect(upperGroup).not.toBeNull()
    expect(upperGroup?.position.y).toBe(UPPER_FLOOR_ELEVATION_MM)
    // The camera frames the whole building: the bounds reach the upper floor's walls,
    // above the upper floor's own elevation, rather than being capped at the ground floor.
    expect(framed.bounds?.max.y ?? 0).toBeGreaterThan(UPPER_FLOOR_ELEVATION_MM)
  })

  it('seats one shared ground plane sized to the whole-building footprint', () => {
    const framed = createFramedSceneReconciler().reconcile(twoFloorBuildingGraph(), emptyPaint())

    const grounds = framed.root.children.filter(isGroundPlane)
    // A single site surface under the whole building, not one plane per floor.
    expect(grounds).toHaveLength(1)
    // Centered on the union footprint (reaching the wider upper floor), not on the
    // narrower ground floor alone.
    expect(grounds[0]?.position.x).toBeGreaterThan(WALL_LENGTH_MM)
  })

  it('renders a single-floor graph as exactly one floor group at its elevation (locks #206)', () => {
    const framed = createFramedSceneReconciler().reconcile(
      floorGraph(groundFloorNode()),
      emptyPaint(),
    )

    const floorIds = collectEntityIds(framed.root).filter((id) => id.startsWith('floor:'))
    expect(floorIds).toEqual(['floor:g'])
    expect(findByEntityId(framed.root, 'floor:g')?.position.y).toBe(0)
  })

  it('carries the building top elevation from the floor whose own ceiling reaches highest', () => {
    const framed = createFramedSceneReconciler().reconcile(
      twoFloorGraphWithCeilings(),
      emptyPaint(),
    )

    // The ground floor's own reach (0 + 2400 = 2400) sits below the upper floor's own
    // reach (3000 + 2400 = 5400), so the building top must track the upper floor.
    expect(framed.buildingTopWorld).toBe(STACKED_TOP_EXPECTED_MM)
  })
})

const ROOM_SPAN_MM = 4000
const ROOM_CEILING_MM = 2400
const WINDOW_WIDTH_MM = 900
const WINDOW_HEIGHT_MM = 1200
const WINDOW_SILL_MM = 900
const CHAIR_MIN_MM = 1000
const CHAIR_MAX_MM = 1500
const CHAIR_HEIGHT_MM = 900

function furnishedWall(id: string, start: Point, end: Point): SceneGraph['walls'][number] {
  return {
    id,
    kind: 'wall',
    floorId: 'g',
    start,
    end,
    thickness: WALL_THICKNESS_MM,
    height: ROOM_CEILING_MM,
  }
}

// A furnished one-room graph: four walls enclosing a room, a window hosted on the
// south wall, and one furniture piece, so the overlay assertions can probe every
// sub-group kind the reconciler builds (walls, rooms, openings, furniture).
function furnishedRoomGraph(): SceneGraph {
  const span = ROOM_SPAN_MM
  const corners = [
    { x: 0, y: 0 },
    { x: span, y: 0 },
    { x: span, y: span },
    { x: 0, y: span },
  ]
  return {
    nodes: [groundFloorNode()],
    walls: [
      furnishedWall('wall:s', { x: 0, y: 0 }, { x: span, y: 0 }),
      furnishedWall('wall:e', { x: span, y: 0 }, { x: span, y: span }),
      furnishedWall('wall:n', { x: span, y: span }, { x: 0, y: span }),
      furnishedWall('wall:w', { x: 0, y: span }, { x: 0, y: 0 }),
    ],
    rooms: [
      {
        id: 'room:r',
        kind: 'room',
        floorId: 'g',
        polygon: corners,
        clearPolygon: corners,
        area: span * span,
        ceilingHeight: ROOM_CEILING_MM,
      },
    ],
    underlays: [],
    openings: [
      {
        id: 'opening:window',
        kind: 'opening',
        floorId: 'g',
        type: 'double-hung-window',
        center: { x: span / 2, y: 0 },
        along: { x: 1, y: 0 },
        normal: { x: 0, y: 1 },
        width: WINDOW_WIDTH_MM,
        height: WINDOW_HEIGHT_MM,
        sillHeight: WINDOW_SILL_MM,
        hostThickness: WALL_THICKNESS_MM,
        orientation: { hinge: 'start', facing: 'positive' },
        hostWallId: 's',
      },
    ],
    dimensions: [],
    stairs: [],
    furniture: [
      {
        id: 'furniture:chair',
        kind: 'furniture',
        floorId: 'g',
        footprintCorners: [
          { x: CHAIR_MIN_MM, y: CHAIR_MIN_MM },
          { x: CHAIR_MAX_MM, y: CHAIR_MIN_MM },
          { x: CHAIR_MAX_MM, y: CHAIR_MAX_MM },
          { x: CHAIR_MIN_MM, y: CHAIR_MAX_MM },
        ],
        elevationZ: 0,
        height: CHAIR_HEIGHT_MM,
        assetRef: { scope: 'user', contentHash: 'c' },
      },
    ],
  }
}

// Whether any edge-overlay line sits under the group, structurally so the bridge test
// does not import three. The surface edge overlay is the only build step that adds
// LineSegments to the scene.
function containsEdgeLines(
  group: { traverse(cb: (object: { type: string }) => void): void } | null,
): boolean {
  if (group === null) return false
  let found = false
  group.traverse((object) => {
    if (object.type === 'LineSegments') found = true
  })
  return found
}

const BELOW_GRADE_MM = -600
const ABOVE_GRADE_MM = 300

// The ground planes seated directly under the assembled root. The site surface is a
// per-scene sibling of the floor group, not a child of any cached sub-group, so it
// shows up as a direct child of the root.
function groundPlanesOf(root: SceneRoot): SceneRoot['children'] {
  return root.children.filter(isGroundPlane)
}

describe('createFramedSceneReconciler ground plane', () => {
  it('seats the assembled root on a ground plane at the graph grade', () => {
    const reconciler = createFramedSceneReconciler()
    const graph: SceneGraph = { ...floorGraph(groundFloorNode()), gradeElevation: BELOW_GRADE_MM }

    const framed = reconciler.reconcile(graph, emptyPaint())

    const grounds = groundPlanesOf(framed.root)
    expect(grounds).toHaveLength(1)
    expect(grounds[0]?.position.y).toBeCloseTo(BELOW_GRADE_MM)
  })

  it('refreshes the ground plane to the new grade with no stale copy left behind', () => {
    const reconciler = createFramedSceneReconciler()
    // Same floor node and paint across both reconciles, so only the grade changes: the
    // cached build must refresh its ground rather than return the stale below-grade copy.
    const node = groundFloorNode()
    const paint = emptyPaint()

    const first = reconciler.reconcile(
      { ...floorGraph(node), gradeElevation: BELOW_GRADE_MM },
      paint,
    )
    expect(groundPlanesOf(first.root)).toHaveLength(1)
    expect(groundPlanesOf(first.root)[0]?.position.y).toBeCloseTo(BELOW_GRADE_MM)
    // Capture the wall sub-group before the second reconcile: the ground is per-scene,
    // so a grade-only edit must refresh it without rebuilding any floor sub-group.
    const wallFirstGroup = findByEntityId(first.root, 'wall:g1')
    expect(wallFirstGroup).not.toBeNull()

    const second = reconciler.reconcile(
      { ...floorGraph(node), gradeElevation: ABOVE_GRADE_MM },
      paint,
    )

    const grounds = groundPlanesOf(second.root)
    expect(grounds).toHaveLength(1)
    expect(grounds[0]?.position.y).toBeCloseTo(ABOVE_GRADE_MM)
    // The grade edit refreshed only the site ground: the unchanged floor's sub-groups
    // (here the wall group) are reused by reference, not rebuilt.
    expect(findByEntityId(second.root, 'wall:g1')).toBe(wallFirstGroup)
  })
})

describe('createFramedSceneReconciler edge overlay', () => {
  it('draws no surface edge overlay by default (an opt-in view toggle, ADR-0132)', () => {
    const framed = createFramedSceneReconciler().reconcile(furnishedRoomGraph(), emptyPaint())

    expect(containsEdgeLines(framed.root)).toBe(false)
  })

  it('draws the overlay on every sub-group kind when the view option turns it on', () => {
    const framed = createFramedSceneReconciler({ edgeOverlay: true }).reconcile(
      furnishedRoomGraph(),
      emptyPaint(),
    )

    expect(containsEdgeLines(findByEntityId(framed.root, 'wall:s'))).toBe(true)
    expect(containsEdgeLines(findByEntityId(framed.root, 'room:r'))).toBe(true)
    expect(containsEdgeLines(findByEntityId(framed.root, 'opening:window'))).toBe(true)
    expect(containsEdgeLines(findByEntityId(framed.root, 'chair'))).toBe(true)
  })
})

// Reads the roughness of the 'top' material on the painted floor slab. The slab mesh is
// found by its floor surface ref, so an unrelated 'top'-named material (a wall cap, a
// junction fill) cannot shadow it whatever the subgroup assembly order. Structural so the
// bridge test does not import three.
function topRoughnessOf(root: unknown): number | undefined {
  let roughness: number | undefined
  ;(root as { traverse(cb: (object: unknown) => void): void }).traverse((object) => {
    const mesh = object as {
      material?: unknown
      userData?: { surface?: { kind?: string } }
    }
    if (mesh.userData?.surface?.kind !== 'floor' || !Array.isArray(mesh.material)) {
      return
    }
    const top = (mesh.material as { name: string; roughness: number }[]).find(
      (material) => material.name === 'top',
    )
    if (top !== undefined) {
      roughness = top.roughness
    }
  })
  return roughness
}

describe('createFramedSceneReconciler paint', () => {
  it('paints a room floor with the roughness of its gloss finish', () => {
    const hex = '#aa5500'
    const ref = { kind: 'floor', floorId: 'g' } as const
    const paint = { [surfaceKey(ref)]: solidTreatment(colorFromHex(hex), 'gloss') }
    const glossRoughness = getEntry(builtinFinishes, 'gloss')?.roughness

    const framed = createFramedSceneReconciler().reconcile(furnishedRoomGraph(), paint)

    expect(glossRoughness).toBeDefined()
    expect(topRoughnessOf(framed.root)).toBe(glossRoughness)
  })
})

