import { afterEach, beforeEach, describe, expect, it, vi, type MockInstance } from 'vitest'
import { sampleRecord } from '../../storage/project-index/project-record-test-kit'
import { documentBreakingFormatRules } from '../../tests/storage/conformance/conformance-documents'
import { placeDocument } from '../handle/handle-test-kit'
import { reconcileIndex } from '..'
import { recordOfOpened } from './project-facts'
import {
  EARLIER_CHANGE,
  STORED_AT,
  USED_AT,
  documentOfNewerVersion,
  documentWithoutFloors,
  failedRecord,
  folderRecord,
  placeSound,
  rebuildPorts,
  soundRecordOf,
  stepWarnings,
  unreadRecordOf,
} from './rebuild-test-kit'

vi.mock('./project-facts', async (importOriginal) => {
  const actual = await importOriginal<typeof import('./project-facts')>()
  return { ...actual, recordOfOpened: vi.fn(actual.recordOfOpened) }
})

let consoleWarn: MockInstance<typeof console.warn>

beforeEach(() => {
  consoleWarn = vi.spyOn(console, 'warn').mockImplementation(() => undefined)
})
afterEach(() => {
  vi.restoreAllMocks()
})

/** The next record of an opened document cannot be built: its build throws once. */
function failNextRecordBuild(): void {
  vi.mocked(recordOfOpened).mockImplementationOnce(() => {
    throw new Error('the record cannot be built')
  })
}

describe('records that the next call makes again', () => {
  it('a document with no floors whose stored files cannot be read is not put and counts one failed step, and the next call puts its record with its name', async () => {
    const ports = rebuildPorts()
    const bytes = documentWithoutFloors('A plan with no floors')
    await placeDocument(ports, 'a', bytes)
    const error = new Error('the stored files cannot be read')
    vi.spyOn(ports.workspace, 'storedFiles').mockRejectedValueOnce(error)
    const put = vi.spyOn(ports.index, 'put')
    const found = failedRecord('a', bytes, 'format-rules')

    expect(await reconcileIndex(ports)).toEqual([{ ...found, name: undefined, assetHashes: [] }])
    expect(put).not.toHaveBeenCalled()
    const warnings = stepWarnings(consoleWarn.mock.calls)
    expect(warnings).toHaveLength(1)
    expect(warnings[0]).toContain(1)
    expect(warnings[0]).toContain(error)

    expect(await reconcileIndex(ports)).toEqual([found])
    expect(await ports.index.get('a')).toEqual(found)
    expect(found.name).toBe('A plan with no floors')
  })

  it('stored files that hold no document file give a record with no name that is put, and once the project is deleted the next call drops it', async () => {
    const ports = rebuildPorts()
    const bytes = documentOfNewerVersion('Drawn by a later release')
    await placeDocument(ports, 'later', bytes)
    vi.spyOn(ports.workspace, 'storedFiles').mockResolvedValueOnce(new Map())
    const nameless = {
      ...failedRecord('later', bytes, 'newer-version'),
      name: undefined,
      assetHashes: [],
    }

    expect(await reconcileIndex(ports)).toEqual([nameless])
    expect(await ports.index.get('later')).toEqual(nameless)
    await ports.workspace.delete('later')

    expect(await reconcileIndex(ports)).toEqual([])
    expect(await ports.index.get('later')).toBeUndefined()
  })

  it('a failed read under a folder record gives the placeholder, and the next read that works puts the rebuilt record in place of the folder record', async () => {
    const ports = rebuildPorts()
    await placeSound(ports, ['a'])
    await ports.index.put(folderRecord('a'))
    vi.spyOn(ports.workspace, 'read').mockRejectedValueOnce(new Error('the store cannot be read'))

    expect(await reconcileIndex(ports)).toEqual([unreadRecordOf('a')])

    expect(await reconcileIndex(ports)).toEqual([soundRecordOf('a')])
    expect(await ports.index.get('a')).toEqual(soundRecordOf('a'))
  })
})

describe('a sound read whose record cannot be built', () => {
  it('keeps the earlier workspace record, puts nothing, and does not warn', async () => {
    const ports = rebuildPorts()
    await placeSound(ports, ['a'])
    const earlier = sampleRecord({ id: 'a', lastChangedAt: EARLIER_CHANGE })
    await ports.index.put(earlier)
    const put = vi.spyOn(ports.index, 'put')
    failNextRecordBuild()

    expect(await reconcileIndex(ports)).toEqual([earlier])

    expect(put).not.toHaveBeenCalled()
    expect(consoleWarn).not.toHaveBeenCalled()
  })

  it('with no earlier record gives the placeholder, puts nothing, and does not warn', async () => {
    const ports = rebuildPorts()
    await placeSound(ports, ['a'])
    const put = vi.spyOn(ports.index, 'put')
    failNextRecordBuild()

    expect(await reconcileIndex(ports)).toEqual([unreadRecordOf('a')])

    expect(put).not.toHaveBeenCalled()
    expect(consoleWarn).not.toHaveBeenCalled()
  })
})

describe('the times of a record that replaces an earlier one', () => {
  it('a document with no floors keeps the time of use of the earlier workspace record', async () => {
    const ports = rebuildPorts()
    const bytes = documentWithoutFloors('A plan with no floors')
    await placeDocument(ports, 'a', bytes)
    await ports.index.put(
      sampleRecord({ id: 'a', lastChangedAt: EARLIER_CHANGE, lastUsedAt: USED_AT }),
    )

    const expected = { ...failedRecord('a', bytes, 'format-rules'), lastUsedAt: USED_AT }
    expect(await reconcileIndex(ports)).toEqual([expected])
    expect(await ports.index.get('a')).toEqual(expected)
  })

  it('a document that fails only the strict check takes the listed time, not the time of change of the record that it replaces', async () => {
    const ports = rebuildPorts()
    await placeDocument(ports, 'a', documentBreakingFormatRules())
    await ports.index.put(
      sampleRecord({ id: 'a', lastChangedAt: EARLIER_CHANGE, lastUsedAt: USED_AT }),
    )

    const [record] = await reconcileIndex(ports)

    expect([record?.lastChangedAt, record?.lastUsedAt]).toEqual([STORED_AT, USED_AT])
    expect((await ports.index.get('a'))?.lastChangedAt).toBe(STORED_AT)
  })

  it('a workspace record with no time of use is rebuilt with the new time of change as its time of use', async () => {
    const ports = rebuildPorts()
    await placeSound(ports, ['a'])
    await ports.index.put(
      sampleRecord({ id: 'a', lastChangedAt: EARLIER_CHANGE, lastUsedAt: undefined }),
    )

    expect(await reconcileIndex(ports)).toEqual([soundRecordOf('a')])
    expect(soundRecordOf('a').lastUsedAt).toBe(STORED_AT)
  })
})

session/handle/open-document-handle-edge.source:
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { renameProject } from '../../core'
import type { ProjectLockPort } from '../../storage'
import {
  currentBytes,
  documentBreakingFormatRules,
  documentOfHigherRevision,
  soundProject,
} from '../../tests/storage/conformance/conformance-documents'
import { openDocumentHandle } from './open-document-handle'
import type { OpenRequest, SaveStatus } from './handle-types'
import {
  IN_FOLDER,
  createTestPorts,
  failureOf,
  openOrThrow,
  placeDocument,
  rememberFolder,
  workspaceRequest,
} from './handle-test-kit'

const PROJECT_ID = 'a'
const FOLDER_REQUEST: OpenRequest = { id: PROJECT_ID, location: IN_FOLDER }

let consoleError: ReturnType<typeof vi.spyOn>

/** Every value that was passed to `console.error`, in one list. */
function loggedValues(): unknown[] {
  return consoleError.mock.calls.flat()
}

function createRequest(id: string): OpenRequest {
  return { ...workspaceRequest(id), create: soundProject }
}

beforeEach(() => {
  vi.useFakeTimers()
  vi.spyOn(console, 'warn').mockImplementation(() => undefined)
  consoleError = vi.spyOn(console, 'error').mockImplementation(() => undefined)
})
afterEach(() => {
  vi.restoreAllMocks()
  vi.useRealTimers()
})

describe('opening a project in a folder whose permission is granted', () => {
  it('a reopen that answers missing gives folder-unavailable', async () => {
    const ports = createTestPorts()
    await rememberFolder(ports, PROJECT_ID, currentBytes())
    vi.spyOn(ports.folders, 'reopen').mockResolvedValue('missing')

    expect(await failureOf(ports, FOLDER_REQUEST)).toEqual({ kind: 'folder-unavailable' })
  })

  it('a reopen that answers denied gives folder-permission', async () => {
    const ports = createTestPorts()
    await rememberFolder(ports, PROJECT_ID, currentBytes())
    vi.spyOn(ports.folders, 'reopen').mockResolvedValue('denied')

    expect(await failureOf(ports, FOLDER_REQUEST)).toEqual({ kind: 'folder-permission' })
  })

  it('a reopen that rejects gives storage-unavailable with the message of the rejection', async () => {
    const ports = createTestPorts()
    await rememberFolder(ports, PROJECT_ID, currentBytes())
    vi.spyOn(ports.folders, 'reopen').mockRejectedValue(new Error('the folder vanished'))

    expect(await failureOf(ports, FOLDER_REQUEST)).toEqual({
      kind: 'storage-unavailable',
      message: 'the folder vanished',
    })
  })
})

describe('opening a project that fails after the lock was taken', () => {
  it('an openDespiteFormatFaults that rejects gives storage-unavailable and frees the lock', async () => {
    const ports = createTestPorts()
    await placeDocument(ports, PROJECT_ID, documentBreakingFormatRules())
    vi.spyOn(ports.workspace, 'openDespiteFormatFaults').mockRejectedValue(
      new Error('the backup could not be written'),
    )

    expect(await failureOf(ports, workspaceRequest(PROJECT_ID))).toEqual({
      kind: 'storage-unavailable',
      message: 'the backup could not be written',
    })
    expect(await ports.locks.heldIds()).toEqual(new Set())
  })

  it('a create that throws gives storage-unavailable with the message, and frees the lock', async () => {
    const ports = createTestPorts()
    const create = (): never => {
      throw new Error('no starting project')
    }

    await expect(
      openDocumentHandle(ports, { ...workspaceRequest(PROJECT_ID), create }),
    ).resolves.toEqual({
      ok: false,
      failure: { kind: 'storage-unavailable', message: 'no starting project' },
    })
    expect(await ports.locks.heldIds()).toEqual(new Set())
  })

  it('a hold whose release rejects still lets the open resolve with its failure, and the error is logged once', async () => {
    const failure = new Error('the release was refused')
    const locks: ProjectLockPort = {
      supported: true,
      tryAcquire: async () => ({ release: () => Promise.reject(failure) }),
      heldIds: async () => new Set(),
    }
    const ports = { ...createTestPorts(), locks }

    await expect(openDocumentHandle(ports, workspaceRequest(PROJECT_ID))).resolves.toEqual({
      ok: false,
      failure: { kind: 'not-found' },
    })
    expect(consoleError).toHaveBeenCalledTimes(1)
    expect(loggedValues()).toContain(failure)
  })

  it('an id that cannot name a project leaves the lock free', async () => {
    const ports = createTestPorts()

    await failureOf(ports, workspaceRequest('a/b'))

    expect(await ports.locks.heldIds()).toEqual(new Set())
  })
})

describe('a handle opened with create', () => {
  it('has the status idle', async () => {
    const handle = await openOrThrow(createTestPorts(), createRequest(PROJECT_ID))

    expect(handle.saveStatus()).toBe('idle')
  })
})

describe('a listener of a handle that throws', () => {
  it('a status listener that throws is logged once to console.error', async () => {
    const failure = new Error('status listener failed')
    const ports = createTestPorts()
    await placeDocument(ports, PROJECT_ID, currentBytes())
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    handle.subscribe(() => {
      throw failure
    })

    handle.session.dispatch(renameProject('Edited'))

    expect(consoleError).toHaveBeenCalledTimes(1)
    expect(loggedValues()).toContain(failure)
  })

  it('a second status listener still gets the status after a listener that throws', async () => {
    const ports = createTestPorts()
    await placeDocument(ports, PROJECT_ID, currentBytes())
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    const seen: SaveStatus[] = []
    handle.subscribe(() => {
      throw new Error('status listener failed')
    })
    handle.subscribe(() => seen.push(handle.saveStatus()))

    handle.session.dispatch(renameProject('Edited'))

    expect(seen).toEqual(['pending'])
  })

  it('a notice listener that gets a held notice and throws is logged once to console.error, and onNotice still returns', async () => {
    const failure = new Error('notice listener failed')
    const ports = createTestPorts()
    await placeDocument(ports, PROJECT_ID, documentOfHigherRevision())
    const handle = await openOrThrow(ports, workspaceRequest(PROJECT_ID))
    const listener = (): void => {
      throw failure
    }

    expect(() => handle.onNotice(listener)).not.toThrow()

    expect(consoleError).toHaveBeenCalledTimes(1)
    expect(loggedValues()).toContain(failure)
  })
})

