import * as THREE from 'three'
import { describe, expect, it } from 'vitest'
import { exteriorWalls, type ExteriorWall } from '../../core'
import { centeredEllFloor, flushEllFloor } from '../../core/scene/wall-runs-test-fixtures'
import { NeutralMaterialProvider } from '../materials/neutral-material-provider'
import { buildScene } from './build-scene'
import { prepareNearWallTransparency, type NearWallTarget } from './near-wall-transparency'
import { enrollNearWallTargets } from './near-wall-transparency-enrollment'
import { fadedScene, piecesOf, sceneGraphOf } from './near-wall-transparency-test-support'
import { WALL_SPAN_KEY } from './wall-span'

const LONG_SOUTH = 'wall:long-south'
// Plan y maps to world -z, so a camera at positive z stands south of the house, on the outside
// of the long south wall.
const SOUTH_OF_FLUSH_ELL = { x: 7000, z: 8000 }

const BOUNDARY_MM = 4000
const WALL_END_MM = 8000
// The boundary mesh spans half a millimeter to each side of the boundary, so its middle is on it.
const SLACK_MM = 0.5

const FIRST_RUN_INDEX = 0

const materialsOf = (mesh: THREE.Mesh): THREE.Material[] =>
  Array.isArray(mesh.material) ? mesh.material : [mesh.material]

/** The positions in `targets` of the targets that hold a material of `mesh`. */
const holdingTargetIndexes = (targets: NearWallTarget[], mesh: THREE.Mesh): number[] =>
  targets.flatMap((target, index) =>
    target.materials.some((record) => materialsOf(mesh).includes(record.material)) ? [index] : [],
  )

const meshesOfWall = (root: THREE.Object3D, entityId: string): THREE.Mesh[] => {
  const meshes: THREE.Mesh[] = []
  root.traverse((object) => {
    if (object instanceof THREE.Mesh && object.userData.entityId === entityId) meshes.push(object)
  })
  return meshes
}

/** The centered ell floor built with the long south wall's meshes stripped of their spans. */
function centeredEllWithoutSpans() {
  const graph = sceneGraphOf(centeredEllFloor())
  const root = buildScene(graph, new NeutralMaterialProvider())
  for (const mesh of meshesOfWall(root, LONG_SOUTH)) delete mesh.userData[WALL_SPAN_KEY]
  return { graph, root, targets: enrollNearWallTargets(root, graph) }
}

const plainWallMesh = (fromMm: number, toMm: number): THREE.Mesh => {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial())
  mesh.userData.entityId = 'wall:w'
  mesh.userData[WALL_SPAN_KEY] = { fromMm, toMm }
  return mesh
}

const runOfWallW = (fromMm: number, toMm: number, normalY: number): ExteriorWall => ({
  wallId: 'wall:w',
  fromMm,
  toMm,
  outwardNormal: { x: 0, y: normalY },
  openingIds: [],
})

describe('the owner run of a wall mesh in the near-wall fade', () => {
  it('gives a wall mesh with no recorded span to the first run of its wall', () => {
    const { graph, root, targets } = centeredEllWithoutSpans()
    const exterior = exteriorWalls(graph.walls, graph.rooms, graph.openings)
    // The first run of the long south wall in the exterior order is the one from 0 to 3000.
    const firstRunIndex = exterior.findIndex((run) => run.wallId === LONG_SOUTH)
    const meshes = meshesOfWall(root, LONG_SOUTH)

    expect(firstRunIndex).toBeGreaterThanOrEqual(0)
    expect(meshes.length).toBeGreaterThan(0)
    for (const mesh of meshes) expect(holdingTargetIndexes(targets, mesh)).toEqual([firstRunIndex])
  })

  it('gives a wall mesh whose middle lies on the boundary of two runs to the first run', () => {
    const first = plainWallMesh(0, BOUNDARY_MM - SLACK_MM)
    const boundary = plainWallMesh(BOUNDARY_MM - SLACK_MM, BOUNDARY_MM + SLACK_MM)
    const last = plainWallMesh(BOUNDARY_MM + SLACK_MM, WALL_END_MM)
    const root = new THREE.Group().add(first, boundary, last)

    const targets = prepareNearWallTransparency(root, [
      runOfWallW(0, BOUNDARY_MM, -1),
      runOfWallW(BOUNDARY_MM, WALL_END_MM, 1),
    ])

    expect(holdingTargetIndexes(targets, first)).toEqual([FIRST_RUN_INDEX])
    expect(holdingTargetIndexes(targets, boundary)).toEqual([FIRST_RUN_INDEX])
  })

  it('gives a mesh whose middle lies in no run to no target, and one within the tolerance to the run', () => {
    const inGap = plainWallMesh(3500, 4500)
    const atToleranceEdge = plainWallMesh(3000.5, 3001.5)
    const root = new THREE.Group().add(inGap, atToleranceEdge)

    const targets = prepareNearWallTransparency(root, [
      runOfWallW(0, 3000, -1),
      runOfWallW(5000, WALL_END_MM, 1),
    ])

    expect(holdingTargetIndexes(targets, inGap)).toEqual([])
    expect(holdingTargetIndexes(targets, atToleranceEdge)).toEqual([FIRST_RUN_INDEX])
  })

  it('still fades only the run past a flush ell, with recorded spans in place', () => {
    const root = fadedScene(flushEllFloor(), SOUTH_OF_FLUSH_ELL)

    // The stretch 0 to 4000 stands against the ell, so only the 4000 to 10000 stretch fades.
    expect(piecesOf(root, LONG_SOUTH).map((piece) => piece.faded)).toEqual([false, true])
  })
})

bridge/react/ambient-occlusion-render-ta.source:
import { act, cleanup, render } from '@testing-library/react'
import { StrictMode, useMemo } from 'react'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { createSceneSessionStore } from '../scene-session/scene-session-store'
import { AmbientOcclusionRenderTakeover } from './ambient-occlusion-render-takeover'
import { SceneSessionProvider } from './scene-session-provider'
import { useLiveViewReadiness, type LiveViewReadinessNotes } from './use-live-view-readiness'

interface FakePipeline {
  dispose: ReturnType<typeof vi.fn>
  setSize: ReturnType<typeof vi.fn>
}

interface PendingBuild {
  resolve: (pipeline: FakePipeline) => void
  pipeline: FakePipeline
}

// The 3D library's hooks and the engine's pipeline builder are the collaborators of the
// takeover. A pending-promise builder lets each test decide when a build settles, so the
// test reads the live-view readiness the takeover reports without a GPU.
const collaborators = vi.hoisted(() => ({
  threeState: {
    scene: {},
    camera: {},
    gl: {},
    size: { width: 800, height: 600 },
  } as Record<string, unknown>,
  builds: [] as PendingBuild[],
}))

vi.mock('@react-three/fiber', () => ({
  useThree: (select: (state: Record<string, unknown>) => unknown) =>
    select(collaborators.threeState),
  useFrame: () => {},
}))

vi.mock('../../engine', () => ({
  // eslint-disable-next-line @typescript-eslint/naming-convention
  AO_DEFAULT_PARAMS: {},
  ambientOcclusionParamsFor: (mode: string) => (mode === 'realistic' ? {} : null),
  renderSceneFrame: () => {},
  buildAmbientOcclusionPipeline: () =>
    new Promise<FakePipeline>((resolve) => {
      const pipeline: FakePipeline = { dispose: vi.fn(), setSize: vi.fn() }
      collaborators.builds.push({ resolve, pipeline })
    }),
}))

let notes: LiveViewReadinessNotes
let store = createSceneSessionStore()
// A stable-identity spy around the real settle note, so the probe never restarts a build
// and the tests can count exactly when the takeover reports a settled build.
const settleSpy = vi.fn(() => notes.notePipelineSettled())

interface ProbeProps {
  realistic: boolean
  // When set, the settle callback is a wrapper that takes a new identity with each version.
  settleVersion?: number
}

function Probe({ realistic, settleVersion }: ProbeProps) {
  notes = useLiveViewReadiness()
  const versionedSettle = useMemo(
    () => Object.assign(() => settleSpy(), { version: settleVersion }),
    [settleVersion],
  )
  return (
    <AmbientOcclusionRenderTakeover
      realistic={realistic}
      onPipelineBuildStarted={notes.notePipelineBuildStarted}
      onPipelineSettled={settleVersion === undefined ? settleSpy : versionedSettle}
    />
  )
}

function ProbeInSession(props: ProbeProps) {
  return (
    <SceneSessionProvider store={store}>
      <Probe {...props} />
    </SceneSessionProvider>
  )
}

function drawFrame(): boolean {
  act(() => notes.noteFrameDrawn())
  return store.getSceneSession().frameDrawnSincePipelineSettled
}

function buildAt(index: number): PendingBuild {
  const build = collaborators.builds[index]
  if (!build) throw new Error(`pipeline build ${index} was never started`)
  return build
}

async function settleBuild(index: number): Promise<void> {
  const build = buildAt(index)
  await act(async () => {
    build.resolve(build.pipeline)
    await new Promise((done) => setTimeout(done, 0))
  })
}

function mountRealisticWithBuildPending() {
  const view = render(<ProbeInSession realistic />)
  expect(collaborators.builds).toHaveLength(1)
  expect(drawFrame()).toBe(false)
  return view
}

beforeEach(() => {
  store = createSceneSessionStore()
  settleSpy.mockClear()
  collaborators.builds.length = 0
  collaborators.threeState.camera = {}
})

afterEach(cleanup)

describe('AmbientOcclusionRenderTakeover readiness while a pipeline build is in flight', () => {
  it('counts the live view as ready after the next frame once realistic lighting turns off mid-build', async () => {
    const view = mountRealisticWithBuildPending()

    view.rerender(<ProbeInSession realistic={false} />)
    expect(drawFrame()).toBe(true)
    expect(settleSpy).toHaveBeenCalledTimes(1)

    await settleBuild(0)
    expect(drawFrame()).toBe(true)
    expect(settleSpy).toHaveBeenCalledTimes(1)
    expect(buildAt(0).pipeline.dispose).toHaveBeenCalledTimes(1)
  })

  it('keeps waiting for the replacement build when a camera change replaces a build in flight', async () => {
    const view = mountRealisticWithBuildPending()

    collaborators.threeState.camera = {}
    view.rerender(<ProbeInSession realistic />)
    expect(collaborators.builds).toHaveLength(2)
    expect(drawFrame()).toBe(false)

    await settleBuild(0)
    expect(drawFrame()).toBe(false)

    await settleBuild(1)
    expect(drawFrame()).toBe(true)
  })

  it('keeps waiting for the new build when realistic lighting turns off and on with no frame between', async () => {
    const view = mountRealisticWithBuildPending()

    view.rerender(<ProbeInSession realistic={false} />)
    view.rerender(<ProbeInSession realistic />)
    expect(drawFrame()).toBe(false)

    await settleBuild(0)
    expect(drawFrame()).toBe(false)

    await settleBuild(1)
    expect(drawFrame()).toBe(true)
  })

  it('keeps waiting for the new build when both effects run again in one flush', async () => {
    render(
      <StrictMode>
        <ProbeInSession realistic />
      </StrictMode>,
    )
    // Strict mode runs each effect as setup, cleanup, setup: two builds start in one flush.
    expect(collaborators.builds).toHaveLength(2)
    expect(drawFrame()).toBe(false)

    await settleBuild(0)
    expect(drawFrame()).toBe(false)
    expect(buildAt(0).pipeline.dispose).toHaveBeenCalledTimes(1)

    await settleBuild(1)
    expect(drawFrame()).toBe(true)
  })

  it('keeps waiting for the new build when the settle callback changes identity during a build', async () => {
    const view = render(<ProbeInSession realistic settleVersion={1} />)
    expect(collaborators.builds).toHaveLength(1)
    expect(drawFrame()).toBe(false)

    view.rerender(<ProbeInSession realistic settleVersion={2} />)
    expect(collaborators.builds).toHaveLength(2)
    expect(drawFrame()).toBe(false)

    await settleBuild(0)
    expect(drawFrame()).toBe(false)
    expect(buildAt(0).pipeline.dispose).toHaveBeenCalledTimes(1)

    await settleBuild(1)
    expect(drawFrame()).toBe(true)
  })

  it('reports the settlement once at the unmount and nothing when the stopped build completes late', async () => {
    const view = mountRealisticWithBuildPending()

    view.unmount()
    const callsAtUnmount = settleSpy.mock.calls.length
    expect(callsAtUnmount).toBe(1)

    await expect(settleBuild(0)).resolves.toBeUndefined()

    expect(settleSpy).toHaveBeenCalledTimes(callsAtUnmount)
    expect(store.getSceneSession().frameDrawnSincePipelineSettled).toBe(false)
    expect(buildAt(0).pipeline.dispose).toHaveBeenCalledTimes(1)
  })
})

