import { describe, it, expect, afterEach } from 'vitest'
import { render, cleanup, act } from '@testing-library/react'
import { PerspectiveCamera, Raycaster } from '../../engine/testing'
import { buildScene } from '../../engine'
import { commitSelectionAt } from '../../bridge/react/scene-selection'
import {
  ActiveFloorProvider,
  EditorSessionProvider,
  SelectionProvider,
  createActiveFloorStore,
  createPerceivedColorStore,
  createSelectionStore,
  useSurfaceSelection,
  type SurfaceSelectionStore,
} from '../../bridge'
import { createEditorSession } from '../../session/testing'
import {
  createEmptyProject,
  createFloor,
  planToWorld,
  type Point,
  type SceneGraph,
  type SurfaceRef,
  type WallSceneNode,
} from '../../core'
import { ThemeProvider } from '../../editor/design-system'
import { NotificationProvider } from '../../editor/design-system/notifications/use-notifications'
import { ActiveToolProvider } from '../../editor/tools/active-tool-provider'
import { EditLayerProvider } from '../../editor/tools/edit-layer-provider'
import { ShellProviders } from '../../editor/shell/shell-providers'

afterEach(cleanup)

// A 3D click on one face of a wall, through the real selection handler, into the shell's
// providers. The wall runs along the plan x axis, so its left face is the one at plan +y
// and its right face the one at plan -y. The click is the centre of the canvas, so the
// camera's aim point is exactly where the ray strikes.

const FLOOR_ID = 'g'
const WALL_ID = 'w1'
const WALL_NODE_ID = `wall:${WALL_ID}`
const WALL_HEIGHT = 2600
const WALL_LENGTH = 4000
const AIM_ALONG = 2000
const AIM_HEIGHT = 1300
const STANDOFF = 2000
const CANVAS_SIZE = 200
const CANVAS_CENTER = CANVAS_SIZE / 2

const wall: WallSceneNode = {
  id: WALL_NODE_ID,
  kind: 'wall',
  floorId: FLOOR_ID,
  start: { x: 0, y: 0 },
  end: { x: WALL_LENGTH, y: 0 },
  thickness: 120,
  height: WALL_HEIGHT,
}

const graph: SceneGraph = {
  nodes: [{ id: `floor:${FLOOR_ID}`, kind: 'floor', name: 'G', elevation: 0 }],
  walls: [wall],
  rooms: [],
  underlays: [],
  openings: [],
  dimensions: [],
  stairs: [],
  furniture: [],
}

const faceRef = (side: 'left' | 'right'): SurfaceRef => ({
  kind: 'wall-face',
  wallId: WALL_ID,
  side,
})

const cameraLooking = (from: Point, at: Point): PerspectiveCamera => {
  const eye = planToWorld(from, AIM_HEIGHT)
  const target = planToWorld(at, AIM_HEIGHT)
  const camera = new PerspectiveCamera(50, 1, 1, 100000)
  camera.position.set(eye.x, eye.y, eye.z)
  camera.lookAt(target.x, target.y, target.z)
  camera.updateMatrixWorld(true)
  return camera
}

/** A camera standing off the wall's given side, aimed square at solid wall. */
const faceOnCamera = (side: 'left' | 'right'): PerspectiveCamera =>
  cameraLooking({ x: AIM_ALONG, y: side === 'left' ? STANDOFF : -STANDOFF }, { x: AIM_ALONG, y: 0 })

const stubCanvas = (): HTMLCanvasElement =>
  ({
    getBoundingClientRect: () => ({ left: 0, top: 0, width: CANVAS_SIZE, height: CANVAS_SIZE }),
  }) as unknown as HTMLCanvasElement

const centreClick = (): PointerEvent =>
  ({
    clientX: CANVAS_CENTER,
    clientY: CANVAS_CENTER,
    shiftKey: false,
    metaKey: false,
    ctrlKey: false,
  }) as unknown as PointerEvent

/** Hands the shell's own surface selection store to the test. */
function SurfaceSelectionProbe({ onStore }: { onStore: (store: SurfaceSelectionStore) => void }) {
  onStore(useSurfaceSelection())
  return null
}

function mountShell() {
  const project = createEmptyProject({
    name: 'Test',
    units: 'imperial',
    period: 'modern',
    appVersion: '0.0.0',
  })
  project.floors = [createFloor('Ground', { id: FLOOR_ID })]
  const selection = createSelectionStore()
  let surfaceSelection: SurfaceSelectionStore | undefined
  render(
    <NotificationProvider>
      <ThemeProvider>
        <EditorSessionProvider session={createEditorSession(project)}>
          <SelectionProvider store={selection}>
            <ActiveFloorProvider store={createActiveFloorStore(FLOOR_ID)}>
              <ActiveToolProvider>
                <EditLayerProvider>
                  <ShellProviders>
                    <SurfaceSelectionProbe onStore={(store) => (surfaceSelection = store)} />
                  </ShellProviders>
                </EditLayerProvider>
              </ActiveToolProvider>
            </ActiveFloorProvider>
          </SelectionProvider>
        </EditorSessionProvider>
      </ThemeProvider>
    </NotificationProvider>,
  )
  return { selection, surfaceSelection: surfaceSelection as SurfaceSelectionStore }
}

function clickInShell(camera: PerspectiveCamera) {
  const shell = mountShell()
  const root = buildScene(graph)
  root.updateMatrixWorld(true)
  act(() =>
    commitSelectionAt(centreClick(), {
      domElement: stubCanvas(),
      camera,
      raycaster: new Raycaster(),
      root,
      selection: shell.selection,
      surfaceSelection: shell.surfaceSelection,
      perceivedColor: createPerceivedColorStore(),
    }),
  )
  return shell
}

describe('a 3D click on a wall face in the shell', () => {
  it.each(['left', 'right'] as const)(
    'selects the wall and leaves the %s face that the click picked as the paint target',
    (side) => {
      const { selection, surfaceSelection } = clickInShell(faceOnCamera(side))

      expect(selection.getSelectedIds()).toEqual(new Set([WALL_NODE_ID]))
      expect(surfaceSelection.getActiveSurface()).toEqual(faceRef(side))
    },
  )
})

engine/scene/wall-builder.test.ts.source:
import * as THREE from 'three'
import { describe, expect, it } from 'vitest'

import { buildWallGraph } from '../../core'
import type { OpeningSceneNode, PlanarGraph, Point, WallSceneNode } from '../../core'
import { NeutralMaterialProvider } from '../materials/neutral-material-provider'
import { materialGroups } from '../testing'

import { buildWalls } from './wall-builder'
import {
  AREA_TOLERANCE,
  CUT_FACE_AREA,
  FACE_GROUP_COUNT,
  FULL_THICKNESS_SPAN,
  HALF_THICKNESS,
  HEIGHT,
  PRECISION,
  SOLID_MASONRY_BRICK_SPAN,
  SPLIT_X,
  THICKNESS,
  VOID_HEIGHT,
  VOID_WIDTH,
  WALL_FACE_AREA,
  WALL_LENGTH,
  centeredOpening,
  drawnRolesOf,
  expectBoxSpan,
  horizontalWall,
  maxAxisOfRole,
  meshesOf,
  oneEdgeGraph,
  roleArea,
  roleTriangleCount,
  singleWallMesh,
  splitEdgeGraph,
  wallGroup,
} from './wall-test-support'

describe('buildWalls', () => {
  it('builds a single box for an unsplit wall with no openings', () => {
    const meshes = meshesOf(wallGroup())
    expect(meshes).toHaveLength(1)

    const mesh = meshes[0]
    expect(mesh).toBeDefined()
    if (mesh === undefined) return
    expect(mesh.userData.entityId).toBe('wall:w1')
    expect(materialGroups(mesh.geometry)).toHaveLength(FACE_GROUP_COUNT)
    expectBoxSpan(mesh, { x: [0, WALL_LENGTH], y: [0, HEIGHT], z: FULL_THICKNESS_SPAN })
  })

  it('sizes a wall footprint from its construction profile total thickness', () => {
    // solid-masonry-brick's total is distinct from the wall's raw 120mm thickness, so
    // the box's cross-wall (world Z) span bites only when the construction-profile total
    // drives the footprint.
    const group = buildWalls({
      graph: oneEdgeGraph(),
      walls: [horizontalWall({ constructionProfile: 'solid-masonry-brick' })],
      openingsByWall: new Map(),
      materials: new NeutralMaterialProvider(),
    })
    const meshes = meshesOf(group)
    expect(meshes).toHaveLength(1)
    const mesh = meshes[0]
    expect(mesh).toBeDefined()
    if (mesh === undefined) return
    expectBoxSpan(mesh, { x: [0, WALL_LENGTH], y: [0, HEIGHT], z: SOLID_MASONRY_BRICK_SPAN })
  })

  it('sizes an opening wall footprint from its construction profile total thickness', () => {
    // The opening path places the long faces from the edge frame's thickness. The
    // footprint already sizes from the solid-masonry-brick total, but the frame must
    // too, or the faces land at the raw 120mm (cross-wall span [-60, 60]) instead of
    // the profile's [-115.5, 115.5].
    const group = buildWalls({
      graph: oneEdgeGraph(),
      walls: [horizontalWall({ constructionProfile: 'solid-masonry-brick' })],
      openingsByWall: new Map([['w1', [centeredOpening()]]]),
      materials: new NeutralMaterialProvider(),
    })
    const mesh = meshesOf(group).find((m) => m.userData.entityId === 'wall:w1')
    expect(mesh).toBeDefined()
    if (mesh === undefined) return
    expectBoxSpan(mesh, { x: [0, WALL_LENGTH], y: [0, HEIGHT], z: SOLID_MASONRY_BRICK_SPAN })
  })

  it('builds one box per edge for a split wall, both carrying the wall node id', () => {
    const meshes = meshesOf(wallGroup([], splitEdgeGraph()))
    expect(meshes).toHaveLength(2)
    expect(meshes.every((mesh) => mesh.userData.entityId === 'wall:w1')).toBe(true)

    const [first, second] = meshes.sort(
      (left, right) =>
        new THREE.Box3().setFromObject(left).min.x - new THREE.Box3().setFromObject(right).min.x,
    )
    expect(first).toBeDefined()
    expect(second).toBeDefined()
    if (first === undefined || second === undefined) return

    expectBoxSpan(first, { x: [0, SPLIT_X], y: [0, HEIGHT], z: FULL_THICKNESS_SPAN })
    expectBoxSpan(second, { x: [SPLIT_X, WALL_LENGTH], y: [0, HEIGHT], z: FULL_THICKNESS_SPAN })
  })

  it('miters the shared corner of two plain walls meeting at a right angle', () => {
    // An L: wall A runs east, wall B turns north from A's far end. Their shared
    // corner (WALL_LENGTH, 0) carries two incident edges, so A's b-end miters: its
    // interior (+normal) face pulls in to the inner corner and its exterior
    // (-normal) face reaches out to the outer corner.
    const wallA = horizontalWall({ id: 'wall:a' })
    const wallB: WallSceneNode = {
      id: 'wall:b',
      kind: 'wall',
      floorId: 'demo',
      start: { x: WALL_LENGTH, y: 0 },
      end: { x: WALL_LENGTH, y: WALL_LENGTH },
      thickness: THICKNESS,
      height: HEIGHT,
    }
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: WALL_LENGTH, y: 0 },
        { x: WALL_LENGTH, y: WALL_LENGTH },
      ],
      edges: [
        { a: 0, b: 1, wallId: 'a' },
        { a: 1, b: 2, wallId: 'b' },
      ],
    }

    const group = buildWalls({
      graph,
      walls: [wallA, wallB],
      openingsByWall: new Map(),
      materials: new NeutralMaterialProvider(),
    })
    const meshA = meshesOf(group).find((mesh) => mesh.userData.entityId === 'wall:a')
    expect(meshA).toBeDefined()
    if (meshA === undefined) return

    expect(maxAxisOfRole(meshA, 'interiorFace', 'x')).toBeCloseTo(
      WALL_LENGTH - HALF_THICKNESS,
      PRECISION,
    )
    expect(maxAxisOfRole(meshA, 'exteriorFace', 'x')).toBeCloseTo(
      WALL_LENGTH + HALF_THICKNESS,
      PRECISION,
    )
  })
})

describe('buildWalls miters opening walls at a corner', () => {
  // An L at the shared vertex (WALL_LENGTH, 0): wall A runs east from the origin
  // and wall B turns away from A's far end toward `bEnd`. The shared corner
  // carries two incident edges, so A's b-end miters. `bEnd` sets the turn angle.
  // The opening (hostWallId 'a', map key 'a') makes A an opening wall.
  const cornerMeshA = (bEnd: Point, openings: OpeningSceneNode[] = []): THREE.Mesh => {
    const wallA = horizontalWall({ id: 'wall:a' })
    const wallB = horizontalWall({ id: 'wall:b', start: { x: WALL_LENGTH, y: 0 }, end: bEnd })
    const group = buildWalls({
      graph: {
        vertices: [{ x: 0, y: 0 }, { x: WALL_LENGTH, y: 0 }, bEnd],
        edges: [
          { a: 0, b: 1, wallId: 'a' },
          { a: 1, b: 2, wallId: 'b' },
        ],
      },
      walls: [wallA, wallB],
      openingsByWall:
        openings.length > 0 ? new Map<string, OpeningSceneNode[]>([['a', openings]]) : new Map(),
      materials: new NeutralMaterialProvider(),
    })
    const mesh = meshesOf(group).find((m) => m.userData.entityId === 'wall:a')
    expect(mesh).toBeDefined()
    return mesh as THREE.Mesh
  }

  const openingOnA = (): OpeningSceneNode[] => [centeredOpening({ hostWallId: 'a' })]

  it('miters an opening wall the same as a plain wall at an oblique corner', () => {
    // Wall B turns away at a non-right angle, leaving an oblique seam at the
    // corner. The opening wall must miter its end identically to the plain wall;
    // today it squares the end and the faces stop short of the mitered extents.
    const obliqueEnd: Point = { x: WALL_LENGTH + 1000, y: 1000 }
    const plain = cornerMeshA(obliqueEnd)
    const open = cornerMeshA(obliqueEnd, openingOnA())

    for (const role of ['interiorFace', 'exteriorFace'] as const) {
      expect(maxAxisOfRole(open, role, 'x')).toBeCloseTo(maxAxisOfRole(plain, role, 'x'), PRECISION)
    }
  })

  it('miters an opening wall to the inner and outer corner at a right angle', () => {
    const open = cornerMeshA({ x: WALL_LENGTH, y: WALL_LENGTH }, openingOnA())

    expect(maxAxisOfRole(open, 'interiorFace', 'x')).toBeCloseTo(
      WALL_LENGTH - HALF_THICKNESS,
      PRECISION,
    )
    expect(maxAxisOfRole(open, 'exteriorFace', 'x')).toBeCloseTo(
      WALL_LENGTH + HALF_THICKNESS,
      PRECISION,
    )
  })

  it('leaves the free ends of a lone opening wall square', () => {
    const mesh = singleWallMesh([centeredOpening()])
    expect(mesh).toBeDefined()
    if (mesh === undefined) return

    expect(maxAxisOfRole(mesh, 'interiorFace', 'x')).toBeCloseTo(WALL_LENGTH, PRECISION)
    expect(maxAxisOfRole(mesh, 'exteriorFace', 'x')).toBeCloseTo(WALL_LENGTH, PRECISION)
  })
})

describe('buildWalls opening voids', () => {
  it('cuts the opening void out of the wall long faces', () => {
    const mesh = singleWallMesh([centeredOpening()])
    expect(mesh).toBeDefined()
    if (mesh === undefined) return
    expect(Math.abs(roleArea(mesh, 'interiorFace') - CUT_FACE_AREA)).toBeLessThan(AREA_TOLERANCE)
  })

  it('leaves the long faces solid when the wall has no openings', () => {
    const mesh = singleWallMesh()
    expect(mesh).toBeDefined()
    if (mesh === undefined) return
    expect(Math.abs(roleArea(mesh, 'interiorFace') - WALL_FACE_AREA)).toBeLessThan(AREA_TOLERANCE)
  })
})

describe('buildWalls curved opening voids', () => {
  const WINDOW_WIDTH = 900
  const WINDOW_HEIGHT = 1500
  const WINDOW_SILL = 800

  const sameSizeWindow = (type: string): THREE.Mesh | undefined =>
    singleWallMesh([
      centeredOpening({
        id: 'opening:cw',
        type,
        width: WINDOW_WIDTH,
        height: WINDOW_HEIGHT,
        sillHeight: WINDOW_SILL,
      }),
    ])

  it('tessellates a round-top void into more reveal facets than the rectangular void of the same size', () => {
    const rectangular = sameSizeWindow('double-hung-window')
    const round = sameSizeWindow('round-top-window')
    expect(rectangular).toBeDefined()
    expect(round).toBeDefined()
    if (rectangular === undefined || round === undefined) return

    // The flat rectangular head needs one reveal facet; the semicircular head is
    // sampled into a curve, so its void carries many more reveal triangles.
    expect(roleTriangleCount(round, 'reveal')).toBeGreaterThan(
      roleTriangleCount(rectangular, 'reveal'),
    )
  })

  it('arcs the round-top head up to the opening top, not flat across at the springline', () => {
    const round = sameSizeWindow('round-top-window')
    expect(round).toBeDefined()
    if (round === undefined) return

    // The semicircular head crowns at the opening top (sill + height); a flat chord
    // across the springline would stop a half-width short of it.
    const openingTop = WINDOW_SILL + WINDOW_HEIGHT
    expect(maxAxisOfRole(round, 'reveal', 'y')).toBeCloseTo(openingTop, PRECISION)
  })
})

describe('buildWalls opening reveals', () => {
  it('lines a sill-zero door void with reveals on the head and jambs but not the floor sill', () => {
    const mesh = singleWallMesh([centeredOpening({ sillHeight: 0 })])
    expect(mesh).toBeDefined()
    if (mesh === undefined) return

    // Head plus two jambs lined; the floor-level sill is on the wall base and is
    // not lined: (width + 2 * height) * thickness.
    const expectedReveal = (VOID_WIDTH + 2 * VOID_HEIGHT) * THICKNESS // 595_680
    expect(Math.abs(roleArea(mesh, 'reveal') - expectedReveal)).toBeLessThan(AREA_TOLERANCE)
  })

  it('lines all four edges of a raised-sill window void, including the sill', () => {
    const windowWidth = 900
    const windowHeight = 1200
    const mesh = singleWallMesh([
      centeredOpening({
        id: 'opening:w1',
        type: 'double-hung-window',
        width: windowWidth,
        height: windowHeight,
        sillHeight: 900,
      }),
    ])
    expect(mesh).toBeDefined()
    if (mesh === undefined) return

    // A raised sill is lined too: (2 * width + 2 * height) * thickness.
    const expectedReveal = (2 * windowWidth + 2 * windowHeight) * THICKNESS // 504_000
    expect(Math.abs(roleArea(mesh, 'reveal') - expectedReveal)).toBeLessThan(AREA_TOLERANCE)
  })
})

describe('buildWalls junction fills', () => {
  const TALLER_HEIGHT = HEIGHT + 400

  // A perpendicular T: a through wall east-west and a partition turning north from
  // its midpoint. buildWallGraph splits the through wall at (2000, 0), so that
  // vertex carries three incident edges: a three-way junction.
  const teeGraph = (): PlanarGraph =>
    buildWallGraph([
      { id: 'through', start: { x: 0, y: 0 }, end: { x: 4000, y: 0 }, thickness: THICKNESS },
      { id: 'part', start: { x: 2000, y: 0 }, end: { x: 2000, y: 2000 }, thickness: THICKNESS },
    ])

  const junctionFills = (group: THREE.Group): THREE.Mesh[] =>
    meshesOf(group).filter((mesh) => drawnRolesOf(mesh).has('junction'))

  it('adds one junction fill at a T-junction, carrying no entity id', () => {
    const walls: WallSceneNode[] = [
      horizontalWall({
        id: 'wall:through',
        start: { x: 0, y: 0 },
        end: { x: 4000, y: 0 },
        thickness: THICKNESS,
        height: HEIGHT,
      }),
      horizontalWall({
        id: 'wall:part',
        start: { x: 2000, y: 0 },
        end: { x: 2000, y: 2000 },
        thickness: THICKNESS,
        height: HEIGHT,
      }),
    ]

    const group = buildWalls({
      graph: teeGraph(),
      walls,
      openingsByWall: new Map(),
      materials: new NeutralMaterialProvider(),
    })

    const fills = junctionFills(group)
    expect(fills).toHaveLength(1)
    const fill = fills[0]
    expect(fill).toBeDefined()
    if (fill === undefined) return
    expect(fill.userData.entityId).toBeUndefined()

    const wallMeshes = meshesOf(group).filter((mesh) => !drawnRolesOf(mesh).has('junction'))
    expect(wallMeshes.length).toBeGreaterThan(0)
    expect(wallMeshes.every((mesh) => String(mesh.userData.entityId).startsWith('wall:'))).toBe(
      true,
    )
  })

  it('raises the junction fill to the tallest incident wall height', () => {
    const walls: WallSceneNode[] = [
      horizontalWall({
        id: 'wall:through',
        start: { x: 0, y: 0 },
        end: { x: 4000, y: 0 },
        thickness: THICKNESS,
        height: HEIGHT,
      }),
      horizontalWall({
        id: 'wall:part',
        start: { x: 2000, y: 0 },
        end: { x: 2000, y: 2000 },
        thickness: THICKNESS,
        height: TALLER_HEIGHT,
      }),
    ]

    const group = buildWalls({
      graph: teeGraph(),
      walls,
      openingsByWall: new Map(),
      materials: new NeutralMaterialProvider(),
    })

    const fills = junctionFills(group)
    expect(fills).toHaveLength(1)
    const fill = fills[0]
    expect(fill).toBeDefined()
    if (fill === undefined) return

    expect(new THREE.Box3().setFromObject(fill).max.y).toBeCloseTo(TALLER_HEIGHT, PRECISION)
  })

  it('adds no junction fill to a room of only two-way corners', () => {
    const corners = [
      { x: 0, y: 0 },
      { x: 4000, y: 0 },
      { x: 4000, y: 3000 },
      { x: 0, y: 3000 },
    ]
    const loopWalls = corners.map((start, index) => ({
      id: `r${index}`,
      start,
      end: corners[(index + 1) % corners.length] ?? start,
      thickness: THICKNESS,
    }))
    const walls: WallSceneNode[] = loopWalls.map((wall) =>
      horizontalWall({
        id: `wall:${wall.id}`,
        start: wall.start,
        end: wall.end,
        thickness: THICKNESS,
        height: HEIGHT,
      }),
    )

    const group = buildWalls({
      graph: buildWallGraph(loopWalls),
      walls,
      openingsByWall: new Map(),
      materials: new NeutralMaterialProvider(),
    })

    expect(junctionFills(group)).toHaveLength(0)
    const meshes = meshesOf(group)
    expect(meshes.length).toBeGreaterThan(0)
    expect(meshes.every((mesh) => String(mesh.userData.entityId).startsWith('wall:'))).toBe(true)
  })
})

