import { describe, expect, it } from 'vitest'
import { comparisonWarnings, formatTimingReport } from './timing-report'
import {
  REFERENCE_EDIT_NAMES,
  RENDER_VARIANT_NAMES,
  aTimingRun,
  summary,
} from './timing-run-fixture'
import type { TimingRun } from './timing-record'

const MAX_LINE_LENGTH = 100
const MOVED_WALL = 'move-wall-endpoint'
const UPDATE_ROW = `3D update, ${MOVED_WALL}`

/** The lines of the report that start with the text: the rows of one kind of time. */
function rowsStartingWith(report: string, start: string): string[] {
  return report.split('\n').filter((line) => line.startsWith(start))
}

function allTimeRows(report: string): string[] {
  return ['Plan redraw', '3D update, ', '3D frame, ', '3D frame after '].flatMap((start) =>
    rowsStartingWith(report, start),
  )
}

function withEdit(edit: (run: TimingRun) => void): TimingRun {
  const run = aTimingRun()
  edit(run)
  return run
}

/** A pair of runs whose update of the moved wall has these medians, all else equal. */
function reportWithMedians(currentMs: number, baselineMs: number): string {
  const current = withEdit((run) => {
    run.times.sceneUpdate[MOVED_WALL] = summary(currentMs, currentMs + 2)
  })
  const baseline = withEdit((run) => {
    run.times.sceneUpdate[MOVED_WALL] = summary(baselineMs, baselineMs + 2)
  })
  return formatTimingReport(current, baseline)
}

describe('the timing report of a run with no baseline', () => {
  const report = formatTimingReport(aTimingRun(), undefined)

  it('says that times are reported and never gated', () => {
    expect(report).toContain('never gated')
  })

  it('says that the baseline was not measured', () => {
    expect(report).toContain('not measured')
  })

  it('has one row for the plan redraw', () => {
    expect(rowsStartingWith(report, 'Plan redraw')).toHaveLength(1)
  })

  it('has one row for the update of each reference edit', () => {
    const rows = rowsStartingWith(report, '3D update, ')

    expect(rows).toHaveLength(REFERENCE_EDIT_NAMES.length)
    REFERENCE_EDIT_NAMES.forEach((name) => {
      expect(rows.some((row) => row.startsWith(`3D update, ${name}`))).toBe(true)
    })
  })

  it('has a main-thread row and an until-GPU-done row for each render variant', () => {
    const rows = rowsStartingWith(report, '3D frame, ')

    expect(rows).toHaveLength(RENDER_VARIANT_NAMES.length * 2)
    RENDER_VARIANT_NAMES.forEach((name) => {
      expect(rows.some((row) => row.startsWith(`3D frame, ${name}, main thread`))).toBe(true)
      expect(rows.some((row) => row.startsWith(`3D frame, ${name}, until GPU done`))).toBe(true)
    })
  })

  it('has a main-thread row and an until-GPU-done row for the frame after each edit', () => {
    const rows = rowsStartingWith(report, '3D frame after ')

    expect(rows).toHaveLength(REFERENCE_EDIT_NAMES.length * 2)
    REFERENCE_EDIT_NAMES.forEach((name) => {
      expect(rows.some((row) => row.startsWith(`3D frame after ${name}, main thread`))).toBe(true)
      expect(rows.some((row) => row.startsWith(`3D frame after ${name}, until GPU done`))).toBe(
        true,
      )
    })
  })

  it('shows n/a in the change cell and not measured in the baseline cell of every time row', () => {
    const rows = allTimeRows(report)

    expect(rows).toHaveLength(27)
    rows.forEach((row) => {
      expect(row.endsWith('n/a')).toBe(true)
      expect(row).toContain('not measured')
    })
  })

  it('shows the median and the 95th percentile of a time with two decimals', () => {
    const [planRow] = rowsStartingWith(report, 'Plan redraw')

    expect(planRow).toContain('3.21')
    expect(planRow).toContain('5.40')
  })

  it('shows the budget of 8.0 ms on each update and frame row', () => {
    const rows = [
      ...rowsStartingWith(report, '3D update, '),
      ...rowsStartingWith(report, '3D frame'),
    ]

    expect(rows).toHaveLength(26)
    rows.forEach((row) => expect(row).toContain('8.0'))
  })

  it('shows the plan budget of 16.7 ms starred, with a footnote saying it is no stated budget', () => {
    const [planRow] = rowsStartingWith(report, 'Plan redraw')
    const [footnote] = rowsStartingWith(report, '* ')

    expect(planRow).toContain('16.7*')
    expect(footnote).toContain('one frame at 60 fps')
    expect(footnote).toContain('no plan budget')
  })

  it('lists what is not measured on a line of its own', () => {
    expect(rowsStartingWith(report, 'Not measured')).toHaveLength(1)
  })
})

describe('the change of a time against the baseline', () => {
  it('shows a slower time as a positive change in milliseconds with its ratio', () => {
    const [row] = rowsStartingWith(reportWithMedians(2.5, 2), UPDATE_ROW)

    expect(row).toContain('+0.50 ms (1.25x)')
  })

  // The surface does not define the other two forms; they follow the same pattern with an ASCII minus.
  it('shows a faster time as a negative change in milliseconds with its ratio', () => {
    const [row] = rowsStartingWith(reportWithMedians(2, 2.5), UPDATE_ROW)

    expect(row).toContain('-0.50 ms (0.80x)')
  })

  it('shows equal times as a change of +0.00 ms and 1.00x on every time row', () => {
    const report = formatTimingReport(aTimingRun(), aTimingRun())

    allTimeRows(report).forEach((row) => expect(row).toContain('+0.00 ms (1.00x)'))
  })

  it('shows the median and the 95th percentile of the baseline, and no n/a, on a row that has one', () => {
    const [row] = rowsStartingWith(reportWithMedians(2.5, 2), UPDATE_ROW)

    expect(row).toContain('2.00/4.00')
    expect(row).not.toContain('n/a')
  })

  it('does not let the 95th percentile of the baseline change the change cell', () => {
    const changeWithBaselineP95 = (baselineP95Ms: number): string | undefined => {
      const current = withEdit((run) => {
        run.times.sceneUpdate[MOVED_WALL] = summary(2.5, 4.5)
      })
      const baseline = withEdit((run) => {
        run.times.sceneUpdate[MOVED_WALL] = summary(2, baselineP95Ms)
      })
      const [row] = rowsStartingWith(formatTimingReport(current, baseline), UPDATE_ROW)
      return row?.match(/[+-]\d+\.\d+ ms \(\d+\.\d+x\)/)?.[0]
    }

    expect(changeWithBaselineP95(3)).toBe('+0.50 ms (1.25x)')
    expect(changeWithBaselineP95(9)).toBe('+0.50 ms (1.25x)')
  })
})

describe('the change of a time that the baseline lacks', () => {
  const MISSING_EDIT = 'move-furniture'

  function baselineLackingOneUpdate(): TimingRun {
    return withEdit((run) => {
      run.times.sceneUpdate = Object.fromEntries(
        Object.entries(run.times.sceneUpdate).filter(([name]) => name !== MISSING_EDIT),
      )
      run.times.sceneUpdate[MOVED_WALL] = summary(2, 4)
    })
  }

  it('shows not measured and n/a on its row, and keeps the baseline cell of the other rows', () => {
    const report = formatTimingReport(aTimingRun(), baselineLackingOneUpdate())
    const [missingRow] = rowsStartingWith(report, `3D update, ${MISSING_EDIT}`)
    const [otherRow] = rowsStartingWith(report, UPDATE_ROW)

    expect(missingRow).toContain('not measured')
    expect(missingRow?.endsWith('n/a')).toBe(true)
    expect(otherRow).toContain('2.00/4.00')
  })
})

describe('the heading of the baseline column of the timing report', () => {
  const report = formatTimingReport(aTimingRun(), aTimingRun())

  it('names the median and the 95th percentile', () => {
    expect(report).toContain('Base med/p95')
  })

  it('no longer names the median alone', () => {
    expect(report).not.toContain('Base median')
  })
})

describe('the lines of the timing report', () => {
  function unusualCurrent(): TimingRun {
    return withEdit((run) => {
      run.conditions.power = 'battery'
      run.conditions.focused = false
      run.machine.browser = 'Chromium 143.0.7500.0 with a long build description attached'
      run.machine.webGpuAdapter = 'apple / metal-3 / Apple M5 Pro with a long device description'
    })
  }

  it.each([
    ['with no baseline', formatTimingReport(aTimingRun(), undefined)],
    ['with an equal baseline', formatTimingReport(aTimingRun(), aTimingRun())],
    ['with warnings', formatTimingReport(unusualCurrent(), aTimingRun())],
  ])('are at most 100 characters long %s', (_situation, report) => {
    report.split('\n').forEach((line) => {
      expect(line.length).toBeLessThanOrEqual(MAX_LINE_LENGTH)
    })
  })

  it('carry no escape character for color', () => {
    const report = formatTimingReport(unusualCurrent(), aTimingRun())

    expect(report).not.toContain('\u001b')
  })
})

describe('the warnings that compare a run with its baseline', () => {
  it('gives none for two equal clean runs', () => {
    expect(comparisonWarnings(aTimingRun(), aTimingRun())).toEqual([])
  })

  it('gives none for a clean run with no baseline', () => {
    expect(comparisonWarnings(aTimingRun(), undefined)).toEqual([])
  })

  it.each([
    {
      field: 'device pixel ratio',
      current: (run: TimingRun) => void (run.conditions.devicePixelRatio = 1.5),
      baseline: (run: TimingRun) => void (run.conditions.devicePixelRatio = 2.25),
      values: ['1.5', '2.25'],
    },
    {
      field: 'drawing buffer size',
      current: (run: TimingRun) =>
        void (run.conditions.sceneDrawingBufferPx = { width: 1280, height: 800 }),
      baseline: (run: TimingRun) =>
        void (run.conditions.sceneDrawingBufferPx = { width: 1920, height: 1200 }),
      values: ['1280 x 800', '1920 x 1200'],
    },
    {
      field: 'browser',
      current: (run: TimingRun) => void (run.machine.browser = 'Chromium 143.0.7500.0'),
      baseline: (run: TimingRun) => void (run.machine.browser = 'Chromium 141.0.7390.0'),
      values: ['Chromium 143.0.7500.0', 'Chromium 141.0.7390.0'],
    },
    {
      field: 'adapter',
      current: (run: TimingRun) =>
        void (run.machine.webGpuAdapter = 'apple / metal-3 / Apple M5 Max'),
      baseline: (run: TimingRun) =>
        void (run.machine.webGpuAdapter = 'apple / metal-3 / Apple M4 Pro'),
      values: ['Apple M5 Max', 'Apple M4 Pro'],
    },
    {
      field: 'processor',
      current: (run: TimingRun) => void (run.machine.processor = 'Apple M5 Max'),
      baseline: (run: TimingRun) => void (run.machine.processor = 'Apple M4 Pro'),
      values: ['Apple M5 Max', 'Apple M4 Pro'],
    },
  ])('gives one warning naming both values for a differing $field', (testCase) => {
    const current = withEdit(testCase.current)
    const baseline = withEdit(testCase.baseline)

    const warnings = comparisonWarnings(current, baseline)

    expect(warnings).toHaveLength(1)
    testCase.values.forEach((value) => expect(warnings[0]).toContain(value))
  })

  // The wording is the implementer's; the lower-cased phrase only has to name the condition.
  it.each([
    {
      condition: 'a quick current run',
      current: (run: TimingRun) => void (run.quick = true),
      baseline: () => undefined,
      phrase: 'quick',
    },
    {
      condition: 'a quick baseline',
      current: () => undefined,
      baseline: (run: TimingRun) => void (run.quick = true),
      phrase: 'quick',
    },
    {
      condition: 'battery power',
      current: (run: TimingRun) => void (run.conditions.power = 'battery'),
      baseline: () => undefined,
      phrase: 'battery',
    },
    {
      condition: 'an unknown power source',
      current: (run: TimingRun) => void (run.conditions.power = 'unknown'),
      baseline: () => undefined,
      phrase: 'unknown',
    },
    {
      condition: 'uncommitted changes',
      current: (run: TimingRun) => void (run.uncommittedChanges = true),
      baseline: () => undefined,
      phrase: 'uncommitted',
    },
    {
      condition: 'a window that was not focused',
      current: (run: TimingRun) => void (run.conditions.focused = false),
      baseline: () => undefined,
      phrase: 'focus',
    },
  ])('gives one warning for $condition', (testCase) => {
    const warnings = comparisonWarnings(withEdit(testCase.current), withEdit(testCase.baseline))

    expect(warnings).toHaveLength(1)
    expect(warnings[0]?.toLowerCase()).toContain(testCase.phrase)
  })
})

tests/performance/timing/run-timing-guar.source:
import { describe, expect, it } from 'vitest'
import { REFERENCE_EDITS } from '../reference-project'
import {
  changingFrames,
  fakeEditFrames,
  fakeObservation,
  fakeSceneUpdateMs,
  fakeTimingPhases,
  fakeVariantFrames,
  timingInput,
} from './fake-timing-phases'
import type { Observation, PhaseName } from './fake-timing-phases'
import type { FrameSample } from './frame-probe'
import { RENDER_VARIANTS } from './render-variants'
import { runTiming } from './run-timing'
import type { TimingOutcome } from './run-timing'

const VARIANT_NAMES = RENDER_VARIANTS.map((variant) => variant.name)
const EDIT_NAMES = REFERENCE_EDITS.map((edit) => edit.name)
const VARIANT = VARIANT_NAMES[2] ?? ''
const EDIT = EDIT_NAMES[1] ?? ''
const MEASURING_PHASES: PhaseName[] = [
  'planRedraw',
  'sceneUpdate',
  'renderFrames',
  'renderAfterEdits',
]

function refusalText(outcome: TimingOutcome): string {
  if (outcome.kind !== 'refused') throw new Error('Expected the run to be refused')
  return outcome.reasons.join('\n')
}

function without<Value>(record: Record<string, Value>, name: string): Record<string, Value> {
  return Object.fromEntries(Object.entries(record).filter(([key]) => key !== name))
}

const noFrames = (frames: Record<string, FrameSample[]>, name: string) => ({
  ...frames,
  [name]: [],
})

const firstFrameWithoutGpuWork = (frame: FrameSample, index: number): FrameSample =>
  index === 0 ? { ...frame, untilGpuDoneMs: null } : frame

const withoutGpuWork = (frame: FrameSample): FrameSample => ({ ...frame, untilGpuDoneMs: null })

describe('a timing run observes the page at its start and at its end', () => {
  it('observes before the first phase and again after the last one', async () => {
    const fake = fakeTimingPhases()
    await runTiming(fake.phases, timingInput())
    expect(fake.calls).toEqual(['observe', ...MEASURING_PHASES, 'observe'])
  })

  it.each([
    ['not visible', { visible: false }],
    ['marked as hidden at some time', { everHidden: true }],
  ])(
    'refuses a run whose window was %s at its end, and keeps no record',
    async (_name, observedAtEnd) => {
      const outcome = await runTiming(fakeTimingPhases({ observedAtEnd }).phases, timingInput())
      expect(outcome.kind).toBe('refused')
      expect(refusalText(outcome)).toMatch(/hidden during the run/i)
      expect(outcome).not.toHaveProperty('run')
    },
  )

  it('refuses a window that was hidden before the run started, before any phase runs', async () => {
    const fake = fakeTimingPhases({ observed: { everHidden: true } })
    const outcome = await runTiming(fake.phases, timingInput())
    expect(refusalText(outcome)).toMatch(/hidden/i)
    expect(fake.calls).toEqual(['observe'])
  })

  it('records a window that stayed visible and focused as visible throughout and focused', async () => {
    const fake = fakeTimingPhases({ observed: { focused: true } })
    const outcome = await runTiming(fake.phases, timingInput())
    if (outcome.kind !== 'measured') throw new Error('Expected a measured run')
    expect(outcome.run.conditions).toMatchObject({ visibleThroughout: true, focused: true })
  })

  it.each([
    ['at its end', { focused: true }, { focused: false }],
    ['at its start', { focused: false }, { focused: true }],
  ])(
    'records the run as not focused when the window lost focus %s, and still measures it',
    async (_name, atStart, observedAtEnd) => {
      const fake = fakeTimingPhases({ observed: atStart, observedAtEnd })
      const outcome = await runTiming(fake.phases, timingInput())
      if (outcome.kind !== 'measured') throw new Error('Expected a measured run')
      expect(outcome.run.conditions.focused).toBe(false)
      expect(outcome.run.conditions.visibleThroughout).toBe(true)
    },
  )
})

describe('the record of a timing run takes its sizes from the end observation', () => {
  async function recordOf(observedAtEnd: Partial<Observation>) {
    const outcome = await runTiming(fakeTimingPhases({ observedAtEnd }).phases, timingInput())
    if (outcome.kind !== 'measured') throw new Error('Expected a measured run')
    return outcome.run
  }

  it('holds the pixel ratio and the three canvas sizes that the page states at its end', async () => {
    const atEnd = {
      devicePixelRatio: 3,
      planCanvasPx: { width: 640, height: 480 },
      sceneCanvasCssPx: { width: 1024, height: 700 },
      sceneDrawingBufferPx: { width: 3072, height: 2100 },
    }

    const { conditions } = await recordOf(atEnd)

    expect({
      devicePixelRatio: conditions.devicePixelRatio,
      planCanvasPx: conditions.planCanvasPx,
      sceneCanvasCssPx: conditions.sceneCanvasCssPx,
      sceneDrawingBufferPx: conditions.sceneDrawingBufferPx,
    }).toEqual(atEnd)
  })

  it('keeps the display frame, the time, and the machine facts of the start observation', async () => {
    const atStart = fakeObservation()

    const run = await recordOf({
      displayFrameMs: 16.67,
      takenAt: '2026-11-21T23:59:59-05:00',
      webGlRenderer: 'a renderer that the page names only at its end',
      webGpuAdapter: { name: 'another / adapter / name', isFallback: false },
      timerResolutionMs: 0.1,
    })

    expect({
      displayFrameMs: run.conditions.displayFrameMs,
      takenAt: run.takenAt,
      webGlRenderer: run.machine.webGlRenderer,
      webGpuAdapter: run.machine.webGpuAdapter,
      timerResolutionMs: run.build.timerResolutionMs,
    }).toEqual({
      displayFrameMs: atStart.displayFrameMs,
      takenAt: atStart.takenAt,
      webGlRenderer: atStart.webGlRenderer,
      webGpuAdapter: atStart.webGpuAdapter?.name,
      timerResolutionMs: atStart.timerResolutionMs,
    })
  })
})

describe('a timing run with odd frame results', () => {
  it.each([
    ['a variant', { renderFrames: noFrames(fakeVariantFrames(), VARIANT) }, VARIANT],
    ['an edit after the edit', { renderAfterEdits: noFrames(fakeEditFrames(), EDIT) }, EDIT],
  ])(
    'refuses %s with no frames, names it, and does not blame WebGL 2',
    async (_n, options, name) => {
      const text = refusalText(await runTiming(fakeTimingPhases(options).phases, timingInput()))
      expect(text).toContain('no frames')
      expect(text).toContain(name)
      expect(text).not.toContain('WebGL 2')
    },
  )

  it.each([
    [
      'a variant',
      { renderFrames: changingFrames(fakeVariantFrames(), VARIANT, firstFrameWithoutGpuWork) },
      VARIANT,
    ],
    [
      'an edit',
      { renderAfterEdits: changingFrames(fakeEditFrames(), EDIT, firstFrameWithoutGpuWork) },
      EDIT,
    ],
  ])('refuses %s where only some frames made GPU work, and names it', async (_n, options, name) => {
    const text = refusalText(await runTiming(fakeTimingPhases(options).phases, timingInput()))
    expect(text).toContain(name)
    expect(text).toMatch(/some frames made no GPU work/i)
  })

  it('refuses an edit whose frames all made no GPU work, as a WebGL 2 fallback', async () => {
    const renderAfterEdits = changingFrames(fakeEditFrames(), EDIT, withoutGpuWork)
    const outcome = await runTiming(fakeTimingPhases({ renderAfterEdits }).phases, timingInput())
    expect(refusalText(outcome)).toContain('WebGL 2')
  })
})

describe('a timing run whose phases return incomplete results', () => {
  it('rejects with an error naming the plan redraw when it returns no samples', async () => {
    const fake = fakeTimingPhases({ planRedraw: [] })
    await expect(runTiming(fake.phases, timingInput())).rejects.toThrow(/plan redraw/i)
  })

  it('rejects with an error naming the 3D update and the edit when an edit has no samples', async () => {
    const sceneUpdate = { ...fakeSceneUpdates(), [EDIT]: [] }
    const fake = fakeTimingPhases({ sceneUpdate })
    const rejection = expect(runTiming(fake.phases, timingInput())).rejects
    await rejection.toThrow(/3D update/i)
    await rejection.toThrow(EDIT)
  })

  it.each([
    ['a render variant', VARIANT, { renderFrames: without(fakeVariantFrames(), VARIANT) }],
    [
      'an edit of the frames after edits',
      EDIT,
      { renderAfterEdits: without(fakeEditFrames(), EDIT) },
    ],
    ['an edit of the 3D update', EDIT, { sceneUpdate: without(fakeSceneUpdates(), EDIT) }],
  ])(
    'rejects with an error naming the missing entry when %s is absent',
    async (_n, name, options) => {
      const fake = fakeTimingPhases(options)
      await expect(runTiming(fake.phases, timingInput())).rejects.toThrow(name)
    },
  )
})

function fakeSceneUpdates(): Record<string, number[]> {
  return Object.fromEntries(REFERENCE_EDITS.map((edit, i) => [edit.name, fakeSceneUpdateMs(i)]))
}

