import { describe, expect, it } from 'vitest'
import { createWall, deriveRooms, roomKey } from '../../index'
import type { Floor, Point, ProjectShape, Wall } from '../../index'
import { rekeyRoomOverridesMigration } from './rekey-room-overrides'

const VERSION_SIXTEEN = 16

/** Footprint shared by every room this file derives, in floor-plan millimeters. */
const ROOM_WIDTH_MM = 4000
const ROOM_DEPTH_MM = 3000

/** Wall ids for the parlor, each carrying dashes of its own (see `dashEraKey`). */
const PARLOR_WALL_IDS = ['parlor-wall-1', 'parlor-wall-2', 'parlor-wall-3', 'parlor-wall-4']

/** Wall ids for the kitchen, a second room disjoint from the parlor. */
const KITCHEN_WALL_IDS = ['kitchen-wall-1', 'kitchen-wall-2', 'kitchen-wall-3', 'kitchen-wall-4']

const PARLOR_OVERRIDE = { name: 'Front Parlor', purpose: 'parlor' }
const KITCHEN_OVERRIDE = { name: 'Back Kitchen', purpose: 'kitchen' }

interface DocumentShape {
  meta?: { schemaVersion?: number }
  floors?: Floor[]
  roomOverrides?: Record<string, unknown>
}

function asDocument(project: ProjectShape): DocumentShape {
  return project as unknown as DocumentShape
}

/** The four corners of a room whose southwest corner sits at `origin`. */
function roomCorners(origin: Point): Point[] {
  return [
    origin,
    { x: origin.x + ROOM_WIDTH_MM, y: origin.y },
    { x: origin.x + ROOM_WIDTH_MM, y: origin.y + ROOM_DEPTH_MM },
    { x: origin.x, y: origin.y + ROOM_DEPTH_MM },
  ]
}

/** Builds one closed loop of walls, one per edge of `roomCorners(origin)`, carrying `wallIds`. */
function roomWalls(origin: Point, wallIds: readonly string[]): Wall[] {
  const corners = roomCorners(origin)
  return corners.map((corner, index) => {
    const next = corners[(index + 1) % corners.length]
    const id = wallIds[index]
    if (next === undefined || id === undefined) {
      throw new Error('expected a closing corner and a wall id per edge')
    }
    return createWall(corner, next, { id })
  })
}

/** The pipe key `roomKey` derives today for the single room enclosed by `walls`. */
function soleDerivedRoomKey(walls: Wall[]): string {
  const [room, ...rest] = deriveRooms(walls)
  if (room === undefined || rest.length > 0) {
    throw new Error('expected exactly one derived room')
  }
  return roomKey(room)
}

/** The dash-era key an early build would have saved for a room enclosed by `wallIds`. */
function dashEraKey(wallIds: readonly string[]): string {
  return [...wallIds].sort().join('-')
}

function makeFloor(id: string, walls: Wall[]): Floor {
  return {
    id,
    name: id,
    elevation: 0,
    defaultCeilingHeight: 2438,
    walls,
    underlays: [],
    openings: [],
    dimensions: [],
    furniture: [],
  }
}

/**
 * Builds a version-16 project document with the given floors and room overrides.
 * Returned as a plain `ProjectShape` so the migration is exercised structurally,
 * exactly as a loaded-from-disk document would arrive.
 */
function makeDocument(floors: Floor[], roomOverrides: Record<string, unknown>): ProjectShape {
  return {
    meta: {
      name: 'Rekey House',
      units: 'imperial',
      period: 'victorian',
      schemaVersion: VERSION_SIXTEEN,
      appVersion: '0.1.0',
      registryVersions: {},
    },
    floors,
    stairs: [],
    roomOverrides,
  }
}

describe('rekey-room-overrides schema migration', () => {
  it('starts its forward step from schema version 16', () => {
    expect(rekeyRoomOverridesMigration.from).toBe(VERSION_SIXTEEN)
  })

  it('does not set meta.schemaVersion inside the migration step itself', () => {
    const document = makeDocument([], {})

    const migrated = rekeyRoomOverridesMigration.migrate(document)

    expect(asDocument(migrated).meta?.schemaVersion).toBe(VERSION_SIXTEEN)
  })

  it('rebinds a dash-era key that matches the wall-id vocabulary to the pipe key roomKey derives', () => {
    const walls = roomWalls({ x: 0, y: 0 }, PARLOR_WALL_IDS)
    const document = makeDocument([makeFloor('floor:ground', walls)], {
      [dashEraKey(PARLOR_WALL_IDS)]: PARLOR_OVERRIDE,
    })

    const migrated = asDocument(rekeyRoomOverridesMigration.migrate(document))

    expect(migrated.roomOverrides?.[soleDerivedRoomKey(walls)]).toEqual(PARLOR_OVERRIDE)
    expect(migrated.roomOverrides?.[dashEraKey(PARLOR_WALL_IDS)]).toBeUndefined()
  })

  it('leaves a dash-joined key that matches no wall untouched, rather than dropping it', () => {
    const walls = roomWalls({ x: 0, y: 0 }, PARLOR_WALL_IDS)
    const unmatchableKey = 'no-such-wall-a-no-such-wall-b'
    const document = makeDocument([makeFloor('floor:ground', walls)], {
      [unmatchableKey]: PARLOR_OVERRIDE,
    })

    const migrated = asDocument(rekeyRoomOverridesMigration.migrate(document))

    expect(migrated.roomOverrides?.[unmatchableKey]).toEqual(PARLOR_OVERRIDE)
  })

  it('is a no-op that returns the same document reference when overrides are already keyed with the pipe separator', () => {
    const walls = roomWalls({ x: 0, y: 0 }, PARLOR_WALL_IDS)
    const document = makeDocument([makeFloor('floor:ground', walls)], {
      [soleDerivedRoomKey(walls)]: PARLOR_OVERRIDE,
    })

    const migrated = rekeyRoomOverridesMigration.migrate(document)

    expect(migrated).toBe(document)
  })

  it('rebinds multiple dash-era overrides in the same document independently', () => {
    const parlorWalls = roomWalls({ x: 0, y: 0 }, PARLOR_WALL_IDS)
    const kitchenWalls = roomWalls({ x: 10000, y: 0 }, KITCHEN_WALL_IDS)
    const document = makeDocument([makeFloor('floor:ground', [...parlorWalls, ...kitchenWalls])], {
      [dashEraKey(PARLOR_WALL_IDS)]: PARLOR_OVERRIDE,
      [dashEraKey(KITCHEN_WALL_IDS)]: KITCHEN_OVERRIDE,
    })

    const migrated = asDocument(rekeyRoomOverridesMigration.migrate(document))

    expect(migrated.roomOverrides?.[soleDerivedRoomKey(parlorWalls)]).toEqual(PARLOR_OVERRIDE)
    expect(migrated.roomOverrides?.[soleDerivedRoomKey(kitchenWalls)]).toEqual(KITCHEN_OVERRIDE)
    expect(migrated.roomOverrides?.[dashEraKey(PARLOR_WALL_IDS)]).toBeUndefined()
    expect(migrated.roomOverrides?.[dashEraKey(KITCHEN_WALL_IDS)]).toBeUndefined()
  })

  it('pools wall ids across every floor, rebinding an override for a room on a later floor', () => {
    const distractorWalls = [createWall({ x: 0, y: 0 }, { x: 1000, y: 0 }, { id: 'garage-wall-1' })]
    const parlorWalls = roomWalls({ x: 0, y: 0 }, PARLOR_WALL_IDS)
    const document = makeDocument(
      [makeFloor('floor:ground', distractorWalls), makeFloor('floor:upper', parlorWalls)],
      { [dashEraKey(PARLOR_WALL_IDS)]: PARLOR_OVERRIDE },
    )

    const migrated = asDocument(rekeyRoomOverridesMigration.migrate(document))

    expect(migrated.roomOverrides?.[soleDerivedRoomKey(parlorWalls)]).toEqual(PARLOR_OVERRIDE)
    expect(migrated.roomOverrides?.[dashEraKey(PARLOR_WALL_IDS)]).toBeUndefined()
  })
})

core/commands/handlers/opening-commands..source:
import { describe, it, expect } from 'vitest'
import {
  placeOpening,
  moveOpening,
  resizeOpening,
  resizeOpeningEdge,
  flipOpening,
  removeOpening,
  setOpeningType,
  registerOpeningCommands,
  PLACE_OPENING,
  MOVE_OPENING,
  RESIZE_OPENING,
  RESIZE_OPENING_EDGE,
  FLIP_OPENING,
  REMOVE_OPENING,
} from './opening-commands'
import type { OpeningDimensions } from './opening-commands'
import { CommandRegistry } from '../command-registry'
import { Dispatcher } from '../dispatcher'
import { createEmptyProject, createFloor, createWall, createOpening } from '../../model/factories'
import { InvalidLengthError, MAX_LENGTH_MM, builtinElementTypes, getEntry } from '../../index'
import type { Opening, Project } from '../../model/types'

const HOST_WALL_ID = 'wall-1'
const NEW_POSITION = 1500
const NEW_DIMENSIONS: OpeningDimensions = { width: 1626, height: 2100, sillHeight: 300 }
const NEW_EDGE_WIDTH = 1626
const NEW_EDGE_POSITION = 1500

function newOpening(position = 1000): Opening {
  return createOpening({ type: 'single-swing-door', hostWallId: HOST_WALL_ID, position })
}

function projectWithTwoFloors(): Project {
  const project = createEmptyProject({
    name: 'House',
    units: 'metric',
    period: 'victorian',
    appVersion: '0.0.0',
  })
  const hostWall = createWall({ x: 0, y: 0 }, { x: 3000, y: 0 }, { id: HOST_WALL_ID })
  project.floors = [
    createFloor('Ground', { id: 'g', walls: [hostWall] }),
    createFloor('Upper', { id: 'u' }),
  ]
  return project
}

function dispatcherFor(project: Project): Dispatcher<Project> {
  const registry = new CommandRegistry<Project>()
  registerOpeningCommands(registry)
  return new Dispatcher<Project>(project, registry)
}

describe('placeOpening', () => {
  it('appends the opening to the target floor', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const opening = newOpening()

    dispatcher.dispatch(placeOpening('g', opening))

    expect(project.floors[0]?.openings).toEqual([opening])
  })

  it('leaves the sibling floor reference-equal', () => {
    const project = projectWithTwoFloors()
    const sibling = project.floors[1]
    const dispatcher = dispatcherFor(project)

    dispatcher.dispatch(placeOpening('g', newOpening()))

    expect(project.floors[1]).toBe(sibling)
  })

  it('removes the appended opening on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    dispatcher.dispatch(placeOpening('g', newOpening()))

    dispatcher.undo()

    expect(project.floors[0]?.openings).toEqual([])
  })

  it('carries a stable command type', () => {
    expect(placeOpening('g', newOpening()).type).toBe(PLACE_OPENING)
  })
})

describe('moveOpening', () => {
  it('sets the target opening position to the new value', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(moveOpening('g', target.id, NEW_POSITION))

    expect(project.floors[0]?.openings[0]?.position).toBe(NEW_POSITION)
  })

  it('leaves a sibling opening reference-equal', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const sibling = newOpening()
    dispatcher.dispatch(placeOpening('g', target))
    dispatcher.dispatch(placeOpening('g', sibling))

    dispatcher.dispatch(moveOpening('g', target.id, NEW_POSITION))

    expect(project.floors[0]?.openings[1]).toBe(sibling)
  })

  it('restores the previous position on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalPosition = target.position
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(moveOpening('g', target.id, NEW_POSITION))
    dispatcher.undo()

    expect(project.floors[0]?.openings[0]?.position).toBe(originalPosition)
  })

  it('carries a stable command type', () => {
    expect(moveOpening('g', 'opening-1', NEW_POSITION).type).toBe(MOVE_OPENING)
  })
})

describe('resizeOpening', () => {
  it('sets the width, height, and sill height together', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpening('g', target.id, NEW_DIMENSIONS))

    const resized = project.floors[0]?.openings[0]
    expect(resized?.width).toBe(NEW_DIMENSIONS.width)
    expect(resized?.height).toBe(NEW_DIMENSIONS.height)
    expect(resized?.sillHeight).toBe(NEW_DIMENSIONS.sillHeight)
  })

  it('leaves a sibling opening reference-equal', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const sibling = newOpening()
    dispatcher.dispatch(placeOpening('g', target))
    dispatcher.dispatch(placeOpening('g', sibling))

    dispatcher.dispatch(resizeOpening('g', target.id, NEW_DIMENSIONS))

    expect(project.floors[0]?.openings[1]).toBe(sibling)
  })

  it('restores the previous dimensions on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpening('g', target.id, NEW_DIMENSIONS))
    dispatcher.undo()

    const restored = project.floors[0]?.openings[0]
    expect(restored?.width).toBe(target.width)
    expect(restored?.height).toBe(target.height)
    expect(restored?.sillHeight).toBe(target.sillHeight)
  })

  it('carries a stable command type', () => {
    expect(resizeOpening('g', 'opening-1', NEW_DIMENSIONS).type).toBe(RESIZE_OPENING)
  })

  it('rejects a non-positive or absurd width or height but allows a zero sill height', () => {
    const rejectedDimensions: OpeningDimensions[] = [
      { width: 0, height: 2100, sillHeight: 300 },
      { width: -5, height: 2100, sillHeight: 300 },
      { width: 1626, height: -10, sillHeight: 300 },
      { width: MAX_LENGTH_MM + 1, height: 2100, sillHeight: 300 },
      { width: 1626, height: 2100, sillHeight: -1 },
      { width: 1626, height: 2100, sillHeight: MAX_LENGTH_MM + 1 },
    ]

    for (const rejected of rejectedDimensions) {
      const project = projectWithTwoFloors()
      const dispatcher = dispatcherFor(project)
      const target = newOpening()
      const originalWidth = target.width
      const originalHeight = target.height
      const originalSillHeight = target.sillHeight
      dispatcher.dispatch(placeOpening('g', target))

      let thrown: unknown
      expect(() => {
        try {
          dispatcher.dispatch(resizeOpening('g', target.id, rejected))
        } catch (error) {
          thrown = error
          throw error
        }
      }).toThrow(/rolled back/)
      expect((thrown as Error).cause).toBeInstanceOf(InvalidLengthError)

      const unchanged = project.floors[0]?.openings[0]
      expect(unchanged?.width).toBe(originalWidth)
      expect(unchanged?.height).toBe(originalHeight)
      expect(unchanged?.sillHeight).toBe(originalSillHeight)
    }

    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpening('g', target.id, { width: 900, height: 2100, sillHeight: 0 }))

    const floorMounted = project.floors[0]?.openings[0]
    expect(floorMounted?.width).toBe(900)
    expect(floorMounted?.height).toBe(2100)
    expect(floorMounted?.sillHeight).toBe(0)
  })
})

describe('resizeOpeningEdge', () => {
  it('sets the target opening width and position to the new values', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpeningEdge('g', target.id, NEW_EDGE_WIDTH, NEW_EDGE_POSITION))

    const resized = project.floors[0]?.openings[0]
    expect(resized?.width).toBe(NEW_EDGE_WIDTH)
    expect(resized?.position).toBe(NEW_EDGE_POSITION)
  })

  it('preserves the opening height and sill height', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalHeight = target.height
    const originalSillHeight = target.sillHeight
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpeningEdge('g', target.id, NEW_EDGE_WIDTH, NEW_EDGE_POSITION))

    const resized = project.floors[0]?.openings[0]
    expect(resized?.height).toBe(originalHeight)
    expect(resized?.sillHeight).toBe(originalSillHeight)
  })

  it('leaves the sibling floor reference-equal', () => {
    const project = projectWithTwoFloors()
    const sibling = project.floors[1]
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpeningEdge('g', target.id, NEW_EDGE_WIDTH, NEW_EDGE_POSITION))

    expect(project.floors[1]).toBe(sibling)
  })

  it('restores the previous width and position on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalWidth = target.width
    const originalPosition = target.position
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(resizeOpeningEdge('g', target.id, NEW_EDGE_WIDTH, NEW_EDGE_POSITION))
    dispatcher.undo()

    const restored = project.floors[0]?.openings[0]
    expect(restored?.width).toBe(originalWidth)
    expect(restored?.position).toBe(originalPosition)
  })

  it('carries a stable command type', () => {
    expect(resizeOpeningEdge('g', 'x', 900, 1000).type).toBe(RESIZE_OPENING_EDGE)
  })
})

describe('flipOpening', () => {
  it('toggles the hinge axis leaving facing unchanged', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalFacing = target.orientation.facing
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(flipOpening('g', target.id, 'hinge'))

    const flipped = project.floors[0]?.openings[0]
    expect(flipped?.orientation.hinge).toBe('end')
    expect(flipped?.orientation.facing).toBe(originalFacing)
  })

  it('toggles the facing axis leaving hinge unchanged', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalHinge = target.orientation.hinge
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(flipOpening('g', target.id, 'facing'))

    const flipped = project.floors[0]?.openings[0]
    expect(flipped?.orientation.facing).toBe('negative')
    expect(flipped?.orientation.hinge).toBe(originalHinge)
  })

  it('restores the previous orientation on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const originalOrientation = target.orientation
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(flipOpening('g', target.id, 'hinge'))
    dispatcher.undo()

    expect(project.floors[0]?.openings[0]?.orientation).toEqual(originalOrientation)
  })

  it('carries a stable command type', () => {
    expect(flipOpening('g', 'opening-1', 'hinge').type).toBe(FLIP_OPENING)
  })
})

describe('removeOpening', () => {
  it('filters the target opening out while a sibling remains', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = newOpening()
    const sibling = newOpening()
    dispatcher.dispatch(placeOpening('g', target))
    dispatcher.dispatch(placeOpening('g', sibling))

    dispatcher.dispatch(removeOpening('g', target.id))

    expect(project.floors[0]?.openings).toEqual([sibling])
  })

  it('restores the removed opening at its original index on undo', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const first = newOpening()
    const middle = newOpening()
    const last = newOpening()
    dispatcher.dispatch(placeOpening('g', first))
    dispatcher.dispatch(placeOpening('g', middle))
    dispatcher.dispatch(placeOpening('g', last))

    dispatcher.dispatch(removeOpening('g', middle.id))
    dispatcher.undo()

    expect(project.floors[0]?.openings).toEqual([first, middle, last])
  })

  it('carries a stable command type', () => {
    expect(removeOpening('g', 'opening-1').type).toBe(REMOVE_OPENING)
  })
})

describe('setOpeningType', () => {
  it('changes only the opening type and preserves every other field', () => {
    const project = projectWithTwoFloors()
    const dispatcher = dispatcherFor(project)
    const target = createOpening({
      type: 'single-swing-door',
      hostWallId: HOST_WALL_ID,
      position: 1200,
      width: 900,
      height: 2100,
      sillHeight: 0,
    })
    dispatcher.dispatch(placeOpening('g', target))

    dispatcher.dispatch(setOpeningType('g', target.id, 'double-swing-door'))

    const retyped = project.floors[0]?.openings[0]
    expect(retyped?.type).toBe('double-swing-door')
    expect(retyped?.hostWallId).toBe(target.hostWallId)
    expect(retyped?.position).toBe(target.position)
    expect(retyped?.width).toBe(target.width)
    expect(retyped?.height).toBe(target.height)
    expect(retyped?.sillHeight).toBe(target.sillHeight)
    expect(retyped?.orientation).toEqual(target.orientation)
  })

  it('resets the sill and height to the new defaults on a cross-category change while preserving placement', () => {
    const windowDefaults = getEntry(builtinElementTypes, 'double-hung-window')?.opening
    const doorDefaults = getEntry(builtinElementTypes, 'single-swing-door')?.opening

    const doorProject = projectWithTwoFloors()
    const doorDispatcher = dispatcherFor(doorProject)
    const door = createOpening({
      type: 'single-swing-door',
      hostWallId: HOST_WALL_ID,
      position: 1200,
      width: 1000,
      height: 2100,
      sillHeight: 0,
    })
    doorDispatcher.dispatch(placeOpening('g', door))

    doorDispatcher.dispatch(setOpeningType('g', door.id, 'double-hung-window'))

    const asWindow = doorProject.floors[0]?.openings[0]
    expect(asWindow?.type).toBe('double-hung-window')
    expect(asWindow?.hostWallId).toBe(door.hostWallId)
    expect(asWindow?.position).toBe(door.position)
    expect(asWindow?.width).toBe(door.width)
    expect(asWindow?.orientation).toEqual(door.orientation)
    expect(asWindow?.sillHeight).toBe(windowDefaults?.defaultSillHeight)
    expect(asWindow?.height).toBe(windowDefaults?.defaultHeight)

    const windowProject = projectWithTwoFloors()
    const windowDispatcher = dispatcherFor(windowProject)
    const window = createOpening({
      type: 'double-hung-window',
      hostWallId: HOST_WALL_ID,
      position: 1200,
      width: 1400,
      height: 1500,
      sillHeight: 750,
    })
    windowDispatcher.dispatch(placeOpening('g', window))

    windowDispatcher.dispatch(setOpeningType('g', window.id, 'single-swing-door'))

    const asDoor = windowProject.floors[0]?.openings[0]
    expect(asDoor?.type).toBe('single-swing-door')
    expect(asDoor?.hostWallId).toBe(window.hostWallId)
    expect(asDoor?.position).toBe(window.position)
    expect(asDoor?.width).toBe(window.width)
    expect(asDoor?.orientation).toEqual(window.orientation)
    expect(asDoor?.sillHeight).toBe(doorDefaults?.defaultSillHeight)
    expect(asDoor?.height).toBe(doorDefaults?.defaultHeight)
  })
})

