import { describe, expect, it } from 'vitest'
import { CURRENT_SCHEMA_VERSION, createEmptyProject, createWall } from '../model/factories'
import type { Point, Project, Wall } from '../model/types'
import { deriveRooms, roomKey } from '../topology/rooms'
import { isMigrationPending, migrateProject } from './migrate'
import type { ProjectShape, RegistryMigration, SchemaMigration } from './types'
import { MalformedProjectError, MigrationFailedError, UnsupportedSchemaVersionError } from './types'

function makeCurrentProject(): Project {
  return createEmptyProject({
    name: 'Test House',
    units: 'imperial',
    period: 'victorian',
    appVersion: '0.1.0',
  })
}

/**
 * Builds a synthetic schema migration that appends `breadcrumb` to a `trail`
 * array on the project, returning a fresh object so the migration stays pure
 * (it never mutates its argument) and the orchestrator owns the version number.
 */
function appendTrailMigration(from: number, breadcrumb: string): SchemaMigration {
  return {
    from,
    migrate(project: ProjectShape): ProjectShape {
      const trail = Array.isArray(project.trail) ? (project.trail as string[]) : []
      return { ...project, trail: [...trail, breadcrumb] }
    },
  }
}

function makeVersionedDocument(schemaVersion: unknown): Record<string, unknown> {
  return { meta: { schemaVersion }, trail: [] }
}

/**
 * Builds a synthetic registry migration that appends `breadcrumb` to the same
 * `trail` array the schema migrations use, returning a fresh object so the
 * migration stays pure and the orchestrator owns the registry version number.
 */
function appendTrailRegistryMigration(
  registry: string,
  from: number,
  breadcrumb: string,
): RegistryMigration {
  return {
    registry,
    from,
    migrate(project: ProjectShape): ProjectShape {
      const trail = Array.isArray(project.trail) ? (project.trail as string[]) : []
      return { ...project, trail: [...trail, breadcrumb] }
    },
  }
}

function makeRegistryDocument(
  schemaVersion: number,
  registryVersions: Record<string, number>,
): Record<string, unknown> {
  return { meta: { schemaVersion, registryVersions }, trail: [] }
}

describe('migrateProject', () => {
  it('returns a current-version project unchanged under the default empty chains', () => {
    const project = makeCurrentProject()
    const before = structuredClone(project)

    const migrated = migrateProject(project)

    expect(migrated).toEqual(before)
    expect(project).toEqual(before)
  })

  it('throws UnsupportedSchemaVersionError for a document newer than the target', () => {
    const project = makeCurrentProject()
    const newerVersion = CURRENT_SCHEMA_VERSION + 1
    const document = {
      ...project,
      meta: { ...project.meta, schemaVersion: newerVersion },
    }

    expect(() => migrateProject(document, { targetVersion: CURRENT_SCHEMA_VERSION })).toThrow(
      UnsupportedSchemaVersionError,
    )

    let thrown: unknown
    try {
      migrateProject(document, { targetVersion: CURRENT_SCHEMA_VERSION })
    } catch (error) {
      thrown = error
    }

    expect(thrown).toBeInstanceOf(UnsupportedSchemaVersionError)
    const error = thrown as UnsupportedSchemaVersionError
    expect(error.fromVersion).toBe(newerVersion)
    expect(error.targetVersion).toBe(CURRENT_SCHEMA_VERSION)
  })

  it('applies injected schema migrations in ascending order, feeding each the previous output', () => {
    const document = makeVersionedDocument(1)
    const schemaMigrations = [appendTrailMigration(1, 'v1->v2'), appendTrailMigration(2, 'v2->v3')]

    const migrated = migrateProject(document, { schemaMigrations, targetVersion: 3 })

    expect((migrated as unknown as { trail: string[] }).trail).toEqual(['v1->v2', 'v2->v3'])
    expect(migrated.meta.schemaVersion).toBe(3)
  })

  it('throws MigrationFailedError at the first missing step in the chain', () => {
    const document = makeVersionedDocument(1)
    const schemaMigrations = [appendTrailMigration(1, 'v1->v2')]

    let thrown: unknown
    try {
      migrateProject(document, { schemaMigrations, targetVersion: 3 })
    } catch (error) {
      thrown = error
    }

    expect(thrown).toBeInstanceOf(MigrationFailedError)
    expect((thrown as MigrationFailedError).fromVersion).toBe(2)
  })

  it('throws MalformedProjectError when the document has no meta', () => {
    let thrown: unknown
    try {
      migrateProject({})
    } catch (error) {
      thrown = error
    }

    expect(thrown).toBeInstanceOf(MalformedProjectError)
  })

  it('throws MalformedProjectError when meta.schemaVersion is not a number', () => {
    let thrown: unknown
    try {
      migrateProject(makeVersionedDocument('1'))
    } catch (error) {
      thrown = error
    }

    expect(thrown).toBeInstanceOf(MalformedProjectError)
  })

  it('applies a pending registry migration and advances that registry version', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, { finishes: 0 })
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'finishes:0->1')]

    const migrated = migrateProject(document, {
      registryMigrations,
      targetVersion: CURRENT_SCHEMA_VERSION,
    })

    expect((migrated as unknown as { trail: string[] }).trail).toEqual(['finishes:0->1'])
    expect(migrated.meta.registryVersions.finishes).toBe(1)
  })

  it('chains consecutive registry migrations for one registry in ascending order', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, { finishes: 0 })
    const registryMigrations = [
      appendTrailRegistryMigration('finishes', 0, 'finishes:0->1'),
      appendTrailRegistryMigration('finishes', 1, 'finishes:1->2'),
    ]

    const migrated = migrateProject(document, {
      registryMigrations,
      targetVersion: CURRENT_SCHEMA_VERSION,
    })

    expect((migrated as unknown as { trail: string[] }).trail).toEqual([
      'finishes:0->1',
      'finishes:1->2',
    ])
    expect(migrated.meta.registryVersions.finishes).toBe(2)
  })

  it('runs the registry pass only after the schema chain completes', () => {
    const document = makeRegistryDocument(1, { finishes: 0 })
    const schemaMigrations = [appendTrailMigration(1, 'schema')]
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'registry')]

    const migrated = migrateProject(document, {
      schemaMigrations,
      registryMigrations,
      targetVersion: 2,
    })

    expect((migrated as unknown as { trail: string[] }).trail).toEqual(['schema', 'registry'])
    expect(migrated.meta.schemaVersion).toBe(2)
    expect(migrated.meta.registryVersions.finishes).toBe(1)
  })

  it('leaves a registry untouched when no migration matches its current version', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, { finishes: 2 })
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'finishes:0->1')]

    const migrated = migrateProject(document, {
      registryMigrations,
      targetVersion: CURRENT_SCHEMA_VERSION,
    })

    expect((migrated as unknown as { trail: string[] }).trail).toEqual([])
    expect(migrated.meta.registryVersions.finishes).toBe(2)
  })
})

describe('migrateProject furniture backfill', () => {
  it('backfills an empty furniture array on each floor when migrating a version-9 document to the current version', () => {
    const documentV9 = {
      meta: {
        name: 'P',
        units: 'imperial',
        period: 'victorian',
        schemaVersion: 9,
        appVersion: '0.1.0',
        registryVersions: {},
      },
      floors: [
        {
          id: 'f1',
          name: 'Ground',
          elevation: 0,
          defaultCeilingHeight: 2438,
          walls: [],
          underlays: [],
          openings: [],
          dimensions: [],
        },
      ],
      stairs: [],
    }

    const migrated = migrateProject(documentV9 as unknown as ProjectShape, {
      targetVersion: CURRENT_SCHEMA_VERSION,
    })

    expect(migrated.meta.schemaVersion).toBe(CURRENT_SCHEMA_VERSION)
    expect(
      (migrated as unknown as { floors: { furniture: unknown[] }[] }).floors[0]?.furniture,
    ).toEqual([])
  })
})

const VERSION_SIXTEEN = 16

/** Corners of one rectangular parlor, in floor-plan millimeters. */
const PARLOR_CORNERS: Point[] = [
  { x: 0, y: 0 },
  { x: 4000, y: 0 },
  { x: 4000, y: 3000 },
  { x: 0, y: 3000 },
]

/**
 * One wall id per edge of `PARLOR_CORNERS`, each carrying dashes of its own. The
 * dashes matter: the dash-era key joined these ids with `-` too, so the saved key
 * cannot be split back into ids on `-`. Only the floor's wall-id vocabulary says
 * where one id ends and the next begins.
 */
const PARLOR_WALL_IDS = ['wall-south-2', 'wall-east-1', 'wall-north-1', 'wall-west-2']

/** The parlor's key as the app wrote it before `roomKey` switched to `|`. */
const DASH_ERA_ROOM_KEY = 'wall-east-1-wall-north-1-wall-south-2-wall-west-2'

const PARLOR_OVERRIDE = { name: 'Front Parlor', purpose: 'parlor' }

function parlorWalls(): Wall[] {
  return PARLOR_CORNERS.map((corner, index) => {
    const next = PARLOR_CORNERS[(index + 1) % PARLOR_CORNERS.length]
    const id = PARLOR_WALL_IDS[index]
    if (next === undefined || id === undefined) {
      throw new Error('expected a closing corner and a wall id per edge')
    }
    return createWall(corner, next, { id })
  })
}

/**
 * Builds a document sitting at the current head version whose one room override is
 * still keyed the dash-era way. No ladder step so far rewrites override keys, so a
 * project saved before the separator changed arrives here still carrying them.
 */
function makeDashEraOverrideDocument(): ProjectShape {
  return {
    meta: {
      name: 'Dash Era House',
      units: 'imperial',
      period: 'victorian',
      schemaVersion: VERSION_SIXTEEN,
      appVersion: '0.1.0',
      registryVersions: {},
    },
    floors: [
      {
        id: 'floor:ground',
        name: 'Ground Floor',
        elevation: 0,
        defaultCeilingHeight: 2438,
        walls: parlorWalls(),
        underlays: [],
        openings: [],
        dimensions: [],
        furniture: [],
      },
    ],
    stairs: [],
    roomOverrides: { [DASH_ERA_ROOM_KEY]: { ...PARLOR_OVERRIDE } },
  }
}

function soleDerivedRoomKey(walls: Wall[]): string {
  const [room, ...rest] = deriveRooms(walls)
  if (room === undefined || rest.length > 0) {
    throw new Error('expected exactly one derived room')
  }
  return roomKey(room)
}

describe('migrateProject dash-era room override keys', () => {
  it('rebinds a dash-joined override key to the pipe key roomKey derives for the same walls', () => {
    const migrated = migrateProject(makeDashEraOverrideDocument())

    const pipeKey = soleDerivedRoomKey(parlorWalls())
    expect(migrated.roomOverrides?.[pipeKey]).toEqual(PARLOR_OVERRIDE)
    expect(migrated.roomOverrides?.[DASH_ERA_ROOM_KEY]).toBeUndefined()
  })
})

describe('isMigrationPending', () => {
  it('is true for a document below the target version', () => {
    expect(isMigrationPending(makeVersionedDocument(1), { targetVersion: 3 })).toBe(true)
  })

  it('is true at the target version when a registry of the document has a step from its version', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, { finishes: 0 })
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'finishes:0->1')]

    expect(isMigrationPending(document, { registryMigrations })).toBe(true)
  })

  it('is false at the target version when no registry step starts from the stored registry version', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, { finishes: 2 })
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'finishes:0->1')]

    expect(isMigrationPending(document, { registryMigrations })).toBe(false)
  })

  it('is false at the target version when the document records no version for the registry', () => {
    const document = makeRegistryDocument(CURRENT_SCHEMA_VERSION, {})
    const registryMigrations = [appendTrailRegistryMigration('finishes', 0, 'finishes:0->1')]

    expect(isMigrationPending(document, { registryMigrations })).toBe(false)
  })

  it('is false for a current-version project under the default steps', () => {
    expect(isMigrationPending(makeCurrentProject())).toBe(false)
  })
})

