import * as THREE from 'three'
import { describe, expect, it } from 'vitest'

import { createFloor, createFurnitureInstance, deriveFurnitureNode } from '../../core'
import type { FurnitureInstance, FurnitureSceneNode } from '../../core'
import type { SurfaceRole } from '../materials/material-provider'
import { NeutralMaterialProvider } from '../materials/neutral-material-provider'
import {
  FURNITURE_BASE_DEPTH_BIAS,
  FURNITURE_COLOR,
  FURNITURE_FAILED_COLOR,
  FURNITURE_FAILED_OPACITY,
  FURNITURE_LOADING_COLOR,
  FURNITURE_LOADING_OPACITY,
  FURNITURE_OPACITY,
} from '../materials/role-appearance'

import { buildFurnitureMassing } from './furniture-builder'

const PRECISION = 3

const POSITION = { x: 1000, y: 2000 }
const FOOTPRINT = { width: 1200, depth: 600 }
const ELEVATION_Z = 0
const HEIGHT = 750

const HALF_WIDTH = FOOTPRINT.width / 2
const HALF_DEPTH = FOOTPRINT.depth / 2

const EXPECTED_MIN_X = POSITION.x - HALF_WIDTH
const EXPECTED_MAX_X = POSITION.x + HALF_WIDTH
// Plan y maps to world -z, so the footprint's z span is the negated y span.
const EXPECTED_MIN_Z = -(POSITION.y + HALF_DEPTH)
const EXPECTED_MAX_Z = -(POSITION.y - HALF_DEPTH)
const EXPECTED_MIN_Y = ELEVATION_Z
const EXPECTED_MAX_Y = ELEVATION_Z + HEIGHT

function buildInstance(): FurnitureInstance {
  return createFurnitureInstance({
    assetRef: { scope: 'user', contentHash: 'abc' },
    position: POSITION,
    footprint: FOOTPRINT,
    rotation: 0,
    elevationZ: ELEVATION_Z,
    height: HEIGHT,
  })
}

function buildNode(instance: FurnitureInstance): FurnitureSceneNode {
  return deriveFurnitureNode(createFloor('Ground'), instance)
}

function firstMeshMaterials(group: THREE.Group): THREE.Material[] {
  let mesh: THREE.Mesh | undefined
  group.traverse((object) => {
    if (mesh === undefined && object instanceof THREE.Mesh) {
      mesh = object
    }
  })
  const material = mesh?.material
  if (material === undefined) {
    return []
  }
  return Array.isArray(material) ? material : [material]
}

describe('buildFurnitureMassing', () => {
  it('tags the massing group with the raw furniture instance id', () => {
    const instance = buildInstance()

    const group = buildFurnitureMassing(buildNode(instance), new NeutralMaterialProvider())

    expect(group.userData.entityId).toBe(instance.id)
  })

  it('flags the massing group as a placeholder box so a loaded model is distinguishable from it', () => {
    const group = buildFurnitureMassing(buildNode(buildInstance()), new NeutralMaterialProvider())

    expect(group.userData.furnitureMassing).toBe(true)
  })

  it('spans the footprint in X and Z and elevation-to-top in Y in world space', () => {
    const group = buildFurnitureMassing(buildNode(buildInstance()), new NeutralMaterialProvider())

    const aabb = new THREE.Box3().setFromObject(group)

    expect(aabb.min.x).toBeCloseTo(EXPECTED_MIN_X, PRECISION)
    expect(aabb.max.x).toBeCloseTo(EXPECTED_MAX_X, PRECISION)
    expect(aabb.min.z).toBeCloseTo(EXPECTED_MIN_Z, PRECISION)
    expect(aabb.max.z).toBeCloseTo(EXPECTED_MAX_Z, PRECISION)
    expect(aabb.min.y).toBeCloseTo(EXPECTED_MIN_Y, PRECISION)
    expect(aabb.max.y).toBeCloseTo(EXPECTED_MAX_Y, PRECISION)
  })

  it('names the box mesh material so painting can key on it', () => {
    const group = buildFurnitureMassing(buildNode(buildInstance()), new NeutralMaterialProvider())

    const materials = firstMeshMaterials(group)

    expect(materials.length).toBeGreaterThan(0)
    for (const material of materials) {
      expect(material.name).toBe('furniture')
    }
  })

  it('carries the distinct red semi-transparent material on the unloaded box mesh', () => {
    const group = buildFurnitureMassing(buildNode(buildInstance()), new NeutralMaterialProvider())

    const materials = firstMeshMaterials(group)

    expect(materials.length).toBeGreaterThan(0)
    for (const material of materials) {
      const colored = material as THREE.Material & { color: THREE.Color }
      expect(colored.color.getHex()).toBe(FURNITURE_COLOR)
      expect(material.transparent).toBe(true)
      expect(material.opacity).toBe(FURNITURE_OPACITY)
    }
  })

  it('carries the furnitureFailed material on a failed-load box mesh', () => {
    const group = buildFurnitureMassing(
      buildNode(buildInstance()),
      new NeutralMaterialProvider(),
      'furnitureFailed',
    )

    const materials = firstMeshMaterials(group)

    expect(materials.length).toBeGreaterThan(0)
    for (const material of materials) {
      const colored = material as THREE.Material & { color: THREE.Color }
      expect(colored.color.getHex()).toBe(FURNITURE_FAILED_COLOR)
      expect(material.name).toBe('furnitureFailed')
      expect(material.transparent).toBe(true)
      expect(material.opacity).toBe(FURNITURE_FAILED_OPACITY)
    }
  })

  it('carries the furnitureLoading material on a loading box mesh', () => {
    const group = buildFurnitureMassing(
      buildNode(buildInstance()),
      new NeutralMaterialProvider(),
      'furnitureLoading' as SurfaceRole,
    )

    const materials = firstMeshMaterials(group)

    expect(materials.length).toBeGreaterThan(0)
    for (const material of materials) {
      const colored = material as THREE.Material & { color: THREE.Color }
      expect(colored.color.getHex()).toBe(FURNITURE_LOADING_COLOR)
      expect(material.name).toBe('furnitureLoading')
      expect(material.transparent).toBe(true)
      expect(material.opacity).toBe(FURNITURE_LOADING_OPACITY)
    }
  })

  it('biases only the base-cap section back in depth so the box loses the depth test to the floor it rests on', () => {
    const group = buildFurnitureMassing(buildNode(buildInstance()), new NeutralMaterialProvider())

    const materials = firstMeshMaterials(group)

    // The base cap is its own material section apart from the sides and top, so the
    // box is a multi-material mesh, the same one-material-per-section shape the wall
    // builders already use.
    expect(materials.length).toBeGreaterThan(1)

    // Exactly the base-cap section carries the furniture-base rung, pushed back far
    // enough to lose the depth test to the slab top and the ground plane beneath it.
    const biased = materials.filter(
      (material) =>
        material.polygonOffset === true &&
        material.polygonOffsetFactor === FURNITURE_BASE_DEPTH_BIAS.factor &&
        material.polygonOffsetUnits === FURNITURE_BASE_DEPTH_BIAS.units,
    )
    expect(biased).toHaveLength(1)

    // The sides and top stay unbiased at the furniture role's default, so only the
    // coincident base cap loses the contest.
    const unbiased = materials.filter((material) => material.polygonOffset !== true)
    expect(unbiased).toHaveLength(materials.length - 1)
  })
})

core/scene/junction-fade.test.ts.source:
import { describe, expect, it } from 'vitest'

import type { Point } from '../model/types'
import { buildWallGraph } from '../topology/wall-graph'
import { junctionFadeGroups, type JunctionFadeGroup } from './junction-fade'
import type { RoomSceneNode, WallSceneNode } from './scene-graph'

const FLOOR_ID = 'g'
const WALL_THICKNESS = 100

function wall(id: string, start: Point, end: Point): WallSceneNode {
  return { id, kind: 'wall', floorId: FLOOR_ID, start, end, thickness: WALL_THICKNESS }
}

function room(id: string, ring: Point[]): RoomSceneNode {
  return { id, kind: 'room', floorId: FLOOR_ID, polygon: ring, clearPolygon: ring, area: 1 }
}

function point(x: number, y: number): Point {
  return { x, y }
}

describe('junctionFadeGroups', () => {
  it('pairs a three-way junction with only the exterior walls meeting it', () => {
    // A through "bar" wall (0,0)->(2000,0) with a "leg" wall teed up from its
    // midpoint at (1000,0). buildWallGraph splits the bar at the tee foot into a
    // left half and a right half, so the vertex at (1000,0) carries three
    // incident edges (two bar halves and the leg). Two rooms sit north of the
    // bar, divided by the leg: Room A west of the leg, Room B east of it.
    //
    //   - The bar is exterior: a room is north of it, open air to the south.
    //   - The leg is an interior partition: Room A on its west, Room B on its
    //     east, so it bounds no outside face and never fades.
    //
    // The fade group for the three-way junction must enumerate only the exterior
    // wall(s) meeting it (the bar), so the junction fill knows which walls' fade
    // it tracks, and must exclude the interior leg.
    const graph = buildWallGraph([
      { id: 'bar', start: point(0, 0), end: point(2000, 0), thickness: WALL_THICKNESS },
      { id: 'leg', start: point(1000, 0), end: point(1000, 1000), thickness: WALL_THICKNESS },
    ])

    const walls = [
      wall('wall:bar', point(0, 0), point(2000, 0)),
      wall('wall:leg', point(1000, 0), point(1000, 1000)),
    ]
    const rooms = [
      room('room:a', [point(0, 0), point(1000, 0), point(1000, 1000), point(0, 1000)]),
      room('room:b', [point(1000, 0), point(2000, 0), point(2000, 1000), point(1000, 1000)]),
    ]

    const groups: JunctionFadeGroup[] = junctionFadeGroups(graph, walls, rooms)

    // Exactly one three-way junction, hence exactly one fade group.
    expect(groups).toHaveLength(1)
    const [group] = groups as [JunctionFadeGroup]

    // The group cites the junction's three incident edges (its identity).
    expect([...group.edgeIndexes].sort((left, right) => left - right)).toEqual(
      [...graph.edges.keys()].sort((left, right) => left - right),
    )

    // It enumerates only the exterior wall meeting the junction (the bar), not
    // the interior leg partition.
    expect([...group.exteriorWallIds].sort()).toEqual(['wall:bar'])
  })

  it('holds a mixed junction fill unconditionally when a non-fading interior wall meets it', () => {
    // Same T-junction fixture: an exterior "bar" wall and an interior "leg"
    // partition meet at a three-way tee with two rooms north of the bar.
    //
    // Near-wall transparency only fades exterior walls, so the interior leg
    // never fades at any camera angle. The junction therefore always keeps a
    // solid neighbor whose mitered end the fill covers and whose mass divides
    // the two rooms, so the fill must hold opaque no matter the camera (issue
    // #227). The fade group records that structural fact, and it still
    // enumerates its member exterior wall ids so the engine can read the policy
    // without re-deriving membership.
    const graph = buildWallGraph([
      { id: 'bar', start: point(0, 0), end: point(2000, 0), thickness: WALL_THICKNESS },
      { id: 'leg', start: point(1000, 0), end: point(1000, 1000), thickness: WALL_THICKNESS },
    ])

    const walls = [
      wall('wall:bar', point(0, 0), point(2000, 0)),
      wall('wall:leg', point(1000, 0), point(1000, 1000)),
    ]
    const rooms = [
      room('room:a', [point(0, 0), point(1000, 0), point(1000, 1000), point(0, 1000)]),
      room('room:b', [point(1000, 0), point(2000, 0), point(2000, 1000), point(1000, 1000)]),
    ]

    const groups: JunctionFadeGroup[] = junctionFadeGroups(graph, walls, rooms)

    expect(groups).toHaveLength(1)
    const [group] = groups as [JunctionFadeGroup]

    // The interior leg never fades, so this junction always keeps a solid
    // neighbor and its fill holds opaque unconditionally.
    expect(group.exteriorWallIds.length).toBeGreaterThanOrEqual(1)
    expect(group.fillHoldsUnconditionally).toBe(true)

    // The member exterior wall ids stay available alongside the policy.
    expect([...group.exteriorWallIds].sort()).toEqual(['wall:bar'])
  })

  it('leaves a pure-exterior junction fill hold conditional on the live camera', () => {
    // Three separate exterior walls meet at the corner (1000,0): a "west" wall
    // and an "east" wall running along the x-axis, plus a "north" wall rising
    // from the corner. Two rooms touch only at that corner, each bordering the
    // walls on one side, so every incident wall has open air on its other side
    // and classifies as exterior:
    //
    //   - 'west' bounds room A to its north, open air to the south.
    //   - 'north' bounds room A to its west, open air to the east.
    //   - 'east' bounds room B to its south, open air to the north.
    //
    // No incident wall is an interior partition, so a camera can sit outside all
    // three at once and fade every one. With no non-fading neighbor guaranteed,
    // the fill's hold cannot be unconditional; whether it holds is decided later
    // per-frame by the engine against the live camera. The group still
    // enumerates all three incident exterior walls the engine tracks.
    const graph = buildWallGraph([
      { id: 'west', start: point(0, 0), end: point(1000, 0), thickness: WALL_THICKNESS },
      { id: 'east', start: point(1000, 0), end: point(2000, 0), thickness: WALL_THICKNESS },
      { id: 'north', start: point(1000, 0), end: point(1000, 1000), thickness: WALL_THICKNESS },
    ])

    const walls = [
      wall('wall:west', point(0, 0), point(1000, 0)),
      wall('wall:east', point(1000, 0), point(2000, 0)),
      wall('wall:north', point(1000, 0), point(1000, 1000)),
    ]
    const rooms = [
      room('room:a', [point(0, 0), point(1000, 0), point(1000, 1000), point(0, 1000)]),
      room('room:b', [point(1000, 0), point(2000, 0), point(2000, -1000), point(1000, -1000)]),
    ]

    const groups: JunctionFadeGroup[] = junctionFadeGroups(graph, walls, rooms)

    expect(groups).toHaveLength(1)
    const [group] = groups as [JunctionFadeGroup]

    // Every incident wall is exterior, so no neighbor is guaranteed solid and
    // the fill's hold stays conditional on the camera.
    expect(group.fillHoldsUnconditionally).toBe(false)

    // All three incident exterior walls are enumerated for the engine to test.
    expect([...group.exteriorWallIds].sort()).toEqual(['wall:east', 'wall:north', 'wall:west'])
  })
})

scripts/pack/vernacular-pack.integration.source:
import { describe, expect, it, vi } from 'vitest'
import { join, resolve } from 'node:path'
import { createNodePackReader, readManifestFromDisk, runPackCli } from './vernacular-pack.mjs'

// Vitest runs with the project root as the working directory, matching the
// repository's other fixture-backed tests (for example derive-underlay-fixture).
const packsDir = resolve('tests/fixtures/packs')

function integrationDeps() {
  const reports = []
  return {
    reports,
    readManifest: readManifestFromDisk,
    createReader: createNodePackReader,
    // Capture the build report in memory so the smoke does not write into the repo.
    writeReport: (_dir, report) => {
      reports.push(report)
      return Promise.resolve()
    },
    log: vi.fn(),
    error: vi.fn(),
  }
}

describe('vernacular-pack against the fixture packs', () => {
  it('validates and builds the well-formed pack with real readers', async () => {
    const deps = integrationDeps()
    const packDir = join(packsDir, 'vernacular-starter-1.0.0')

    expect(await runPackCli(['validate', packDir], deps)).toBe(0)
    expect(await runPackCli(['build', packDir], deps)).toBe(0)
    expect(deps.error).not.toHaveBeenCalled()

    const report = deps.reports.at(-1)
    expect(report.status).toBe('PASS')
    expect(report.assets).toHaveLength(1)
    expect(report.licenses.distinct).toEqual(['CC0-1.0'])
  })

  it('reports every distinct problem in the broken pack', async () => {
    const deps = integrationDeps()
    const packDir = join(packsDir, 'broken-pack-wrong')

    expect(await runPackCli(['validate', packDir], deps)).toBe(1)

    const messages = deps.error.mock.calls.map((call) => call[0]).join('\n')
    expect(messages).toMatch(/forbids redistribution/)
    expect(messages).toMatch(/content hash does not match/)
    expect(messages).toMatch(/thumbnail missing/)
    expect(messages).toMatch(/orphan file not referenced/)
    expect(messages).toMatch(/NOTICE: required pack file missing/)
    expect(messages).toMatch(/broken-pack-1\.0\.0/)
  })
})

core/environment/shadow-fit.test.ts.source:
import { describe, expect, it } from 'vitest'
import { boundsRadius, shadowFitBounds } from './shadow-fit'
import type { Bounds3, Vector3 } from '../scene/vector3'

// The world frame is right-handed and Y-up (core/scene/vector3.ts), lengths are
// millimetres. The sun direction points FROM the scene TOWARD the sun, so a
// shadow falls on the opposite side: a point at height h above the ground lands
// h / tan(altitude) away from the sun along the ground. With the casters' top
// at 2600 mm:
//   45 degree sun: 2600 / tan(45) = 2600, so the shadow reaches x = 0 - 2600.
//   5 degree sun:  2600 / tan(5) is about 29718, far past the ground's -5000.

const CASTERS: Bounds3 = {
  min: { x: 0, y: 0, z: -3000 },
  max: { x: 4000, y: 2600, z: 0 },
}
const GROUND: Bounds3 = {
  min: { x: -5000, y: 0, z: -8000 },
  max: { x: 9000, y: 0, z: 5000 },
}
const NO_CAP = 1e9
const ONE_MILLIMETRE = 1

const FIVE_DEGREES = (5 * Math.PI) / 180
const OVERHEAD: Vector3 = { x: 0, y: 1, z: 0 }
const FORTY_FIVE_DEGREES: Vector3 = { x: 0.7071, y: 0.7071, z: 0 }
const FIVE_DEGREES_UP: Vector3 = { x: Math.cos(FIVE_DEGREES), y: Math.sin(FIVE_DEGREES), z: 0 }
const ON_THE_HORIZON: Vector3 = { x: 1, y: 0, z: 0 }
const BELOW_THE_HORIZON: Vector3 = { x: 0.995, y: -0.0995, z: 0 }

function numbersOf(bounds: Bounds3): number[] {
  const { min, max } = bounds
  return [min.x, min.y, min.z, max.x, max.y, max.z]
}

function expectWithin(actual: number, expected: number, tolerance: number): void {
  expect(Math.abs(actual - expected)).toBeLessThan(tolerance)
}

describe('boundsRadius', () => {
  it('is half the diagonal of the box', () => {
    expect(boundsRadius(CASTERS)).toBeCloseTo(Math.hypot(4000, 2600, 3000) / 2, 6)
  })
})

describe('shadowFitBounds', () => {
  it('equals the casters when the sun is straight overhead', () => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection: OVERHEAD,
      maxRadius: NO_CAP,
    })
    expect(fit).toEqual(CASTERS)
  })

  it.each([
    ['a sun overhead', OVERHEAD],
    ['a sun 5 degrees up', FIVE_DEGREES_UP],
    ['a sun on the horizon', ON_THE_HORIZON],
    ['a sun below the horizon', BELOW_THE_HORIZON],
  ])('equals the casters when there is no ground, for %s', (_name, sunDirection) => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: null,
      sunDirection,
      maxRadius: NO_CAP,
    })
    expect(fit).toEqual(CASTERS)
  })

  it('extends the fit to where the roof edge casts its shadow on the ground', () => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection: FORTY_FIVE_DEGREES,
      maxRadius: NO_CAP,
    })
    expectWithin(fit.min.x, -2600, ONE_MILLIMETRE)
    expect(fit.min.y).toBe(CASTERS.min.y)
    expect(fit.min.z).toBe(CASTERS.min.z)
    expect(fit.max).toEqual(CASTERS.max)
  })

  it('clips the shadow of a low sun to the edge of the ground', () => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection: FIVE_DEGREES_UP,
      maxRadius: NO_CAP,
    })
    expectWithin(fit.min.x, -5000, ONE_MILLIMETRE)
  })

  it.each([
    ['on the horizon', ON_THE_HORIZON],
    ['below the horizon', BELOW_THE_HORIZON],
  ])(
    'reaches the ground edge away from a sun %s with every value finite',
    (_name, sunDirection) => {
      const fit = shadowFitBounds({
        casters: CASTERS,
        ground: GROUND,
        sunDirection,
        maxRadius: NO_CAP,
      })
      expectWithin(fit.min.x, -5000, ONE_MILLIMETRE)
      expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
    },
  )

  it('keeps a basement in the fit and projects no corner that lies below the ground', () => {
    const casters: Bounds3 = {
      min: { x: 0, y: -2400, z: -3000 },
      max: { x: 4000, y: 2600, z: 0 },
    }
    const fit = shadowFitBounds({
      casters,
      ground: GROUND,
      sunDirection: FORTY_FIVE_DEGREES,
      maxRadius: NO_CAP,
    })
    expect(fit.min.y).toBe(-2400)
    // Projecting the basement floor corners toward the sun would land them at
    // x = 4000 + 2400 = 6400 and push the far edge out; they must stay out.
    expect(fit.max).toEqual(casters.max)
    expectWithin(fit.min.x, -2600, ONE_MILLIMETRE)
  })

  it('shrinks the fit toward the casters until its radius equals the cap', () => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection: FIVE_DEGREES_UP,
      maxRadius: 4000,
    })
    // The uncapped box spans x in [-5000, 4000], radius about 4918, above the
    // cap of 4000 and above the casters' own radius of about 2818.
    expectWithin(boundsRadius(fit), 4000, ONE_MILLIMETRE)
    expect(fit.max).toEqual(CASTERS.max)
    expect(fit.min.x).toBeGreaterThan(-5000)
    expect(fit.min.x).toBeLessThan(0)
  })

  it('never shrinks the casters, so a cap under their own radius returns them', () => {
    const fit = shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection: FIVE_DEGREES_UP,
      maxRadius: 2000,
    })
    expect(fit).toEqual(CASTERS)
    expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
  })

  it('returns very large casters unchanged when their radius already exceeds the cap', () => {
    // 60 m by 40 m by 30 m: radius hypot(60000, 40000, 30000) / 2 is about 39051.
    const casters: Bounds3 = {
      min: { x: 0, y: 0, z: -30000 },
      max: { x: 60000, y: 40000, z: 0 },
    }
    const fit = shadowFitBounds({
      casters,
      ground: GROUND,
      sunDirection: FORTY_FIVE_DEGREES,
      maxRadius: 20000,
    })
    expect(fit).toEqual(casters)
    expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
  })
})

describe('shadowFitBounds near the horizon', () => {
  // A sun due east as the application computes it carries a z component of
  // floating-point noise (Math.cos(Math.PI / 2) is about 6.1e-17).
  const COSINE_NOISE = -6.1e-17

  function fitFor(sunDirection: Vector3): Bounds3 {
    return shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection,
      maxRadius: NO_CAP,
    })
  }

  function dueEastAt(altitude: number): Vector3 {
    return {
      x: Math.cos(altitude),
      y: Math.sin(altitude),
      z: COSINE_NOISE * Math.cos(altitude),
    }
  }

  function expectSameBox(actual: Bounds3, expected: Bounds3): void {
    const differences = numbersOf(actual).map((value, index) =>
      Math.abs(value - (numbersOf(expected)[index] ?? Number.NaN)),
    )
    expect(Math.max(...differences)).toBeLessThan(ONE_MILLIMETRE)
  }

  it('gives the same box for a due-east sun just above the horizon and on it', () => {
    expectSameBox(fitFor(dueEastAt(2e-6)), fitFor(dueEastAt(0)))
  })

  it('gives the same box for a due-east sun at two altitudes either side of the threshold', () => {
    expectSameBox(fitFor(dueEastAt(2e-6)), fitFor(dueEastAt(1e-6)))
  })

  it('gives the same box just above and just below the height threshold', () => {
    const above = fitFor({ x: 1, y: 1.000001e-6, z: 1e-7 })
    const below = fitFor({ x: 1, y: 0.999999e-6, z: 1e-7 })
    expectSameBox(above, below)
  })

  it('treats a sun below the horizon as a sun on the horizon', () => {
    const onTheHorizon = fitFor({ x: 1, y: 0, z: 1e-7 })
    const below = fitFor({ x: 1, y: -0.1, z: 1e-7 })
    expectSameBox(below, onTheHorizon)
  })

  it.each([
    ['on the horizon', ON_THE_HORIZON],
    ['5 degrees up', FIVE_DEGREES_UP],
    ['below the horizon', BELOW_THE_HORIZON],
  ])('leaves the depth of the casters alone for a sun %s with no sideways component', (_n, sun) => {
    const fit = fitFor(sun)
    expect(fit.min.z).toBe(CASTERS.min.z)
    expect(fit.max.z).toBe(CASTERS.max.z)
  })
})

describe('shadowFitBounds with input that is not finite', () => {
  function fitFor(sunDirection: Vector3): Bounds3 {
    return shadowFitBounds({
      casters: CASTERS,
      ground: GROUND,
      sunDirection,
      maxRadius: NO_CAP,
    })
  }

  it.each([
    ['x is NaN', { ...FORTY_FIVE_DEGREES, x: Number.NaN }],
    ['y is NaN', { ...FORTY_FIVE_DEGREES, y: Number.NaN }],
    ['z is Infinity', { ...FORTY_FIVE_DEGREES, z: Number.POSITIVE_INFINITY }],
    ['x is -Infinity', { ...FORTY_FIVE_DEGREES, x: Number.NEGATIVE_INFINITY }],
    ['y is -Infinity', { ...FORTY_FIVE_DEGREES, y: Number.NEGATIVE_INFINITY }],
  ])('gives the casters, with every value finite, when the sun direction %s', (_name, sun) => {
    const fit = fitFor(sun)
    expect(fit).toEqual(CASTERS)
    expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
  })

  it('gives a copy of the casters, not the box that was passed in', () => {
    const fit = fitFor({ ...FORTY_FIVE_DEGREES, x: Number.NaN })
    expect(fit).not.toBe(CASTERS)
  })

  describe('with a cap on the radius that is not a finite number', () => {
    function fitWithCap(maxRadius: number): Bounds3 {
      return shadowFitBounds({
        casters: CASTERS,
        ground: GROUND,
        sunDirection: FORTY_FIVE_DEGREES,
        maxRadius,
      })
    }

    it('gives a copy of the casters, with every value finite, when the cap is NaN', () => {
      const fit = fitWithCap(Number.NaN)
      expect(fit).toEqual(CASTERS)
      expect(fit).not.toBe(CASTERS)
      expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
    })

    it('means no cap when the cap is Infinity', () => {
      expect(fitWithCap(Number.POSITIVE_INFINITY)).toEqual(fitWithCap(NO_CAP))
    })

    it('gives the casters when the cap is -Infinity', () => {
      expect(fitWithCap(Number.NEGATIVE_INFINITY)).toEqual(CASTERS)
    })
  })

  describe('with a ground box that has a number that is not finite', () => {
    const EMPTY_GROUND: Bounds3 = {
      min: { x: Infinity, y: Infinity, z: Infinity },
      max: { x: -Infinity, y: -Infinity, z: -Infinity },
    }

    it.each([
      ['min.x is NaN', { ...GROUND, min: { ...GROUND.min, x: Number.NaN } }, FORTY_FIVE_DEGREES],
      ['it is an empty box', EMPTY_GROUND, FORTY_FIVE_DEGREES],
      [
        'min.y and max.y are -Infinity',
        {
          min: { ...GROUND.min, y: Number.NEGATIVE_INFINITY },
          max: { ...GROUND.max, y: Number.NEGATIVE_INFINITY },
        },
        OVERHEAD,
      ],
      [
        'max.x is Infinity',
        { ...GROUND, max: { ...GROUND.max, x: Number.POSITIVE_INFINITY } },
        FORTY_FIVE_DEGREES,
      ],
    ])('gives a copy of the casters, with every value finite, when %s', (_name, ground, sun) => {
      const fit = shadowFitBounds({
        casters: CASTERS,
        ground,
        sunDirection: sun,
        maxRadius: NO_CAP,
      })
      expect(fit).toEqual(CASTERS)
      expect(fit).not.toBe(CASTERS)
      expect(numbersOf(fit).every(Number.isFinite)).toBe(true)
    })
  })
})

