import { describe, it, expect } from 'vitest'
import {
  hitTest,
  hitTestWalls,
  hitTestOpenings,
  hitTestDimensions,
  dimensionBounds,
  openingBounds,
  roomBounds,
  wallBounds,
  DEFAULT_HIT_TOLERANCE_MM,
} from './hit-test'
import type {
  DimensionSceneNode,
  OpeningSceneNode,
  RoomSceneNode,
  SceneGraph,
  StairSceneNode,
  WallSceneNode,
} from '../../core'

const WALL_THICKNESS_MM = 114
const OPENING_WIDTH_MM = 800
const OPENING_HALF_WIDTH_MM = OPENING_WIDTH_MM / 2
const HOST_HALF_THICKNESS_MM = WALL_THICKNESS_MM / 2

function wall(
  id: string,
  start: { x: number; y: number },
  end: { x: number; y: number },
): WallSceneNode {
  return { id, kind: 'wall', floorId: 'g', start, end, thickness: WALL_THICKNESS_MM }
}

function opening(id: string, center: { x: number; y: number }): OpeningSceneNode {
  return {
    id,
    kind: 'opening',
    floorId: 'g',
    type: 'single-swing-door',
    center,
    along: { x: 1, y: 0 },
    normal: { x: 0, y: 1 },
    width: OPENING_WIDTH_MM,
    height: 2032,
    sillHeight: 0,
    hostThickness: WALL_THICKNESS_MM,
    orientation: { hinge: 'start', facing: 'positive' },
  }
}

describe('hitTestWalls', () => {
  it('returns the id of a wall the point lies on', () => {
    const walls = [wall('wall:a', { x: 0, y: 0 }, { x: 1000, y: 0 })]

    expect(hitTestWalls(walls, { x: 500, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe('wall:a')
  })

  it('returns null when the point is beyond the tolerance', () => {
    const walls = [wall('wall:a', { x: 0, y: 0 }, { x: 1000, y: 0 })]

    expect(hitTestWalls(walls, { x: 500, y: 5000 }, DEFAULT_HIT_TOLERANCE_MM)).toBeNull()
  })

  it('returns the nearest wall when several are in range', () => {
    const walls = [
      wall('wall:far', { x: 0, y: 100 }, { x: 1000, y: 100 }),
      wall('wall:near', { x: 0, y: 0 }, { x: 1000, y: 0 }),
    ]

    expect(hitTestWalls(walls, { x: 500, y: 10 }, DEFAULT_HIT_TOLERANCE_MM)).toBe('wall:near')
  })

  it('clamps the projection to the segment endpoints', () => {
    const walls = [wall('wall:a', { x: 0, y: 0 }, { x: 1000, y: 0 })]

    // A point well past the segment end, but near the endpoint, is within tolerance;
    // a point past the end and far away is not.
    expect(hitTestWalls(walls, { x: 1050, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe('wall:a')
    expect(hitTestWalls(walls, { x: 5000, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBeNull()
  })
})

describe('wallBounds', () => {
  it('spans the wall endpoints regardless of draw direction', () => {
    const rightToLeftBottomToTop = wall('wall:a', { x: 1000, y: 3000 }, { x: 200, y: 500 })

    expect(wallBounds(rightToLeftBottomToTop)).toEqual({
      min: { x: 200, y: 500 },
      max: { x: 1000, y: 3000 },
    })
  })
})

function room(id: string, polygon: { x: number; y: number }[]): RoomSceneNode {
  return { id, kind: 'room', floorId: 'g', polygon, area: 0, clearPolygon: polygon }
}

function dimension(
  id: string,
  start: { x: number; y: number },
  end: { x: number; y: number },
): DimensionSceneNode {
  return { id, kind: 'dimension', floorId: 'g', start, end, offset: 0, length: 0 }
}

describe('roomBounds', () => {
  it('spans every vertex of the room polygon', () => {
    const lShape = room('room:a', [
      { x: 0, y: 0 },
      { x: 4000, y: 0 },
      { x: 4000, y: 2000 },
      { x: 2000, y: 2000 },
      { x: 2000, y: 5000 },
      { x: 0, y: 5000 },
    ])

    expect(roomBounds(lShape)).toEqual({ min: { x: 0, y: 0 }, max: { x: 4000, y: 5000 } })
  })
})

interface SceneExtras {
  openings?: OpeningSceneNode[]
  dimensions?: DimensionSceneNode[]
  stairs?: StairSceneNode[]
}

function scene(
  walls: WallSceneNode[],
  rooms: RoomSceneNode[] = [],
  extras: SceneExtras = {},
): SceneGraph {
  return {
    nodes: [],
    walls,
    rooms,
    underlays: [],
    openings: extras.openings ?? [],
    dimensions: extras.dimensions ?? [],
    stairs: extras.stairs ?? [],
    furniture: [],
  }
}

describe('hitTest', () => {
  it('returns the nearest wall within tolerance', () => {
    const graph = scene([
      wall('wall:far', { x: 0, y: 100 }, { x: 1000, y: 100 }),
      wall('wall:near', { x: 0, y: 0 }, { x: 1000, y: 0 }),
    ])

    expect(hitTest(graph, { x: 500, y: 10 }, DEFAULT_HIT_TOLERANCE_MM)).toBe('wall:near')
  })

  const wallAndRoomScene = (): SceneGraph =>
    scene(
      [wall('wall:edge', { x: 0, y: 0 }, { x: 4000, y: 0 })],
      [
        room('room:a', [
          { x: 0, y: 0 },
          { x: 4000, y: 0 },
          { x: 4000, y: 4000 },
          { x: 0, y: 4000 },
        ]),
      ],
    )

  it('falls back to the room whose polygon contains the point when no wall is in range', () => {
    expect(hitTest(wallAndRoomScene(), { x: 2000, y: 2000 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'room:a',
    )
  })

  it('prefers a wall in range over a containing room', () => {
    expect(hitTest(wallAndRoomScene(), { x: 2000, y: 50 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'wall:edge',
    )
  })

  it('returns null when the point hits neither a wall nor a room', () => {
    expect(
      hitTest(wallAndRoomScene(), { x: 50_000, y: 50_000 }, DEFAULT_HIT_TOLERANCE_MM),
    ).toBeNull()
  })
})

describe('openingBounds', () => {
  it('spans the opening footprint, width along the wall by thickness across', () => {
    const node = opening('opening:o1', { x: 1000, y: 0 })

    expect(openingBounds(node)).toEqual({
      min: { x: 1000 - OPENING_HALF_WIDTH_MM, y: -HOST_HALF_THICKNESS_MM },
      max: { x: 1000 + OPENING_HALF_WIDTH_MM, y: HOST_HALF_THICKNESS_MM },
    })
  })
})

describe('hitTestOpenings', () => {
  it('returns the id of an opening whose footprint contains the point', () => {
    const openings = [opening('opening:o1', { x: 1000, y: 0 })]

    expect(hitTestOpenings(openings, { x: 1000, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'opening:o1',
    )
  })

  it('returns null when the point is outside every opening footprint', () => {
    const openings = [opening('opening:o1', { x: 1000, y: 0 })]

    expect(hitTestOpenings(openings, { x: 5000, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBeNull()
  })
})

describe('hitTest opening priority', () => {
  const openingOnWallScene = (): SceneGraph =>
    scene(
      [wall('wall:host', { x: 0, y: 0 }, { x: 2000, y: 0 })],
      [
        room('room:a', [
          { x: 0, y: 0 },
          { x: 2000, y: 0 },
          { x: 2000, y: 2000 },
          { x: 0, y: 2000 },
        ]),
      ],
      { openings: [opening('opening:o1', { x: 1000, y: 0 })] },
    )

  it('returns the opening id when the click is on an opening that sits on its host wall', () => {
    expect(hitTest(openingOnWallScene(), { x: 1000, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'opening:o1',
    )
  })

  it('returns the wall id when the click is on the host wall but off every opening', () => {
    expect(hitTest(openingOnWallScene(), { x: 100, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'wall:host',
    )
  })

  it('falls back to the containing room when no wall or opening is in range', () => {
    expect(hitTest(openingOnWallScene(), { x: 1000, y: 1500 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'room:a',
    )
  })
})

describe('dimensionBounds', () => {
  it('spans the dimension endpoints', () => {
    const node = dimension('dimension:d1', { x: 0, y: 0 }, { x: 1000, y: 0 })

    expect(dimensionBounds(node)).toEqual({ min: { x: 0, y: 0 }, max: { x: 1000, y: 0 } })
  })
})

describe('hitTestDimensions', () => {
  it('returns the id of a dimension whose line lies within tolerance of the point', () => {
    const dimensions = [dimension('dimension:d1', { x: 0, y: 0 }, { x: 1000, y: 0 })]

    expect(hitTestDimensions(dimensions, { x: 500, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'dimension:d1',
    )
  })

  it('returns null when the point is beyond the tolerance of every dimension line', () => {
    const dimensions = [dimension('dimension:d1', { x: 0, y: 0 }, { x: 1000, y: 0 })]

    expect(hitTestDimensions(dimensions, { x: 500, y: 5000 }, DEFAULT_HIT_TOLERANCE_MM)).toBeNull()
  })
})

describe('hitTest dimension priority', () => {
  const wallRoomAndDimensionScene = (): SceneGraph =>
    scene(
      [wall('wall:edge', { x: 0, y: 0 }, { x: 4000, y: 0 })],
      [
        room('room:a', [
          { x: 0, y: 0 },
          { x: 4000, y: 0 },
          { x: 4000, y: 4000 },
          { x: 0, y: 4000 },
        ]),
      ],
      { dimensions: [dimension('dimension:d1', { x: 0, y: 2000 }, { x: 4000, y: 2000 })] },
    )

  it('returns the dimension id when the click is on the dimension line away from the wall', () => {
    expect(
      hitTest(wallRoomAndDimensionScene(), { x: 2000, y: 2000 }, DEFAULT_HIT_TOLERANCE_MM),
    ).toBe('dimension:d1')
  })

  it('falls back to what is beneath a dimension when the dimensions overlay is hidden', () => {
    expect(
      hitTest(wallRoomAndDimensionScene(), { x: 2000, y: 2000 }, DEFAULT_HIT_TOLERANCE_MM, {
        dimensionsVisible: false,
      }),
    ).toBe('room:a')
  })

  it('prefers the wall over a dimension when the click is on the wall', () => {
    expect(hitTest(wallRoomAndDimensionScene(), { x: 2000, y: 0 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'wall:edge',
    )
  })

  it('falls back to the containing room when no wall, opening, or dimension is in range', () => {
    expect(
      hitTest(wallRoomAndDimensionScene(), { x: 2000, y: 1000 }, DEFAULT_HIT_TOLERANCE_MM),
    ).toBe('room:a')
  })
})

// A run 1000 mm across by 3000 mm long whose base sits on the wall along y = 0,
// so the footprint spans x 1000..2000 and y 0..3000 inside the room.
function stairNode(id: string): StairSceneNode {
  return {
    id,
    kind: 'stair',
    floorId: 'g',
    wellFloorId: 'upper',
    runType: 'straight',
    position: { x: 1000, y: 0 },
    width: 1000,
    length: 3000,
    rotation: 0,
  }
}

describe('hitTest stair priority', () => {
  const stairInRoomScene = (): SceneGraph =>
    scene(
      [wall('wall:edge', { x: 0, y: 0 }, { x: 4000, y: 0 })],
      [
        room('room:a', [
          { x: 0, y: 0 },
          { x: 4000, y: 0 },
          { x: 4000, y: 4000 },
          { x: 0, y: 4000 },
        ]),
      ],
      { stairs: [stairNode('stair:s1')] },
    )

  it('returns the stair id when the click lands on a stair drawn over a room', () => {
    expect(hitTest(stairInRoomScene(), { x: 1500, y: 2000 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'stair:s1',
    )
  })

  it('prefers the wall over a stair where the run meets the wall it lands on', () => {
    expect(hitTest(stairInRoomScene(), { x: 1500, y: 50 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'wall:edge',
    )
  })

  it('falls back to the containing room when the click misses the stair footprint', () => {
    expect(hitTest(stairInRoomScene(), { x: 3000, y: 2000 }, DEFAULT_HIT_TOLERANCE_MM)).toBe(
      'room:a',
    )
  })
})

