import { describe, expect, it } from 'vitest'
import {
  DAYLIGHT_REFERENCE_INSTANT,
  DAYLIGHT_REFERENCE_PLACE,
  referenceLightingInput,
} from './daylight-reference'
import { solarPosition } from './solar-position'

// The reference place and instant are the fixed observation that the daylight calibration is
// anchored to: the March equinox, mid-morning, at a site the sun stands about 45 degrees over.
// The exact height comes from solarPosition, never from a rounded 45.

const REFERENCE_SUN_HEIGHT_DEGREES = 44.9877
const REFERENCE_SUN_HEIGHT_TOLERANCE_DEGREES = 1e-4
const DEGREES_PER_RADIAN = 180 / Math.PI

describe('the daylight reference', () => {
  it('sits at latitude 40 and longitude 1.86 on 2026-03-20 at 630 minutes after midnight', () => {
    expect(DAYLIGHT_REFERENCE_PLACE).toEqual({ latitude: 40, longitude: 1.86 })
    expect(DAYLIGHT_REFERENCE_INSTANT).toEqual({ date: '2026-03-20', minutesSinceMidnight: 630 })
  })

  it('builds a lighting input at that place and instant with no offset, no north bearing, and a clear sky', () => {
    expect(referenceLightingInput()).toEqual({
      latLong: DAYLIGHT_REFERENCE_PLACE,
      observedAt: DAYLIGHT_REFERENCE_INSTANT,
      utcOffsetMinutes: 0,
      northBearing: 0,
      cloudCover: 0,
    })
  })

  it('puts the sun 44.9877 degrees above the horizon', () => {
    const input = referenceLightingInput()
    const { altitude } = solarPosition({
      latitude: input.latLong.latitude,
      longitude: input.latLong.longitude,
      observedAt: input.observedAt,
      utcOffsetMinutes: input.utcOffsetMinutes,
    })

    expect(Math.abs(altitude * DEGREES_PER_RADIAN - REFERENCE_SUN_HEIGHT_DEGREES)).toBeLessThan(
      REFERENCE_SUN_HEIGHT_TOLERANCE_DEGREES,
    )
  })
})

core/migrations/schema/add-site-grade-el.source:
import { describe, expect, it } from 'vitest'
import type { ProjectShape } from '../../index'
import { addSiteGradeElevationMigration } from './add-site-grade-elevation'

const VERSION_TWELVE = 12

interface SiteShape {
  northBearing?: number
  gradeElevation?: number
}

interface DocumentShape {
  meta?: { schemaVersion?: number }
  site?: SiteShape
}

/**
 * Builds a version-12 project document whose site predates the `gradeElevation`
 * field. Returned as a plain `ProjectShape` so the migration is exercised
 * structurally, exactly as a loaded-from-disk version-12 document would arrive.
 */
function makeVersionTwelveDocument(): ProjectShape {
  return {
    meta: {
      name: 'P',
      units: 'imperial',
      period: 'victorian',
      schemaVersion: VERSION_TWELVE,
      appVersion: '0.1.0',
      registryVersions: {},
    },
    floors: [],
    site: { northBearing: 0 },
  } as ProjectShape
}

function asDocument(project: ProjectShape): DocumentShape {
  return project as unknown as DocumentShape
}

describe('add-site-grade-elevation schema migration', () => {
  it('starts its forward step from schema version 12', () => {
    expect(addSiteGradeElevationMigration.from).toBe(VERSION_TWELVE)
  })

  it('leaves an existing site unchanged (an optional field needs no backfill)', () => {
    const migrated = addSiteGradeElevationMigration.migrate(makeVersionTwelveDocument())

    expect(asDocument(migrated).site?.gradeElevation).toBeUndefined()
  })

  it('does not set meta.schemaVersion inside the migration step itself', () => {
    const migrated = addSiteGradeElevationMigration.migrate(makeVersionTwelveDocument())

    expect(asDocument(migrated).meta?.schemaVersion).toBe(VERSION_TWELVE)
  })
})

