import { describe, it, expect } from 'vitest'
import {
  advanceWallTool,
  backspaceWallTool,
  cancelWallTool,
  finishWallTool,
  wallGhostSegments,
  wallPreviewSegment,
  IDLE_WALL_TOOL,
} from './wall-tool'
import { ADD_WALL, type AddWallParams, type Command } from '../../core'

const p = (x: number, y: number) => ({ x, y })
const wallOf = (command: Command | undefined) => (command as Command<AddWallParams>).params.wall

describe('advanceWallTool', () => {
  it('anchors the first corner without emitting a command', () => {
    const result = advanceWallTool(IDLE_WALL_TOOL, p(100, 100), 'g')

    expect(result.state).toEqual({ phase: 'drawing', vertices: [p(100, 100)] })
    expect(result.commands).toBeUndefined()
  })

  it('commits one wall as each further corner is placed and keeps drawing', () => {
    const start = advanceWallTool(IDLE_WALL_TOOL, p(100, 100), 'g').state
    const placed = advanceWallTool(start, p(500, 100), 'g')

    expect(placed.state).toEqual({ phase: 'drawing', vertices: [p(100, 100), p(500, 100)] })
    const commands = placed.commands ?? []
    expect(commands).toHaveLength(1)
    expect(wallOf(commands[0]).start).toEqual(p(100, 100))
    expect(wallOf(commands[0]).end).toEqual(p(500, 100))
  })

  it('ends the run on a click back on the active corner without committing', () => {
    const start = advanceWallTool(IDLE_WALL_TOOL, p(100, 100), 'g').state
    const drawn = advanceWallTool(start, p(500, 100), 'g').state
    const ended = advanceWallTool(drawn, p(500, 100), 'g')

    expect(ended.state).toEqual(IDLE_WALL_TOOL)
    expect(ended.commands).toBeUndefined()
  })

  it('closes the loop on a click on the first corner with a single closing segment', () => {
    let state = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state
    state = advanceWallTool(state, p(400, 0), 'g').state
    state = advanceWallTool(state, p(400, 400), 'g').state
    const closed = advanceWallTool(state, p(0, 0), 'g')

    expect(closed.state).toEqual(IDLE_WALL_TOOL)
    const commands = closed.commands ?? []
    expect(commands).toHaveLength(1)
    expect(commands[0]?.type).toBe(ADD_WALL)
    expect(wallOf(commands[0]).start).toEqual(p(400, 400))
    expect(wallOf(commands[0]).end).toEqual(p(0, 0))
  })
})

describe('finishWallTool', () => {
  it('ends a run without a command because each segment is already committed', () => {
    let state = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state
    state = advanceWallTool(state, p(400, 0), 'g').state
    const finished = finishWallTool(state)

    expect(finished.state).toEqual(IDLE_WALL_TOOL)
    expect(finished.commands).toBeUndefined()
  })

  it('is inert on idle', () => {
    expect(finishWallTool(IDLE_WALL_TOOL)).toEqual({ state: IDLE_WALL_TOOL })
  })
})

describe('backspaceWallTool', () => {
  it('steps the draw-from corner back while two or more remain', () => {
    let state = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state
    state = advanceWallTool(state, p(400, 0), 'g').state
    state = advanceWallTool(state, p(400, 400), 'g').state

    expect(backspaceWallTool(state)).toEqual({ phase: 'drawing', vertices: [p(0, 0), p(400, 0)] })
  })

  it('returns to idle when the last remaining corner is removed', () => {
    const one = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state

    expect(backspaceWallTool(one)).toEqual(IDLE_WALL_TOOL)
  })

  it('is idempotent on idle', () => {
    expect(backspaceWallTool(IDLE_WALL_TOOL)).toEqual(IDLE_WALL_TOOL)
  })
})

describe('cancelWallTool', () => {
  it('abandons a run to idle', () => {
    const one = advanceWallTool(IDLE_WALL_TOOL, p(1, 2), 'g').state

    expect(cancelWallTool(one)).toEqual(IDLE_WALL_TOOL)
  })

  it('is idempotent on idle', () => {
    expect(cancelWallTool(IDLE_WALL_TOOL)).toEqual(IDLE_WALL_TOOL)
  })
})

describe('wallPreviewSegment', () => {
  it('previews from the last corner to the cursor while drawing', () => {
    let state = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state
    state = advanceWallTool(state, p(400, 0), 'g').state

    expect(wallPreviewSegment(state, p(400, 240))).toEqual({ start: p(400, 0), end: p(400, 240) })
    expect(wallPreviewSegment(IDLE_WALL_TOOL, p(400, 240))).toBeUndefined()
  })
})

describe('wallGhostSegments', () => {
  it('is empty because the placed segments render as committed walls', () => {
    let state = advanceWallTool(IDLE_WALL_TOOL, p(0, 0), 'g').state
    state = advanceWallTool(state, p(400, 0), 'g').state
    state = advanceWallTool(state, p(400, 400), 'g').state

    expect(wallGhostSegments(state)).toEqual([])
    expect(wallGhostSegments(IDLE_WALL_TOOL)).toEqual([])
  })
})

core/geometry/wall-face-junction.test.ts.source:
import { describe, expect, it } from 'vitest'

import type { Point, Wall } from '../model/types'
import { wallFootprints } from '../topology/wall-footprint'
import { buildWallGraph } from '../topology/wall-graph'
import { distance } from './point'
import { segmentIntersection } from './segment'
import { dot, subtract } from './vector'
import type { WallFaceGap, WallFaceRun, WallFaceStretch } from './wall-face'
import { wallFaceGeometry } from './wall-face'

/** A plastered two-by-four partition, the wall an old house is mostly built from. */
const THICKNESS_MM = 114
const HALF_MM = THICKNESS_MM / 2
const ARM_LENGTH_MM = 1000
const COORDINATE_DIGITS = 6
const COINCIDENT_TOLERANCE_MM = 1e-6

/**
 * How far a 45 degree miter reaches along the run axis: half a thickness times
 * cot(22.5 degrees), and cot(22.5 degrees) is 1 + sqrt(2). On the acute side the
 * miter reaches backward, pulling that face corner short of the run's own end.
 */
const MITER_REACH_MM = HALF_MM * (1 + Math.SQRT2)

/** A doorway hard against the acute corner, the way old houses routinely place one. */
const CORNER_DOORWAY: WallFaceGap = { from: 900, to: 950 }

/** A doorway in the clear middle of the same run, well short of either miter. */
const MID_RUN_DOORWAY: WallFaceGap = { from: 200, to: 300 }

const required = <T>(value: T | undefined, what: string): T => {
  if (value === undefined) throw new Error(`expected ${what}`)
  return value
}

const wallOf = (id: string, start: Point, end: Point): Wall => ({
  id,
  start,
  end,
  thickness: THICKNESS_MM,
})

/**
 * The east arm of two walls meeting at 45 degrees, mitred by the same graph and
 * footprint helpers the plan renderer uses, so the corners fed in here are the
 * ones production geometry produces.
 */
const acuteCornerRun = (gaps: readonly WallFaceGap[]): WallFaceRun => {
  const meet: Point = { x: ARM_LENGTH_MM, y: 0 }
  const graph = buildWallGraph([
    wallOf('east', { x: 0, y: 0 }, meet),
    wallOf('spur', meet, {
      x: meet.x - ARM_LENGTH_MM * Math.SQRT1_2,
      y: ARM_LENGTH_MM * Math.SQRT1_2,
    }),
  ])
  const footprints = wallFootprints(
    graph,
    graph.edges.map(() => THICKNESS_MM),
  )
  const east = required(graph.edges[0], 'the east edge')
  return {
    start: required(graph.vertices[east.a], 'a start vertex'),
    end: required(graph.vertices[east.b], 'an end vertex'),
    corners: required(footprints[0], 'the east footprint'),
    gaps,
  }
}

/** The two non-adjacent edges of a four-corner ring, as pairs of corner indexes. */
const OPPOSED_EDGES = [
  [0, 1, 2, 3],
  [1, 2, 3, 0],
] as const

const ringEdge = (ring: readonly Point[], from: number, to: number): [Point, Point] => [
  required(ring[from], 'a poche corner'),
  required(ring[to], 'a poche corner'),
]

/**
 * A simple ring does not cross itself. Adjacent edges always touch at the corner
 * they share, so only the two non-adjacent pairs can cross, and a crossing there
 * is a bow tie: the fill then paints the wrong region.
 */
const expectSimplePoche = ({ poche }: WallFaceStretch): void => {
  for (const [first, second, third, fourth] of OPPOSED_EDGES) {
    const edge = ringEdge(poche, first, second)
    const opposed = ringEdge(poche, third, fourth)
    // A face cut back onto its own corner collapses the ring to a triangle. The
    // collapsed edge shares a corner with its opposite, which touches rather
    // than crosses, so it is not a bow tie and does not belong in this check.
    if (distance(...edge) < COINCIDENT_TOLERANCE_MM) continue
    if (distance(...opposed) < COINCIDENT_TOLERANCE_MM) continue
    expect(segmentIntersection(...edge, ...opposed)).toBeNull()
  }
}

/**
 * Positive when both face lines of a stretch advance the same way along the run
 * axis. Negative means one face runs backward while the other runs forward, the
 * signature of a bow tie.
 */
const faceAgreement = ({ plusFace, minusFace }: WallFaceStretch): number =>
  dot(subtract(plusFace[1], plusFace[0]), subtract(minusFace[1], minusFace[0]))

const expectStretchIsSimple = (stretch: WallFaceStretch): void => {
  expect(faceAgreement(stretch)).toBeGreaterThanOrEqual(0)
  expectSimplePoche(stretch)
}

describe('wallFaceGeometry where an opening reaches a mitred corner', () => {
  it('keeps every poche ring simple when a doorway jamb sits past the pulled-back miter', () => {
    const run = acuteCornerRun([CORNER_DOORWAY])
    // The acute miter pulls the plus corner back short of the run's own end at
    // x = 1000, so the near jamb at x = 900 already lies beyond that face.
    expect(run.corners.bPlus.x).toBeCloseTo(ARM_LENGTH_MM - MITER_REACH_MM, COORDINATE_DIGITS)
    expect(run.corners.bPlus.x).toBeLessThan(CORNER_DOORWAY.from)

    for (const stretch of wallFaceGeometry(run)) expectStretchIsSimple(stretch)
  })

  it('still cuts two simple stretches for a doorway in the clear middle of the run', () => {
    const stretches = wallFaceGeometry(acuteCornerRun([MID_RUN_DOORWAY]))

    expect(stretches).toHaveLength(2)
    for (const stretch of stretches) expectStretchIsSimple(stretch)
  })
})

core/registries/element-types.test.ts.source:
import { describe, expect, it } from 'vitest'
import { getEntry } from './registry'
import { ELEMENT_TYPE_REGISTRY_VERSION, builtinElementTypes } from './element-types'

describe('builtin element types', () => {
  it('seeds a straight wall and a single-swing door', () => {
    expect(getEntry(builtinElementTypes, 'straight-wall')?.category).toBe('wall')
    expect(getEntry(builtinElementTypes, 'single-swing-door')?.category).toBe('opening')
    expect(builtinElementTypes.version).toBe(ELEMENT_TYPE_REGISTRY_VERSION)
  })

  it('wires each entry to its 2D symbol and 3D builder', () => {
    const wall = getEntry(builtinElementTypes, 'straight-wall')
    expect(wall?.plan2D.symbol).toBe('wall-line')
    expect(wall?.scene3D.builder).toBe('extruded-wall')

    const door = getEntry(builtinElementTypes, 'single-swing-door')
    expect(door?.plan2D.symbol).toBe('door-swing')
    expect(door?.scene3D.builder).toBe('door-frame')
  })

  it('exposes the opening type parameters for each registered opening', () => {
    const cases = [
      {
        id: 'single-swing-door',
        symbol: 'door-swing',
        opening: { family: 'swing', defaultWidth: 813, defaultHeight: 2032, defaultSillHeight: 0 },
      },
      {
        id: 'double-swing-door',
        symbol: 'door-swing',
        opening: { family: 'swing', double: true, defaultWidth: 1626 },
      },
      { id: 'pocket-door', symbol: 'door-slide', opening: { family: 'slide' } },
      { id: 'bifold-door', symbol: 'door-fold', opening: { family: 'fold' } },
      { id: 'pivot-door', symbol: 'door-pivot', opening: { family: 'pivot' } },
      { id: 'cased-opening', symbol: 'cased-opening', opening: { family: 'cased' } },
      {
        id: 'double-hung-window',
        symbol: 'window-fixed',
        opening: {
          family: 'window-hung',
          defaultWidth: 900,
          defaultHeight: 1200,
          defaultSillHeight: 900,
        },
      },
      {
        id: 'casement-window',
        symbol: 'window-crank',
        opening: { family: 'window-crank', hingeEdge: 'jamb' },
      },
    ] as const

    for (const expected of cases) {
      const entry = getEntry(builtinElementTypes, expected.id)
      expect(entry?.category).toBe('opening')
      expect(entry?.plan2D.symbol).toBe(expected.symbol)
      expect(entry?.opening).toMatchObject(expected.opening)
    }

    expect(ELEMENT_TYPE_REGISTRY_VERSION).toBe(7)
  })

  it('marks every conventional opening element type with a rectangular void contour', () => {
    const curvedHeads = new Set(['arched-window', 'round-top-window', 'lancet-window'])
    const openings = Object.values(builtinElementTypes.entries).filter(
      (entry) => entry.category === 'opening',
    )
    expect(openings.length).toBeGreaterThan(0)

    for (const entry of openings) {
      if (curvedHeads.has(entry.id)) continue
      expect(entry.scene3D.voidContour).toBe('rectangular')
    }
  })

  it('registers curved-head window types carrying their head shape as the void contour', () => {
    const cases = [
      { id: 'arched-window', voidContour: 'arched' },
      { id: 'round-top-window', voidContour: 'round' },
      { id: 'lancet-window', voidContour: 'lancet' },
    ] as const

    for (const { id, voidContour } of cases) {
      const entry = getEntry(builtinElementTypes, id)
      expect(entry?.category).toBe('opening')
      expect(entry?.plan2D.symbol).toBe('window-fixed')
      expect(entry?.scene3D.voidContour).toBe(voidContour)
      expect(entry?.scene3D.fill).toBe('window-sash')
    }
  })

  it('names the three-dimensional fill kind for each opening family', () => {
    for (const id of ['single-swing-door', 'double-swing-door', 'pocket-door'] as const) {
      expect(getEntry(builtinElementTypes, id)?.scene3D.fill).toBe('door-leaf')
    }

    for (const id of ['double-hung-window', 'single-hung-window'] as const) {
      expect(getEntry(builtinElementTypes, id)?.scene3D.fill).toBe('window-sash-hung')
    }

    for (const id of ['casement-window', 'picture-window'] as const) {
      expect(getEntry(builtinElementTypes, id)?.scene3D.fill).toBe('window-sash')
    }

    expect(getEntry(builtinElementTypes, 'cased-opening')?.scene3D.fill).toBeUndefined()
  })

  it('leaves the wall and stair types without a fill kind', () => {
    expect(getEntry(builtinElementTypes, 'straight-wall')?.scene3D.fill).toBeUndefined()
    expect(getEntry(builtinElementTypes, 'straight-stair')?.scene3D.fill).toBeUndefined()
  })

  it('leaves the wall and stair types without a void contour', () => {
    const wall = getEntry(builtinElementTypes, 'straight-wall')
    expect(wall?.category).toBe('wall')
    expect(wall?.scene3D.voidContour).toBeUndefined()

    const stair = getEntry(builtinElementTypes, 'straight-stair')
    expect(stair?.category).toBe('stair')
    expect(stair?.scene3D.voidContour).toBeUndefined()
  })
})

describe('operable window families', () => {
  it('splits the hung and sliding windows into their own motion families', () => {
    const families: ReadonlyArray<readonly [string, string]> = [
      ['double-hung-window', 'window-hung'],
      ['single-hung-window', 'window-hung'],
      ['sliding-window', 'window-slide'],
    ]
    for (const [id, family] of families) {
      expect(getEntry(builtinElementTypes, id)?.opening?.family).toBe(family)
    }
  })

  it('tags each crank window with its hinge edge', () => {
    const hingeEdges: ReadonlyArray<readonly [string, string]> = [
      ['casement-window', 'jamb'],
      ['awning-window', 'head'],
      ['hopper-window', 'sill'],
    ]
    for (const [id, hingeEdge] of hingeEdges) {
      const entry = getEntry(builtinElementTypes, id)
      expect(entry?.opening?.family).toBe('window-crank')
      expect(entry?.opening?.hingeEdge).toBe(hingeEdge)
    }
  })

  it('keeps the truly fixed windows in the window-fixed family', () => {
    const fixed = [
      'picture-window',
      'transom-window',
      'sidelight-window',
      'arched-window',
      'round-top-window',
      'lancet-window',
    ]
    for (const id of fixed) {
      expect(getEntry(builtinElementTypes, id)?.opening?.family).toBe('window-fixed')
    }
  })
})

describe('stair element type', () => {
  it('registers a straight stair in the stair category with a stair plan symbol', () => {
    const stair = getEntry(builtinElementTypes, 'straight-stair')
    expect(stair?.category).toBe('stair')
    expect(stair?.plan2D.symbol).toBe('stair-run')
  })
})

