import { describe, expect, it } from 'vitest'
import {
  patternTreatment,
  solidTreatment,
  surfaceKey,
  surfaceTintHex,
  type SurfaceRef,
} from './paint'
import { colorFromHex } from '../color/color'

const leftFace: SurfaceRef = { kind: 'wall-face', wallId: 'wall-1', side: 'left' }
const rightFace: SurfaceRef = { kind: 'wall-face', wallId: 'wall-1', side: 'right' }
const floor: SurfaceRef = { kind: 'floor', floorId: 'floor-1' }
const ceiling: SurfaceRef = { kind: 'ceiling', floorId: 'floor-1' }

describe('surfaceKey', () => {
  it('is stable for structurally equal refs', () => {
    expect(surfaceKey({ kind: 'floor', floorId: 'floor-1' })).toBe(surfaceKey(floor))
  })

  it('distinguishes the two faces of one wall', () => {
    expect(surfaceKey(leftFace)).not.toBe(surfaceKey(rightFace))
  })

  it('distinguishes a floor from a ceiling on the same floor', () => {
    expect(surfaceKey(floor)).not.toBe(surfaceKey(ceiling))
  })

  it('keys an unsubdivided wall face without a region segment', () => {
    expect(surfaceKey(leftFace)).toBe('wall-face:wall-1:left')
  })

  it('appends the region to the key of a subdivided wall face', () => {
    const fieldRegion: SurfaceRef = {
      kind: 'wall-face',
      wallId: 'wall-1',
      side: 'left',
      region: 'field',
    }
    expect(surfaceKey(fieldRegion)).toBe('wall-face:wall-1:left:field')
  })

  it('distinguishes sub-areas of one wall face by region', () => {
    const wainscot: SurfaceRef = {
      kind: 'wall-face',
      wallId: 'wall-1',
      side: 'left',
      region: 'wainscot',
    }
    const field: SurfaceRef = {
      kind: 'wall-face',
      wallId: 'wall-1',
      side: 'left',
      region: 'field',
    }
    expect(surfaceKey(wainscot)).not.toBe(surfaceKey(field))
    expect(surfaceKey(wainscot)).not.toBe(surfaceKey(leftFace))
    expect(surfaceKey(field)).not.toBe(surfaceKey(leftFace))
  })
})

describe('solidTreatment', () => {
  it('builds a solid surface treatment from a color and finish', () => {
    const color = colorFromHex('#9aa583')
    expect(solidTreatment(color, 'matte')).toEqual({
      kind: 'solid',
      color: colorFromHex('#9aa583'),
      finishId: 'matte',
    })
  })
})

describe('patternTreatment', () => {
  it('builds a pattern surface treatment from a pattern id, scale, and colors', () => {
    const oak = colorFromHex('#8a6240')
    const grain = colorFromHex('#6f4d31')
    expect(patternTreatment('plank', 150, [oak, grain])).toEqual({
      kind: 'pattern',
      patternId: 'plank',
      scale: 150,
      colors: [colorFromHex('#8a6240'), colorFromHex('#6f4d31')],
    })
  })
})

describe('surfaceTintHex', () => {
  it('uses the color of a solid treatment', () => {
    expect(surfaceTintHex(solidTreatment(colorFromHex('#9aa583'), 'matte'))).toBe(
      colorFromHex('#9aa583').srgbHex,
    )
  })

  it('uses the base (first) color of a pattern treatment', () => {
    const base = colorFromHex('#8a6240')
    const grain = colorFromHex('#6f4d31')
    expect(surfaceTintHex(patternTreatment('plank', 150, [base, grain]))).toBe(base.srgbHex)
  })
})

tests/format/known-keys-variants.test.ts.source:
import { describe, expect, it } from 'vitest'
import { KNOWN_KEYS, type KnownValue } from '../../core'
import { buildKnownKeys } from '../../scripts/schema/build-known-keys.mjs'

type KnownUnion = Extract<KnownValue, { kind: 'union' }>

/** Every union value found anywhere in the table, however deeply it is nested. */
function unionValuesIn(node: unknown): KnownUnion[] {
  if (Array.isArray(node)) return node.flatMap(unionValuesIn)
  if (node === null || typeof node !== 'object') return []
  const found = Object.values(node).flatMap(unionValuesIn)
  return (node as { kind?: unknown }).kind === 'union' ? [node as KnownUnion, ...found] : found
}

const UNION_NAME = 'Shape'

/** A tagged union of two object variants whose tag constant is the given value, behind `Shape`. */
function schemaWithTagConstants(first: unknown, second: unknown) {
  const variant = (tagConstant: unknown) => ({
    type: 'object',
    properties: { kind: { const: tagConstant }, size: { type: 'number' } },
    required: ['kind', 'size'],
    additionalProperties: false,
  })
  return {
    $schema: 'http://json-schema.org/draft-07/schema#',
    type: 'object',
    properties: { value: { $ref: `#/definitions/${UNION_NAME}` } },
    required: ['value'],
    additionalProperties: false,
    definitions: { [UNION_NAME]: { anyOf: [variant(first), variant(second)] } },
  }
}

describe('each union in the generated table of known keys', () => {
  const unions = unionValuesIn(KNOWN_KEYS)

  it('is found in the real table, so the checks below have something to check', () => {
    expect(unions.length).toBeGreaterThan(0)
  })

  it('lists its variants with the tag value and the entry name of each', () => {
    expect(KNOWN_KEYS.Project.keys.paint).toEqual({
      kind: 'map',
      value: {
        kind: 'union',
        tag: 'kind',
        variants: [
          { value: 'solid', type: 'SurfaceTreatment.solid' },
          { value: 'pattern', type: 'SurfaceTreatment.pattern' },
        ],
      },
    })
  })

  it('carries no list of type names beside its variants', () => {
    for (const union of unions) {
      expect(union).not.toHaveProperty('types')
      expect(Array.isArray(union.variants)).toBe(true)
    }
  })

  it('names, for each variant, an entry of the table that has the tag key', () => {
    for (const union of unions) {
      for (const { type } of union.variants) {
        expect(Object.keys(KNOWN_KEYS), type).toContain(type)
        expect(Object.keys(KNOWN_KEYS[type]?.keys ?? {}), type).toContain(union.tag)
      }
    }
  })

  it('gives each variant its own tag value', () => {
    for (const union of unions) {
      const values = union.variants.map(({ value }) => value)
      expect(new Set(values).size).toBe(values.length)
    }
  })
})

describe('the table of known keys, for a variant whose tag constant is not a string', () => {
  it('refuses the schema with an error that names the union', () => {
    const schema = schemaWithTagConstants(1, 2)
    expect(() => buildKnownKeys(schema)).toThrow(/Shape.*string|string.*Shape/)
  })

  it('refuses the schema when only one of the variants has such a constant', () => {
    const schema = schemaWithTagConstants('circle', null)
    expect(() => buildKnownKeys(schema)).toThrow(/Shape.*string|string.*Shape/)
  })
})

