import { describe, expect, it } from 'vitest'
import { distance, rotatePoint, translatePoint } from './point'

describe('distance', () => {
  it('returns the Euclidean distance between two points in millimeter plan space', () => {
    expect(distance({ x: 0, y: 0 }, { x: 3000, y: 4000 })).toBe(5000)
  })

  it('returns zero for two coincident points', () => {
    expect(distance({ x: 10, y: 10 }, { x: 10, y: 10 })).toBe(0)
  })
})

describe('translatePoint', () => {
  it('offsets the point by the delta components', () => {
    expect(translatePoint({ x: 10, y: 20 }, { x: 3, y: -4 })).toEqual({ x: 13, y: 16 })
  })
})

describe('rotatePoint', () => {
  it('rotates counter-clockwise about the origin in plan space where y increases upward', () => {
    const rotated = rotatePoint({ x: 100, y: 0 }, { x: 0, y: 0 }, Math.PI / 2)
    expect(rotated.x).toBeCloseTo(0)
    expect(rotated.y).toBeCloseTo(100)
  })

  it('returns the original coordinates for a zero-radian rotation', () => {
    const point = { x: 42, y: -17 }
    const rotated = rotatePoint(point, { x: 5, y: 9 }, 0)
    expect(rotated.x).toBeCloseTo(point.x)
    expect(rotated.y).toBeCloseTo(point.y)
  })

  it('rotates in pivot-relative coordinates about a non-origin pivot', () => {
    const rotated = rotatePoint({ x: 110, y: 0 }, { x: 10, y: 0 }, Math.PI / 2)
    expect(rotated.x).toBeCloseTo(10)
    expect(rotated.y).toBeCloseTo(100)
  })
})

editor/plan/scale-bar.test.ts.source:
import { describe, it, expect } from 'vitest'
import {
  DEFAULT_IMPERIAL_PREFERENCES,
  DEFAULT_METRIC_PREFERENCES,
  feetToMillimeters,
} from '../../core'
import { scaleBar } from './scale-bar'

describe('scaleBar', () => {
  it('fills the target width when a round meter count fits it exactly', () => {
    // 100 px at 0.1 px/mm spans 1000 mm = 1 m, a round value that fits exactly.
    const bar = scaleBar(0.1, DEFAULT_METRIC_PREFERENCES, 100)

    expect(bar.lengthPx).toBe(100)
    expect(bar.label).toBe('1.00 m')
  })

  it('rounds down to the largest 1-2-5 value not exceeding the target width', () => {
    // 250 px at 0.1 px/mm spans 2.5 m; the nicest value that still fits is 2 m.
    const bar = scaleBar(0.1, DEFAULT_METRIC_PREFERENCES, 250)

    expect(bar.lengthPx).toBe(200)
    expect(bar.label).toBe('2.00 m')
  })

  it('drops to a sub-meter form when no whole meter fits', () => {
    // 40 px at 0.1 px/mm spans 0.4 m; the nicest value that fits is 0.2 m.
    const bar = scaleBar(0.1, DEFAULT_METRIC_PREFERENCES, 40)

    expect(bar.lengthPx).toBeCloseTo(20, 6)
    expect(bar.label).toBe('20.0 cm')
  })

  it('measures the bar in whole feet for an imperial project', () => {
    // 100 px at 0.1 px/mm spans about 3.28 ft; the nicest value that fits is 2 ft.
    const bar = scaleBar(0.1, DEFAULT_IMPERIAL_PREFERENCES, 100)

    expect(bar.lengthPx).toBeCloseTo(feetToMillimeters(2) * 0.1, 6)
    expect(bar.label).toBe("2'")
  })
})

core/units/length-bounds.test.ts.source:
import { describe, expect, it } from 'vitest'
import {
  assertPositiveLength,
  InvalidLengthError,
  MAX_LENGTH_MM,
  MIN_POSITIVE_LENGTH_MM,
} from './length-bounds'

describe('assertPositiveLength', () => {
  it('pins the accepted millimetre bounds', () => {
    expect(MIN_POSITIVE_LENGTH_MM).toBe(1)
    expect(MAX_LENGTH_MM).toBe(100_000)
  })

  it('rejects out-of-range dimensions with an InvalidLengthError', () => {
    expect(() => assertPositiveLength(0, 'Width')).toThrow(InvalidLengthError)
    expect(() => assertPositiveLength(-1, 'Width')).toThrow(InvalidLengthError)
    expect(() => assertPositiveLength(Number.NaN, 'Width')).toThrow(InvalidLengthError)
    expect(() => assertPositiveLength(MAX_LENGTH_MM + 1, 'Width')).toThrow(InvalidLengthError)
  })

  it('accepts a dimension at each edge of the in-range interval', () => {
    expect(() => assertPositiveLength(MIN_POSITIVE_LENGTH_MM, 'Width')).not.toThrow()
    expect(() => assertPositiveLength(MAX_LENGTH_MM, 'Width')).not.toThrow()
  })

  it('carries the label and offending value on the thrown error', () => {
    let caught: unknown
    try {
      assertPositiveLength(-5, 'Thickness')
    } catch (error) {
      caught = error
    }

    expect(caught).toBeInstanceOf(InvalidLengthError)
    const invalid = caught as InvalidLengthError
    expect(invalid.label).toBe('Thickness')
    expect(invalid.valueMm).toBe(-5)
    expect(invalid.message).toContain('Thickness')
    expect(invalid.message.toLowerCase()).toContain('positive length')
  })
})

editor/plan/underlay-trace-points.test.t.source:
import { describe, expect, it } from 'vitest'

import type { SceneGraph, UnderlaySceneNode } from '../../core'

import { floorUnderlayTracePoints, underlayTracePoints } from './underlay-trace-points'

const node: UnderlaySceneNode = {
  id: 'underlay:u1',
  kind: 'underlay',
  floorId: 'f1',
  source: { kind: 'raster', image: { scope: 'project', contentHash: 'abc' } },
  width: 100,
  height: 50,
  placement: { offset: { x: 1000, y: 2000 }, millimetersPerPixel: 10, rotation: 0 },
  opacity: 1,
  visible: true,
}

describe('underlayTracePoints', () => {
  it('returns the four calibrated footprint corners in plan millimeters', () => {
    const points = underlayTracePoints(node)
    // Footprint: offset (1000, 2000) is the top-left in the y-up world; the image's
    // downward pixel axis maps to downward world-y, so the height spans toward
    // DECREASING y. Size 100 * 10 by 50 * 10 = 1000 by 500, so the bottom edge is
    // at y = 2000 - 500 = 1500.
    expect(points).toHaveLength(4)
    expect(points).toContainEqual({ x: 1000, y: 2000 })
    expect(points).toContainEqual({ x: 2000, y: 2000 })
    expect(points).toContainEqual({ x: 2000, y: 1500 })
    expect(points).toContainEqual({ x: 1000, y: 1500 })
  })
})

const visibleUnderlayNode = node
const hiddenUnderlayNode: UnderlaySceneNode = {
  ...node,
  id: 'underlay:u2',
  visible: false,
}

describe('floorUnderlayTracePoints', () => {
  it('returns the footprint corners of every visible underlay when enabled', () => {
    const graph = {
      underlays: [visibleUnderlayNode, hiddenUnderlayNode],
    } as SceneGraph

    // Only the visible underlay contributes its four footprint corners.
    expect(floorUnderlayTracePoints(graph, true)).toHaveLength(4)
  })

  it('returns undefined when the trace snap is disabled', () => {
    const graph = {
      underlays: [visibleUnderlayNode, hiddenUnderlayNode],
    } as SceneGraph

    expect(floorUnderlayTracePoints(graph, false)).toBeUndefined()
  })
})

core/scene/plan-to-world.test.ts.source:
import { describe, it, expect } from 'vitest'
import { planToWorld, worldToPlan } from './plan-to-world'

describe('planToWorld', () => {
  it('maps plan x to world X and plan north (+y) to world -Z at the given height', () => {
    // The plan is rendered y-up (worldToScreen negates y), so larger plan y is
    // north. North must map to world -Z so the three-dimensional scene is not a
    // mirror image of the plan, and so it agrees with the camera-preset axis map.
    expect(planToWorld({ x: 3, y: 7 }, 2700)).toEqual({ x: 3, y: 2700, z: -7 })
  })

  it('places a point on the finished floor at world Y = 0', () => {
    expect(planToWorld({ x: -1, y: 4 }, 0)).toEqual({ x: -1, y: 0, z: -4 })
  })

  it('preserves plan orientation rather than reflecting it', () => {
    // The plan basis (east = +x, north = +y) is right-handed for a viewer looking
    // down at the y-up plan. Laid onto the ground it must stay right-handed about
    // world up (+Y): east cross north points to the sky (+Y), not the ground.
    // A reflecting map (the prior z = +y bug) points it at -Y.
    const origin = planToWorld({ x: 0, y: 0 }, 0)
    const east = planToWorld({ x: 1, y: 0 }, 0)
    const north = planToWorld({ x: 0, y: 1 }, 0)
    const e = { x: east.x - origin.x, z: east.z - origin.z }
    const n = { x: north.x - origin.x, z: north.z - origin.z }
    const crossUp = e.z * n.x - e.x * n.z // +Y component of east x north
    expect(crossUp).toBeGreaterThan(0)
  })
})

describe('worldToPlan', () => {
  it('maps a world point back to its plan point, dropping height and negating Z', () => {
    // World X is plan x, world -Z is plan north (+y), and world Y (height) is
    // discarded: worldToPlan is the ground-plane inverse of planToWorld.
    expect(worldToPlan({ x: 100, y: 2500, z: -300 })).toEqual({ x: 100, y: 300 })
  })

  it('round-trips a plan point through planToWorld at an arbitrary height', () => {
    const point = { x: 42, y: 900 }
    expect(worldToPlan(planToWorld(point, 2700))).toEqual(point)
  })

  it('round-trips a point on the floor line (plan y = 0) back to plan y = 0', () => {
    // The naive -point.y would yield world z = -0 when plan y = 0; planToWorld
    // uses 0 - point.y instead to land on a clean +0. Negating that with 0 -
    // world.z also gives +0, so the round-trip compares equal to 0.
    const onFloorLine = { x: 5, y: 0 }
    expect(worldToPlan(planToWorld(onFloorLine, 0))).toEqual(onFloorLine)
  })

  it('locks the sign both ways: negative plan y maps through positive world Z', () => {
    // A plan point south of the origin (y < 0) becomes world z > 0, and mapping
    // it back must restore the negative plan y.
    const world = planToWorld({ x: -7, y: -50 }, 1200)
    expect(world.z).toBeGreaterThan(0)
    expect(worldToPlan(world)).toEqual({ x: -7, y: -50 })
  })
})

editor/plan/ruler-label-spacing.test.ts.source:
import { describe, it, expect } from 'vitest'
import { DEFAULT_IMPERIAL_PREFERENCES, DEFAULT_METRIC_PREFERENCES, MM_PER_FOOT } from '../../core'
import { rulerLabelSpacingMm } from './ruler-label-spacing'
import { RULER_MIN_LABEL_GAP_PX } from './ruler'

// The 1-2-5 nice feet the imperial branch may land on; the spacing must be one
// of these multiplied by MM_PER_FOOT so labels read as whole feet ("0', 5', ...").
const NICE_FEET = [1, 2, 5, 10, 20, 50, 100, 200, 500]

describe('rulerLabelSpacingMm', () => {
  it('snaps imperial spacing to the smallest whole-foot 1-2-5 multiple that clears the label gap', () => {
    // minWorldMm = 60 / 0.05 = 1200 mm = 3.94 ft; smallest 1-2-5 nice feet >= 3.94 is 5 ft.
    const spacing = rulerLabelSpacingMm(DEFAULT_IMPERIAL_PREFERENCES, 0.05)

    expect(spacing).toBe(5 * MM_PER_FOOT)
    expect(Number.isInteger(spacing / MM_PER_FOOT)).toBe(true)
    expect(spacing / MM_PER_FOOT).toBe(5)
    expect(NICE_FEET).toContain(spacing / MM_PER_FOOT)
  })

  it('rolls imperial spacing up to the next nice foot count at a coarser zoom', () => {
    // minWorldMm = 60 / 0.01 = 6000 mm = 19.69 ft; smallest 1-2-5 nice feet >= 19.69 is 20 ft.
    const spacing = rulerLabelSpacingMm(DEFAULT_IMPERIAL_PREFERENCES, 0.01)

    expect(spacing).toBe(20 * MM_PER_FOOT)
    expect(Number.isInteger(spacing / MM_PER_FOOT)).toBe(true)
    expect(spacing / MM_PER_FOOT).toBe(20)
    expect(NICE_FEET).toContain(spacing / MM_PER_FOOT)
  })

  it('snaps metric spacing to the smallest 1-2-5 decade of millimetres that clears the label gap', () => {
    // minWorldMm = 60 / 0.1 = 600 mm; smallest 1-2-5 decade of mm >= 600 is 1000.
    const spacing = rulerLabelSpacingMm(DEFAULT_METRIC_PREFERENCES, 0.1)

    expect(spacing).toBe(1000)
  })

  it('keeps the on-screen label gap at least RULER_MIN_LABEL_GAP_PX wide across zoom levels', () => {
    for (const scale of [0.02, 0.05, 0.1, 0.5, 1]) {
      expect(rulerLabelSpacingMm(DEFAULT_METRIC_PREFERENCES, scale) * scale).toBeGreaterThanOrEqual(
        RULER_MIN_LABEL_GAP_PX,
      )
      expect(
        rulerLabelSpacingMm(DEFAULT_IMPERIAL_PREFERENCES, scale) * scale,
      ).toBeGreaterThanOrEqual(RULER_MIN_LABEL_GAP_PX)
    }
  })
})

