    expect(colorFromHex('#336699', 'Heritage Blue 12').originalSpec).toBe('Heritage Blue 12')
  })

  it('maps white to a near-one lightness', () => {
    expect(colorFromHex('#ffffff').oklab.L).toBeCloseTo(1, 2)
  })
})

