import { describe, expect, it } from 'vitest'
import { resolveOpeningEdge } from './opening-edge'
import type { GraphEdge, PlanarGraph } from './wall-graph'

interface OpeningInput {
  center: { x: number; y: number }
  hostWallId?: string
}

describe('resolveOpeningEdge', () => {
  it('places an opening on its single host edge at its distance from the a-vertex', () => {
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: 4000, y: 0 },
      ],
      edges: [{ a: 0, b: 1, wallId: 'w1' }],
    }
    const opening: OpeningInput = { center: { x: 1000, y: 0 }, hostWallId: 'w1' }

    const result = resolveOpeningEdge(opening, graph)

    expect(result).not.toBeNull()
    expect(result?.edge).toBe(graph.edges[0])
    expect(result?.positionAlongEdge).toBeCloseTo(1000)
  })

  it('selects the host edge whose span contains the center when the wall is split', () => {
    const firstEdge: GraphEdge = { a: 0, b: 1, wallId: 'w1' }
    const secondEdge: GraphEdge = { a: 1, b: 2, wallId: 'w1' }
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: 2000, y: 0 },
        { x: 4000, y: 0 },
      ],
      edges: [firstEdge, secondEdge],
    }
    const opening: OpeningInput = { center: { x: 3000, y: 0 }, hostWallId: 'w1' }

    const result = resolveOpeningEdge(opening, graph)

    expect(result).not.toBeNull()
    expect(result?.edge).toBe(secondEdge)
    expect(result?.edge.a).toBe(1)
    expect(result?.edge.b).toBe(2)
    expect(result?.positionAlongEdge).toBeCloseTo(1000)
  })

  it('returns null when the opening has no host wall id', () => {
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: 4000, y: 0 },
      ],
      edges: [{ a: 0, b: 1, wallId: 'w1' }],
    }
    const opening: OpeningInput = { center: { x: 1000, y: 0 } }

    expect(resolveOpeningEdge(opening, graph)).toBeNull()
  })

  it('returns null when no edge carries the opening host wall id', () => {
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: 4000, y: 0 },
      ],
      edges: [{ a: 0, b: 1, wallId: 'w1' }],
    }
    const opening: OpeningInput = { center: { x: 1000, y: 0 }, hostWallId: 'nope' }

    expect(resolveOpeningEdge(opening, graph)).toBeNull()
  })

  it('returns null when the center projects past every matching edge', () => {
    const graph: PlanarGraph = {
      vertices: [
        { x: 0, y: 0 },
        { x: 4000, y: 0 },
      ],
      edges: [{ a: 0, b: 1, wallId: 'w1' }],
    }
    // The host wall id matches, but the center sits beyond the edge end (5000 > 4000).
    const opening: OpeningInput = { center: { x: 5000, y: 0 }, hostWallId: 'w1' }

    expect(resolveOpeningEdge(opening, graph)).toBeNull()
  })
})

engine/scene/wall-span.test.ts.source:
import * as THREE from 'three'
import { describe, expect, it } from 'vitest'
import type { SceneGraph } from '../../core'
import { nodesOf, offCenterPartitionFloor } from '../../core/scene/wall-runs-test-fixtures'
import { NeutralMaterialProvider } from '../materials/neutral-material-provider'
import { buildScene } from './build-scene'
import { wallSpanOf, WALL_SPAN_KEY, type WallSpan } from './wall-span'

/** The block of two rooms, with the partition at x = 3000, as a scene graph of one floor. */
function partitionedBlockGraph(): SceneGraph {
  return {
    nodes: [{ id: 'floor:g', kind: 'floor', name: 'Ground', elevation: 0 }],
    ...nodesOf(offCenterPartitionFloor()),
    underlays: [],
    dimensions: [],
    stairs: [],
    furniture: [],
  }
}

/** Every mesh under `root` that carries `entityId`, in traversal order. */
function meshesOf(root: THREE.Object3D, entityId: string): THREE.Mesh[] {
  const meshes: THREE.Mesh[] = []
  root.traverse((object) => {
    if (object instanceof THREE.Mesh && object.userData.entityId === entityId) {
      meshes.push(object)
    }
  })
  return meshes
}

const byStart = (a: WallSpan, b: WallSpan): number => a.fromMm - b.fromMm

describe('the span a wall mesh records', () => {
  const root = buildScene(partitionedBlockGraph(), new NeutralMaterialProvider())

  it('covers, for each piece of a wall split at a partition, the stretch from its start', () => {
    const meshes = meshesOf(root, 'wall:south')
    const spans = meshes.map((mesh) => wallSpanOf(mesh) as WallSpan).sort(byStart)

    expect(meshes).toHaveLength(2)
    expect(spans).toEqual([
      { fromMm: 0, toMm: 3000 },
      { fromMm: 3000, toMm: 8000 },
    ])
    expect(meshes.map((mesh) => mesh.userData[WALL_SPAN_KEY] as WallSpan).sort(byStart)).toEqual(
      spans,
    )
  })

  it('is undefined on an object that records none', () => {
    expect(wallSpanOf(new THREE.Mesh())).toBeUndefined()
  })
})

