      name: 'House',
      units: 'metric',
      period: 'victorian',
      appVersion: '0.1.0',
    })

    const result = exporter.export(project)

    expect(result.media).toBe('image/svg+xml')
    expect(result.media).toBe(exporter.media)
    expect(result.extension).toBe('svg')
    expect(result.content).toBe('<svg/>')

    expect(project).toEqual(
      createEmptyProject({
        name: 'House',
        units: 'metric',
        period: 'victorian',
        appVersion: '0.1.0',
      }),
    )
  })
})

